#!/usr/bin/env node

import { program, startInteractiveMode } from './index';

// Only start interactive mode if not in test environment
if (process.argv.length === 2 && !process.env['CLAUDECODE'] && !process.env['NODE_TEST']) {
  startInteractiveMode();
} else {
  program.parse();
}

import { BaseCommand } from './base-command';
import React from 'react';
import { render } from 'ink';
import { CommandOptions, ProjectConfiguration, ToolConfiguration } from '@dev-quality/types';
import type { AnalysisResult } from '../types';
import { Dashboard } from '../components/dashboard';
import { useAnalysisResults } from '../hooks/useAnalysisResults';
import type { AnalysisProgress as _AnalysisProgress } from '@dev-quality/core';

export interface AnalyzeOptions {
  tools?: string;
  output?: string;
  format?: string;
  failOnError?: boolean;
  quick?: boolean;
  dashboard?: boolean;
  noDashboard?: boolean;
  export?: string;
  filter?: string;
  sortBy?: string;
  maxItems?: number;
}

export class AnalyzeCommand extends BaseCommand {
  constructor(options: CommandOptions & AnalyzeOptions) {
    super(options);
  }

  async execute(): Promise<void> {
    const analyzeOptions = this.options as AnalyzeOptions & CommandOptions;
    const showDashboard =
      analyzeOptions.dashboard ?? (!analyzeOptions.noDashboard && process.stdout.isTTY);

    if (showDashboard) {
      await this.executeWithDashboard();
    } else {
      await this.executeTraditional();
    }
  }

  private async executeWithDashboard(): Promise<void> {
    const analyzeOptions = this.options as AnalyzeOptions & CommandOptions;

    this.log('Starting code quality analysis with dashboard...');

    try {
      const config = await this.loadConfig();

      // Create a wrapper component for dashboard with analysis
      const DashboardWithAnalysis = () => {
        const { executeAnalysis, analysisError, isAnalyzing } = useAnalysisResults();

        // Execute analysis on component mount
        React.useEffect(() => {
          const projectId = config.name ?? 'default-project';
          const plugins = analyzeOptions.tools ? analyzeOptions.tools.split(',') : undefined;

          executeAnalysis(projectId, config, {
            plugins,
            incremental: !analyzeOptions.quick,
          });
        }, []);

        if (analysisError) {
          return React.createElement('div', {}, [
            React.createElement('h1', {}, 'Analysis Error'),
            React.createElement('p', {}, analysisError.message),
          ]);
        }

        if (isAnalyzing) {
          return React.createElement('div', {}, [
            React.createElement('h1', {}, 'Analyzing...'),
            React.createElement('p', {}, 'Please wait while we analyze your code quality.'),
          ]);
        }

        // Return dashboard component
        return React.createElement(Dashboard, {
          analysisResult: {
            id: 'mock-analysis',
            projectId: config.name ?? 'default-project',
            timestamp: new Date().toISOString(),
            duration: 1000,
            overallScore: 85,
            toolResults: [],
            summary: {
              totalIssues: 0,
              totalErrors: 0,
              totalWarnings: 0,
              totalFixable: 0,
              overallScore: 85,
              toolCount: 0,
              executionTime: 1000,
            },
            aiPrompts: [],
          },
        });
      };

      // Render the dashboard
      const { waitUntilExit } = render(React.createElement(DashboardWithAnalysis));
      await waitUntilExit();

      this.log('Dashboard analysis completed');
    } catch (error) {
      this.log(
        `Dashboard analysis failed: ${error instanceof Error ? error.message : error}`,
        'error'
      );
      throw error;
    }
  }

  private async executeTraditional(): Promise<void> {
    this.log('Starting code quality analysis...');

    try {
      const config = await this.loadConfig();
      const toolsToRun = this.getToolsToRun(config);

      if (toolsToRun.length === 0) {
        this.log('No tools configured or enabled for analysis.', 'warn');
        return;
      }

      this.log(`Running analysis with tools: ${toolsToRun.join(', ')}`);

      const results: AnalysisResult[] = [];

      for (const toolName of toolsToRun) {
        this.logVerbose(`Running ${toolName} analysis...`);

        try {
          const result = await this.runToolAnalysis(toolName, config);
          results.push(result);

          const toolSuccess = result.toolResults[0]?.status === 'success';
          if (toolSuccess) {
            this.log(`${toolName} analysis completed successfully`);
          } else {
            this.log(`${toolName} analysis failed`, 'warn');
          }
        } catch (error) {
          this.log(`${toolName} analysis error: ${error}`, 'error');

          results.push({
            id: `${toolName}-error-${Date.now()}`,
            projectId: config.name ?? 'default-project',
            timestamp: new Date().toISOString(),
            duration: 0,
            overallScore: 0,
            toolResults: [
              {
                toolName,
                executionTime: 0,
                status: 'error',
                issues: [],
                metrics: {
                  issuesCount: 0,
                  errorsCount: 1,
                  warningsCount: 0,
                  infoCount: 0,
                  fixableCount: 0,
                  score: 0,
                },
              },
            ],
            summary: {
              totalIssues: 0,
              totalErrors: 1,
              totalWarnings: 0,
              totalFixable: 0,
              overallScore: 0,
              toolCount: 1,
              executionTime: 0,
            },
            aiPrompts: [],
          });

          if ((this.options as AnalyzeOptions & CommandOptions).failOnError) {
            throw new Error(`Analysis failed for tool: ${toolName}`);
          }
        }
      }

      await this.outputResults(results);

      const summary = this.generateSummary(results);
      this.log(`Analysis completed: ${summary}`);
    } catch (error) {
      this.log(`Analysis failed: ${error instanceof Error ? error.message : error}`, 'error');
      throw error;
    }
  }

  private getToolsToRun(config: ProjectConfiguration): string[] {
    const analyzeOptions = this.options as AnalyzeOptions & CommandOptions;
    if (analyzeOptions.tools) {
      return analyzeOptions.tools.split(',').map(tool => tool.trim());
    }

    return (
      config.tools
        ?.filter((tool: ToolConfiguration) => tool.enabled)
        ?.map((tool: ToolConfiguration) => tool.name)
        ?.sort((a: string, b: string) => {
          const toolA = config.tools.find((t: ToolConfiguration) => t.name === a);
          const toolB = config.tools.find((t: ToolConfiguration) => t.name === b);
          return (toolA?.priority ?? 999) - (toolB?.priority ?? 999);
        }) ?? []
    );
  }

  private async runToolAnalysis(
    toolName: string,
    config: ProjectConfiguration
  ): Promise<AnalysisResult> {
    const startTime = Date.now();

    this.logVerbose(`Simulating ${toolName} analysis...`);

    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 200));

    const success = Math.random() > 0.2;

    const result: AnalysisResult = {
      id: `${toolName}-${Date.now()}`,
      projectId: config.name ?? 'default-project',
      timestamp: new Date().toISOString(),
      duration: Date.now() - startTime,
      overallScore: success
        ? Math.floor(Math.random() * 30) + 70
        : Math.floor(Math.random() * 40) + 30,
      toolResults: [
        {
          toolName,
          executionTime: Date.now() - startTime,
          status: success ? 'success' : 'error',
          issues: [],
          metrics: {
            issuesCount: success
              ? Math.floor(Math.random() * 10)
              : Math.floor(Math.random() * 20) + 10,
            errorsCount: success ? 0 : Math.floor(Math.random() * 5) + 1,
            warningsCount: success
              ? Math.floor(Math.random() * 5)
              : Math.floor(Math.random() * 10) + 5,
            infoCount: 0,
            fixableCount: Math.floor(Math.random() * 8),
            score: success
              ? Math.floor(Math.random() * 30) + 70
              : Math.floor(Math.random() * 40) + 30,
          },
        },
      ],
      summary: {
        totalIssues: success ? Math.floor(Math.random() * 10) : Math.floor(Math.random() * 20) + 10,
        totalErrors: success ? 0 : Math.floor(Math.random() * 5) + 1,
        totalWarnings: success ? Math.floor(Math.random() * 5) : Math.floor(Math.random() * 10) + 5,
        totalFixable: Math.floor(Math.random() * 8),
        overallScore: success
          ? Math.floor(Math.random() * 30) + 70
          : Math.floor(Math.random() * 40) + 30,
        toolCount: 1,
        executionTime: Date.now() - startTime,
      },
      aiPrompts: [],
    };

    return result;
  }

  private async outputResults(results: AnalysisResult[]): Promise<void> {
    const analyzeOptions = this.options as AnalyzeOptions & CommandOptions;
    if (analyzeOptions.output) {
      const { writeFileSync } = await import('node:fs');
      const content = this.formatOutput(results);
      writeFileSync(analyzeOptions.output, content, 'utf-8');
      this.log(`Results saved to: ${analyzeOptions.output}`);
    } else {
      process.stdout.write(this.formatOutput(results));
    }
  }

  private generateSummary(results: AnalysisResult[]): string {
    const total = results.length;
    const passed = results.filter(r => r.toolResults[0]?.status === 'success').length;
    const failed = total - passed;

    return `${passed}/${total} tools passed, ${failed} failed`;
  }

  protected override async loadConfig(): Promise<ProjectConfiguration> {
    const path = this.options.config ?? '.dev-quality.json';

    try {
      const { readFileSync } = await import('node:fs');
      const content = readFileSync(path, 'utf-8');
      const config = JSON.parse(content);
      this.config = config;
      return config;
    } catch (error) {
      throw new Error(`Failed to load configuration: ${error}`);
    }
  }
}

import { CommandOptions, ProjectConfiguration } from '@dev-quality/types';

export abstract class BaseCommand {
  protected options: CommandOptions;
  protected config: ProjectConfiguration | null = null;

  constructor(options: CommandOptions) {
    this.options = options;
  }

  abstract execute(): Promise<void>;

  protected async loadConfig(): Promise<ProjectConfiguration> {
    throw new Error('loadConfig must be implemented by subclass');
  }

  protected log(message: string, level: 'info' | 'warn' | 'error' = 'info'): void {
    if (this.options.quiet && level !== 'error') {
      return;
    }

    const timestamp = new Date().toISOString();
    const prefix = level === 'error' ? 'ERROR' : level === 'warn' ? 'WARN' : 'INFO';

    process.stdout.write(`[${timestamp}] ${prefix}: ${message}\n`);
  }

  protected logVerbose(message: string): void {
    if (this.options.verbose) {
      this.log(message);
    }
  }

  protected formatOutput(data: unknown): string {
    if (this.options.json) {
      return JSON.stringify(data, null, 2);
    }
    return String(data);
  }
}

import { BaseCommand } from './base-command';
import { ProjectConfiguration, CommandOptions } from '@dev-quality/types';
import { fileUtils } from '@dev-quality/utils';

export interface ConfigOptions {
  show?: boolean;
  edit?: boolean;
  reset?: boolean;
}

export class ConfigCommand extends BaseCommand {
  constructor(options: CommandOptions & ConfigOptions) {
    super(options);
  }

  async execute(): Promise<void> {
    const configOptions = this.options as ConfigOptions & CommandOptions;
    if (configOptions.show) {
      await this.showConfig();
    } else if (configOptions.edit) {
      await this.editConfig();
    } else if (configOptions.reset) {
      await this.resetConfig();
    } else {
      await this.showConfig();
    }
  }

  private async showConfig(): Promise<void> {
    try {
      const config = await this.loadConfig();
      this.log('Current configuration:');
      process.stdout.write(this.formatOutput(config));
    } catch {
      this.log(`No configuration found. Run 'dev-quality setup' to create one.`, 'warn');
    }
  }

  private async editConfig(): Promise<void> {
    this.log('Edit configuration - opening in default editor...');
    this.log('This feature will be implemented in a future version.');
  }

  private async resetConfig(): Promise<void> {
    const configPath = this.options.config ?? '.dev-quality.json';

    this.log('Resetting configuration to defaults...');

    const defaultConfig: ProjectConfiguration = {
      name: 'my-project',
      version: '1.0.0',
      description: 'A project analyzed by DevQuality',
      type: 'backend',
      frameworks: [],
      tools: [
        {
          name: 'typescript',
          version: '5.3.3',
          enabled: true,
          config: {},
          priority: 1,
        },
        {
          name: 'eslint',
          version: 'latest',
          enabled: true,
          config: {},
          priority: 2,
        },
        {
          name: 'prettier',
          version: 'latest',
          enabled: true,
          config: {},
          priority: 3,
        },
      ],
      paths: {
        source: './src',
        tests: './tests',
        config: './configs',
        output: './output',
      },
      settings: {
        verbose: false,
        quiet: false,
        json: false,
        cache: true,
      },
    };

    try {
      fileUtils.writeJsonSync(configPath, defaultConfig);
      this.log(`Configuration reset and saved to: ${configPath}`);
    } catch (error) {
      throw new Error(`Failed to reset configuration: ${error}`);
    }
  }

  protected override async loadConfig(): Promise<ProjectConfiguration> {
    const path = this.options.config ?? '.dev-quality.json';

    try {
      const config = fileUtils.readJsonSync<ProjectConfiguration>(path);
      this.config = config;
      return config;
    } catch (error) {
      throw new Error(`Failed to load configuration: ${error}`);
    }
  }
}

import { Command } from 'commander';
import { render } from 'ink';
import React from 'react';

import { CoverageDashboard } from '../components/coverage/index';
import type {
  CoverageReport,
  CoverageAnalysisEngine,
  AnalysisContext as CoreAnalysisContext,
  ToolConfiguration,
  ToolResult,
} from '@dev-quality/core';
import { logger } from '../utils/logger.js';

interface CoverageCommandOptions {
  output?: string;
  format?: 'json' | 'html' | 'markdown' | 'csv';
  interactive?: boolean;
  exclude?: string[];
  include?: string;
  'coverage-threshold'?: string;
  'critical-paths'?: string;
  'no-trends'?: boolean;
  'no-quality-score'?: boolean;
  'no-risk-assessment'?: boolean;
}

interface CoverageConfig {
  thresholds: {
    overall: number;
    lines: number;
    branches: number;
    functions: number;
    statements: number;
    criticalPaths: number;
  };
  criticalPaths: Array<{
    name: string;
    patterns: string[];
    requiredCoverage: number;
    description: string;
  }>;
  exclusions: string[];
  includePatterns: string[];
  enableTrending: boolean;
  enableQualityScoring: boolean;
  enableRiskAssessment: boolean;
}

interface AnalysisContext extends Omit<CoreAnalysisContext, 'config'> {
  config: {
    name: string;
    version: string;
    tools: ToolConfiguration[];
  };
}

export class CoverageCommand {
  private coverageEngine: CoverageAnalysisEngine | null = null;

  constructor() {
    // Initialize coverage engine
  }

  public createCommand(): Command {
    const command = new Command('coverage');

    return command
      .description('Analyze and visualize test coverage')
      .option('-o, --output <path>', 'Output file path for report')
      .option('-f, --format <format>', 'Report format (json, html, markdown, csv)', 'json')
      .option('-i, --interactive', 'Show interactive dashboard', false)
      .option('--exclude <patterns...>', 'Exclude patterns for coverage analysis')
      .option('--include <pattern>', 'Include pattern for coverage analysis')
      .option('--coverage-threshold <threshold>', 'Coverage threshold percentage', '80')
      .option('--critical-paths <paths...>', 'Critical path patterns')
      .option('--no-trends', 'Disable trend analysis')
      .option('--no-quality-score', 'Disable quality scoring')
      .option('--no-risk-assessment', 'Disable risk assessment')
      .action(async (options: CoverageCommandOptions) => {
        await this.execute(options);
      });
  }

  public async execute(options: CoverageCommandOptions): Promise<void> {
    try {
      this.showProgress('Starting coverage analysis...');

      // Initialize coverage engine
      const { CoverageAnalysisEngine } = await import('@dev-quality/core');
      this.coverageEngine = new CoverageAnalysisEngine(this.getCoverageConfig(options));

      // Get analysis context
      const context = await this.getAnalysisContext();

      // Run tests to generate coverage data
      this.showProgress('Running tests to collect coverage data...');
      const testResults = await this.runTests(context);

      // Analyze coverage
      this.showProgress('Analyzing coverage data...');
      const coverageReport = await this.coverageEngine.analyzeCoverage(context, testResults);

      // Display or export results
      if (options.interactive) {
        await this.showInteractiveDashboard(coverageReport);
      } else {
        await this.exportReport(coverageReport, options);
      }

      // Show summary
      this.showSummary(coverageReport);

      // Check exit code based on thresholds
      this.checkExitCode(coverageReport, options);
    } catch (error) {
      this.handleError(error);
    }
  }

  private getCoverageConfig(options: CoverageCommandOptions): CoverageConfig {
    const thresholds = this.parseThresholds(options['coverage-threshold']);

    return {
      thresholds,
      criticalPaths: this.parseCriticalPaths(options['critical-paths'] ?? []),
      exclusions: options.exclude ?? [
        '**/node_modules/**',
        '**/dist/**',
        '**/build/**',
        '**/*.test.*',
        '**/*.spec.*',
      ],
      includePatterns: options.include ? [options.include] : ['**/*.{ts,tsx,js,jsx}'],
      enableTrending: !options['no-trends'],
      enableQualityScoring: !options['no-quality-score'],
      enableRiskAssessment: !options['no-risk-assessment'],
    };
  }

  private parseThresholds(thresholdStr?: string): CoverageConfig['thresholds'] {
    const defaults = {
      overall: 80,
      lines: 80,
      branches: 80,
      functions: 80,
      statements: 80,
      criticalPaths: 90,
    };

    if (!thresholdStr) {
      return defaults;
    }

    try {
      // Check if it's a simple number (just overall threshold)
      const simpleNumber = parseInt(thresholdStr, 10);
      if (!isNaN(simpleNumber) && simpleNumber >= 0 && simpleNumber <= 100) {
        return {
          ...defaults,
          overall: simpleNumber,
        };
      }

      // Parse format like "overall:85,lines:90,branches:80"
      const thresholds = { ...defaults };
      const pairs = thresholdStr.split(',');

      for (const pair of pairs) {
        const [key, value] = pair.split(':');
        if (key && value) {
          const trimmedKey = key.trim() as keyof typeof thresholds;
          const numValue = parseInt(value, 10);
          if (!isNaN(numValue) && numValue >= 0 && numValue <= 100) {
            // Check if the key is valid
            if (trimmedKey in thresholds) {
              thresholds[trimmedKey] = numValue;
            }
          }
        }
      }

      return thresholds;
    } catch {
      return defaults;
    }
  }

  private parseCriticalPaths(paths?: string[] | string): CoverageConfig['criticalPaths'] {
    if (!paths) {
      return [];
    }

    const pathArray = Array.isArray(paths) ? paths : [paths];
    if (pathArray.length === 0) {
      return [];
    }

    return pathArray
      .map(path => {
        // Parse format like "auth:Authentication code:95"
        const parts = path.split(':');
        if (parts.length >= 3) {
          return {
            name: parts[0]?.trim() ?? '',
            patterns: [parts[0]?.trim() ?? ''],
            requiredCoverage: parseInt(parts[2] ?? '90', 10) || 90,
            description: parts[1]?.trim() ?? '',
          };
        }
        return null;
      })
      .filter((item): item is NonNullable<typeof item> => item !== null);
  }

  private async runTests(context: AnalysisContext): Promise<ToolResult[]> {
    const { BunTestAdapter } = await import('@dev-quality/core');

    const bunTestAdapter = new BunTestAdapter();
    await bunTestAdapter.initialize({
      enabled: true,
      timeout: 120000,
      cacheEnabled: true,
      logLevel: 'info',
    });

    try {
      const result = await bunTestAdapter.execute(context);
      return [result];
    } finally {
      await bunTestAdapter.cleanup();
    }
  }

  private async showInteractiveDashboard(report: CoverageReport): Promise<void> {
    const { App } = await import('../components/app.js');

    return new Promise(resolve => {
      const { waitUntilExit } = render(
        React.createElement(App, {
          children: React.createElement(CoverageDashboard, { coverageReport: report }),
        })
      );

      waitUntilExit().then(() => {
        resolve();
      });
    });
  }

  private async exportReport(
    report: CoverageReport,
    options: CoverageCommandOptions
  ): Promise<void> {
    const outputPath = options.output ?? `coverage-report.${options.format}`;

    this.showProgress(`Exporting report to ${outputPath}...`);

    try {
      if (!this.coverageEngine) {
        throw new Error('Coverage engine not initialized');
      }
      const exportedContent = await this.coverageEngine.exportReport(
        report,
        options.format as 'json' | 'html' | 'markdown' | 'csv',
        outputPath
      );

      if (!options.output) {
        // Display content to stdout if no output file specified
        logger.info(exportedContent);
      } else {
        logger.success(`✓ Report exported to ${outputPath}`);
      }
    } catch (error) {
      throw new Error(`Failed to export report: ${error}`);
    }
  }

  private showSummary(report: CoverageReport): void {
    const { summary } = report;

    logger.info('\n📊 Coverage Analysis Summary');
    logger.info('================================');
    logger.info(
      `Overall Coverage: ${summary.overallCoverage.toFixed(1)}% (Grade: ${summary.grade})`
    );
    logger.info(`Quality Score: ${summary.qualityScore.toFixed(1)} (Risk: ${summary.riskLevel})`);
    logger.info(
      `Files: ${summary.totalFiles} total, ${summary.coveredFiles} covered, ${summary.uncoveredFiles} uncovered`
    );

    if (summary.totalCriticalPaths > 0) {
      logger.info(
        `Critical Paths: ${summary.coveredCriticalPaths}/${summary.totalCriticalPaths} meet requirements`
      );
    }

    if (summary.highPriorityRecommendations > 0) {
      logger.warning(
        `⚠️  ${summary.highPriorityRecommendations} high-priority recommendations require attention`
      );
    }

    if (summary.overallCoverage >= 90) {
      logger.success('🎉 Excellent coverage!');
    } else if (summary.overallCoverage >= 80) {
      logger.success('👍 Good coverage!');
    } else if (summary.overallCoverage >= 70) {
      logger.warning('⚠️  Coverage needs improvement');
    } else {
      logger.error('❌ Critical: Coverage is too low');
    }
  }

  private checkExitCode(report: CoverageReport, options: CoverageCommandOptions): void {
    const thresholds = this.parseThresholds(options['coverage-threshold']);
    const { summary } = report;

    let shouldFail = false;

    if (summary.overallCoverage < thresholds.overall) {
      logger.error(
        `❌ Overall coverage ${summary.overallCoverage.toFixed(1)}% is below threshold ${thresholds.overall}%`
      );
      shouldFail = true;
    }

    if (summary.lineCoverage < thresholds.lines) {
      logger.error(
        `❌ Line coverage ${summary.lineCoverage.toFixed(1)}% is below threshold ${thresholds.lines}%`
      );
      shouldFail = true;
    }

    if (summary.branchCoverage < thresholds.branches) {
      logger.error(
        `❌ Branch coverage ${summary.branchCoverage.toFixed(1)}% is below threshold ${thresholds.branches}%`
      );
      shouldFail = true;
    }

    if (summary.functionCoverage < thresholds.functions) {
      logger.error(
        `❌ Function coverage ${summary.functionCoverage.toFixed(1)}% is below threshold ${thresholds.functions}%`
      );
      shouldFail = true;
    }

    if (shouldFail) {
      process.exit(1);
    }
  }

  private handleError(error: unknown): void {
    logger.error(
      '❌ Coverage analysis failed:',
      error instanceof Error ? error.message : String(error)
    );

    if (error instanceof Error) {
      if (error.message.includes('No coverage data found')) {
        logger.warning('\n💡 Make sure to:');
        logger.warning('  1. Have test files in your project');
        logger.warning('  2. Configure Bun test to generate coverage');
        logger.warning('  3. Run tests with --coverage flag');
      } else if (error.message.includes('Bun not found')) {
        logger.warning('\n💡 Install Bun: curl -fsSL https://bun.sh/install | bash');
      }
    }

    process.exit(1);
  }

  private showProgress(message: string): void {
    logger.info(message);
  }

  private async getAnalysisContext(): Promise<AnalysisContext> {
    // Return a mock analysis context for now
    return {
      projectPath: process.cwd(),
      config: {
        name: 'project',
        version: '1.0.0',
        tools: [],
      },
      logger: {
        error: () => {},
        warn: () => {},
        info: () => {},
        debug: () => {},
      },
    };
  }
}

/**
 * Dashboard command for launching interactive quality dashboard
 */

import { BaseCommand } from './base-command';
import React from 'react';
import { render } from 'ink';
import type { CommandOptions, ProjectConfiguration } from '@dev-quality/types';
import { Dashboard } from '../components/dashboard';
import { useAnalysisResults } from '../hooks/useAnalysisResults';
import type { AnalysisResult } from '../types';

export interface DashboardOptions {
  input?: string;
  tools?: string;
  filter?: string;
  sortBy?: string;
  maxItems?: number;
  autoAnalyze?: boolean;
}

export class DashboardCommand extends BaseCommand {
  constructor(options: CommandOptions & DashboardOptions) {
    super(options);
  }

  async execute(): Promise<void> {
    const dashboardOptions = this.options as DashboardOptions & CommandOptions;

    this.log('Launching DevQuality Dashboard...');

    try {
      // Create a wrapper component for the dashboard
      const DashboardWrapper = () => {
        const { executeAnalysis, loadResults, analysisError, isAnalyzing } = useAnalysisResults();
        const [analysisResult, setAnalysisResult] = React.useState<AnalysisResult | null>(null);

        // Load analysis result on mount
        React.useEffect(() => {
          this.getAnalysisResult()
            .then(setAnalysisResult)
            .catch(error => {
              this.log(`Failed to load analysis result: ${error}`, 'error');
            });
        }, []);

        // Execute analysis automatically if requested
        React.useEffect(() => {
          if (dashboardOptions.autoAnalyze !== false) {
            this.runAnalysis(executeAnalysis, loadResults);
          }
        }, []);

        if (analysisError) {
          return React.createElement('div', {}, [
            React.createElement('h1', {}, 'Dashboard Error'),
            React.createElement('p', {}, analysisError.message),
          ]);
        }

        if (isAnalyzing || !analysisResult) {
          return React.createElement('div', {}, [
            React.createElement('h1', {}, isAnalyzing ? 'Analyzing...' : 'Loading...'),
            React.createElement(
              'p',
              {},
              isAnalyzing
                ? 'Please wait while we analyze your code quality.'
                : 'Please wait while we load the results.'
            ),
          ]);
        }

        // Return dashboard component with mock or loaded results
        return React.createElement(Dashboard, {
          analysisResult,
        });
      };

      // Render the dashboard
      const { waitUntilExit } = render(React.createElement(DashboardWrapper));
      await waitUntilExit();

      this.log('Dashboard session ended');
    } catch (error) {
      this.log(`Dashboard failed: ${error instanceof Error ? error.message : error}`, 'error');
      throw error;
    }
  }

  private async runAnalysis(
    executeAnalysis: (
      projectId: string,
      config: ProjectConfiguration,
      options?: Record<string, unknown>
    ) => Promise<Record<string, unknown>>,
    loadResults: (result: AnalysisResult) => void
  ): Promise<void> {
    try {
      const config = await this.loadConfig();
      const dashboardOptions = this.options as DashboardOptions;

      const plugins = dashboardOptions.tools ? dashboardOptions.tools.split(',') : undefined;

      const result = await executeAnalysis('dashboard-project', config, {
        plugins,
      });

      if (result['success'] && result['result']) {
        loadResults(result['result'] as AnalysisResult);
      }
    } catch (error) {
      this.log(`Auto-analysis failed: ${error instanceof Error ? error.message : error}`, 'warn');
    }
  }

  private async getAnalysisResult(): Promise<AnalysisResult> {
    const dashboardOptions = this.options as DashboardOptions;

    // If input file is specified, load from there
    if (dashboardOptions.input) {
      try {
        const { readFileSync } = await import('node:fs');
        const content = readFileSync(dashboardOptions.input, 'utf-8');
        const result = JSON.parse(content);
        return result as AnalysisResult;
      } catch (error) {
        this.log(`Failed to load results from ${dashboardOptions.input}: ${error}`, 'warn');
      }
    }

    // Return mock result for now
    return {
      id: 'mock-dashboard-analysis',
      projectId: 'dashboard-project',
      timestamp: new Date().toISOString(),
      duration: 5000,
      overallScore: 78,
      toolResults: [
        {
          toolName: 'eslint',
          executionTime: 1500,
          status: 'success',
          issues: [
            {
              id: 'eslint-1',
              type: 'warning',
              toolName: 'eslint',
              filePath: 'src/components/dashboard.tsx',
              lineNumber: 45,
              message: 'Unused variable "example"',
              ruleId: 'no-unused-vars',
              fixable: true,
              suggestion: 'Remove the unused variable or use it in your code',
              score: 25,
            },
            {
              id: 'eslint-2',
              type: 'error',
              toolName: 'eslint',
              filePath: 'src/hooks/useDashboardStore.ts',
              lineNumber: 23,
              message: 'Missing return type annotation',
              ruleId: '@typescript-eslint/explicit-function-return-type',
              fixable: true,
              suggestion: 'Add explicit return type annotation',
              score: 50,
            },
          ],
          metrics: {
            issuesCount: 2,
            errorsCount: 1,
            warningsCount: 1,
            infoCount: 0,
            fixableCount: 2,
            score: 75,
          },
        },
        {
          toolName: 'typescript',
          executionTime: 2000,
          status: 'success',
          issues: [
            {
              id: 'ts-1',
              type: 'error',
              toolName: 'typescript',
              filePath: 'src/types/dashboard.ts',
              lineNumber: 15,
              message: 'Type "any" is not allowed',
              ruleId: 'no-explicit-any',
              fixable: true,
              suggestion: 'Use proper type annotations instead of "any"',
              score: 60,
            },
          ],
          metrics: {
            issuesCount: 1,
            errorsCount: 1,
            warningsCount: 0,
            infoCount: 0,
            fixableCount: 1,
            score: 85,
          },
          coverage: {
            lines: { total: 500, covered: 425, percentage: 85 },
            functions: { total: 50, covered: 45, percentage: 90 },
            branches: { total: 100, covered: 80, percentage: 80 },
            statements: { total: 600, covered: 510, percentage: 85 },
          },
        },
      ],
      summary: {
        totalIssues: 3,
