/**
 * Base abstract component for all dashboard widgets
 */

import React, { useCallback } from 'react';
import { Box, Text, useInput } from 'ink';
import type { WidgetConfig } from '../../types/dashboard';

// Re-export types for widget registry
export type { WidgetConfig } from '../../types/dashboard';

interface BaseWidgetProps {
  config: WidgetConfig;
  isSelected: boolean;
  onSelect: (widgetId: string) => void;
  onUpdate: (widgetId: string, updates: Partial<WidgetConfig>) => void;
  children: React.ReactNode;
}

export function BaseWidget({
  config,
  isSelected,
  onSelect: _onSelect,
  onUpdate,
  children,
}: BaseWidgetProps): React.ReactElement {
  const { id, position, visible } = config;

  // Handle keyboard input for widget management
  useInput((input, key) => {
    if (!isSelected) return;

    switch (input) {
      case 'r': // Resize widget
        if (key.ctrl) {
          handleResize();
        }
        break;
      case 'm': // Move widget
        if (key.ctrl) {
          handleMove();
        }
        break;
      case 'h': // Toggle visibility
        if (key.ctrl) {
          handleToggleVisibility();
        }
        break;
      case '+': // Increase size
        if (key.ctrl) {
          handleIncreaseSize();
        }
        break;
      case '-': // Decrease size
        if (key.ctrl) {
          handleDecreaseSize();
        }
        break;
    }
  });

  const handleResize = useCallback(() => {
    // Cycle through common sizes
    const sizes = [
      { width: 40, height: 10 },
      { width: 60, height: 15 },
      { width: 80, height: 20 },
      { width: 100, height: 25 },
    ];

    const currentIndex = sizes.findIndex(
      size => size.width === position.width && size.height === position.height
    );
    const nextIndex = (currentIndex + 1) % sizes.length;

    onUpdate(id, {
      position: {
        ...position,
        ...sizes[nextIndex],
      },
    });
  }, [id, position, onUpdate]);

  const handleMove = useCallback(() => {
    // Simple movement pattern: right -> down -> left -> up
    const step = 5;
    let newPosition = { ...position };

    if (position.x < 80) {
      newPosition.x += step;
    } else if (position.y < 20) {
      newPosition.y += step;
      newPosition.x = 0;
    } else {
      newPosition = { x: 0, y: 0, width: position.width, height: position.height };
    }

    onUpdate(id, { position: newPosition });
  }, [id, position, onUpdate]);

  const handleToggleVisibility = useCallback(() => {
    onUpdate(id, { visible: !visible });
  }, [id, visible, onUpdate]);

  const handleIncreaseSize = useCallback(() => {
    onUpdate(id, {
      position: {
        ...position,
        width: Math.min(120, position.width + 10),
        height: Math.min(30, position.height + 5),
      },
    });
  }, [id, position, onUpdate]);

  const handleDecreaseSize = useCallback(() => {
    onUpdate(id, {
      position: {
        ...position,
        width: Math.max(20, position.width - 10),
        height: Math.min(5, position.height - 5),
      },
    });
  }, [id, position, onUpdate]);

  // Render widget only if visible
  if (!visible) {
    return <Box />;
  }

  return (
    <Box
      flexDirection="column"
      borderStyle={isSelected ? 'double' : 'single'}
      borderColor={isSelected ? 'blue' : 'gray'}
      paddingX={position.x > 0 ? 0 : 1}
      paddingY={position.y > 0 ? 0 : 1}
    >
      {/* Widget Header */}
      <Box
        width="100%"
        borderStyle="single"
        borderColor={isSelected ? 'blue' : 'gray'}
        justifyContent="space-between"
        paddingX={1}
      >
        <Text bold color={isSelected ? 'blue' : 'white'}>
          {config.type.toUpperCase()}
        </Text>
        <Text color="gray" dimColor>
          {position.width}×{position.height}
        </Text>
      </Box>

      {/* Widget Content */}
      <Box flexGrow={1} paddingX={1} paddingY={1}>
        {children}
      </Box>

      {/* Widget Footer (when selected) */}
      {isSelected && (
        <Box
          width="100%"
          borderStyle="single"
          borderColor="blue"
          justifyContent="center"
          paddingX={1}
        >
          <Text color="blue" dimColor>
            Ctrl+R:Resize Ctrl+M:Move Ctrl+H:Hide +/-:Size
          </Text>
        </Box>
      )}
    </Box>
  );
}

// Widget factory function type
export type WidgetFactory = (
  config: WidgetConfig,
  isSelected: boolean,
  onSelect: (widgetId: string) => void,
  onUpdate: (widgetId: string, updates: Partial<WidgetConfig>) => void
) => React.ReactElement | null;

// Widget registration interface
export interface WidgetRegistration {
  type: string;
  name: string;
  description: string;
  factory: WidgetFactory;
  defaultConfig: Partial<WidgetConfig>;
  minSize: { width: number; height: number };
  maxSize: { width: number; height: number };
}

/**
 * Breadcrumb Navigation Component
 * Displays hierarchical navigation path with keyboard support
 */

import React from 'react';
import { Box, Text, useInput } from 'ink';
import type { NavigationBreadcrumb } from '../../types/dashboard';

interface BreadcrumbNavigationProps {
  breadcrumbs: NavigationBreadcrumb[];
  onSelect?: (breadcrumb: NavigationBreadcrumb, index: number) => void;
  showSeparator?: boolean;
  maxItems?: number;
}

const SEPARATOR = ' › ';

export const BreadcrumbNavigation: React.FC<BreadcrumbNavigationProps> = ({
  breadcrumbs,
  onSelect,
  showSeparator = true,
  maxItems = 10,
}) => {
  const [selectedIndex, setSelectedIndex] = React.useState(-1);

  useInput((input, key) => {
    if (breadcrumbs.length === 0 || !onSelect) return;

    if (key.leftArrow) {
      setSelectedIndex(prev => Math.max(0, prev - 1));
    } else if (key.rightArrow) {
      setSelectedIndex(prev => Math.min(breadcrumbs.length - 1, prev + 1));
    } else if (key.return && selectedIndex >= 0 && selectedIndex < breadcrumbs.length) {
      const selectedBreadcrumb = breadcrumbs[selectedIndex];
      if (selectedBreadcrumb) {
        onSelect(selectedBreadcrumb, selectedIndex);
      }
    }
  });

  // Limit breadcrumbs to prevent overflow
  const displayBreadcrumbs = breadcrumbs.slice(-maxItems);
  const hasMoreItems = breadcrumbs.length > maxItems;

  const renderBreadcrumb = (breadcrumb: NavigationBreadcrumb, index: number, isLast: boolean) => {
    const isSelected = selectedIndex === index;
    const displayLabel =
      breadcrumb.label.length > 20 ? `${breadcrumb.label.slice(0, 17)}...` : breadcrumb.label;

    return (
      <Box key={breadcrumb.id}>
        <Text color={isSelected ? 'blue' : 'gray'} underline={isSelected} bold={isSelected}>
          {displayLabel}
        </Text>
        {!isLast && showSeparator && <Text color="gray">{SEPARATOR}</Text>}
      </Box>
    );
  };

  return (
    <Box flexDirection="row" alignItems="center">
      {hasMoreItems && (
        <Box marginRight={1}>
          <Text color="gray">...</Text>
          <Text color="gray">{SEPARATOR}</Text>
        </Box>
      )}

      {displayBreadcrumbs.map((breadcrumb, index) =>
        renderBreadcrumb(breadcrumb, index, index === displayBreadcrumbs.length - 1)
      )}

      {selectedIndex >= 0 && selectedIndex < displayBreadcrumbs.length && (
        <Box marginLeft={1}>
          <Text color="gray">(Selected: {displayBreadcrumbs[selectedIndex]?.label})</Text>
        </Box>
      )}

      {breadcrumbs.length > 0 && onSelect && (
        <Box marginLeft={1}>
          <Text color="gray" italic>
            [Use arrow keys to select, Enter to navigate]
          </Text>
        </Box>
      )}
    </Box>
  );
};

export default BreadcrumbNavigation;

/** * Comparison Summary Component * Displays summary metrics and key insights from comparison */
import React from 'react'; import { Box, Text } from 'ink'; import type { ComparisonResult } from '../../hooks/useComparisonStore';
interface ComparisonSummaryProps { comparison: ComparisonResult; }
export const ComparisonSummary: React.FC<ComparisonSummaryProps> = ({ comparison }) => { const { baseline, comparison: comp, summary } = comparison;
const getTrendIndicator = (value: number) => { if (value > 0) return { symbol: '📈', color: 'red', text: 'increased' }; if (value < 0) return { symbol: '📉', color: 'green', text: 'decreased' }; return { symbol: '➡️', color: 'yellow', text: 'unchanged' }; };
const getImprovementStatus = () => { if (summary.improvementRate > 10) { return { text: 'Significant Improvement', color: 'green' }; } if (summary.improvementRate > 0) { return { text: 'Improvement', color: 'green' }; } if (summary.improvementRate > -10) { return { text: 'Minor Degradation', color: 'yellow' }; } return { text: 'Significant Degradation', color: 'red' }; };
const totalIssuesTrend = getTrendIndicator(summary.totalIssuesDiff); const criticalIssuesTrend = getTrendIndicator(summary.criticalIssuesDiff); const scoreTrend = getTrendIndicator(summary.scoreDiff); const improvementStatus = getImprovementStatus();
return ( <Box flexDirection="column"> {/* Overview Section */} <Box flexDirection="column" marginBottom={2}> <Text bold color="blue"> Overview </Text> <Box flexDirection="row" marginTop={1}> <Text color="gray"> Comparing {baseline.version ?? baseline.id.slice(0, 8)} ( {baseline.timestamp.toLocaleDateString()}) </Text> <Text color="gray"> with </Text> <Text color="gray"> {comp.version ?? comp.id.slice(0, 8)} ({comp.timestamp.toLocaleDateString()}) </Text> </Box> </Box>
{/* Key Metrics */} <Box flexDirection="column" marginBottom={2}> <Text bold color="blue"> Key Metrics </Text>
<Box flexDirection="row" marginTop={1}> <Box width={30}> <Text>Total Issues</Text> </Box> <Box width={15}> <Text color="gray">{baseline.metadata.totalIssues}</Text> </Box> <Box width={3}> <Text color="gray">→</Text> </Box> <Box width={15}> <Text color="gray">{comp.metadata.totalIssues}</Text> </Box> <Box width={10}> <Text color={totalIssuesTrend.color}> {totalIssuesTrend.symbol} {Math.abs(summary.totalIssuesDiff)} </Text> </Box> <Box> <Text color={totalIssuesTrend.color} dimColor> ({totalIssuesTrend.text}) </Text> </Box> </Box>
<Box flexDirection="row"> <Box width={30}> <Text>Critical Issues</Text> </Box> <Box width={15}> <Text color="gray">{baseline.metadata.criticalIssues}</Text> </Box> <Box width={3}> <Text color="gray">→</Text> </Box> <Box width={15}> <Text color="gray">{comp.metadata.criticalIssues}</Text> </Box> <Box width={10}> <Text color={criticalIssuesTrend.color}> {criticalIssuesTrend.symbol} {Math.abs(summary.criticalIssuesDiff)} </Text> </Box> <Box> <Text color={criticalIssuesTrend.color} dimColor> ({criticalIssuesTrend.text}) </Text> </Box> </Box>
<Box flexDirection="row"> <Box width={30}> <Text>Quality Score</Text> </Box> <Box width={15}> <Text color="gray">{baseline.metadata.score}</Text> </Box> <Box width={3}> <Text color="gray">→</Text> </Box> <Box width={15}> <Text color="gray">{comp.metadata.score}</Text> </Box> <Box width={10}> <Text color={scoreTrend.color}> {scoreTrend.symbol} {Math.abs(summary.scoreDiff)} </Text> </Box> <Box> <Text color={scoreTrend.color} dimColor> ({scoreTrend.text}) </Text> </Box> </Box> </Box>
{/* Issues Changes */} <Box flexDirection="column" marginBottom={2}> <Text bold color="blue"> Issues Changes </Text>
<Box flexDirection="row" marginTop={1}> <Box width={25}> <Text color="green">New Issues:</Text> </Box> <Box width={10}> <Text color="green" bold> +{summary.newIssuesCount} </Text> </Box> <Box> <Text color="gray" dimColor> (introduced in comparison) </Text> </Box> </Box>
<Box flexDirection="row"> <Box width={25}> <Text color="red">Resolved Issues:</Text> </Box> <Box width={10}> <Text color="red" bold> -{summary.resolvedIssuesCount} </Text> </Box> <Box> <Text color="gray" dimColor> (fixed in comparison) </Text> </Box> </Box>
<Box flexDirection="row"> <Box width={25}> <Text color="gray">Unchanged Issues:</Text> </Box> <Box width={10}> <Text color="gray">{summary.unchangedIssuesCount}</Text> </Box> <Box> <Text color="gray" dimColor> (persisting issues) </Text> </Box> </Box> </Box>
{/* Severity Breakdown */} <Box flexDirection="column" marginBottom={2}> <Text bold color="blue"> Severity Breakdown </Text>
{comparison.trends.severity.map(trend => { const severityTrend = getTrendIndicator(trend.diff); return ( <Box flexDirection="row" key={trend.type} marginTop={1}> <Box width={15}> <Text bold>{trend.type.toUpperCase()}:</Text> </Box> <Box width={10}> <Text color="gray">{trend.baseline}</Text> </Box> <Box width={3}> <Text color="gray">→</Text> </Box> <Box width={10}> <Text color="gray">{trend.comparison}</Text> </Box> <Box width={8}> <Text color={severityTrend.color}> {severityTrend.symbol} {Math.abs(trend.diff)} </Text> </Box> </Box> ); })} </Box>
{/* Overall Status */} <Box flexDirection="column" marginBottom={2}> <Text bold color="blue"> Overall Status </Text>
<Box flexDirection="row" marginTop={1}> <Text color={improvementStatus.color} bold> {improvementStatus.text} </Text> <Box flexGrow={1} /> <Text color="gray">Improvement Rate: {summary.improvementRate.toFixed(2)}%</Text> </Box>
<Box flexDirection="row" marginTop={1}> <Text color="gray" dimColor> {summary.improvementRate > 0 ? `🟢 Good progress! ${summary.resolvedIssuesCount} issues resolved with ${summary.newIssuesCount} new issues introduced.` : `⚠️ Need attention. ${summary.newIssuesCount} new issues introduced while only ${summary.resolvedIssuesCount} were resolved.`} </Text> </Box> </Box>
{/* Tool Analysis */} <Box flexDirection="column"> <Text bold color="blue"> Tool Analysis </Text>
{comparison.trends.tools.map(trend => { const toolTrend = getTrendIndicator(trend.diff); return ( <Box flexDirection="row" key={trend.tool} marginTop={1}> <Box width={15}> <Text>{trend.tool}:</Text> </Box> <Box width={10}> <Text color="gray">{trend.baseline}</Text> </Box> <Box width={3}> <Text color="gray">→</Text> </Box> <Box width={10}> <Text color="gray">{trend.comparison}</Text> </Box> <Box width={8}> <Text color={toolTrend.color}> {toolTrend.symbol} {Math.abs(trend.diff)} </Text> </Box> </Box> ); })} </Box> </Box> ); };

/**
 * Dashboard Layout component with keyboard-based panel management
 */

import React, { useState, useCallback, useEffect } from 'react';
import { Box, Text, useInput, type Key } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { WidgetRegistry } from './widget-registry';
import type { DashboardLayout as DashboardLayoutType, WidgetConfig } from '../../types/dashboard';

interface DashboardLayoutProps {
  layout: DashboardLayoutType;
  onLayoutUpdate: (layout: DashboardLayoutType) => void;
  onExit: () => void;
}

interface LayoutMode {
  mode: 'normal' | 'edit' | 'add-widget' | 'manage-layouts';
  selectedWidgetId: string | null;
  selectedWidgetIndex: number;
}

export function DashboardLayout({ layout, onLayoutUpdate, onExit }: DashboardLayoutProps): React.ReactElement {
  const { setCurrentLayout } = useDashboardStore();
  const [layoutMode, setLayoutMode] = useState<LayoutMode>({
    mode: 'normal',
    selectedWidgetId: null,
    selectedWidgetIndex: 0,
  });

  // Update store when layout changes
  useEffect(() => {
    setCurrentLayout(layout);
  }, [layout, setCurrentLayout]);

  // Handle keyboard input
  useInput((input, key) => {
    switch (layoutMode.mode) {
      case 'normal':
        handleNormalMode(input, key);
        break;
      case 'edit':
        handleEditMode(input, key);
        break;
      case 'add-widget':
        handleAddWidgetMode(input, key);
        break;
      case 'manage-layouts':
        handleManageLayoutsMode(input, key);
        break;
    }
  });

  const handleNormalMode = useCallback((input: string, key: Key) => {
    switch (input) {
      case 'q':
        onExit();
        break;
      case 'e':
        // Enter edit mode
        if (layout.widgets.length > 0) {
          setLayoutMode(prev => ({
            ...prev,
            mode: 'edit',
            selectedWidgetId: layout.widgets[0]?.id ?? null,
            selectedWidgetIndex: 0,
          }));
        }
        break;
      case 'a':
        // Add widget mode
        setLayoutMode(prev => ({ ...prev, mode: 'add-widget' }));
        break;
      case 'l':
        // Manage layouts mode
        setLayoutMode(prev => ({ ...prev, mode: 'manage-layouts' }));
        break;
      case 'r':
        // Reset layout to default
        if (key.ctrl) {
          resetToDefaultLayout();
        }
        break;
    }
  }, [layout.widgets, onExit]);

  const handleEditMode = useCallback((input: string, key: Key) => {
    const { selectedWidgetIndex } = layoutMode;
    const widgets = layout.widgets;

    switch (input) {
      case 'escape':
        // Exit edit mode
        setLayoutMode(prev => ({ ...prev, mode: 'normal', selectedWidgetId: null }));
        break;
      case 'arrowleft':
        // Select previous widget
        if (selectedWidgetIndex > 0) {
          const newIndex = selectedWidgetIndex - 1;
          setLayoutMode(prev => ({
            ...prev,
            selectedWidgetIndex: newIndex,
            selectedWidgetId: widgets[newIndex]?.id ?? null,
          }));
        }
        break;
      case 'arrowright':
        // Select next widget
        if (selectedWidgetIndex < widgets.length - 1) {
          const newIndex = selectedWidgetIndex + 1;
          setLayoutMode(prev => ({
            ...prev,
            selectedWidgetIndex: newIndex,
            selectedWidgetId: widgets[newIndex]?.id ?? null,
          }));
        }
        break;
      case 'd':
        // Delete selected widget
        if (key.ctrl && layoutMode.selectedWidgetId) {
          deleteWidget(layoutMode.selectedWidgetId);
        }
        break;
      case 'h':
        // Toggle widget visibility
        if (key.ctrl && layoutMode.selectedWidgetId) {
          toggleWidgetVisibility(layoutMode.selectedWidgetId);
        }
        break;
    }
  }, [layoutMode, layout.widgets]);

  const handleAddWidgetMode = useCallback((input: string, _key: Key) => {
    const availableTypes = WidgetRegistry.getAvailableWidgetTypes();

    switch (input) {
      case 'escape':
        setLayoutMode(prev => ({ ...prev, mode: 'normal' }));
        break;
      default: {
        // Number keys to select widget type
        const widgetIndex = parseInt(input, 10);
        if (widgetIndex >= 1 && widgetIndex <= availableTypes.length) {
          const widgetType = availableTypes[widgetIndex - 1];
          if (widgetType) {
            addWidget(widgetType.type);
          }
        }
        break;
      }
    }
  }, []);

  const handleManageLayoutsMode = useCallback((input: string, key: Key) => {
    switch (input) {
      case 'escape':
        setLayoutMode(prev => ({ ...prev, mode: 'normal' }));
        break;
      case 's':
        // Save current layout
        if (key.ctrl) {
          saveLayout();
        }
        break;
      case 'i':
        // Import layout
        if (key.ctrl) {
          importLayout();
        }
        break;
      case 'x':
        // Export layout
        if (key.ctrl) {
          exportLayout();
        }
        break;
    }
  }, []);

  const deleteWidget = useCallback((widgetId: string) => {
    const updatedLayout = {
      ...layout,
      widgets: layout.widgets.filter(w => w.id !== widgetId),
      updatedAt: new Date(),
    };
    onLayoutUpdate(updatedLayout);

    // Update selection
    const remainingWidgets = updatedLayout.widgets;
    if (remainingWidgets.length === 0) {
      setLayoutMode(prev => ({ ...prev, mode: 'normal', selectedWidgetId: null }));
    } else {
      const newSelectedIndex = Math.min(layoutMode.selectedWidgetIndex, remainingWidgets.length - 1);
      setLayoutMode(prev => ({
        ...prev,
        selectedWidgetIndex: newSelectedIndex,
        selectedWidgetId: remainingWidgets[newSelectedIndex]?.id ?? null,
      }));
    }
  }, [layout, layoutMode.selectedWidgetIndex, onLayoutUpdate]);

  const toggleWidgetVisibility = useCallback((widgetId: string) => {
    const updatedLayout = {
      ...layout,
      widgets: layout.widgets.map(widget =>
        widget.id === widgetId ? { ...widget, visible: !widget.visible } : widget
      ),
      updatedAt: new Date(),
    };
    onLayoutUpdate(updatedLayout);
  }, [layout, onLayoutUpdate]);

  const addWidget = useCallback((widgetType: string) => {
    const newWidget = WidgetRegistry.getDefaultConfig(widgetType);
    if (!newWidget) return;

    // Position new widget to avoid overlap
    const existingPositions = layout.widgets.map(w => w.position);
    const newPosition = { ...newWidget.position };

    // Simple positioning algorithm: place to the right of existing widgets
    if (existingPositions.length > 0) {
      const rightmostWidget = existingPositions.reduce((rightmost, current) => 
        current.x > rightmost.x ? current : rightmost
      );
      newPosition.x = rightmostWidget.x + rightmostWidget.width + 2;

      // Wrap to next line if too far right
      if (newPosition.x > 100) {
        newPosition.x = 0;
        const bottomWidget = existingPositions.reduce((bottom, current) =>
          current.y > bottom.y ? current : bottom
        );
        newPosition.y = bottomWidget.y + bottomWidget.height + 2;
      }
    }

    const updatedWidget = { ...newWidget, position: newPosition };
    const updatedLayout = {
      ...layout,
      widgets: [...layout.widgets, updatedWidget],
      updatedAt: new Date(),
    };
    onLayoutUpdate(updatedLayout);
    setLayoutMode(prev => ({ ...prev, mode: 'normal' }));
  }, [layout, onLayoutUpdate]);

  const resetToDefaultLayout = useCallback(() => {
    const defaultLayout = createDefaultLayout();
    onLayoutUpdate(defaultLayout);
    setLayoutMode(prev => ({ ...prev, mode: 'normal' }));
  }, [onLayoutUpdate]);

  const saveLayout = useCallback(() => {
    // This would integrate with SQLite persistence
    // TODO: Implement SQLite persistence
    setLayoutMode(prev => ({ ...prev, mode: 'normal' }));
  }, []);

  const importLayout = useCallback(() => {
    // This would handle layout import from JSON
    // TODO: Implement JSON import functionality
    setLayoutMode(prev => ({ ...prev, mode: 'normal' }));
  }, []);

  const exportLayout = useCallback(() => {
    // This would handle layout export to JSON
    // TODO: Implement JSON export functionality
    setLayoutMode(prev => ({ ...prev, mode: 'normal' }));
  }, [layout]);

  const handleWidgetUpdate = useCallback((widgetId: string, updates: Partial<WidgetConfig>) => {
    const updatedLayout = {
      ...layout,
      widgets: layout.widgets.map(widget =>
        widget.id === widgetId ? { ...widget, ...updates } : widget
      ),
      updatedAt: new Date(),
    };
    onLayoutUpdate(updatedLayout);
  }, [layout, onLayoutUpdate]);

  const renderModeSpecificContent = () => {
    switch (layoutMode.mode) {
      case 'add-widget':
        return renderAddWidgetMenu();
      case 'manage-layouts':
        return renderManageLayoutsMenu();
      default:
        return null;
    }
  };

  const renderAddWidgetMenu = () => {
    const availableTypes = WidgetRegistry.getAvailableWidgetTypes();

    return (
      <Box
        borderStyle="double"
        borderColor="cyan"
        flexDirection="column"
        paddingX={1}
        marginX={10}
        marginTop={5}
        marginBottom={5}
      >
        <Box marginBottom={1}>
          <Text bold color="cyan">Add Widget</Text>
        </Box>
        <Text color="gray">Select widget type to add:</Text>
        <Box marginTop={1}>
          {availableTypes.map((type, index) => (
            <Box key={type.type}>
              <Text color="yellow">{index + 1}.</Text>
              <Text> {type.name} - {type.description}</Text>
            </Box>
          ))}
        </Box>
        <Box marginTop={1}>
          <Text color="gray" dimColor>Press 1-{availableTypes.length} to select, Escape to cancel</Text>
        </Box>
      </Box>
    );
  };

  const renderManageLayoutsMenu = () => {
    return (
      <Box
        borderStyle="double"
        borderColor="magenta"
        flexDirection="column"
        paddingX={1}
        marginX={10}
        marginTop={5}
        marginBottom={5}
      >
        <Box marginBottom={1}>
          <Text bold color="magenta">Manage Layouts</Text>
        </Box>
        <Text>Ctrl+S: Save current layout</Text>
        <Text>Ctrl+I: Import layout from JSON</Text>
        <Text>Ctrl+X: Export layout to JSON</Text>
        <Box marginTop={1}>
          <Text color="gray" dimColor>Escape to cancel</Text>
        </Box>
      </Box>
    );
  };

  return (
    <Box flexDirection="column" width="100%" height="100%">
      {/* Header */}
      <Box marginBottom={1}>
        <Box justifyContent="space-between" width="100%">
          <Text bold color="blue">
            Layout: {layout.name} ({layoutMode.mode})
          </Text>
          <Text color="gray">
            Widgets: {layout.widgets.length} | Mode: {layoutMode.mode}
          </Text>
        </Box>
      </Box>

      {/* Widget Area */}
      <Box flexGrow={1} flexDirection="column">
        {layout.widgets.map((widget, _index) => {
          const widgetElement = WidgetRegistry.createWidget(
            widget,
            widget.id === layoutMode.selectedWidgetId,
            (widgetId: string) => {
              setLayoutMode(prev => ({
                ...prev,
                selectedWidgetId: widgetId,
                selectedWidgetIndex: layout.widgets.findIndex(w => w.id === widgetId),
              }));
            },
            handleWidgetUpdate
          );
          return widgetElement;
        })}
      </Box>

      {/* Mode-specific overlays */}
      {renderModeSpecificContent()}

      {/* Footer */}
      <Box marginTop={1}>
        <Box justifyContent="space-between" width="100%">
          <Text color="gray" dimColor>
            {layoutMode.mode === 'normal' && 'E:Edit A:Add L:Manage Ctrl+R:Reset Q:Quit'}
            {layoutMode.mode === 'edit' && '←→:Select Ctrl+D:Delete Ctrl+H:Hide Esc:Exit'}
            {layoutMode.mode === 'add-widget' && '1-9:Select Widget Esc:Cancel'}
            {layoutMode.mode === 'manage-layouts' && 'Ctrl+S:Save Ctrl+I:Import Ctrl+X:Export Esc:Cancel'}
          </Text>
        </Box>
      </Box>
    </Box>
  );
}

// Helper function to create default layout
function createDefaultLayout(): DashboardLayoutType {
  const summaryWidget = WidgetRegistry.getDefaultConfig('summary', {
    id: 'summary-default',
    position: { x: 0, y: 0, width: 50, height: 12 },
  });

  const issuesWidget = WidgetRegistry.getDefaultConfig('issues', {
    id: 'issues-default',
    position: { x: 55, y: 0, width: 45, height: 15 },
  });

  const coverageWidget = WidgetRegistry.getDefaultConfig('coverage', {
    id: 'coverage-default',
    position: { x: 0, y: 14, width: 45, height: 10 },
  });

  const trendsWidget = WidgetRegistry.getDefaultConfig('trends', {
    id: 'trends-default',
    position: { x: 50, y: 17, width: 50, height: 10 },
  });

  return {
    id: 'default-layout',
    name: 'Default Layout',
    description: 'Default dashboard layout with all widgets',
    isPreset: true,
    widgets: [summaryWidget, issuesWidget, coverageWidget, trendsWidget].filter(Boolean) as WidgetConfig[],
    createdAt: new Date(),
    updatedAt: new Date(),
  };
}

/**
 * Dashboard Navigator Component
 * Handles drill-down navigation between different dashboard views
 */

import React from 'react';
import { Box, Text, useInput } from 'ink';
import type { DashboardView, NavigationBreadcrumb } from '../../types/dashboard';
import type { Issue } from '../../types/analysis';

interface NavigatorState {
  view: DashboardView;
  context: {
    selectedIssue?: Issue;
    selectedFile?: string;
    selectedModule?: string;
  };
  depth: number;
}

interface DashboardNavigatorProps {
  currentView: DashboardView;
  onNavigate: (view: DashboardView, context?: Record<string, unknown>) => void;
  onGoBack?: () => void;
  _availableViews?: DashboardView[];
}

const VIEW_DESCRIPTIONS: Record<DashboardView, string> = {
  dashboard: 'Dashboard Overview',
  'issue-list': 'All Issues',
  'issue-details': 'Issue Details',
  comparison: 'Run Comparison',
  trends: 'Trend Analysis',
  'layout-customization': 'Layout Settings',
};

const createBreadcrumb = (
  view: DashboardView,
  label: string,
  data?: Record<string, unknown>
): NavigationBreadcrumb => ({
  id: `${view}-${Date.now()}`,
  label,
  view,
  data,
});

export const DashboardNavigator: React.FC<DashboardNavigatorProps> = ({
  currentView,
  onNavigate,
  onGoBack,
  _availableViews = [
    'dashboard',
    'issue-list',
    'issue-details',
    'comparison',
    'trends',
    'layout-customization',
  ],
}) => {
  const [navigationHistory, setNavigationHistory] = React.useState<NavigatorState[]>([]);
  const [navigationIndex, setNavigationIndex] = React.useState(0);

  // Create breadcrumbs from navigation history
  const breadcrumbs: NavigationBreadcrumb[] = React.useMemo(() => {
    const crumbs: NavigationBreadcrumb[] = [];

    // Add current view
    crumbs.push(createBreadcrumb(currentView, VIEW_DESCRIPTIONS[currentView]));

    // Add context-specific breadcrumbs
    if (navigationHistory.length > 0) {
      const currentState = navigationHistory[navigationIndex];
      if (currentState) {
        if (currentState.context.selectedFile) {
          const fileName = currentState.context.selectedFile.split('/').pop() ?? 'Unknown File';
          crumbs.push(
            createBreadcrumb('issue-list', `File: ${fileName}`, {
              filePath: currentState.context.selectedFile,
            })
          );
        }

        if (currentState.context.selectedIssue) {
          crumbs.push(
            createBreadcrumb(
              'issue-details',
              `Issue: ${currentState.context.selectedIssue.message.slice(0, 30)}...`,
              {
                issueId: currentState.context.selectedIssue.id,
              }
            )
          );
        }

        if (currentState.context.selectedModule) {
          crumbs.push(
            createBreadcrumb('issue-list', `Module: ${currentState.context.selectedModule}`, {
              module: currentState.context.selectedModule,
            })
          );
        }
      }
    }

    return crumbs;
  }, [currentView, navigationHistory, navigationIndex]);

  const handleNavigate = (view: DashboardView, context?: Record<string, unknown>) => {
    const newState: NavigatorState = {
      view,
      context: context ?? {},
      depth: navigationHistory.length + 1,
    };

    // Update navigation history
    const newHistory = navigationHistory.slice(0, navigationIndex + 1);
    newHistory.push(newState);
    setNavigationHistory(newHistory);
    setNavigationIndex(newHistory.length - 1);

    onNavigate(view, context);
  };

  const handleGoBack = () => {
    if (navigationIndex > 0) {
      const previousIndex = navigationIndex - 1;
      const previousState = navigationHistory[previousIndex];
      if (previousState) {
        setNavigationIndex(previousIndex);
        onNavigate(previousState.view, previousState.context);
      }
    } else {
      onGoBack?.();
    }
  };

  // Keyboard navigation
  useInput((input, key) => {
    // Back navigation
    if (key.escape) {
      handleGoBack();
    }

    // Quick navigation shortcuts
    if (input) {
      switch (input) {
        case '\u0004': // Ctrl+D
          handleNavigate('dashboard');
          break;
        case '\u0009': // Ctrl+I
          handleNavigate('issue-list');
          break;
        case '\u0003': // Ctrl+C
          handleNavigate('comparison');
          break;
        case '\u0014': // Ctrl+T
          handleNavigate('trends');
          break;
      }
    }
  });

  const canGoBack = navigationIndex > 0 || (currentView !== 'dashboard' && onGoBack);

  return (
    <Box flexDirection="column" marginBottom={1}>
      <Box flexDirection="row" alignItems="center" marginBottom={1}>
        <Text bold color="blue">
          Navigator
        </Text>
        <Text color="gray"> | </Text>
        <Text>Current: </Text>
        <Text color="cyan" bold>
          {VIEW_DESCRIPTIONS[currentView]}
        </Text>
        {canGoBack && (
          <>
            <Text color="gray"> | </Text>
            <Text color="yellow">[Esc] Back</Text>
          </>
        )}
      </Box>

      {/* Quick navigation shortcuts */}
      <Box flexDirection="row" marginBottom={1}>
        <Text color="gray">Quick Nav: </Text>
        <Text color="blue">[Ctrl+D]</Text>
        <Text color="gray"> Dashboard</Text>
        <Text color="gray"> | </Text>
        <Text color="blue">[Ctrl+I]</Text>
        <Text color="gray"> Issues</Text>
        <Text color="gray"> | </Text>
        <Text color="blue">[Ctrl+C]</Text>
        <Text color="gray"> Compare</Text>
        <Text color="gray"> | </Text>
        <Text color="blue">[Ctrl+T]</Text>
        <Text color="gray"> Trends</Text>
      </Box>

      {/* Breadcrumb navigation */}
      <Box flexDirection="row" alignItems="center">
        <Text color="gray">Path:</Text>
        <Box marginLeft={1}>
          {breadcrumbs.length > 1 ? (
            <Text>
              {breadcrumbs.map((crumb, index) => (
                <Text key={crumb.id}>
                  {index > 0 && <Text color="gray"> › </Text>}
                  <Text color={index === breadcrumbs.length - 1 ? 'cyan' : 'blue'}>
                    {crumb.label}
                  </Text>
                </Text>
              ))}
            </Text>
          ) : (
            <Text color="gray">Root</Text>
          )}
        </Box>
      </Box>

      {/* Navigation info */}
      {navigationHistory.length > 0 && (
        <Box flexDirection="row" marginTop={1}>
          <Text color="gray">
            Navigation depth: {navigationHistory.length} | Position: {navigationIndex + 1}/
            {navigationHistory.length}
          </Text>
        </Box>
      )}
    </Box>
  );
};

export default DashboardNavigator;

/**
 * Main dashboard component
 */

import React, { useEffect, useCallback } from 'react';
import { Box, Text, useInput, useApp } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { MetricsSummary } from './metrics-summary';
import { IssueList } from './issue-list';
import { IssueDetails } from './issue-details';
import { FilterBar } from './filters';
import { FilterMenu } from './filter-menu';
import { ExportMenu } from './export-menu';
import { AnalysisProgress } from '../progress/analysis-progress';
import {
  createKeyboardHandler as _createKeyboardHandler,
  defaultKeyboardShortcuts as _defaultKeyboardShortcuts,
} from '../../utils/keyboard-navigation';
import type { DashboardView as _DashboardView } from '../../types/dashboard';

interface DashboardProps {
  analysisResult: import('../../types').AnalysisResult;
}

export function Dashboard({ analysisResult }: DashboardProps): React.ReactElement {
  const { exit } = useApp();
  const {
    currentView,
    filteredIssues,
    selectedIssue: _selectedIssue,
    isAnalyzing,
    analysisProgress,
    ui: { isFilterMenuOpen, isExportMenuOpen },
    setAnalysisResult,
    setCurrentView,
    setSelectedIssue,
    setAnalyzing: _setAnalyzing,
  } = useDashboardStore();

  // Initialize dashboard with analysis result
  useEffect(() => {
    setAnalysisResult(analysisResult);
  }, [analysisResult, setAnalysisResult]);

  // Handle keyboard input
  const handleNavigation = useCallback(
    (direction: string) => {
      const { selectedIndex: _selectedIndex } = useDashboardStore.getState().navigation;

      switch (direction) {
        case 'escape':
          if (currentView === 'issue-details') {
            setCurrentView('dashboard');
            setSelectedIssue(null);
          } else if (currentView === 'dashboard' || currentView === 'issue-list') {
            exit();
          }
          break;
        case 'q':
          exit();
          break;
        case 'f': {
          // Toggle filters
          const { toggleFilterMenu } = useDashboardStore.getState();
          toggleFilterMenu();
          break;
        }
        case 'e': {
          // Toggle export
          const { toggleExportMenu } = useDashboardStore.getState();
          toggleExportMenu();
          break;
        }
      }
    },
    [currentView, exit, setCurrentView, setSelectedIssue]
  );

  useInput((input, key) => {
    if (key.escape) {
      handleNavigation('escape');
    } else if (input === 'q') {
      handleNavigation('q');
    } else if (input === 'f' && !isFilterMenuOpen && !isExportMenuOpen) {
      handleNavigation('f');
    } else if (input === 'e' && !isFilterMenuOpen && !isExportMenuOpen) {
      handleNavigation('e');
    }
  });

  const renderCurrentView = () => {
    switch (currentView) {
      case 'issue-details':
        return <IssueDetails />;
      case 'issue-list':
        return <IssueList />;
      case 'dashboard':
      default:
        return (
          <>
            <MetricsSummary />
            <Box marginBottom={1}>
              <FilterBar />
            </Box>
            <IssueList />
          </>
        );
    }
  };

  return (
    <Box flexDirection="column" padding={1}>
      {/* Header */}
      <Box marginBottom={1}>
        <Box justifyContent="space-between" width="100%">
          <Text bold color="blue">
            DevQuality Dashboard
          </Text>
          <Text color="gray">
            {analysisResult.projectId} - Score: {analysisResult.overallScore}
          </Text>
        </Box>
      </Box>

      {/* Analysis Progress */}
      {isAnalyzing && analysisProgress && (
        <Box marginBottom={1}>
          <AnalysisProgress progress={analysisProgress} />
        </Box>
      )}

      {/* Filter Menu Overlay */}
      {isFilterMenuOpen && (
        <Box marginBottom={1}>
          <FilterMenu
            isOpen={isFilterMenuOpen}
            onClose={() => {
              const { toggleFilterMenu } = useDashboardStore.getState();
              toggleFilterMenu();
            }}
          />
        </Box>
      )}

      {/* Export Menu Overlay */}
      {isExportMenuOpen && (
        <Box marginBottom={1}>
          <ExportMenu
            isOpen={isExportMenuOpen}
            onClose={() => {
              const { toggleExportMenu } = useDashboardStore.getState();
              toggleExportMenu();
            }}
          />
        </Box>
      )}

      {/* Main Content */}
      <Box flexGrow={1}>{renderCurrentView()}</Box>

      {/* Footer */}
      <Box marginTop={1}>
        <Box justifyContent="space-between" width="100%">
          <Text color="gray" dimColor>
            Issues: {filteredIssues.length} | View: {currentView}
          </Text>
          <Text color="gray" dimColor>
            Press 'q' to quit, 'f' for filters, 'e' for export
          </Text>
        </Box>
      </Box>
    </Box>
  );
}

/**
 * Export menu component
 */

import React, { useState } from 'react';
import { Box, Text, useInput } from 'ink';
import { useExport } from '../../hooks/useExport';
import { useMenuNavigation } from '../../hooks/useNavigation';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import type { ExportFormat } from '../../types/export';

interface ExportMenuProps {
  isOpen: boolean;
  onClose: () => void;
}

export function ExportMenu({ isOpen, onClose }: ExportMenuProps): React.ReactElement | null {
  if (!isOpen) return null;

  const {
    supportedFormats,
    exportResults,
    isExporting,
    exportProgress,
    exportError,
    resetExportState,
  } = useExport();
  const { toggleExportMenu } = useDashboardStore();
  const [selectedFormat, setSelectedFormat] = useState<ExportFormat | null>(null);
  const [includeSummary, setIncludeSummary] = useState(true);
  const [includeIssues, setIncludeIssues] = useState(true);
  const [includeMetrics, setIncludeMetrics] = useState(true);
  const [includeFixed, setIncludeFixed] = useState(false);

  // Calculate total menu items
  const formatItems = supportedFormats.length;
  const optionItems = 4; // summary, issues, metrics, fixed
  const actionItems = 2; // export, cancel
  const totalItems = formatItems + optionItems + actionItems;

  const { selectedIndex } = useMenuNavigation(
    totalItems,
    index => handleMenuAction(index),
    onClose,
    isOpen
  );

  const handleMenuAction = async (index: number) => {
    let currentOffset = 0;

    // Check if it's a format item
    if (index < formatItems) {
      const format = supportedFormats[index];
      setSelectedFormat(format ?? null);
      return;
    }
    currentOffset += formatItems;

    // Check if it's an option item
    if (index < currentOffset + optionItems) {
      const optionIndex = index - currentOffset;
      switch (optionIndex) {
        case 0:
          setIncludeSummary(!includeSummary);
          break;
        case 1:
          setIncludeIssues(!includeIssues);
          break;
        case 2:
          setIncludeMetrics(!includeMetrics);
          break;
        case 3:
          setIncludeFixed(!includeFixed);
          break;
      }
      return;
    }
    currentOffset += optionItems;

    // Check if it's an action item
    if (index < currentOffset + actionItems) {
      const actionIndex = index - currentOffset;
      if (actionIndex === 0) {
        // Export action
        if (selectedFormat) {
          await performExport(selectedFormat);
        }
      } else if (actionIndex === 1) {
        // Cancel action
        resetExportState();
        onClose();
        toggleExportMenu();
      }
      return;
    }
  };

  const performExport = async (format: ExportFormat) => {
    const result = await exportResults(format.id, {
      includeSummary,
      includeIssues,
      includeMetrics,
      includeFixed,
    });

    if (result.success) {
      // Auto-close on success
      setTimeout(() => {
        onClose();
        toggleExportMenu();
        resetExportState();
      }, 2000);
    }
  };

  // Handle keyboard input
  useInput((input, key) => {
    if (key.escape && !isExporting) {
      resetExportState();
      onClose();
      toggleExportMenu();
    }
  });

  // Render format section
  const renderFormatSection = () => (
    <Box flexDirection="column" marginBottom={1}>
      <Box marginBottom={1}>
        <Text bold color="cyan">
          Export Format
        </Text>
      </Box>
      {supportedFormats.map((format, index) => {
        const isSelected = selectedFormat?.id === format.id;
        const isHighlighted = index === selectedIndex;

        return (
          <Box key={format.id} marginLeft={1}>
            <Text color={isHighlighted ? 'white' : 'gray'}>[{isSelected ? '✓' : ' '}]</Text>
            <Text color={isHighlighted ? 'white' : 'reset'}>
              {' '}
              {format.name} (.{format.extension})
            </Text>
            <Text color="gray" dimColor>
              {' '}
              - {format.description}
            </Text>
          </Box>
        );
      })}
    </Box>
  );

  // Render options section
  const renderOptionsSection = () => {
    const optionStartIndex = supportedFormats.length;

    return (
      <Box flexDirection="column" marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold color="cyan">
            Export Options
          </Text>
        </Box>

        <Box marginLeft={1}>
          <Text color={optionStartIndex === selectedIndex ? 'white' : 'gray'}>
            [{optionStartIndex === selectedIndex ? '>' : ' '}]
          </Text>
          <Text color={optionStartIndex === selectedIndex ? 'white' : 'reset'}>
            {' '}
            [{includeSummary ? '✓' : ' '}] Include summary
          </Text>
        </Box>

        <Box marginLeft={1}>
          <Text color={optionStartIndex + 1 === selectedIndex ? 'white' : 'gray'}>
            [{optionStartIndex + 1 === selectedIndex ? '>' : ' '}]
          </Text>
          <Text color={optionStartIndex + 1 === selectedIndex ? 'white' : 'reset'}>
            {' '}
            [{includeIssues ? '✓' : ' '}] Include issues
          </Text>
        </Box>

        <Box marginLeft={1}>
          <Text color={optionStartIndex + 2 === selectedIndex ? 'white' : 'gray'}>
            [{optionStartIndex + 2 === selectedIndex ? '>' : ' '}]
          </Text>
          <Text color={optionStartIndex + 2 === selectedIndex ? 'white' : 'reset'}>
            {' '}
            [{includeMetrics ? '✓' : ' '}] Include metrics
          </Text>
        </Box>

        <Box marginLeft={1}>
          <Text color={optionStartIndex + 3 === selectedIndex ? 'white' : 'gray'}>
            [{optionStartIndex + 3 === selectedIndex ? '>' : ' '}]
          </Text>
          <Text color={optionStartIndex + 3 === selectedIndex ? 'white' : 'reset'}>
            {' '}
            [{includeFixed ? '✓' : ' '}] Include fixed issues
          </Text>
        </Box>
      </Box>
    );
  };

  // Render actions section
  const renderActionsSection = () => {
    const actionStartIndex = supportedFormats.length + 4;
    const exportIndex = actionStartIndex;
    const cancelIndex = actionStartIndex + 1;

    return (
      <Box flexDirection="column" marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold color="cyan">
            Actions
          </Text>
        </Box>

        <Box marginLeft={1}>
          <Text color={exportIndex === selectedIndex ? 'white' : 'gray'}>
            [{exportIndex === selectedIndex ? '>' : ' '}]
          </Text>
          <Text color={exportIndex === selectedIndex ? 'white' : selectedFormat ? 'green' : 'gray'}>
            {' '}
            Export {selectedFormat ? `as ${selectedFormat.name}` : '(select format first)'}
          </Text>
        </Box>

        <Box marginLeft={1}>
          <Text color={cancelIndex === selectedIndex ? 'white' : 'gray'}>
            [{cancelIndex === selectedIndex ? '>' : ' '}]
          </Text>
          <Text color={cancelIndex === selectedIndex ? 'white' : 'red'}> Cancel</Text>
        </Box>
      </Box>
    );
  };

  // Render progress
  const renderProgress = () => {
    if (!isExporting || !exportProgress) return null;

    return (
      <Box
        flexDirection="column"
        marginBottom={1}
        padding={1}
        borderStyle="single"
        borderColor="blue"
      >
        <Box marginBottom={1}>
          <Text bold color="blue">
            Exporting...
          </Text>
        </Box>
        <Box marginBottom={1}>
          <Text>{exportProgress.currentStep}</Text>
        </Box>
        <Box>
          <Text>Progress: {exportProgress.percentage}%</Text>
          {exportProgress.bytesWritten && (
            <Text> Size: {(exportProgress.bytesWritten / 1024).toFixed(1)}KB</Text>
          )}
        </Box>
      </Box>
    );
  };

  // Render result
  const renderResult = () => {
    if (!exportProgress || exportProgress.percentage < 100) return null;

    return (
      <Box
        flexDirection="column"
        marginBottom={1}
        padding={1}
        borderStyle="single"
        borderColor={exportError ? 'red' : 'green'}
      >
        {exportError ? (
          <>
            <Box marginBottom={1}>
              <Text bold color="red">
                Export Failed
              </Text>
            </Box>
            <Text color="red">{exportError}</Text>
          </>
        ) : (
          <>
            <Box marginBottom={1}>
              <Text bold color="green">
                Export Complete
              </Text>
            </Box>
            <Text color="green">Report saved successfully!</Text>
          </>
        )}
      </Box>
    );
  };

  return (
    <Box flexDirection="column" borderStyle="double" borderColor="blue" padding={1}>
      <Box marginBottom={1}>
        <Text bold color="blue">
          Export Options
        </Text>
      </Box>

      {renderFormatSection()}
      {renderOptionsSection()}
      {renderActionsSection()}
      {renderProgress()}
      {renderResult()}

      <Box marginTop={1}>
        <Text color="gray" dimColor>
          ↑↓ Navigate | Space: Toggle | Enter: Select | Esc: Close
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Filter Indicators Component
 * Shows active filters as removable badges
 */

import React from 'react';
import { Box, Text } from 'ink';
import { useFilterStore } from '../../hooks/useFilterStore';

interface FilterIndicatorsProps {
  onClearFilter: (filterType: string, value?: string) => void;
  onClearAll: () => void;
}

export const FilterIndicators: React.FC<FilterIndicatorsProps> = ({
  onClearFilter: _onClearFilter,
  onClearAll: _onClearAll,
}) => {
  const { filters, search } = useFilterStore();

  const getActiveFilters = () => {
    const activeFilters: Array<{
      type: string;
      value: string;
      display: string;
      color?: string;
    }> = [];

    // Severity filters
    if (filters.severity?.length) {
      filters.severity.forEach(severity => {
        activeFilters.push({
          type: 'severity',
          value: severity,
          display: `Severity: ${severity}`,
          color: getSeverityColor(severity),
        });
      });
    }

    // Tool filters
    if (filters.tools?.length) {
      filters.tools.forEach(tool => {
        activeFilters.push({
          type: 'tool',
          value: tool,
          display: `Tool: ${tool}`,
          color: 'blue',
        });
      });
    }

    // Priority filters
    if (filters.priority?.length) {
      filters.priority.forEach(priority => {
        activeFilters.push({
          type: 'priority',
          value: priority,
          display: `Priority: ${priority}`,
          color: getPriorityColor(priority),
        });
      });
    }

    // File filters
    if (filters.files?.length) {
      filters.files.forEach(file => {
        activeFilters.push({
          type: 'file',
          value: file,
          display: `File: ${file}`,
          color: 'cyan',
        });
      });
    }

    // Module filters
    if (filters.modules?.length) {
      filters.modules.forEach(module => {
        activeFilters.push({
          type: 'module',
          value: module,
          display: `Module: ${module}`,
          color: 'magenta',
        });
      });
    }

    // Score range filter
    if (filters.scoreRange && (filters.scoreRange[0] > 1 || filters.scoreRange[1] < 10)) {
      activeFilters.push({
        type: 'scoreRange',
        value: `${filters.scoreRange[0]}-${filters.scoreRange[1]}`,
        display: `Score: ${filters.scoreRange[0]}-${filters.scoreRange[1]}`,
        color: 'yellow',
      });
    }

    // Fixable filter
    if (filters.hasFix !== undefined) {
      activeFilters.push({
        type: 'hasFix',
        value: filters.hasFix.toString(),
        display: filters.hasFix ? 'Fixable only' : 'Not fixable',
        color: filters.hasFix ? 'green' : 'red',
      });
    }

    // Search query
    if (search.query.trim()) {
      activeFilters.push({
        type: 'search',
        value: search.query,
        display: `Search: "${search.query}"`,
        color: 'green',
      });
    }

    return activeFilters;
  };

  const activeFilters = getActiveFilters();

  if (activeFilters.length === 0) {
    return (
      <Box flexDirection="row" alignItems="center">
        <Text color="gray">No active filters</Text>
        <Box paddingLeft={1}>
          <Text color="gray">Press [Ctrl+F] to add filters</Text>
        </Box>
      </Box>
    );
  }

  return (
    <Box flexDirection="column">
      {/* Filter count */}
      <Box flexDirection="row" alignItems="center" marginBottom={1}>
        <Text color="blue" bold>
          Active Filters ({activeFilters.length}):
        </Text>
        <Box paddingLeft={2}>
          <Text color="red" backgroundColor="gray">
            [Clear All]
          </Text>
        </Box>
        <Box paddingLeft={1}>
          <Text color="gray">Press [Ctrl+F] to modify</Text>
        </Box>
      </Box>

      {/* Filter badges */}
      <Box flexDirection="row" flexWrap="wrap">
        {activeFilters.map((filter, index) => (
          <Box
            key={`${filter.type}-${filter.value}-${index}`}
            flexDirection="row"
            alignItems="center"
            marginRight={1}
            marginBottom={1}
            paddingX={1}
            backgroundColor={filter.color ?? 'gray'}
          >
            <Text color="white" dimColor>
              {filter.display}
            </Text>
            <Box paddingLeft={1}>
              <Text color="white" bold>
                ×
              </Text>
            </Box>
          </Box>
        ))}
      </Box>

      {/* Filter summary */}
      <Box flexDirection="row" marginTop={1}>
        <Text color="gray" dimColor>
          {activeFilters.length === 1
            ? '1 filter applied'
            : `${activeFilters.length} filters applied`}
        </Text>
      </Box>
    </Box>
  );
};

/**
 * Helper functions for colors
 */
function getSeverityColor(severity: string): string {
  switch (severity.toLowerCase()) {
    case 'error':
      return 'red';
    case 'warning':
      return 'yellow';
    case 'info':
      return 'blue';
    default:
      return 'gray';
  }
}

function getPriorityColor(priority: string): string {
  switch (priority.toLowerCase()) {
    case 'critical':
      return 'red';
    case 'high':
      return 'orange';
    case 'medium':
      return 'yellow';
    case 'low':
      return 'green';
    default:
      return 'gray';
  }
}

export default FilterIndicators;

/**
 * Filter menu component
 */

import React, { useState } from 'react';
import { Box, Text, useInput } from 'ink';
import { useFilters } from '../../hooks/useFilters';
import { useMenuNavigation } from '../../hooks/useNavigation';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { getSeverityColor, getSeveritySymbol } from '../../utils/color-coding';
import type { IssueSeverity as _IssueSeverity } from '../../types/dashboard';

interface FilterMenuProps {
  isOpen: boolean;
  onClose: () => void;
}

export function FilterMenu({ isOpen, onClose }: FilterMenuProps): React.ReactElement | null {
  if (!isOpen) return null;

  const {
    filters,
    availableSeverities,
    availableTools,
    toggleSeverity,
    toggleTool,
    toggleFixable,
    setSearchQuery,
    clearAllFilters,
  } = useFilters();

  const { toggleFilterMenu } = useDashboardStore();
  const [searchQuery, setSearchQueryState] = useState(filters.searchQuery);
  const [currentSection, setCurrentSection] = useState<'severity' | 'tools' | 'fixable' | 'search'>(
    'severity'
  );

  // Calculate total menu items
  const severityItems = availableSeverities.length;
  const toolItems = Math.min(availableTools.length, 10); // Limit to first 10 tools
  const fixableItems = 1;
  const searchItems = 1;
  const actionItems = 2; // Clear filters, Apply filters
  const totalItems = severityItems + toolItems + fixableItems + searchItems + actionItems;

  const { selectedIndex } = useMenuNavigation(
    totalItems,
    index => handleMenuAction(index),
    onClose,
    isOpen
  );

  const handleMenuAction = (index: number) => {
    let currentOffset = 0;

    // Check if it's a severity item
    if (index < severityItems) {
      const severity = availableSeverities[index];
      if (severity) {
        toggleSeverity(severity);
      }
      return;
    }
    currentOffset += severityItems;

    // Check if it's a tool item
    if (index < currentOffset + toolItems) {
      const toolIndex = index - currentOffset;
      if (toolIndex < availableTools.length) {
        const tool = availableTools[toolIndex];
        if (tool) {
          toggleTool(tool);
        }
      }
      return;
    }
    currentOffset += toolItems;

    // Check if it's the fixable item
    if (index < currentOffset + fixableItems) {
      toggleFixable();
      return;
    }
    currentOffset += fixableItems;

    // Check if it's the search item
    if (index < currentOffset + searchItems) {
      setCurrentSection('search');
      return;
    }
    currentOffset += searchItems;

    // Check if it's an action item
    if (index < currentOffset + actionItems) {
      const actionIndex = index - currentOffset;
      if (actionIndex === 0) {
        clearAllFilters();
        setSearchQueryState('');
      } else if (actionIndex === 1) {
        setSearchQuery(searchQuery);
        onClose();
        toggleFilterMenu();
      }
      return;
    }
  };

  // Handle search input
  useInput((input, key) => {
    if (currentSection === 'search' && isOpen) {
      if (key.return) {
        setSearchQuery(searchQuery);
        setCurrentSection('severity');
        return;
      } else if (key.escape) {
        setSearchQueryState(filters.searchQuery);
        setCurrentSection('severity');
        return;
      } else if (key.backspace || key.delete) {
        setSearchQueryState(prev => prev.slice(0, -1));
        return;
      } else if (input && !key.ctrl && !key.meta) {
        setSearchQueryState(prev => prev + input);
        return;
      }
    }
  });

  // Render severity section
  const renderSeveritySection = () => (
    <Box flexDirection="column" marginBottom={1}>
      <Box marginBottom={1}>
        <Text bold color="cyan">
          Severity Filter
        </Text>
      </Box>
      {availableSeverities.map((severity, index) => {
        const isSelected = filters.severity.includes(severity);
        const isHighlighted = currentSection === 'severity' && index === selectedIndex;

        return (
          <Box key={severity} marginLeft={1}>
            <Text color={isHighlighted ? 'white' : 'gray'}>[{isSelected ? '✓' : ' '}]</Text>
            <Text color={getSeverityColor(severity)}> {getSeveritySymbol(severity)}</Text>
            <Text color={isHighlighted ? 'white' : 'reset'}>
              {' '}
              {severity.charAt(0).toUpperCase() + severity.slice(1)}
            </Text>
          </Box>
        );
      })}
    </Box>
  );

  // Render tools section
  const renderToolsSection = () => (
    <Box flexDirection="column" marginBottom={1}>
      <Box marginBottom={1}>
        <Text bold color="cyan">
          Tools Filter
        </Text>
        <Text color="gray" dimColor>
          {' '}
          (showing first {Math.min(availableTools.length, 10)} of {availableTools.length})
        </Text>
      </Box>
      {availableTools.slice(0, 10).map((tool, index) => {
        const isSelected = filters.tools.includes(tool);
        const _itemIndex = availableSeverities.length + index;
        const isHighlighted =
          currentSection === 'tools' && index === selectedIndex - availableSeverities.length;

        return (
          <Box key={tool} marginLeft={1}>
            <Text color={isHighlighted ? 'white' : 'gray'}>[{isSelected ? '✓' : ' '}]</Text>
            <Text color={isHighlighted ? 'white' : 'reset'}> {tool}</Text>
          </Box>
        );
      })}
    </Box>
  );

  // Render fixable section
  const renderFixableSection = () => {
    const fixableIndex = availableSeverities.length + Math.min(availableTools.length, 10);
    const isHighlighted = currentSection === 'fixable' && selectedIndex === fixableIndex;

    return (
      <Box flexDirection="column" marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold color="cyan">
            Fixable Filter
          </Text>
        </Box>
        <Box marginLeft={1}>
          <Text color={isHighlighted ? 'white' : 'gray'}>
            [{filters.fixable === true ? '✓' : filters.fixable === false ? '✗' : ' '}]
          </Text>
          <Text color={isHighlighted ? 'white' : 'reset'}>
            {' '}
            {filters.fixable === true
              ? 'Fixable only'
              : filters.fixable === false
                ? 'Non-fixable only'
                : 'All issues'}
          </Text>
        </Box>
      </Box>
    );
  };

  // Render search section
  const renderSearchSection = () => {
    const searchIndex = availableSeverities.length + Math.min(availableTools.length, 10) + 1;
    const isHighlighted = currentSection === 'search' && selectedIndex === searchIndex;

    return (
      <Box flexDirection="column" marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold color="cyan">
            Search Filter
          </Text>
        </Box>
        <Box marginLeft={1}>
          <Text color={(isHighlighted ?? currentSection === 'search') ? 'white' : 'gray'}>
            [{currentSection === 'search' ? '>' : ' '}]
          </Text>
          <Text color={currentSection === 'search' ? 'white' : 'reset'}>
            {' '}
            {searchQuery ?? '(type to search...)'}
          </Text>
          {currentSection === 'search' && (
            <Text color="gray" dimColor>
              {' '}
              [Enter to apply, Esc to cancel]
            </Text>
          )}
        </Box>
      </Box>
    );
  };

  // Render actions section
  const renderActionsSection = () => {
    const actionStartIndex = availableSeverities.length + Math.min(availableTools.length, 10) + 2;
    const clearIndex = actionStartIndex;
    const applyIndex = actionStartIndex + 1;

    return (
      <Box flexDirection="column" marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold color="cyan">
            Actions
          </Text>
        </Box>
        <Box marginLeft={1}>
          <Text color={selectedIndex === clearIndex ? 'white' : 'gray'}>
            [{selectedIndex === clearIndex ? '>' : ' '}]
          </Text>
          <Text color={selectedIndex === clearIndex ? 'white' : 'reset'}> Clear all filters</Text>
        </Box>
        <Box marginLeft={1}>
          <Text color={selectedIndex === applyIndex ? 'white' : 'gray'}>
            [{selectedIndex === applyIndex ? '>' : ' '}]
          </Text>
          <Text color={selectedIndex === applyIndex ? 'white' : 'green'}> Apply filters</Text>
        </Box>
      </Box>
    );
  };

  return (
    <Box flexDirection="column" borderStyle="double" borderColor="blue" padding={1}>
      <Box marginBottom={1}>
        <Text bold color="blue">
          Filter Options
        </Text>
      </Box>

      {renderSeveritySection()}
      {renderToolsSection()}
      {renderFixableSection()}
      {renderSearchSection()}
      {renderActionsSection()}

      <Box marginTop={1}>
        <Text color="gray" dimColor>
          ↑↓ Navigate | Space: Toggle | Enter: Select | Esc: Close
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Filter Panel Component
 * Multi-criteria filtering interface for dashboard issues
 */

import React, { useState, useMemo } from 'react';
import { Box, Text, useInput } from 'ink';
import { useFilterStore, type FilterCriteria, type FilterPreset } from '../../hooks/useFilterStore';
import { MultiSelect } from './multi-select';
import { RangeSlider } from './range-slider';

interface FilterPanelProps {
  availableSeverities: string[];
  availableTools: string[];
  availableFiles: string[];
  availableModules: string[];
  onApply: () => void;
  onReset: () => void;
}

export const FilterPanel: React.FC<FilterPanelProps> = ({
  availableSeverities,
  availableTools,
  availableFiles: _availableFiles,
  availableModules: _availableModules,
  onApply: _onApply,
  onReset: _onReset,
}) => {
  const {
    filters,
    search,
    presets,
    currentPresetId,
    setFilters,
    setSearch,
    loadPreset,
    savePreset,
    deletePreset,
    setDefaultPreset,
  } = useFilterStore();

  const [activeTab, setActiveTab] = useState<'criteria' | 'search' | 'presets'>('criteria');
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const [presetName, setPresetName] = useState('');
  const [presetDescription, setPresetDescription] = useState('');

  // Get active filter count for badge
  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.severity?.length) count++;
    if (filters.tools?.length) count++;
    if (filters.priority?.length) count++;
    if (filters.files?.length) count++;
    if (filters.modules?.length) count++;
    if (filters.hasFix !== undefined) count++;
    if (filters.scoreRange && (filters.scoreRange[0] > 1 || filters.scoreRange[1] < 10)) count++;
    if (search.query.trim()) count++;
    return count;
  }, [filters, search]);

  // Keyboard navigation
  useInput((input, key) => {
    if (key.ctrl && input === 'f') {
      setActiveTab('criteria');
    } else if (key.ctrl && input === 's') {
      setActiveTab('search');
    } else if (key.ctrl && input === 'p') {
      setActiveTab('presets');
    } else if (key.escape) {
      setShowSaveDialog(false);
      setPresetName('');
      setPresetDescription('');
    }
  });

  const _handleSavePreset = () => {
    if (presetName.trim()) {
      savePreset(presetName.trim(), presetDescription.trim());
      setShowSaveDialog(false);
      setPresetName('');
      setPresetDescription('');
    }
  };

  const handleDeletePreset = (presetId: string) => {
    deletePreset(presetId);
  };

  const handleSetDefaultPreset = (presetId: string) => {
    setDefaultPreset(presetId);
  };

  return (
    <Box flexDirection="column" width={80}>
      {/* Header */}
      <Box flexDirection="row" marginBottom={1}>
        <Text bold color="blue">
          Filters
        </Text>
        {activeFilterCount > 0 && (
          <Text color="cyan" backgroundColor="blue">
            {' '}
            {activeFilterCount} active{' '}
          </Text>
        )}
        <Box flexGrow={1} />
        <Text color="gray">[Ctrl+F] Filters [Ctrl+S] Search [Ctrl+P] Presets [Esc] Close</Text>
      </Box>

      {/* Tab Navigation */}
      <Box flexDirection="row" marginBottom={1}>
        {[
          { key: 'criteria', label: 'Filter Criteria' },
          { key: 'search', label: 'Search' },
          { key: 'presets', label: 'Presets' },
        ].map(tab => (
          <Box
            key={tab.key}
            marginRight={1}
            paddingX={1}
            backgroundColor={activeTab === tab.key ? 'blue' : 'gray'}
          >
            <Text color={activeTab === tab.key ? 'white' : 'black'} bold={activeTab === tab.key}>
              {tab.label}
            </Text>
          </Box>
        ))}
      </Box>

      {/* Tab Content */}
      {activeTab === 'criteria' && (
        <FilterCriteriaTab
          filters={filters}
          availableSeverities={availableSeverities}
          availableTools={availableTools}
          availableFiles={_availableFiles}
          availableModules={_availableModules}
          onFiltersChange={setFilters}
        />
      )}

      {activeTab === 'search' && <SearchTab search={search} onSearchChange={setSearch} />}

      {activeTab === 'presets' && (
        <PresetsTab
          presets={presets}
          currentPresetId={currentPresetId}
          onLoadPreset={loadPreset}
          onDeletePreset={handleDeletePreset}
          onSetDefaultPreset={handleSetDefaultPreset}
          onSaveNew={() => setShowSaveDialog(true)}
        />
      )}

      {/* Save Preset Dialog */}
      {showSaveDialog && (
        <Box
          flexDirection="column"
          marginTop={1}
          padding={1}
          borderStyle="round"
          borderColor="blue"
        >
          <Text bold color="blue">
            Save Current Filters as Preset
          </Text>
          <Box flexDirection="column" marginTop={1}>
            <Text color="gray">Name:</Text>
            <Box paddingLeft={1}>
              <Text color="yellow">"{presetName || '(empty)'}"</Text>
            </Box>
          </Box>
          <Box flexDirection="column" marginTop={1}>
            <Text color="gray">Description:</Text>
            <Box paddingLeft={1}>
              <Text color="yellow">"{presetDescription || '(empty)'}"</Text>
            </Box>
          </Box>
          <Box flexDirection="row" marginTop={1}>
            <Text color="green">[Enter] Save</Text>
            <Box paddingLeft={2}>
              <Text color="red">[Esc] Cancel</Text>
            </Box>
          </Box>
        </Box>
      )}

      {/* Action Buttons */}
      <Box flexDirection="row" marginTop={2}>
        <Box backgroundColor="green">
          <Text color="black"> [Enter] Apply Filters </Text>
        </Box>
        <Box paddingLeft={1} backgroundColor="yellow">
          <Text color="black"> [R] Reset </Text>
        </Box>
        <Box paddingLeft={1} backgroundColor="blue">
          <Text color="black"> [Ctrl+S] Save Preset </Text>
        </Box>
      </Box>
    </Box>
  );
};

interface FilterCriteriaTabProps {
  filters: FilterCriteria;
  availableSeverities: string[];
  availableTools: string[];
  availableFiles: string[];
  availableModules: string[];
  onFiltersChange: (filters: Partial<FilterCriteria>) => void;
}

const FilterCriteriaTab: React.FC<FilterCriteriaTabProps> = ({
  filters,
  availableSeverities,
  availableTools,
  availableFiles: _availableFiles,
  availableModules: _availableModules,
  onFiltersChange,
}) => {
  return (
    <Box flexDirection="column">
      {/* Severity Filter */}
      <Box flexDirection="column" marginBottom={1}>
        <Text bold color="cyan">
          Severity
        </Text>
        <MultiSelect
          items={availableSeverities}
          selectedItems={filters.severity ?? []}
          onChange={severity => onFiltersChange({ severity })}
          placeholder="Select severities..."
        />
      </Box>

      {/* Tools Filter */}
      <Box flexDirection="column" marginBottom={1}>
        <Text bold color="cyan">
          Tools
        </Text>
        <MultiSelect
          items={availableTools}
          selectedItems={filters.tools ?? []}
          onChange={tools => onFiltersChange({ tools })}
          placeholder="Select tools..."
        />
      </Box>

      {/* Priority Filter */}
      <Box flexDirection="column" marginBottom={1}>
        <Text bold color="cyan">
          Priority
        </Text>
        <MultiSelect
          items={['critical', 'high', 'medium', 'low']}
          selectedItems={filters.priority ?? []}
          onChange={priority => onFiltersChange({ priority })}
          placeholder="Select priorities..."
        />
      </Box>

      {/* Score Range Filter */}
      <Box flexDirection="column" marginBottom={1}>
        <Text bold color="cyan">
          Score Range: {filters.scoreRange?.[0] ?? 1} - {filters.scoreRange?.[1] ?? 10}
        </Text>
        <RangeSlider
          min={1}
          max={10}
          value={filters.scoreRange ?? [1, 10]}
          onChange={scoreRange => onFiltersChange({ scoreRange })}
        />
      </Box>

      {/* Fixable Filter */}
      <Box flexDirection="row" marginBottom={1}>
        <Text color="cyan">[F] Fixable only:</Text>
        <Box paddingLeft={1}>
          <Text color={filters.hasFix === true ? 'green' : 'gray'}>
            {filters.hasFix === true ? '☑' : '☐'}
          </Text>
        </Box>
      </Box>
    </Box>
  );
};

interface SearchTabProps {
  search: {
    query: string;
    fields: ('message' | 'filePath' | 'ruleId' | 'toolName')[];
    caseSensitive: boolean;
    useRegex: boolean;
  };
  onSearchChange: (search: Partial<SearchTabProps['search']>) => void;
}

const SearchTab: React.FC<SearchTabProps> = ({ search, onSearchChange }) => {
  return (
    <Box flexDirection="column">
      <Box flexDirection="column" marginBottom={1}>
        <Text bold color="cyan">
          Search Query
        </Text>
        <Box flexDirection="row">
          <Text color="gray">Query:</Text>
          <Box paddingLeft={1}>
            <Text color="yellow">"{search.query || '(empty)'}"</Text>
          </Box>
        </Box>
      </Box>

      <Box flexDirection="column" marginBottom={1}>
        <Text bold color="cyan">
          Search Fields
        </Text>
        <MultiSelect
          items={['message', 'filePath', 'ruleId', 'toolName']}
          selectedItems={search.fields}
          onChange={fields => onSearchChange({ fields: fields as (typeof search.fields)[0][] })}
          placeholder="Select fields to search..."
        />
      </Box>

      <Box flexDirection="row" marginBottom={1}>
        <Text color="cyan">[C] Case sensitive:</Text>
        <Box paddingLeft={1}>
          <Text color={search.caseSensitive ? 'green' : 'gray'}>
            {search.caseSensitive ? '☑' : '☐'}
          </Text>
        </Box>
      </Box>

      <Box flexDirection="row" marginBottom={1}>
        <Text color="cyan">[R] Use regex:</Text>
        <Box paddingLeft={1}>
          <Text color={search.useRegex ? 'green' : 'gray'}>{search.useRegex ? '☑' : '☐'}</Text>
        </Box>
      </Box>
    </Box>
  );
};

interface PresetsTabProps {
  presets: FilterPreset[];
  currentPresetId?: string;
  onLoadPreset: (presetId: string) => void;
  onDeletePreset: (presetId: string) => void;
  onSetDefaultPreset: (presetId: string) => void;
  onSaveNew: () => void;
}

const PresetsTab: React.FC<PresetsTabProps> = ({
  presets,
  currentPresetId,
  onLoadPreset: _onLoadPreset,
  onDeletePreset: _onDeletePreset,
  onSetDefaultPreset: _onSetDefaultPreset,
  onSaveNew: _onSaveNew,
}) => {
  return (
    <Box flexDirection="column">
      <Box flexDirection="row" marginBottom={1}>
        <Text bold color="cyan">
          Filter Presets
        </Text>
        <Box flexGrow={1} />
        <Text color="blue" inverse={true}>
          {' '}
          [N] New Preset{' '}
        </Text>
      </Box>

      {presets.map(preset => (
        <Box
          key={preset.id}
          flexDirection="column"
          marginBottom={1}
          padding={1}
          borderStyle="round"
          borderColor={currentPresetId === preset.id ? 'green' : 'gray'}
        >
          <Box flexDirection="row">
            <Text bold>
              {preset.name}
              {preset.isDefault && <Text color="yellow"> (default)</Text>}
            </Text>
            {currentPresetId === preset.id && <Text color="green"> ✓</Text>}
          </Box>
          <Text color="gray">{preset.description}</Text>
          <Box flexDirection="row" marginTop={1}>
            <Text color="blue">[Enter] Load</Text>
            <Box paddingLeft={2}>
              <Text color="green">[D] Set Default</Text>
            </Box>
            {!preset.isDefault && (
              <Box paddingLeft={2}>
                <Text color="red">[Delete] Remove</Text>
              </Box>
            )}
          </Box>
        </Box>
      ))}

      {presets.length === 0 && (
        <Box flexDirection="row" padding={2} borderStyle="round" borderColor="gray">
          <Text color="gray">No presets saved yet. Create your first preset!</Text>
        </Box>
      )}
    </Box>
  );
};

export default FilterPanel;

/**
 * Filter bar component
 */

import React from 'react';
import { Box, Text } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { getSeveritySymbol } from '../../utils/color-coding';
import type { IssueSeverity as _IssueSeverity } from '../../types/dashboard';

export function FilterBar(): React.ReactElement {
  const { filters, filteredIssues } = useDashboardStore();
  const { severity, tools, fixable, searchQuery } = filters;

  // Count active filters
  const activeFilterCount = [
    severity.length < 3 ? 1 : 0,
    tools.length > 0 ? 1 : 0,
    fixable !== null ? 1 : 0,
    searchQuery.trim() !== '' ? 1 : 0,
  ].reduce((sum, count) => sum + count, 0);

  // Get severity filter display
  const getSeverityDisplay = () => {
    if (severity.length === 3) return 'All';
    return severity
      .map(s => {
        const symbol = getSeveritySymbol(s);
        return `${symbol}${s.charAt(0).toUpperCase()}`;
      })
      .join(' ');
  };

  // Get other filters display
  const getOtherFiltersDisplay = () => {
    const parts: string[] = [];

    if (tools.length > 0) {
      parts.push(`Tools: ${tools.length}`);
    }

    if (fixable !== null) {
      parts.push(`Fixable: ${fixable ? 'Yes' : 'No'}`);
    }

    if (searchQuery.trim() !== '') {
      parts.push(`Search: "${searchQuery}"`);
    }

    return parts.join(' | ');
  };

  return (
    <Box flexDirection="column" marginBottom={1}>
      <Box justifyContent="space-between">
        <Box>
          <Text color="gray" dimColor>
            Filters:
          </Text>
          <Text color="cyan"> {getSeverityDisplay()}</Text>
          {activeFilterCount > 0 && <Text color="yellow"> ({activeFilterCount} active)</Text>}
        </Box>

        <Box>
          <Text color="gray" dimColor>
            Press 'f' to modify filters
          </Text>
        </Box>
      </Box>

      {/* Additional filter details */}
      {(tools.length > 0 || fixable !== null || searchQuery.trim() !== '') && (
        <Box>
          <Text color="gray" dimColor>
            {' '}
            {getOtherFiltersDisplay()}
          </Text>
        </Box>
      )}

      {/* Results count */}
      <Box marginTop={1}>
        <Text color="gray" dimColor>
          Showing {filteredIssues.length} issues
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Historical Run Selector Component
 * Allows selecting historical runs for comparison
 */

import React, { useState, useMemo } from 'react';
import { Box, Text, useInput } from 'ink';
import { useComparisonStore, type AnalysisRun } from '../../hooks/useComparisonStore';

interface HistoricalRunSelectorProps {
  onSelectRuns: (baselineId: string, comparisonId: string) => void;
  onCancel: () => void;
  allowSameRun?: boolean;
}

interface RunDisplayInfo extends AnalysisRun {
  displayDate: string;
  displayVersion: string;
  relativeTime: string;
  isSelected: boolean;
  isBaseline: boolean;
  isComparison: boolean;
}

export const HistoricalRunSelector: React.FC<HistoricalRunSelectorProps> = ({
  onSelectRuns,
  onCancel,
  allowSameRun = false,
}) => {
  const {
    runs,
    selectedBaselineRun,
    selectedComparisonRun,
    selectBaselineRun,
    selectComparisonRun,
    getRecentRuns,
  } = useComparisonStore();

  const [selectedIndex, setSelectedIndex] = useState(0);
  const [filterMode, setFilterMode] = useState<'all' | 'recent' | 'by-date'>('all');
  const [dateFilter, _setDateFilter] = useState<string>('');

  // Get runs for display
  const displayRuns = useMemo(() => {
    let filteredRuns = [...runs];

    // Apply filters
    switch (filterMode) {
      case 'recent':
        filteredRuns = getRecentRuns(20);
        break;
      case 'by-date':
        if (dateFilter) {
          const filterDate = new Date(dateFilter);
          filteredRuns = runs.filter(run => {
            const runDate = new Date(run.timestamp);
            return runDate.toDateString() === filterDate.toDateString();
          });
        }
        break;
    }

    // Add display information
    return filteredRuns.map(run => {
      const now = new Date();
      const runTime = new Date(run.timestamp);
      const diffMs = now.getTime() - runTime.getTime();
      const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
      const diffDays = Math.floor(diffHours / 24);

      let relativeTime: string;
      if (diffHours < 1) {
        relativeTime = 'Just now';
      } else if (diffHours < 24) {
        relativeTime = `${diffHours}h ago`;
      } else if (diffDays < 7) {
        relativeTime = `${diffDays}d ago`;
      } else {
        relativeTime = runTime.toLocaleDateString();
      }

      return {
        ...run,
        displayDate: runTime.toLocaleDateString(),
        displayVersion: run.version ?? run.id.slice(0, 8),
        relativeTime,
        isSelected: selectedBaselineRun === run.id || selectedComparisonRun === run.id,
        isBaseline: selectedBaselineRun === run.id,
        isComparison: selectedComparisonRun === run.id,
      };
    });
  }, [runs, filterMode, dateFilter, selectedBaselineRun, selectedComparisonRun, getRecentRuns]);

  // Keyboard navigation
  useInput((input, key) => {
    switch (true) {
      case key.upArrow:
        setSelectedIndex(prev => Math.max(0, prev - 1));
        break;
      case key.downArrow:
        setSelectedIndex(prev => Math.min(displayRuns.length - 1, prev + 1));
        break;
      case input === '\u0001': // Ctrl+A (home)
        setSelectedIndex(0);
        break;
      case input === '\u0005': // Ctrl+E (end)
        setSelectedIndex(displayRuns.length - 1);
        break;
      case key.return:
        if (displayRuns.length > 0 && selectedIndex >= 0 && selectedIndex < displayRuns.length) {
          const selectedRun = displayRuns[selectedIndex];
          if (!selectedBaselineRun) {
            if (selectedRun?.id) selectBaselineRun(selectedRun.id);
          } else if (!selectedComparisonRun) {
            if (allowSameRun || selectedRun?.id !== selectedBaselineRun) {
              if (selectedRun?.id) selectComparisonRun(selectedRun.id);
            }
          } else {
            // Both selected, replace comparison
            if (allowSameRun || selectedRun?.id !== selectedBaselineRun) {
              if (selectedRun?.id) selectComparisonRun(selectedRun.id);
            }
          }
        }
        break;

      case input === 'b':
        if (displayRuns.length > 0 && selectedIndex >= 0 && selectedIndex < displayRuns.length) {
          const runId = displayRuns[selectedIndex]?.id;
          if (runId) selectBaselineRun(runId);
        }
        break;
      case input === 'c':
        if (displayRuns.length > 0 && selectedIndex >= 0 && selectedIndex < displayRuns.length) {
          const selectedRun = displayRuns[selectedIndex];
          if (
            selectedRun &&
            (allowSameRun || (selectedRun.id && selectedRun.id !== selectedBaselineRun))
          ) {
            selectComparisonRun(selectedRun.id);
          }
        }
        break;

      case input === 'r':
        setFilterMode('recent');
        break;
      case input === 'a':
        setFilterMode('all');
        break;
      case input === 'd':
        setFilterMode('by-date');
        break;

      case key.escape:
        onCancel();
        break;

      case input === 'x':
        // Execute comparison
        if (selectedBaselineRun && selectedComparisonRun) {
          onSelectRuns(selectedBaselineRun, selectedComparisonRun);
        }
        break;

      case input === '1':
        setSelectedIndex(0);
        break;
      case input === '2':
        setSelectedIndex(1);
        break;
      case input === '3':
        setSelectedIndex(2);
        break;
      case input === '4':
        setSelectedIndex(3);
        break;
      case input === '5':
        setSelectedIndex(4);
        break;
    }
  });

  const renderRun = (run: RunDisplayInfo, index: number) => {
    const isSelected = index === selectedIndex;
    const backgroundColor = isSelected ? 'blue' : undefined;
    const textColor = isSelected ? 'white' : 'black';

    const getRunTypeColor = () => {
      if (run.isBaseline) return 'green';
      if (run.isComparison) return 'yellow';
      return 'gray';
    };

    return (
      <Box
        key={run.id}
        flexDirection="column"
        padding={1}
        borderStyle="single"
        borderColor={isSelected ? 'blue' : 'gray'}
        backgroundColor={backgroundColor}
      >
        <Box flexDirection="row">
          <Box width={15}>
            <Text color={textColor} bold>
              {run.displayVersion}
            </Text>
          </Box>
          <Box width={12}>
            <Text color={textColor}>{run.displayDate}</Text>
          </Box>
          <Box width={10}>
            <Text color={textColor}>{run.relativeTime}</Text>
          </Box>
          <Box width={20}>
            <Text color={getRunTypeColor()}>
              {run.isBaseline && '[BASELINE]'}
              {run.isComparison && '[COMPARISON]'}
            </Text>
          </Box>
        </Box>

        <Box flexDirection="row" marginTop={1}>
          <Box width={50}>
            <Text color={textColor} dimColor>
              {run.commitHash ? `Commit: ${run.commitHash.slice(0, 7)}` : ''}
            </Text>
          </Box>
        </Box>

        <Box flexDirection="row">
          <Box width={20}>
            <Text color={textColor} dimColor>
              Issues: {run.metadata.totalIssues}
            </Text>
          </Box>
          <Box width={15}>
            <Text color={textColor} dimColor>
              Critical: {run.metadata.criticalIssues}
            </Text>
          </Box>
          <Box width={15}>
            <Text color={textColor} dimColor>
              Score: {run.metadata.score}
            </Text>
          </Box>
        </Box>

        <Box flexDirection="row">
          <Text color={textColor} dimColor>
            Tools: {run.metadata.tools.join(', ')}
          </Text>
        </Box>
      </Box>
    );
  };

  return (
    <Box flexDirection="column" width={100}>
      {/* Header */}
      <Box flexDirection="row" marginBottom={1}>
        <Text bold color="blue">
          Select Runs for Comparison
        </Text>
        <Box flexGrow={1} />
        <Text color="gray">[Esc] Cancel</Text>
      </Box>

      {/* Selection Status */}
      <Box flexDirection="row" marginBottom={1}>
        <Box width={25}>
          <Text color={selectedBaselineRun ? 'green' : 'gray'}>
            Baseline: {selectedBaselineRun ? selectedBaselineRun.slice(0, 8) : 'Not selected'}
          </Text>
        </Box>
        <Box width={25}>
          <Text color={selectedComparisonRun ? 'yellow' : 'gray'}>
            Comparison: {selectedComparisonRun ? selectedComparisonRun.slice(0, 8) : 'Not selected'}
          </Text>
        </Box>
        <Box flexGrow={1} />
        {selectedBaselineRun && selectedComparisonRun && <Text color="green">[X] Compare</Text>}
      </Box>

      {/* Filter Controls */}
      <Box flexDirection="row" marginBottom={1}>
        <Text color="gray">Filter:</Text>
        <Box paddingLeft={1}>
          <Text color={filterMode === 'all' ? 'blue' : 'gray'}>[A] All</Text>
        </Box>
        <Box paddingLeft={1}>
          <Text color={filterMode === 'recent' ? 'blue' : 'gray'}>[R] Recent</Text>
        </Box>
        <Box paddingLeft={1}>
          <Text color={filterMode === 'by-date' ? 'blue' : 'gray'}>[D] By Date</Text>
        </Box>
      </Box>

      {/* Runs List */}
      <Box flexDirection="column" height={20} borderStyle="single" borderColor="gray">
        {displayRuns.length === 0 ? (
          <Box flexDirection="column" justifyContent="center" alignItems="center" height={20}>
            <Text color="gray">No runs found</Text>
            <Text color="gray" dimColor>
              Try adjusting filters or run an analysis first
            </Text>
          </Box>
        ) : (
          <Box flexDirection="column">
            {displayRuns.slice(0, 10).map((run, index) => renderRun(run, index))}
          </Box>
        )}
      </Box>

      {/* Instructions */}
      <Box flexDirection="row" marginTop={1}>
        <Text color="gray" dimColor>
          [↑↓] Navigate • [Enter] Select • [B] Baseline • [C] Comparison • [X] Compare
        </Text>
        <Box flexGrow={1} />
        <Text color="gray" dimColor>
          {selectedIndex + 1}/{displayRuns.length}
        </Text>
      </Box>

      {/* Legend */}
      <Box flexDirection="row" marginTop={1}>
        <Text color="green" dimColor>
          ● Baseline
        </Text>
        <Box paddingLeft={2}>
          <Text color="yellow" dimColor>
            ● Comparison
          </Text>
        </Box>
        <Box flexGrow={1} />
        <Text color="gray" dimColor>
          {!allowSameRun && 'Cannot select same run for comparison'}
        </Text>
      </Box>
    </Box>
  );
};

