/**
 * Issue details component
 */

import React from 'react';
import { Box, Text, useInput } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { getSeverityColor, getSeveritySymbol, getScoreColor } from '../../utils/color-coding';
import type { Issue as _Issue } from '@dev-quality/core';
import type { IssueSeverity } from '../../types/dashboard';

export function IssueDetails(): React.ReactElement {
  const { selectedIssue, setCurrentView } = useDashboardStore();

  // Handle keyboard input
  useInput((input, key) => {
    if (key.escape) {
      setCurrentView('dashboard');
    }
  });

  if (!selectedIssue) {
    return (
      <Box flexDirection="column" padding={2}>
        <Box marginBottom={1}>
          <Text color="gray">No issue selected</Text>
        </Box>
        <Box>
          <Text color="gray" dimColor>
            Press Escape to go back
          </Text>
        </Box>
      </Box>
    );
  }

  const { id, type, toolName, filePath, lineNumber, message, ruleId, fixable, suggestion, score } =
    selectedIssue;

  // Format file path with line numbers
  const _fileLocation = `${filePath}:${lineNumber}`;
  const fileName = filePath.split('/').pop() ?? filePath;

  return (
    <Box flexDirection="column" padding={1}>
      {/* Header */}
      <Box
        marginBottom={1}
        borderStyle="single"
        borderColor={getSeverityColor(type as IssueSeverity)}
        paddingX={1}
      >
        <Box justifyContent="space-between">
          <Box>
            <Text color={getSeverityColor(type as IssueSeverity)}>
              {getSeveritySymbol(type as IssueSeverity)}
            </Text>
            <Text bold color={getSeverityColor(type as IssueSeverity)}>
              {' '}
              {type.toUpperCase()}
            </Text>
            <Text bold color="white">
              {' '}
              Issue Details
            </Text>
          </Box>
          <Box>
            <Text color={getScoreColor(score)}>Score: {score}</Text>
          </Box>
        </Box>
      </Box>

      {/* Issue Information */}
      <Box flexDirection="column" marginBottom={1}>
        {/* Message */}
        <Box marginBottom={1}>
          <Text bold color="white">
            Message:
          </Text>
          <Box marginLeft={2}>
            <Text>{message}</Text>
          </Box>
        </Box>

        {/* File Location */}
        <Box marginBottom={1}>
          <Text bold color="white">
            Location:
          </Text>
          <Box marginLeft={2}>
            <Text color="cyan">{fileName}</Text>
            <Text color="gray" dimColor>
              :{lineNumber}
            </Text>
          </Box>
          <Box marginLeft={2}>
            <Text color="gray" dimColor>
              {filePath}
            </Text>
          </Box>
        </Box>

        {/* Tool Information */}
        <Box marginBottom={1}>
          <Text bold color="white">
            Tool:
          </Text>
          <Box marginLeft={2}>
            <Text color="yellow">{toolName}</Text>
            {ruleId && (
              <>
                <Text color="gray" dimColor>
                  {' '}
                  - Rule:{' '}
                </Text>
                <Text color="cyan">{ruleId}</Text>
              </>
            )}
          </Box>
        </Box>

        {/* Issue ID */}
        <Box marginBottom={1}>
          <Text bold color="white">
            ID:
          </Text>
          <Box marginLeft={2}>
            <Text color="gray" dimColor>
              {id}
            </Text>
          </Box>
        </Box>

        {/* Fixable Status */}
        <Box marginBottom={1}>
          <Text bold color="white">
            Fixable:
          </Text>
          <Box marginLeft={2}>
            {fixable ? <Text color="green">✓ Yes</Text> : <Text color="red">✗ No</Text>}
          </Box>
        </Box>

        {/* Suggestion */}
        {suggestion && (
          <Box marginBottom={1}>
            <Text bold color="white">
              Suggestion:
            </Text>
            <Box marginLeft={2}>
              <Text color="cyan">💡 {suggestion}</Text>
            </Box>
          </Box>
        )}
      </Box>

      {/* Footer */}
      <Box borderStyle="single" borderColor="gray" paddingX={1}>
        <Text color="gray" dimColor>
          Press Escape to go back to the issue list
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Issue Diff List Component
 * Displays list of issues with diff visualization
 */

import React, { useState, useMemo } from 'react';
import { Box, Text, useInput } from 'ink';
import type { Issue } from '../../types/analysis';
import type { ComparisonResult } from '../../hooks/useComparisonStore';
import { PriorityBadge } from './priority-badge';

interface IssueDiffListProps {
  comparison: ComparisonResult;
  issueType: 'new' | 'resolved' | 'unchanged';
  filters: {
    showNewIssues: boolean;
    showResolvedIssues: boolean;
    showUnchangedIssues: boolean;
    severityFilter: string[];
    toolFilter: string[];
  };
  visualization: {
    showCharts: boolean;
    showDiffs: boolean;
    showTrends: boolean;
  };
}

interface IssueWithDiff extends Issue {
  diffType: 'new' | 'resolved' | 'unchanged';
  oldSeverity?: string;
  newSeverity?: string;
  oldScore?: number;
  newScore?: number;
  scoreDiff?: number;
}

export const IssueDiffList: React.FC<IssueDiffListProps> = ({
  comparison,
  issueType,
  filters,
  visualization,
}) => {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [sortBy, setSortBy] = useState<'severity' | 'score' | 'tool' | 'file'>('severity');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  // Get issues based on type
  const rawIssues = useMemo(() => {
    let issues: IssueWithDiff[] = [];

    switch (issueType) {
      case 'new':
        issues = comparison.differences.newIssues.map(issue => ({
          ...issue,
          diffType: 'new',
        }));
        break;
      case 'resolved':
        issues = comparison.differences.resolvedIssues.map(issue => ({
          ...issue,
          diffType: 'resolved',
        }));
        break;
      case 'unchanged':
        issues = comparison.differences.unchangedIssues.map(issue => ({
          ...issue,
          diffType: 'unchanged',
        }));
        break;
    }

    // Add severity changes and score changes for unchanged issues
    if (issueType === 'unchanged') {
      comparison.differences.severityChanges.forEach(change => {
        const existingIndex = issues.findIndex(i => i.id === change.issue.id);
        if (existingIndex >= 0 && change.issue.id) {
          const existingIssue = issues[existingIndex];
          if (existingIssue) {
            issues[existingIndex] = {
              ...existingIssue,
              oldSeverity: change.oldSeverity,
              newSeverity: change.newSeverity,
              diffType: 'unchanged',
              type: change.issue.type || 'error',
              id: change.issue.id,
              toolName: change.issue.toolName || existingIssue.toolName,
              filePath: change.issue.filePath || existingIssue.filePath,
              lineNumber: change.issue.lineNumber ?? existingIssue.lineNumber,
            };
          }
        }
      });

      comparison.differences.scoreChanges.forEach(change => {
        const existingIndex = issues.findIndex(i => i.id === change.issue.id);
        if (existingIndex >= 0 && change.issue.id) {
          const existingIssue = issues[existingIndex];
          if (existingIssue) {
            issues[existingIndex] = {
              ...existingIssue,
              oldScore: change.oldScore,
              newScore: change.newScore,
              scoreDiff: change.diff,
              diffType: 'unchanged',
              type: change.issue.type || 'error',
              id: change.issue.id,
              toolName: change.issue.toolName || existingIssue.toolName,
              filePath: change.issue.filePath || existingIssue.filePath,
              lineNumber: change.issue.lineNumber ?? existingIssue.lineNumber,
            };
          }
        }
      });
    }

    return issues;
  }, [comparison, issueType]);

  // Apply filters and sorting
  const filteredAndSortedIssues = useMemo(() => {
    let filtered = rawIssues;

    // Apply severity filter
    if (filters.severityFilter.length > 0) {
      filtered = filtered.filter(issue => filters.severityFilter.includes(issue.type));
    }

    // Apply tool filter
    if (filters.toolFilter.length > 0) {
      filtered = filtered.filter(issue => filters.toolFilter.includes(issue.toolName));
    }

    // Apply sorting
    filtered.sort((a, b) => {
      let comparisonValue = 0;

      switch (sortBy) {
        case 'severity': {
          const severityOrder = { error: 3, warning: 2, info: 1 };
          comparisonValue = severityOrder[a.type] - severityOrder[b.type];
          break;
        }
        case 'score':
          comparisonValue = (a.score || 0) - (b.score || 0);
          break;
        case 'tool':
          comparisonValue = a.toolName.localeCompare(b.toolName);
          break;
        case 'file':
          comparisonValue = a.filePath.localeCompare(b.filePath);
          break;
      }

      return sortOrder === 'asc' ? comparisonValue : -comparisonValue;
    });

    return filtered;
  }, [rawIssues, filters, sortBy, sortOrder]);

  // Keyboard navigation
  useInput((input, key) => {
    switch (true) {
      case key.upArrow:
        setSelectedIndex(prev => Math.max(0, prev - 1));
        break;
      case key.downArrow:
        setSelectedIndex(prev => Math.min(filteredAndSortedIssues.length - 1, prev + 1));
        break;
      case input === '\u0001': // Ctrl+A (home)
        setSelectedIndex(0);
        break;
      case input === '\u0005': // Ctrl+E (end)
        setSelectedIndex(filteredAndSortedIssues.length - 1);
        break;

      case input === 's':
        setSortBy('severity');
        break;
      case input === 'c':
        setSortBy('score');
        break;
      case input === 't':
        setSortBy('tool');
        break;
      case input === 'f':
        setSortBy('file');
        break;

      case input === 'o':
        setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        break;

      case input === '1':
        setSortBy('severity');
        break;
      case input === '2':
        setSortBy('score');
        break;
      case input === '3':
        setSortBy('tool');
        break;
      case input === '4':
        setSortBy('file');
        break;
    }
  });

  const renderIssue = (issue: IssueWithDiff, index: number) => {
    const isSelected = index === selectedIndex;
    const backgroundColor = isSelected ? 'blue' : undefined;
    const textColor = isSelected ? 'white' : 'black';

    // Get colors based on diff type
    const getDiffTypeColor = () => {
      switch (issue.diffType) {
        case 'new':
          return 'red';
        case 'resolved':
          return 'green';
        default:
          return 'gray';
      }
    };

    const diffTypeColor = getDiffTypeColor();

    return (
      <Box
        key={issue.id}
        flexDirection="column"
        padding={1}
        borderStyle="single"
        borderColor={isSelected ? 'blue' : 'gray'}
        backgroundColor={backgroundColor}
      >
        <Box flexDirection="row">
          <Text color={textColor} bold>
            {issue.diffType === 'new' ? '+' : issue.diffType === 'resolved' ? '-' : ' '}
          </Text>
          <Box paddingLeft={1}>
            <Text color={textColor}>
              {issue.message.length > 60 ? `${issue.message.slice(0, 57)}...` : issue.message}
            </Text>
          </Box>
        </Box>

        <Box flexDirection="row" marginTop={1}>
          <Box width={20}>
            <Text color={textColor} dimColor>
              {issue.filePath.split('/').pop()}
            </Text>
          </Box>
          <Box width={15}>
            <Text color={textColor} dimColor>
              {issue.toolName}
            </Text>
          </Box>
          <Box width={15}>
            <Text color={textColor} dimColor>
              {issue.type}
            </Text>
          </Box>
          <Box width={10}>
            <PriorityBadge score={issue.score} showScore={false} />
          </Box>
          <Box width={15}>
            <Text color={diffTypeColor} bold>
              {issue.diffType.toUpperCase()}
            </Text>
          </Box>
        </Box>

        {/* Show changes for unchanged issues */}
        {issue.diffType === 'unchanged' && visualization.showDiffs && (
          <Box flexDirection="column" marginTop={1}>
            {issue.oldSeverity && issue.newSeverity && (
              <Text color={textColor} dimColor>
                Severity: {issue.oldSeverity} → {issue.newSeverity}
              </Text>
            )}
            {issue.oldScore !== undefined && issue.newScore !== undefined && (
              <Text color={textColor} dimColor>
                Score: {issue.oldScore} → {issue.newScore} ({(issue.scoreDiff ?? 0) > 0 ? '+' : ''}
                {issue.scoreDiff ?? 0})
              </Text>
            )}
          </Box>
        )}

        <Box flexDirection="row" marginTop={1}>
          <Text color={textColor} dimColor>
            Line {issue.lineNumber} • {issue.ruleId}
          </Text>
          {issue.fixable && (
            <Box paddingLeft={2}>
              <Text color={textColor} bold>
                [FIXABLE]
              </Text>
            </Box>
          )}
        </Box>
      </Box>
    );
  };

  if (filteredAndSortedIssues.length === 0) {
    return (
      <Box flexDirection="column" padding={2}>
        <Text color="gray">No {issueType} issues found</Text>
        <Box marginTop={1}>
          <Text color="gray" dimColor>
            Try adjusting filters or check other issue types
          </Text>
        </Box>
      </Box>
    );
  }

  return (
    <Box flexDirection="column">
      {/* Header with sorting controls */}
      <Box flexDirection="row" marginBottom={1} padding={1}>
        <Text color="blue" bold>
          {issueType.charAt(0).toUpperCase() + issueType.slice(1)} Issues (
          {filteredAndSortedIssues.length})
        </Text>
        <Box flexGrow={1} />
        <Text color="gray" dimColor>
          Sort: [
          {sortBy === 'severity' ? '1' : sortBy === 'score' ? '2' : sortBy === 'tool' ? '3' : '4'}]{' '}
          {sortBy} [{sortOrder === 'asc' ? '↑' : '↓'}]
        </Text>
      </Box>

      {/* Sort shortcuts */}
      <Box flexDirection="row" marginBottom={1} paddingX={1}>
        <Text color="gray" dimColor>
          [1] Severity [2] Score [3] Tool [4] File [O] Order
        </Text>
        <Box flexGrow={1} />
        <Text color="gray" dimColor>
          {selectedIndex + 1}/{filteredAndSortedIssues.length}
        </Text>
      </Box>

      {/* Issues list */}
      <Box flexDirection="column" height={20}>
        <Box flexDirection="column">
          {filteredAndSortedIssues.slice(0, 10).map((issue, index) => renderIssue(issue, index))}
        </Box>
      </Box>

      {/* Legend */}
      <Box flexDirection="row" marginTop={1} paddingX={1}>
        <Text color="red" dimColor>
          + New
        </Text>
        <Box paddingLeft={2}>
          <Text color="gray" dimColor>
            - Resolved
          </Text>
        </Box>
        <Box paddingLeft={2}>
          <Text color="gray" dimColor>
            ± Unchanged
          </Text>
        </Box>
        <Box flexGrow={1} />
        <Text color="gray" dimColor>
          [↑↓] Navigate • [Home/End] First/Last
        </Text>
      </Box>
    </Box>
  );
};

/**
 * Issue list component with navigation
 */

import React, { useState, useEffect } from 'react';
import { Box, Text, useInput } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { createListNavigation } from '../../utils/keyboard-navigation';
// import { getSeverityColor, getSeveritySymbol } from '../../utils/color-coding'; // Unused imports
import { IssueItem } from '../issues/issue-item';
import { SortControls } from './sort-controls';
import { Pagination } from './pagination';

export function IssueList(): React.ReactElement {
  const {
    filteredIssues,
    selectedIssue: _selectedIssue,
    currentView,
    currentPage,
    itemsPerPage,
    sortBy,
    sortOrder,
    setSelectedIssue,
    setCurrentView,
    setSelectedIndex,
    addToNavigationHistory,
  } = useDashboardStore();

  const [selectedIndex, setSelectedIndexState] = useState(0);

  // Calculate pagination
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = Math.min(startIndex + itemsPerPage, filteredIssues.length);
  const currentIssues = filteredIssues.slice(startIndex, endIndex);
  const totalPages = Math.ceil(filteredIssues.length / itemsPerPage);

  // Sort issues
  const sortedIssues = [...currentIssues].sort((a, b) => {
    let comparison = 0;

    switch (sortBy) {
      case 'score':
        comparison = a.score - b.score;
        break;
      case 'severity': {
        const severityOrder = { error: 3, warning: 2, info: 1 };
        comparison = severityOrder[a.type] - severityOrder[b.type];
        break;
      }
      case 'filePath':
        comparison = a.filePath.localeCompare(b.filePath);
        break;
      case 'toolName':
        comparison = a.toolName.localeCompare(b.toolName);
        break;
      case 'lineNumber':
        comparison = a.lineNumber - b.lineNumber;
        break;
      default:
        comparison = 0;
    }

    return sortOrder === 'asc' ? comparison : -comparison;
  });

  // Create navigation handler
  const navigationHandler = createListNavigation(
    sortedIssues.length,
    index => {
      const issue = sortedIssues[index];
      if (issue) {
        setSelectedIssue(issue);
        setCurrentView('issue-details');
        addToNavigationHistory('issue-details', index);
      }
    },
    { wrapAround: true, skipDisabled: true, pageSize: 5 }
  );

  // Handle keyboard input
  useInput((_input, key) => {
    if (currentView === 'dashboard' || currentView === 'issue-list') {
      let newIndex = selectedIndex;

      if (key.upArrow || _input === 'k') {
        newIndex = navigationHandler.handleKeyDown('up', selectedIndex);
      } else if (key.downArrow || _input === 'j') {
        newIndex = navigationHandler.handleKeyDown('down', selectedIndex);
      } else if (key.ctrl && _input === 'a') {
        // Ctrl+A for home
        newIndex = navigationHandler.handleKeyDown('home', selectedIndex);
      } else if (key.ctrl && _input === 'e') {
        // Ctrl+E for end
        newIndex = navigationHandler.handleKeyDown('end', selectedIndex);
      } else if (key.pageUp) {
        newIndex = navigationHandler.handleKeyDown('pageup', selectedIndex);
      } else if (key.pageDown) {
        newIndex = navigationHandler.handleKeyDown('pagedown', selectedIndex);
      } else if (key.return) {
        navigationHandler.handleKeyDown('enter', selectedIndex);
        return;
      } else if (_input >= '1' && _input <= '9') {
        const numericIndex = parseInt(_input) - 1;
        if (numericIndex < sortedIssues.length) {
          newIndex = numericIndex;
          navigationHandler.handleKeyDown('enter', numericIndex);
        }
      }

      if (newIndex !== selectedIndex) {
        setSelectedIndexState(newIndex);
        setSelectedIndex(newIndex);

        // Auto-select the issue
        if (sortedIssues[newIndex]) {
          setSelectedIssue(sortedIssues[newIndex] ?? null);
        }
      }
    }
  });

  // Update selected issue when selectedIndex changes
  useEffect(() => {
    if (sortedIssues[selectedIndex]) {
      setSelectedIssue(sortedIssues[selectedIndex]);
    }
  }, [selectedIndex, sortedIssues, setSelectedIssue]);

  // Render header
  const renderHeader = () => (
    <Box marginBottom={1}>
      <Box justifyContent="space-between" width="100%">
        <Text bold color="cyan">
          Issues ({startIndex + 1}-{endIndex} of {filteredIssues.length})
        </Text>
        <Text color="gray" dimColor>
          Page {currentPage} of {totalPages}
        </Text>
      </Box>
    </Box>
  );

  // Render empty state
  if (sortedIssues.length === 0) {
    return (
      <Box flexDirection="column">
        {renderHeader()}
        <Box justifyContent="center" padding={2}>
          <Text color="gray">No issues found</Text>
        </Box>
      </Box>
    );
  }

  return (
    <Box flexDirection="column">
      {renderHeader()}

      {/* Sort Controls */}
      <Box marginBottom={1}>
        <SortControls />
      </Box>

      {/* Issue List */}
      <Box flexDirection="column" marginBottom={1}>
        {sortedIssues.length > 0 ? (
          sortedIssues.map((issue, index) => (
            <IssueItem
              key={issue.id}
              issue={issue}
              isSelected={index === selectedIndex}
              index={index}
            />
          ))
        ) : (
          <Box justifyContent="center" padding={2}>
            <Text color="gray">No issues found</Text>
          </Box>
        )}
      </Box>

      {/* Pagination */}
      <Pagination />

      {/* Footer with navigation hints */}
      <Box marginTop={1}>
        <Text color="gray" dimColor>
          ↑↓ Navigate | Enter: Details | 1-9: Quick jump | Home/End: First/Last | Page Up/Down:
          Navigate pages
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Metric Card Component
 * Displays a single metric with optional trend indicator
 */

import React from 'react';
import { Box, Text } from 'ink';

interface MetricCardProps {
  title: string;
  value: number | string;
  previousValue?: number;
  unit?: string;
  color?: 'red' | 'yellow' | 'green' | 'blue' | 'gray' | 'cyan' | 'magenta';
  size?: 'small' | 'medium' | 'large';
  showTrend?: boolean;
  width?: number;
}

export const MetricCard: React.FC<MetricCardProps> = ({
  title,
  value,
  previousValue,
  unit = '',
  color = 'blue',
  size = 'medium',
  showTrend = false,
  width = 20,
}) => {
  const getTrend = () => {
    if (previousValue === undefined || typeof value !== 'number') return null;

    const diff = value - previousValue;
    const percentChange = previousValue !== 0 ? (diff / previousValue) * 100 : 0;

    let trend: string;
    let trendColor: string;

    if (diff > 0) {
      trend = '📈';
      trendColor = 'red';
    } else if (diff < 0) {
      trend = '📉';
      trendColor = 'green';
    } else {
      trend = '➡️';
      trendColor = 'yellow';
    }

    return { trend, trendColor, diff, percentChange };
  };

  const trend = getTrend();

  const getSizeClasses = () => {
    switch (size) {
      case 'small':
        return { titleSize: 'small', valueSize: 'small' };
      case 'large':
        return { titleSize: 'medium', valueSize: 'large' };
      default:
        return { titleSize: 'small', valueSize: 'medium' };
    }
  };

  const { titleSize: _titleSize, valueSize: _valueSize } = getSizeClasses();

  return (
    <Box flexDirection="column" width={width} padding={1} borderStyle="round" borderColor={color}>
      <Box flexDirection="row" justifyContent="space-between">
        <Text color={color}>{title}</Text>
        {trend && showTrend && <Text color={trend.trendColor}>{trend.trend}</Text>}
      </Box>

      <Box flexDirection="row" alignItems="flex-start" marginTop={1}>
        <Text color={color} bold>
          {value}
        </Text>
        {unit && (
          <Box paddingLeft={1}>
            <Text color={color} dimColor>
              {unit}
            </Text>
          </Box>
        )}
      </Box>

      {trend && showTrend && (
        <Box flexDirection="row" marginTop={1}>
          <Text color={trend.trendColor} dimColor>
            {trend.diff > 0 ? '+' : ''}
            {trend.diff}
          </Text>
          <Box paddingLeft={1}>
            <Text color="gray" dimColor>
              ({trend.percentChange > 0 ? '+' : ''}
              {trend.percentChange.toFixed(1)}%)
            </Text>
          </Box>
        </Box>
      )}
    </Box>
  );
};

/**
 * Metrics summary component
 */

import React from 'react';
import { Box, Text } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { getScoreColor, getCoverageColor } from '../../utils/color-coding';

export function MetricsSummary(): React.ReactElement {
  const { currentResult, filteredIssues } = useDashboardStore();

  if (!currentResult) {
    return (
      <Box marginBottom={1}>
        <Text color="gray">No analysis results available</Text>
      </Box>
    );
  }

  const { summary: _summary, toolResults, duration, overallScore } = currentResult;

  // Calculate metrics
  const errorCount = filteredIssues.filter(issue => issue.type === 'error').length;
  const warningCount = filteredIssues.filter(issue => issue.type === 'warning').length;
  const infoCount = filteredIssues.filter(issue => issue.type === 'info').length;
  const fixableCount = filteredIssues.filter(issue => issue.fixable).length;

  // Get coverage from first tool that has it
  const coverage = toolResults.find(result => result.coverage)?.coverage;

  return (
    <Box marginBottom={1} flexDirection="column">
      <Box marginBottom={1}>
        <Text bold color="cyan">
          Analysis Summary
        </Text>
      </Box>

      <Box justifyContent="space-between" marginBottom={1}>
        {/* Overall Score */}
        <Box marginRight={2}>
          <Text>Score: </Text>
          <Text bold color={getScoreColor(overallScore)}>
            {overallScore}/100
          </Text>
        </Box>

        {/* Issues Summary */}
        <Box marginRight={2}>
          <Text>Issues: </Text>
          <Text color="red">{errorCount}</Text>
          <Text> / </Text>
          <Text color="yellow">{warningCount}</Text>
          <Text> / </Text>
          <Text color="blue">{infoCount}</Text>
          <Text dimColor> (E/W/I)</Text>
        </Box>

        {/* Fixable Issues */}
        <Box marginRight={2}>
          <Text>Fixable: </Text>
          <Text color="green">{fixableCount}</Text>
        </Box>

        {/* Duration */}
        <Box>
          <Text>Time: </Text>
          <Text color="magenta">{(duration / 1000).toFixed(1)}s</Text>
        </Box>
      </Box>

      {/* Coverage Information */}
      {coverage && (
        <Box justifyContent="space-between" marginBottom={1}>
          <Box marginRight={2}>
            <Text>Coverage: </Text>
            <Text color={getCoverageColor(coverage.lines.percentage)}>
              L:{coverage.lines.percentage.toFixed(1)}%
            </Text>
            <Text> / </Text>
            <Text color={getCoverageColor(coverage.functions.percentage)}>
              F:{coverage.functions.percentage.toFixed(1)}%
            </Text>
            <Text> / </Text>
            <Text color={getCoverageColor(coverage.branches.percentage)}>
              B:{coverage.branches.percentage.toFixed(1)}%
            </Text>
          </Box>
        </Box>
      )}

      {/* Tools Summary */}
      <Box justifyContent="space-between">
        <Text color="gray" dimColor>
          Tools analyzed: {toolResults.length} | Total issues: {filteredIssues.length}
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Multi-Select Component
 * Allows selecting multiple items from a list with keyboard navigation
 */

import React, { useState, useEffect } from 'react';
import { Box, Text, useInput } from 'ink';

interface MultiSelectProps {
  items: string[];
  selectedItems: string[];
  onChange: (selectedItems: string[]) => void;
  placeholder?: string;
  maxHeight?: number;
  searchable?: boolean;
}

export const MultiSelect: React.FC<MultiSelectProps> = ({
  items,
  selectedItems,
  onChange,
  placeholder = 'Select items...',
  maxHeight = 5,
  searchable: _searchable = true,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [focusedIndex, setFocusedIndex] = useState(0);

  // Filter items based on search term
  const filteredItems = items.filter(item => item.toLowerCase().includes(searchTerm.toLowerCase()));

  // Get display items (show selected items when closed, filtered items when open)
  const _displayItems = isOpen ? filteredItems : selectedItems;

  // Handle keyboard navigation
  useInput((input, key) => {
    if (!isOpen) {
      if (key.return) {
        setIsOpen(true);
        setFocusedIndex(0);
      }
      return;
    }

    switch (true) {
      case key.return: {
        // Toggle selection
        const focusedItem = filteredItems[focusedIndex];
        if (focusedItem) {
          const isSelected = selectedItems.includes(focusedItem);
          const newSelection = isSelected
            ? selectedItems.filter(item => item !== focusedItem)
            : [...selectedItems, focusedItem];
          onChange(newSelection);
        }
        break;
      }

      case key.escape:
        setIsOpen(false);
        setSearchTerm('');
        break;

      case key.upArrow:
        setFocusedIndex(prev => Math.max(0, prev - 1));
        break;

      case key.downArrow:
        setFocusedIndex(prev => Math.min(filteredItems.length - 1, prev + 1));
        break;

      case key.ctrl && input === 'a':
        // Select all filtered items
        onChange([...new Set([...selectedItems, ...filteredItems])]);
        break;

      case key.ctrl && input === 'n':
        // Deselect all
        onChange([]);
        break;

      default:
        // Handle search input
        if (input && !key.ctrl && !key.meta) {
          setSearchTerm(prev => prev + input);
          setFocusedIndex(0);
        }
        break;
    }
  });

  // Auto-focus logic
  useEffect(() => {
    if (isOpen && focusedIndex >= filteredItems.length) {
      setFocusedIndex(Math.max(0, filteredItems.length - 1));
    }
  }, [filteredItems.length, focusedIndex, isOpen]);

  const _handleRemoveItem = (itemToRemove: string) => {
    onChange(selectedItems.filter(item => item !== itemToRemove));
  };

  if (!isOpen) {
    return (
      <Box flexDirection="column">
        {/* Selected items display */}
        <Box flexDirection="row" borderStyle="single" borderColor="gray" padding={1} minHeight={3}>
          {selectedItems.length === 0 ? (
            <Text color="gray">{placeholder}</Text>
          ) : (
            <Box flexDirection="row" flexWrap="wrap">
              {selectedItems.map(item => (
                <Box
                  key={item}
                  flexDirection="row"
                  marginRight={1}
                  marginBottom={1}
                  paddingX={1}
                  backgroundColor="blue"
                >
                  <Text color="white">{item}</Text>
                  <Text color="red" bold>
                    {' '}
                    ×
                  </Text>
                </Box>
              ))}
            </Box>
          )}
        </Box>
        <Text color="gray" dimColor>
          [Enter] to open • {selectedItems.length} selected
        </Text>
      </Box>
    );
  }

  // Open state with search and list
  return (
    <Box flexDirection="column">
      {/* Search input */}
      <Box flexDirection="row" borderStyle="single" borderColor="blue" padding={1}>
        <Text color="blue">Search: </Text>
        <Text>{searchTerm}</Text>
        <Text color="gray">_</Text>
      </Box>

      {/* Filtered items list */}
      <Box flexDirection="column" borderStyle="single" borderColor="gray">
        {filteredItems.length === 0 ? (
          <Box padding={1}>
            <Text color="gray">No items found</Text>
          </Box>
        ) : (
          filteredItems.slice(0, maxHeight).map((item, index) => {
            const isSelected = selectedItems.includes(item);
            const isFocused = index === focusedIndex;

            return (
              <Box
                key={item}
                flexDirection="row"
                padding={1}
                backgroundColor={
                  isFocused ? (isSelected ? 'green' : 'blue') : isSelected ? 'cyan' : undefined
                }
              >
                <Text color={isSelected || isFocused ? 'white' : 'black'}>
                  {isSelected ? '✓' : ' '} {item}
                </Text>
              </Box>
            );
          })
        )}

        {/* Show more indicator */}
        {filteredItems.length > maxHeight && (
          <Box padding={1} borderTop={true}>
            <Text color="gray">...and {filteredItems.length - maxHeight} more items</Text>
          </Box>
        )}
      </Box>

      {/* Help text */}
      <Box flexDirection="row" marginTop={1}>
        <Text color="gray">
          [↑↓] Navigate • [Enter] Select • [Esc] Close • [Ctrl+A] All • [Ctrl+N] None
        </Text>
      </Box>
    </Box>
  );
};

export default MultiSelect;

/**
 * Navigation Transitions Component
 * Provides smooth transitions between different dashboard views
 */

import React, { useEffect, useState } from 'react';
import { Box, Text } from 'ink';

interface TransitionState {
  isTransitioning: boolean;
  fromView: string;
  toView: string;
  progress: number;
}

interface NavigationTransitionsProps {
  isTransitioning: boolean;
  fromView: string;
  toView: string;
  duration?: number;
  onComplete?: () => void;
}

export const NavigationTransitions: React.FC<NavigationTransitionsProps> = ({
  isTransitioning,
  fromView,
  toView,
  duration = 500,
  onComplete,
}) => {
  const [progress, setProgress] = useState(0);
  const [transitionState, setTransitionState] = useState<TransitionState>({
    isTransitioning: false,
    fromView: '',
    toView: '',
    progress: 0,
  });

  useEffect(() => {
    if (isTransitioning && !transitionState.isTransitioning) {
      setTransitionState({
        isTransitioning: true,
        fromView,
        toView,
        progress: 0,
      });
      setProgress(0);

      // Animate progress using setInterval instead of requestAnimationFrame
      const startTime = Date.now();
      const animateInterval = setInterval(() => {
        const elapsed = Date.now() - startTime;
        const currentProgress = Math.min(elapsed / duration, 1);

        setProgress(currentProgress);
        setTransitionState(prev => ({ ...prev, progress: currentProgress }));

        if (currentProgress >= 1) {
          clearInterval(animateInterval);
          setTransitionState({
            isTransitioning: false,
            fromView: '',
            toView: '',
            progress: 1,
          });
          onComplete?.();
        }
      }, 16); // ~60fps

      return () => clearInterval(animateInterval);
    }
  }, [isTransitioning, fromView, toView, duration, onComplete, transitionState.isTransitioning]);

  if (!transitionState.isTransitioning) {
    return null;
  }

  // Render transition animation
  return (
    <Box flexDirection="column" alignItems="center" paddingY={1}>
      <Box flexDirection="row" alignItems="center" marginBottom={1}>
        <Text color="gray">Transitioning: </Text>
        <Text color="blue">{transitionState.fromView}</Text>
        <Text color="gray"> → </Text>
        <Text color="green">{transitionState.toView}</Text>
      </Box>

      {/* Progress bar */}
      <Box width={30} flexDirection="row">
        <Text color="gray">[</Text>
        {Array.from({ length: 28 }).map((_, index) => {
          const isActive = index / 28 <= progress;
          return (
            <Text key={index} color={isActive ? 'green' : 'gray'}>
              {isActive ? '█' : '░'}
            </Text>
          );
        })}
        <Text color="gray">]</Text>
      </Box>

      <Text color="gray">{Math.round(progress * 100)}%</Text>
    </Box>
  );
};

/**
 * Fade transition component
 */
export const FadeTransition: React.FC<{
  show: boolean;
  children: React.ReactNode;
}> = ({ show, children }) => {
  const [visible, setVisible] = useState(show);

  useEffect(() => {
    if (show !== visible) {
      const timer = setTimeout(() => setVisible(show), 50);
      return () => clearTimeout(timer);
    }
  }, [show, visible]);

  return visible ? <Box>{children}</Box> : null;
};

/**
 * Slide transition component
 */
export const SlideTransition: React.FC<{
  show: boolean;
  direction?: 'left' | 'right' | 'up' | 'down';
  children: React.ReactNode;
}> = ({ show, direction = 'right', children }) => {
  const [visible, setVisible] = useState(show);
  const [currentDirection, setCurrentDirection] = useState(direction);

  useEffect(() => {
    if (show !== visible) {
      setCurrentDirection(show ? 'right' : 'left');
      const timer = setTimeout(() => setVisible(show), 100);
      return () => clearTimeout(timer);
    }
  }, [show, visible]);

  if (!visible) return null;

  const getOffset = () => {
    switch (currentDirection) {
      case 'left':
        return '←';
      case 'right':
        return '→';
      case 'up':
        return '↑';
      case 'down':
        return '↓';
      default:
        return '';
    }
  };

  return (
    <Box flexDirection="row" alignItems="center">
      {currentDirection === 'left' && <Text color="gray">{getOffset()}</Text>}
      <Box>{children}</Box>
      {currentDirection === 'right' && <Text color="gray">{getOffset()}</Text>}
    </Box>
  );
};

/**
 * Loading transition for view changes
 */
export const LoadingTransition: React.FC<{
  message?: string;
  duration?: number;
}> = ({ message = 'Loading...', duration = 2000 }) => {
  const [dots, setDots] = useState('');
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    const dotInterval = setInterval(() => {
      setDots(prev => (prev.length >= 3 ? '' : prev + '.'));
    }, 200);

    const timeInterval = setInterval(() => {
      setElapsed(prev => prev + 100);
    }, 100);

    return () => {
      clearInterval(dotInterval);
      clearInterval(timeInterval);
    };
  }, []);

  const progress = Math.min(elapsed / duration, 1);
  const progressWidth = Math.round(progress * 20);

  return (
    <Box flexDirection="column" alignItems="center" paddingY={1}>
      <Box flexDirection="row" alignItems="center" marginBottom={1}>
        <Text color="cyan">{message}</Text>
        <Text color="gray">{dots}</Text>
      </Box>

      <Box width={22} flexDirection="row">
        <Text color="gray">[</Text>
        {Array.from({ length: 20 }).map((_, index) => {
          const isActive = index < progressWidth;
          return (
            <Text key={index} color={isActive ? 'cyan' : 'gray'}>
              {isActive ? '█' : '░'}
            </Text>
          );
        })}
        <Text color="gray">]</Text>
      </Box>

      {progress < 1 && (
        <Text color="gray" italic>
          Preparing view... ({Math.round(progress * 100)}%)
        </Text>
      )}
    </Box>
  );
};

export default NavigationTransitions;

/**
 * Pagination component
 */

import React from 'react';
import { Box, Text } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';

export function Pagination(): React.ReactElement | null {
  const {
    filteredIssues,
    ui: { currentPage, itemsPerPage },
    setCurrentPage,
  } = useDashboardStore();

  const totalItems = filteredIssues.length;
  const totalPages = Math.ceil(totalItems / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage + 1;
  const endIndex = Math.min(currentPage * itemsPerPage, totalItems);

  if (totalPages <= 1) {
    return null;
  }

  const goToPage = (page: number) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
    }
  };

  const _goToFirstPage = () => goToPage(1);
  const _goToLastPage = () => goToPage(totalPages);
  const _goToPreviousPage = () => goToPage(currentPage - 1);
  const _goToNextPage = () => goToPage(currentPage + 1);

  // Create page numbers to show
  const getVisiblePages = () => {
    const maxVisible = 5;
    const halfVisible = Math.floor(maxVisible / 2);

    let startPage = Math.max(1, currentPage - halfVisible);
    const endPage = Math.min(totalPages, startPage + maxVisible - 1);

    // Adjust if we're near the end
    if (endPage - startPage < maxVisible - 1) {
      startPage = Math.max(1, endPage - maxVisible + 1);
    }

    const pages: number[] = [];
    for (let i = startPage; i <= endPage; i++) {
      pages.push(i);
    }

    return pages;
  };

  const visiblePages = getVisiblePages();

  return (
    <Box flexDirection="column" marginBottom={1}>
      <Box justifyContent="space-between" alignItems="center">
        {/* Previous button */}
        <Box marginRight={2}>
          <Text color={currentPage > 1 ? 'cyan' : 'gray'} dimColor={currentPage === 1}>
            {currentPage > 1 ? '← Previous' : '← Previous'}
          </Text>
        </Box>

        {/* Page numbers */}
        <Box flexGrow={1} justifyContent="center">
          {visiblePages.map((page, _index) => {
            const isCurrentPage = page === currentPage;
            const showStartEllipsis = _index === 0 && page > 2;
            const showEndEllipsis = _index === visiblePages.length - 1 && page < totalPages - 1;

            return (
              <React.Fragment key={page}>
                {showStartEllipsis && (
                  <>
                    <Box marginRight={1}>
                      <Text color="gray">1</Text>
                    </Box>
                    <Box marginRight={1}>
                      <Text color="gray">...</Text>
                    </Box>
                  </>
                )}

                <Box marginRight={1}>
                  <Text
                    color={isCurrentPage ? 'white' : 'cyan'}
                    backgroundColor={isCurrentPage ? 'blue' : undefined}
                    underline={isCurrentPage}
                  >
                    {page}
                  </Text>
                </Box>

                {showEndEllipsis && (
                  <>
                    <Box marginRight={1}>
                      <Text color="gray">...</Text>
                    </Box>
                    <Box marginRight={1}>
                      <Text color="gray">{totalPages}</Text>
                    </Box>
                  </>
                )}
              </React.Fragment>
            );
          })}
        </Box>

        {/* Next button */}
        <Box marginLeft={2}>
          <Text
            color={currentPage < totalPages ? 'cyan' : 'gray'}
            dimColor={currentPage === totalPages}
          >
            {currentPage < totalPages ? 'Next →' : 'Next →'}
          </Text>
        </Box>
      </Box>

      {/* Items information */}
      <Box justifyContent="center" marginTop={1}>
        <Text color="gray" dimColor>
          Showing {startIndex}-{endIndex} of {totalItems} issues
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Priority Badge Component
 * Displays priority level with color coding
 */

import React from 'react';
import { Text } from 'ink';

interface PriorityBadgeProps {
  score: number;
  level?: 'critical' | 'high' | 'medium' | 'low';
  showScore?: boolean;
}

const getPriorityColor = (level: string): string => {
  switch (level) {
    case 'critical':
      return 'red';
    case 'high':
      return 'yellow';
    case 'medium':
      return 'blue';
    case 'low':
      return 'green';
    default:
      return 'gray';
  }
};

const getPriorityFromScore = (score: number): 'critical' | 'high' | 'medium' | 'low' => {
  if (score >= 8) return 'critical';
  if (score >= 6) return 'high';
  if (score >= 4) return 'medium';
  return 'low';
};

export const PriorityBadge: React.FC<PriorityBadgeProps> = ({ score, level, showScore = true }) => {
  const priorityLevel = level ?? getPriorityFromScore(score);
  const color = getPriorityColor(priorityLevel);
  const label = priorityLevel.toUpperCase();

  return (
    <Text color={color} bold>
      {showScore ? `${label} (${score.toFixed(1)})` : label}
    </Text>
  );
};

export default PriorityBadge;

/**
 * Range Slider Component
 * Allows selecting a range between min and max values
 */

import React, { useState, useEffect } from 'react';
import { Box, Text, useInput } from 'ink';

interface RangeSliderProps {
  min: number;
  max: number;
  value: [number, number];
  onChange: (value: [number, number]) => void;
  step?: number;
  showLabels?: boolean;
  width?: number;
}

export const RangeSlider: React.FC<RangeSliderProps> = ({
  min,
  max,
  value,
  onChange,
  step = 1,
  showLabels = true,
  width = 40,
}) => {
  const [activeHandle, setActiveHandle] = useState<'min' | 'max' | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  // Clamp value to valid range
  const clampedValue: [number, number] = [
    Math.max(min, Math.min(max, value[0])),
    Math.max(min, Math.min(max, value[1])),
  ].sort((a, b) => a - b) as [number, number];

  // Calculate handle positions
  const range = max - min;
  const minPosition = Math.round(((clampedValue[0] - min) / range) * (width - 2));
  const maxPosition = Math.round(((clampedValue[1] - min) / range) * (width - 2));

  // Generate slider bar representation
  const generateSliderBar = () => {
    const bar = Array(width).fill(' ');

    // Fill the selected range
    for (let i = minPosition; i <= maxPosition; i++) {
      if (i >= 0 && i < width) {
        bar[i] = '█';
      }
    }

    // Add handles
    if (minPosition >= 0 && minPosition < width) {
      bar[minPosition] = activeHandle === 'min' ? '▼' : '◄';
    }
    if (maxPosition >= 0 && maxPosition < width && maxPosition !== minPosition) {
      bar[maxPosition] = activeHandle === 'max' ? '▲' : '►';
    }

    return bar.join('');
  };

  // Handle keyboard input
  useInput((input, key) => {
    if (key.escape) {
      setActiveHandle(null);
      setIsDragging(false);
      return;
    }

    // If no handle is active, select one
    if (!activeHandle && !isDragging) {
      if (key.leftArrow || key.rightArrow) {
        setActiveHandle(key.leftArrow ? 'max' : 'min');
        setIsDragging(true);
      } else if (input === 'h' || input === 'l') {
        setActiveHandle(input === 'h' ? 'max' : 'min');
        setIsDragging(true);
      }
      return;
    }

    if (activeHandle && isDragging) {
      let newValue = [...clampedValue] as [number, number];
      const handleIndex = activeHandle === 'min' ? 0 : 1;

      switch (true) {
        case key.leftArrow:
        case input === 'h':
          newValue[handleIndex] = Math.max(min, newValue[handleIndex] - step);
          break;

        case key.rightArrow:
        case input === 'l':
          newValue[handleIndex] = Math.min(max, newValue[handleIndex] + step);
          break;

        case input === '\u0001': // Ctrl+A (home)
        case input === '^':
          newValue[handleIndex] = activeHandle === 'min' ? min : clampedValue[0];
          break;

        case input === '\u0005': // Ctrl+E (end)
        case input === '$':
          newValue[handleIndex] = activeHandle === 'max' ? max : clampedValue[1];
          break;

        case key.tab:
          // Switch between handles
          setActiveHandle(activeHandle === 'min' ? 'max' : 'min');
          return;

        case key.return:
          setActiveHandle(null);
          setIsDragging(false);
          return;

        default:
          // Handle number input for direct value setting
          if (input >= '0' && input <= '9') {
            const digit = parseInt(input);
            newValue[handleIndex] = Math.min(max, Math.max(min, digit));
          }
          break;
      }

      // Ensure min <= max
      if (newValue[0] > newValue[1]) {
        newValue = newValue.reverse() as [number, number];
        setActiveHandle(activeHandle === 'min' ? 'max' : 'min');
      }

      onChange(newValue);
    }

    // Allow initial handle selection
    if (!activeHandle && !isDragging) {
      if (input === '1' || input === '2') {
        setActiveHandle(input === '1' ? 'min' : 'max');
        setIsDragging(true);
      }
    }
  });

  // Auto-reset active handle when value changes externally
  useEffect(() => {
    if (!isDragging) {
      setActiveHandle(null);
    }
  }, [value, isDragging]);

  return (
    <Box flexDirection="column">
      {/* Value display */}
      {showLabels && (
        <Box flexDirection="row" justifyContent="space-between" marginBottom={1}>
          <Text color="cyan">
            Min: <Text bold>{clampedValue[0]}</Text>
          </Text>
          <Text color="cyan">
            Max: <Text bold>{clampedValue[1]}</Text>
          </Text>
        </Box>
      )}

      {/* Slider bar */}
      <Box flexDirection="row" marginBottom={1}>
        <Text color="gray">[</Text>
        <Text color={activeHandle ? 'yellow' : 'green'}>{generateSliderBar()}</Text>
        <Text color="gray">]</Text>
        {activeHandle && (
          <Text color="yellow" bold>
            {' '}
            {activeHandle === 'min' ? 'MIN' : 'MAX'}{' '}
          </Text>
        )}
      </Box>

      {/* Help text */}
      <Box flexDirection="row">
        <Text color="gray" dimColor>
          {!activeHandle
            ? '[←→] or [H/L] to activate • [1/2] quick select'
            : '[←→] or [H/L] adjust • [Tab] switch • [Enter] confirm • [Esc] cancel'}
        </Text>
      </Box>

      {/* Range labels */}
      {showLabels && (
        <Box flexDirection="row" justifyContent="space-between" marginTop={1}>
          <Text color="gray">{min}</Text>
          <Text color="gray">{max}</Text>
        </Box>
      )}
    </Box>
  );
};

export default RangeSlider;

/**
 * Run Comparison Component
 * Side-by-side analysis of two analysis runs
 */

import React, { useState } from 'react';
import { Box, Text, useInput } from 'ink';
import { useComparisonStore, type ComparisonResult } from '../../hooks/useComparisonStore';
import { MetricCard as _MetricCard } from './metric-card';
import { IssueDiffList } from './issue-diff-list';
import { TrendChart } from './trend-chart';
import { ComparisonSummary } from './comparison-summary';

interface RunComparisonProps {
  comparison?: ComparisonResult;
  onExport?: (format: 'json' | 'csv' | 'markdown') => void;
  onNewComparison?: () => void;
}

export const RunComparison: React.FC<RunComparisonProps> = ({
  comparison,
  onExport,
  onNewComparison,
}) => {
  const {
    currentComparison,
    comparisonConfig,
    setFilters,
    setVisualization,
    exportComparison: _exportComparison,
  } = useComparisonStore();

  const [activeTab, setActiveTab] = useState<'summary' | 'issues' | 'trends' | 'details'>(
    'summary'
  );
  const [selectedIssueType, setSelectedIssueType] = useState<'new' | 'resolved' | 'unchanged'>(
    'new'
  );

  const comparisonData = comparison ?? currentComparison;

  // Keyboard navigation
  useInput((input, key) => {
    switch (true) {
      case input === '1':
        setActiveTab('summary');
        break;
      case input === '2':
        setActiveTab('issues');
        break;
      case input === '3':
        setActiveTab('trends');
        break;
      case input === '4':
        setActiveTab('details');
        break;

      case key.ctrl && input === 'e':
        if (onExport) {
          onExport('json');
        }
        break;

      case key.ctrl && input === 'c':
        if (onExport) {
          onExport('csv');
        }
        break;

      case key.ctrl && input === 'm':
        if (onExport) {
          onExport('markdown');
        }
        break;

      case key.ctrl && input === 'n':
        if (onNewComparison) {
          onNewComparison();
        }
        break;

      case input === 'n':
        setSelectedIssueType('new');
        break;
      case input === 'r':
        setSelectedIssueType('resolved');
        break;
      case input === 'u':
        setSelectedIssueType('unchanged');
        break;

      case input === 'f':
        setFilters({ showNewIssues: !comparisonConfig.filters.showNewIssues });
        break;
      case input === 'g':
        setFilters({ showResolvedIssues: !comparisonConfig.filters.showResolvedIssues });
        break;
      case input === 'h':
        setFilters({ showUnchangedIssues: !comparisonConfig.filters.showUnchangedIssues });
        break;

      case input === 'c':
        setVisualization({ showCharts: !comparisonConfig.visualization.showCharts });
        break;
      case input === 'd':
        setVisualization({ showDiffs: !comparisonConfig.visualization.showDiffs });
        break;
      case input === 't':
        setVisualization({ showTrends: !comparisonConfig.visualization.showTrends });
        break;
    }
  });

  if (!comparisonData) {
    return (
      <Box flexDirection="column" padding={2}>
        <Text color="yellow" bold>
          No comparison data available
        </Text>
        <Text color="gray">Select two runs to compare using the run selector</Text>
        {onNewComparison && (
          <Box marginTop={1}>
            <Text color="blue">[Ctrl+N] New Comparison</Text>
          </Box>
        )}
      </Box>
    );
  }

  const tabs = [
    { key: 'summary', label: 'Summary', shortcut: '1' },
    { key: 'issues', label: 'Issues', shortcut: '2' },
    { key: 'trends', label: 'Trends', shortcut: '3' },
    { key: 'details', label: 'Details', shortcut: '4' },
  ];

  const issueTypeTabs = [
    { key: 'new', label: `New (${comparisonData.summary.newIssuesCount})`, shortcut: 'n' },
    {
      key: 'resolved',
      label: `Resolved (${comparisonData.summary.resolvedIssuesCount})`,
      shortcut: 'r',
    },
    {
      key: 'unchanged',
      label: `Unchanged (${comparisonData.summary.unchangedIssuesCount})`,
      shortcut: 'u',
    },
  ];

  return (
    <Box flexDirection="column" width={120}>
      {/* Header */}
      <Box flexDirection="row" marginBottom={1}>
        <Text bold color="blue">
          Run Comparison
        </Text>
        <Box flexGrow={1} />
        <Text color="gray">
          Baseline: {comparisonData.baseline.version ?? comparisonData.baseline.id.slice(0, 8)}
        </Text>
        <Box paddingLeft={1}>
          <Text color="gray">vs</Text>
        </Box>
        <Box paddingLeft={1}>
          <Text color="gray">
            {comparisonData.comparison.version ?? comparisonData.comparison.id.slice(0, 8)}
          </Text>
        </Box>
      </Box>

      {/* Tab Navigation */}
      <Box flexDirection="row" marginBottom={1}>
        {tabs.map(tab => (
          <Box
            key={tab.key}
            marginRight={1}
            paddingX={1}
            backgroundColor={activeTab === tab.key ? 'blue' : 'gray'}
          >
            <Text color={activeTab === tab.key ? 'white' : 'black'}>
              {tab.label} [{tab.shortcut}]
            </Text>
          </Box>
        ))}
        <Box flexGrow={1} />
        <Text color="gray">[Ctrl+E] JSON [Ctrl+C] CSV [Ctrl+M] MD</Text>
      </Box>

      {/* Tab Content */}
      {activeTab === 'summary' && <ComparisonSummary comparison={comparisonData} />}

      {activeTab === 'issues' && (
        <Box flexDirection="column">
          {/* Issue Type Tabs */}
          <Box flexDirection="row" marginBottom={1}>
            {issueTypeTabs.map(tab => (
              <Box
                key={tab.key}
                marginRight={1}
                paddingX={1}
                backgroundColor={selectedIssueType === tab.key ? 'green' : 'gray'}
              >
                <Text color={selectedIssueType === tab.key ? 'white' : 'black'}>
                  {tab.label} [{tab.shortcut}]
                </Text>
              </Box>
            ))}
            <Box flexGrow={1} />
            <Text color="gray">Filters: [F] New [G] Resolved [H] Unchanged</Text>
          </Box>

          {/* Issues List */}
          <IssueDiffList
            comparison={comparisonData}
            issueType={selectedIssueType}
            filters={comparisonConfig.filters}
            visualization={comparisonConfig.visualization}
          />
        </Box>
      )}

      {activeTab === 'trends' && (
        <TrendChart
          trends={comparisonData.trends}
          showCharts={comparisonConfig.visualization.showCharts}
          showDiffs={comparisonConfig.visualization.showDiffs}
        />
      )}

      {activeTab === 'details' && (
        <Box flexDirection="column">
          <Text bold color="cyan">
            Detailed Comparison
          </Text>
          <Box marginTop={1}>
            <Text>Baseline Run Details:</Text>
            <Text color="gray"> ID: {comparisonData.baseline.id}</Text>
            <Text color="gray"> Timestamp: {comparisonData.baseline.timestamp.toISOString()}</Text>
            <Text color="gray"> Version: {comparisonData.baseline.version ?? 'N/A'}</Text>
            <Text color="gray"> Commit: {comparisonData.baseline.commitHash ?? 'N/A'}</Text>
            <Text color="gray"> Branch: {comparisonData.baseline.branch ?? 'N/A'}</Text>
            <Text color="gray"> Tools: {comparisonData.baseline.metadata.tools.join(', ')}</Text>
            <Text color="gray">
              {' '}
              Execution Time: {comparisonData.baseline.metadata.executionTime}ms
            </Text>
          </Box>

          <Box marginTop={1}>
            <Text>Comparison Run Details:</Text>
            <Text color="gray"> ID: {comparisonData.comparison.id}</Text>
            <Text color="gray">
              {' '}
              Timestamp: {comparisonData.comparison.timestamp.toISOString()}
            </Text>
            <Text color="gray"> Version: {comparisonData.comparison.version ?? 'N/A'}</Text>
            <Text color="gray"> Commit: {comparisonData.comparison.commitHash ?? 'N/A'}</Text>
            <Text color="gray"> Branch: {comparisonData.comparison.branch ?? 'N/A'}</Text>
            <Text color="gray"> Tools: {comparisonData.comparison.metadata.tools.join(', ')}</Text>
            <Text color="gray">
              {' '}
              Execution Time: {comparisonData.comparison.metadata.executionTime}ms
            </Text>
          </Box>

          <Box marginTop={1}>
            <Text>Configuration:</Text>
            <Text color="gray">
              {' '}
              Show Charts: {comparisonConfig.visualization.showCharts ? 'Yes' : 'No'}
            </Text>
            <Text color="gray">
              {' '}
              Show Diffs: {comparisonConfig.visualization.showDiffs ? 'Yes' : 'No'}
            </Text>
            <Text color="gray">
              {' '}
              Show Trends: {comparisonConfig.visualization.showTrends ? 'Yes' : 'No'}
            </Text>
            <Text color="gray">
              {' '}
              Show New Issues: {comparisonConfig.filters.showNewIssues ? 'Yes' : 'No'}
            </Text>
            <Text color="gray">
              {' '}
              Show Resolved Issues: {comparisonConfig.filters.showResolvedIssues ? 'Yes' : 'No'}
            </Text>
            <Text color="gray">
              {' '}
              Show Unchanged Issues: {comparisonConfig.filters.showUnchangedIssues ? 'Yes' : 'No'}
            </Text>
          </Box>
        </Box>
      )}

      {/* Footer */}
      <Box flexDirection="row" marginTop={2} borderTop={true} paddingY={1}>
        <Text color="gray" dimColor>
          Visualization: [C] Charts [D] Diffs [T] Trends
        </Text>
        <Box flexGrow={1} />
        <Text color="gray" dimColor>
          [Ctrl+N] New Comparison
        </Text>
      </Box>

      {/* Performance Summary */}
      <Box flexDirection="row" marginBottom={1}>
        <Text color={comparisonData.summary.improvementRate > 0 ? 'green' : 'red'}>
          {comparisonData.summary.improvementRate > 0 ? '🟢' : '🔴'} Improvement Rate:{' '}
          {comparisonData.summary.improvementRate.toFixed(2)}%
        </Text>
        <Box flexGrow={1} />
        <Text color="gray" dimColor>
          Generated: {comparisonData.generatedAt.toLocaleString()}
        </Text>
      </Box>
    </Box>
  );
};

export default RunComparison;

/**
 * Search Bar Component
 * Real-time search with advanced options
 */

import React, { useState, useEffect } from 'react';
import { Box, Text, useInput } from 'ink';
import { useFilterStore } from '../../hooks/useFilterStore';

interface SearchBarProps {
  onSearch: (query: string) => void;
  placeholder?: string;
  showAdvanced?: boolean;
  autoFocus?: boolean;
}

export const SearchBar: React.FC<SearchBarProps> = ({
  onSearch,
  placeholder = 'Search issues...',
  showAdvanced = true,
  autoFocus = false,
}) => {
  const {
    search,
    setSearch,
    filterResults: _filterResults,
    totalResults,
    isLoading,
  } = useFilterStore();

  const [isFocused, setIsFocused] = useState(autoFocus);
  const [showAdvancedOptions, setShowAdvancedOptions] = useState(false);
  const [searchHistory, setSearchHistory] = useState<string[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Debounced search
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (search.query.trim()) {
        onSearch(search.query.trim());
      }
    }, 300);

    return () => clearTimeout(timeoutId);
  }, [search.query, onSearch]);

  // Update search history
  useEffect(() => {
    if (search.query.trim() && !searchHistory.includes(search.query.trim())) {
      setSearchHistory(prev => [...prev.slice(-9), search.query.trim()]);
    }
  }, [search.query, searchHistory]);

  // Keyboard navigation
  useInput((input, key) => {
    if (!isFocused) {
      if (input === '/' && !key.ctrl) {
        setIsFocused(true);
        return;
      }
      return;
    }

    switch (true) {
      case key.escape:
        setIsFocused(false);
        setShowAdvancedOptions(false);
        break;

      case key.ctrl && input === 'r':
        // Toggle regex
        setSearch({ useRegex: !search.useRegex });
        break;

      case key.ctrl && input === 'c':
        // Toggle case sensitivity
        setSearch({ caseSensitive: !search.caseSensitive });
        break;

      case key.ctrl && input === 'a':
        // Show advanced options
        setShowAdvancedOptions(!showAdvancedOptions);
        break;

      case key.upArrow:
        // Navigate search history
        if (searchHistory.length > 0) {
          const newIndex = Math.min(historyIndex + 1, searchHistory.length - 1);
          setHistoryIndex(newIndex);
          setSearch({ query: searchHistory[searchHistory.length - 1 - newIndex] });
        }
        break;

      case key.downArrow:
        // Navigate search history
        if (historyIndex > 0) {
          const newIndex = historyIndex - 1;
          setHistoryIndex(newIndex);
          setSearch({ query: searchHistory[searchHistory.length - 1 - newIndex] });
        } else if (historyIndex === 0) {
          setHistoryIndex(-1);
          setSearch({ query: '' });
        }
        break;

      case key.tab && showAdvanced: {
        // Cycle through search fields
        const fields = ['message', 'filePath', 'ruleId', 'toolName'];
        const currentFieldIndex = search.fields.indexOf(
          search.fields[search.fields.length - 1] as 'message' | 'filePath' | 'ruleId' | 'toolName'
        );
        const nextFieldIndex = (currentFieldIndex + 1) % fields.length;
        const newFields = [...search.fields];

        if (key.shift) {
          // Remove last field
          if (newFields.length > 1) {
            newFields.pop();
          }
        } else {
          // Add next field if not already present
          const nextField = fields[nextFieldIndex] as
            | 'message'
            | 'filePath'
            | 'ruleId'
            | 'toolName';
          if (!newFields.includes(nextField)) {
            newFields.push(nextField);
          }
        }

        setSearch({ fields: newFields });
        break;
      }

      case key.ctrl && input === 'h':
        // Clear search history
        setSearchHistory([]);
        setHistoryIndex(-1);
        break;

      case key.return:
        // Trigger search immediately
        if (search.query.trim()) {
          onSearch(search.query.trim());
        }
        break;

      default:
        break;
    }
  });

  const _handleInputChange = (value: string) => {
    setSearch({ query: value });
    setHistoryIndex(-1); // Reset history index when typing
  };

  const _clearSearch = () => {
    setSearch({ query: '' });
    setHistoryIndex(-1);
    setIsFocused(false);
  };

  const getSearchFieldDisplay = () => {
    if (search.fields.length === 4) return 'All';
    if (search.fields.length === 1) return search.fields[0];
    return `${search.fields.length} fields`;
  };

  const getStatusColor = () => {
    if (isLoading) return 'yellow';
    if (search.query.trim()) return 'green';
    return 'gray';
  };

  return (
    <Box flexDirection="column">
      {/* Main search bar */}
      <Box flexDirection="row" alignItems="center">
        <Text color={isFocused ? 'blue' : 'gray'} bold>
          {' '}
          🔍{' '}
        </Text>

        <Box flexGrow={1}>
          <Text color={isFocused ? 'green' : 'gray'}>{search.query || placeholder}</Text>
        </Box>

        {/* Search status */}
        <Box paddingLeft={1}>
          <Text color={getStatusColor()}>
            {isLoading ? '⏳' : search.query.trim() ? '✓' : ' / '}
          </Text>
        </Box>

        {/* Results count */}
        {search.query.trim() && (
          <Box paddingLeft={1}>
            <Text color="cyan">({totalResults} results)</Text>
          </Box>
        )}

        {/* Clear button */}
        {search.query.trim() && (
          <Box paddingLeft={1}>
            <Text color="red">[X]</Text>
          </Box>
        )}
      </Box>

      {/* Search options bar */}
      {showAdvanced && (showAdvancedOptions || search.query.trim()) && (
        <Box flexDirection="row" marginTop={1} paddingX={1} backgroundColor="gray">
          <Text color="black" dimColor>
            Fields: <Text bold>{getSearchFieldDisplay()}</Text>
          </Text>
          <Box paddingLeft={2}>
            <Text color="black" dimColor>
              Case: <Text bold>{search.caseSensitive ? 'Yes' : 'No'}</Text>
            </Text>
          </Box>
          <Box paddingLeft={2}>
            <Text color="black" dimColor>
              Regex: <Text bold>{search.useRegex ? 'Yes' : 'No'}</Text>
            </Text>
          </Box>

          {searchHistory.length > 0 && (
            <Box paddingLeft={2}>
              <Text color="black" dimColor>
                History: {searchHistory.length} items
              </Text>
            </Box>
          )}
        </Box>
      )}

      {/* Help text */}
      {isFocused && (
        <Box flexDirection="row" marginTop={1}>
          <Text color="gray" dimColor>
            [↑↓] History • [Ctrl+R] Regex • [Ctrl+C] Case • [Ctrl+A] Advanced • [Esc] Focus out
            {showAdvanced && ' • [Tab] Fields • [Ctrl+H] Clear history'}
          </Text>
        </Box>
      )}

      {/* Search history dropdown */}
      {isFocused && searchHistory.length > 0 && historyIndex >= 0 && (
        <Box flexDirection="column" marginTop={1} borderStyle="single" borderColor="gray">
          <Text color="gray" bold>
            Search History:
          </Text>
          {searchHistory
            .slice(-5)
            .reverse()
            .map((query, index) => (
              <Box
                key={query}
                flexDirection="row"
                padding={1}
                backgroundColor={index === historyIndex ? 'blue' : undefined}
              >
                <Text color={index === historyIndex ? 'white' : 'black'}>{query}</Text>
              </Box>
            ))}
        </Box>
      )}

      {/* No focus indicator */}
      {!isFocused && (
        <Box flexDirection="row" marginTop={1}>
          <Text color="gray" dimColor>
            Press [/] to focus search
          </Text>
        </Box>
      )}
    </Box>
  );
};

export default SearchBar;

/**
 * Sort controls component
 */

import React from 'react';
import { Box, Text } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import type { SortField, SortOrder } from '../../types/dashboard';

interface SortControlsProps {
  onSortChange?: (field: SortField, order: SortOrder) => void;
}

export function SortControls({
  onSortChange: _onSortChange,
}: SortControlsProps): React.ReactElement {
  const {
    ui: { sortBy, sortOrder },
    setSortOrder,
  } = useDashboardStore();

  const handleSortChange = (field: SortField, order: SortOrder) => {
    setSortOrder(field, order);
    _onSortChange?.(field, order);
  };

  const _toggleSortOrder = (field: SortField) => {
    const newOrder: SortOrder = sortBy === field && sortOrder === 'desc' ? 'asc' : 'desc';
    handleSortChange(field, newOrder);
  };

  const sortFields: Array<{ field: SortField; label: string; width: number }> = [
    { field: 'score', label: 'Score', width: 8 },
    { field: 'severity', label: 'Sev', width: 6 },
    { field: 'filePath', label: 'File', width: 30 },
    { field: 'toolName', label: 'Tool', width: 12 },
    { field: 'lineNumber', label: 'Line', width: 6 },
  ];

  return (
    <Box marginBottom={1} borderStyle="single" borderColor="gray" paddingX={1}>
      <Box justifyContent="space-between">
        {sortFields.map(({ field, label, width: _width }) => {
          const isActive = sortBy === field;
          const orderSymbol = isActive ? (sortOrder === 'asc' ? '↑' : '↓') : ' ';

          return (
            <Box key={field} marginRight={1}>
              <Text color={isActive ? 'cyan' : 'gray'} underline={isActive} bold={isActive}>
                {label}
              </Text>
              <Box marginLeft={1}>
                <Text color={isActive ? 'yellow' : 'gray'}>{orderSymbol}</Text>
              </Box>
            </Box>
          );
        })}
      </Box>
      <Box marginTop={1}>
        <Text color="gray" dimColor>
          Click headers or use Tab to sort
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Trend Chart Component
 * ASCII-based trend visualization for comparison metrics
 */

import React, { useMemo } from 'react';
import { Box, Text } from 'ink';
import type { ComparisonResult } from '../../hooks/useComparisonStore';

interface TrendChartProps {
  trends: ComparisonResult['trends'];
  showCharts: boolean;
  showDiffs: boolean;
}

export const TrendChart: React.FC<TrendChartProps> = ({ trends, showCharts, showDiffs }) => {
  const severityData = useMemo(() => {
    const maxValue = Math.max(...trends.severity.map(t => Math.max(t.baseline, t.comparison)));
    return {
      data: trends.severity.map(trend => ({
        label: trend.type,
        baseline: trend.baseline,
        comparison: trend.comparison,
        diff: trend.diff,
        trend: trend.trend,
      })),
      maxValue,
    };
  }, [trends.severity]);

  const toolsData = useMemo(() => {
    const maxValue = Math.max(...trends.tools.map(t => Math.max(t.baseline, t.comparison)));
    return {
      data: trends.tools.map(trend => ({
        label: trend.tool,
        baseline: trend.baseline,
        comparison: trend.comparison,
        diff: trend.diff,
        trend: trend.trend,
      })),
      maxValue,
    };
  }, [trends.tools]);

  const categoriesData = useMemo(() => {
    const maxValue = Math.max(...trends.categories.map(t => Math.max(t.baseline, t.comparison)));
    return {
      data: trends.categories.map(trend => ({
        label: trend.category,
        baseline: trend.baseline,
        comparison: trend.comparison,
        diff: trend.diff,
        trend: trend.trend,
      })),
      maxValue,
    };
  }, [trends.categories]);

  const createSimpleBarChart = (
    data: Array<{ label: string; baseline: number; comparison: number }>,
    maxValue: number
  ) => {
    const chartWidth = 30;
    const maxBarLength = chartWidth - 10; // Leave space for labels

    return data.map(item => {
      const baselineLength = Math.round((item.baseline / maxValue) * maxBarLength);
      const comparisonLength = Math.round((item.comparison / maxValue) * maxBarLength);

      const baselineBar = '█'.repeat(Math.max(1, baselineLength));
      const comparisonBar = '░'.repeat(Math.max(1, comparisonLength));

      return (
        <Box key={item.label} flexDirection="row">
          <Box width={12}>
            <Text color="gray" dimColor>
              {item.label}
            </Text>
          </Box>
          <Box flexDirection="row" width={chartWidth}>
            <Text color="blue">{baselineBar}</Text>
            <Text color="green">{comparisonBar}</Text>
          </Box>
          <Box width={15}>
            <Text color="gray" dimColor>
              {item.baseline} → {item.comparison}
            </Text>
          </Box>
        </Box>
      );
    });
  };

  const createSparkline = (values: number[]) => {
    if (values.length === 0) return '';

    const min = Math.min(...values);
    const max = Math.max(...values);
    const range = max - min || 1;

    const chars = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█'];
    return values
      .map(value => {
        const normalized = (value - min) / range;
        const index = Math.floor(normalized * (chars.length - 1));
        return chars[Math.min(index, chars.length - 1)];
      })
      .join('');
  };

  const getTrendSymbol = (trend: 'up' | 'down' | 'stable') => {
    switch (trend) {
      case 'up':
        return '📈';
      case 'down':
        return '📉';
      default:
        return '➡️';
    }
  };

  const getTrendColor = (trend: 'up' | 'down' | 'stable') => {
    switch (trend) {
      case 'up':
        return 'red';
      case 'down':
        return 'green';
      default:
        return 'yellow';
    }
  };

  if (!showCharts) {
    return (
      <Box flexDirection="column">
        <Text color="gray">Charts are disabled. Enable them with [C] key.</Text>
      </Box>
    );
  }

  return (
    <Box flexDirection="column">
      {/* Severity Trends */}
      <Box flexDirection="column" marginBottom={2}>
        <Text bold color="blue">
          Severity Trends
        </Text>

        {showDiffs && (
          <Box flexDirection="row" marginTop={1} marginBottom={1}>
            <Box width={12}>
              <Text color="gray" dimColor>
                Type
              </Text>
            </Box>
            <Box width={30}>
              <Text color="gray" dimColor>
                Baseline vs Comparison
              </Text>
            </Box>
            <Box width={15}>
              <Text color="gray" dimColor>
                Values
              </Text>
            </Box>
            <Box width={15}>
              <Text color="gray" dimColor>
                Change
              </Text>
            </Box>
          </Box>
        )}

        {createSimpleBarChart(severityData.data, severityData.maxValue)}

        {showDiffs && (
          <Box flexDirection="column" marginTop={1}>
            {severityData.data.map(trend => (
              <Box key={trend.label} flexDirection="row">
                <Box width={12}>
                  <Text color="gray" dimColor>
                    {trend.label}
                  </Text>
                </Box>
                <Box width={30}>
                  <Text color="gray" dimColor>
                    {createSparkline([trend.baseline, trend.comparison])}
                  </Text>
                </Box>
                <Box width={15}>
                  <Text color="gray" dimColor>
                    {trend.baseline} → {trend.comparison}
                  </Text>
                </Box>
                <Box width={15}>
                  <Text color={getTrendColor(trend.trend)} dimColor>
                    {getTrendSymbol(trend.trend)} {trend.diff > 0 ? '+' : ''}
                    {trend.diff}
                  </Text>
                </Box>
              </Box>
            ))}
          </Box>
        )}
      </Box>

      {/* Tools Trends */}
      <Box flexDirection="column" marginBottom={2}>
        <Text bold color="blue">
          Tool Trends
        </Text>

        {showDiffs && (
          <Box flexDirection="row" marginTop={1} marginBottom={1}>
            <Box width={12}>
              <Text color="gray" dimColor>
                Tool
              </Text>
            </Box>
            <Box width={30}>
              <Text color="gray" dimColor>
                Baseline vs Comparison
              </Text>
            </Box>
            <Box width={15}>
              <Text color="gray" dimColor>
                Values
              </Text>
            </Box>
            <Box width={15}>
              <Text color="gray" dimColor>
                Change
              </Text>
            </Box>
          </Box>
        )}

        {createSimpleBarChart(toolsData.data, toolsData.maxValue)}

        {showDiffs && (
          <Box flexDirection="column" marginTop={1}>
            {toolsData.data.map(trend => (
              <Box key={trend.label} flexDirection="row">
                <Box width={12}>
                  <Text color="gray" dimColor>
                    {trend.label}
                  </Text>
                </Box>
                <Box width={30}>
                  <Text color="gray" dimColor>
                    {createSparkline([trend.baseline, trend.comparison])}
                  </Text>
                </Box>
                <Box width={15}>
                  <Text color="gray" dimColor>
                    {trend.baseline} → {trend.comparison}
                  </Text>
                </Box>
                <Box width={15}>
                  <Text color={getTrendColor(trend.trend)} dimColor>
                    {getTrendSymbol(trend.trend)} {trend.diff > 0 ? '+' : ''}
                    {trend.diff}
                  </Text>
                </Box>
              </Box>
            ))}
          </Box>
        )}
      </Box>

      {/* Categories Trends */}
      <Box flexDirection="column" marginBottom={2}>
        <Text bold color="blue">
          Category Trends
        </Text>

        {showDiffs && (
          <Box flexDirection="row" marginTop={1} marginBottom={1}>
            <Box width={12}>
              <Text color="gray" dimColor>
                Category
              </Text>
            </Box>
            <Box width={30}>
              <Text color="gray" dimColor>
                Baseline vs Comparison
              </Text>
            </Box>
            <Box width={15}>
              <Text color="gray" dimColor>
                Values
              </Text>
            </Box>
            <Box width={15}>
              <Text color="gray" dimColor>
                Change
              </Text>
            </Box>
          </Box>
        )}

        {createSimpleBarChart(categoriesData.data, categoriesData.maxValue)}

        {showDiffs && (
          <Box flexDirection="column" marginTop={1}>
            {categoriesData.data.map(trend => (
              <Box key={trend.label} flexDirection="row">
                <Box width={12}>
                  <Text color="gray" dimColor>
                    {trend.label}
                  </Text>
                </Box>
                <Box width={30}>
                  <Text color="gray" dimColor>
                    {createSparkline([trend.baseline, trend.comparison])}
                  </Text>
                </Box>
                <Box width={15}>
                  <Text color="gray" dimColor>
                    {trend.baseline} → {trend.comparison}
                  </Text>
                </Box>
                <Box width={15}>
                  <Text color={getTrendColor(trend.trend)} dimColor>
                    {getTrendSymbol(trend.trend)} {trend.diff > 0 ? '+' : ''}
                    {trend.diff}
                  </Text>
                </Box>
              </Box>
            ))}
          </Box>
        )}
      </Box>

      {/* Legend */}
      <Box flexDirection="row" marginTop={2} borderTop={true} paddingY={1}>
        <Box flexDirection="row">
          <Text color="blue" dimColor>
            █ Baseline
          </Text>
          <Box paddingLeft={2}>
            <Text color="gray" dimColor>
              ░ Comparison
            </Text>
          </Box>
          <Box paddingLeft={2}>
            <Text color="gray" dimColor>
