/**
 * Triage Suggestion Component
 * Displays automated triage recommendations with actions
 */

import React from 'react';
import { Box, Text, useInput } from 'ink';
import type { TriageSuggestion as TriageSuggestionType } from '@dev-quality/types';

interface TriageSuggestionProps {
  suggestion: TriageSuggestionType;
  onAccept?: () => void;
  onReject?: () => void;
  interactive?: boolean;
}

const getActionColor = (action: string): string => {
  switch (action) {
    case 'fix-now':
      return 'red';
    case 'schedule':
      return 'yellow';
    case 'delegate':
      return 'blue';
    case 'monitor':
      return 'cyan';
    case 'ignore':
      return 'gray';
    default:
      return 'white';
  }
};

const getConfidenceColor = (confidence: number): string => {
  if (confidence >= 0.8) return 'green';
  if (confidence >= 0.6) return 'yellow';
  if (confidence >= 0.4) return 'orange';
  return 'red';
};

export const TriageSuggestion: React.FC<TriageSuggestionProps> = ({
  suggestion,
  onAccept,
  onReject,
  interactive = false,
}) => {
  const [selectedIndex, setSelectedIndex] = React.useState(0);
  const actions = ['accept', 'reject'];

  useInput((input, key) => {
    if (!interactive) return;

    if (key.leftArrow) {
      setSelectedIndex(prev => (prev - 1 + actions.length) % actions.length);
    } else if (key.rightArrow) {
      setSelectedIndex(prev => (prev + 1) % actions.length);
    } else if (key.return) {
      if (selectedIndex === 0 && onAccept) {
        onAccept();
      } else if (selectedIndex === 1 && onReject) {
        onReject();
      }
    }
  });

  return (
    <Box flexDirection="column" padding={1}>
      <Box marginBottom={1}>
        <Text bold color={getActionColor(suggestion.action)}>
          {suggestion.action.toUpperCase()}
        </Text>
        <Text> (Priority: {suggestion.priority}/10)</Text>
      </Box>

      <Box marginBottom={1}>
        <Text color="gray">Reasoning: </Text>
        <Text>{suggestion.reasoning}</Text>
      </Box>

      <Box marginBottom={1}>
        <Text color="gray">Effort: </Text>
        <Text>{suggestion.estimatedEffort}h</Text>
        <Text color="gray"> | Confidence: </Text>
        <Text color={getConfidenceColor(suggestion.confidence)}>
          {(suggestion.confidence * 100).toFixed(0)}%
        </Text>
      </Box>

      {suggestion.assignee && (
        <Box marginBottom={1}>
          <Text color="gray">Assignee: </Text>
          <Text>{suggestion.assignee}</Text>
        </Box>
      )}

      {suggestion.deadline && (
        <Box marginBottom={1}>
          <Text color="gray">Deadline: </Text>
          <Text>{suggestion.deadline.toLocaleDateString()}</Text>
        </Box>
      )}

      {interactive && (
        <Box marginTop={1}>
          {actions.map((action, index) => (
            <Box key={action} marginRight={1}>
              <Text
                color={index === selectedIndex ? 'blue' : 'gray'}
                underline={index === selectedIndex}
              >
                [{action.toUpperCase()}]
              </Text>
            </Box>
          ))}
          <Text color="gray"> (Use arrow keys and Enter to select)</Text>
        </Box>
      )}
    </Box>
  );
};

export default TriageSuggestion;

/**
 * Virtualized issue list for handling large datasets efficiently
 */

import React, { useState, useEffect, useMemo } from 'react';
import { Box, Text, useInput } from 'ink';
import { useDashboardStore } from '../../hooks/useDashboardStore';
import { createListNavigation } from '../../utils/keyboard-navigation';
import { IssueItem } from '../issues/issue-item';
import { transformCoreIssueToCLI } from '../../utils/type-transformers';
import type { Issue } from '@dev-quality/core';
import type { VirtualizationConfig } from '../../types/dashboard';

interface VirtualizedIssueListProps {
  issues: Issue[];
  itemsPerPage?: number;
  bufferItems?: number;
}

export function VirtualizedIssueList({
  issues,
  itemsPerPage = 10,
  bufferItems = 5,
}: VirtualizedIssueListProps): React.ReactElement {
  const {
    selectedIssue: _selectedIssue,
    setSelectedIssue,
    setCurrentView,
    addToNavigationHistory,
  } = useDashboardStore();

  const [selectedIndex, setSelectedIndexState] = useState(0);
  const [scrollTop, setScrollTop] = useState(0);

  // Calculate virtualization
  const _virtualization: VirtualizationConfig = useMemo(
    () => ({
      windowSize: itemsPerPage,
      bufferItems,
      totalItems: issues.length,
      scrollTop,
    }),
    [itemsPerPage, bufferItems, issues.length, scrollTop]
  );

  // Calculate visible range with buffer
  const visibleRange = useMemo(() => {
    const bufferedStart = Math.max(0, scrollTop - bufferItems);
    const bufferedEnd = Math.min(issues.length, scrollTop + itemsPerPage + bufferItems);
    return { start: bufferedStart, end: bufferedEnd };
  }, [scrollTop, itemsPerPage, bufferItems, issues.length]);

  // Get visible issues
  const visibleIssues = useMemo(() => {
    return issues.slice(visibleRange.start, visibleRange.end);
  }, [issues, visibleRange]);

  // Create navigation handler
  const navigationHandler = useMemo(() => {
    return createListNavigation(
      issues.length,
      index => {
        const issue = issues[index];
        if (issue) {
          setSelectedIssue(transformCoreIssueToCLI(issue));
          setCurrentView('issue-details');
          addToNavigationHistory('issue-details', index);
        }
      },
      { wrapAround: true, skipDisabled: true, pageSize: Math.floor(itemsPerPage / 2) }
    );
  }, [issues, itemsPerPage, setSelectedIssue, setCurrentView, addToNavigationHistory]);

  // Handle keyboard input
  useInput((_input, key) => {
    let newIndex = selectedIndex;

    if (key.upArrow || _input === 'k') {
      newIndex = navigationHandler.handleKeyDown('up', selectedIndex);
    } else if (key.downArrow || _input === 'j') {
      newIndex = navigationHandler.handleKeyDown('down', selectedIndex);
    } else if (key.ctrl && _input === 'a') {
      // Ctrl+A for home
      newIndex = navigationHandler.handleKeyDown('home', selectedIndex);
    } else if (key.ctrl && _input === 'e') {
      // Ctrl+E for end
      newIndex = navigationHandler.handleKeyDown('end', selectedIndex);
    } else if (key.pageUp) {
      newIndex = navigationHandler.handleKeyDown('pageup', selectedIndex);
    } else if (key.pageDown) {
      newIndex = navigationHandler.handleKeyDown('pagedown', selectedIndex);
    } else if (key.return) {
      navigationHandler.handleKeyDown('enter', selectedIndex);
      return;
    } else if (_input >= '1' && _input <= '9') {
      const numericIndex = parseInt(_input) - 1;
      if (numericIndex < issues.length) {
        newIndex = numericIndex;
        navigationHandler.handleKeyDown('enter', numericIndex);
      }
    }

    if (newIndex !== selectedIndex) {
      setSelectedIndexState(newIndex);

      // Update scroll position if needed
      if (newIndex < scrollTop + bufferItems) {
        setScrollTop(Math.max(0, newIndex - bufferItems));
      } else if (newIndex >= scrollTop + itemsPerPage - bufferItems) {
        setScrollTop(Math.min(issues.length - itemsPerPage, newIndex - itemsPerPage + bufferItems));
      }

      // Auto-select the issue
      const issue = issues[newIndex];
      if (issue) {
        setSelectedIssue(transformCoreIssueToCLI(issue));
      }
    }
  });

  // Update selected issue when selectedIndex changes
  useEffect(() => {
    if (issues[selectedIndex]) {
      setSelectedIssue(transformCoreIssueToCLI(issues[selectedIndex]));
    }
  }, [selectedIndex, issues, setSelectedIssue]);

  // Reset scroll when issues change
  useEffect(() => {
    setScrollTop(0);
    setSelectedIndexState(0);
  }, [issues.length]);

  // Calculate display offset for visible items
  const getDisplayOffset = (index: number): number => {
    return index - visibleRange.start;
  };

  if (issues.length === 0) {
    return (
      <Box justifyContent="center" padding={2}>
        <Text color="gray">No issues found</Text>
      </Box>
    );
  }

  return (
    <Box flexDirection="column">
      {/* Header with virtualization info */}
      <Box marginBottom={1}>
        <Text color="gray" dimColor>
          Showing {visibleRange.start + 1}-{Math.min(visibleRange.end, issues.length)} of{' '}
          {issues.length} issues
        </Text>
        {issues.length > itemsPerPage && (
          <Box marginLeft={2}>
            <Text color="gray" dimColor>
              (Virtualized: {itemsPerPage} items, {bufferItems} buffer)
            </Text>
          </Box>
        )}
      </Box>

      {/* Virtualized list */}
      <Box flexDirection="column" height={itemsPerPage}>
        {visibleIssues.map((issue, visibleIndex) => {
          const actualIndex = visibleRange.start + visibleIndex;
          const isSelected = actualIndex === selectedIndex;
          const displayOffset = getDisplayOffset(actualIndex);

          // Only render if within visible window
          if (displayOffset < 0 || displayOffset >= itemsPerPage + bufferItems * 2) {
            return null;
          }

          return (
            <Box key={issue.id}>
              <IssueItem issue={issue} isSelected={isSelected} index={actualIndex} />
            </Box>
          );
        })}
      </Box>

      {/* Footer with navigation hints */}
      <Box marginTop={1}>
        <Text color="gray" dimColor>
          ↑↓ Navigate | Enter: Details | 1-9: Quick jump | Home/End: First/Last | Page Up/Down:
          Navigate
        </Text>
      </Box>
    </Box>
  );
}

/**
 * Virtualized Navigator List Component
 * Optimized for handling large datasets (10K+ items) with virtual scrolling
 */

import React from 'react';
import { Box, Text, useInput } from 'ink';
import type { Issue } from '../../types/analysis';
import type { IssueWithPriority } from '../../types/dashboard';

interface VirtualizedNavigatorListProps {
  items: (Issue | IssueWithPriority)[];
  selectedIndex: number;
  onSelect: (item: Issue | IssueWithPriority, index: number) => void;
  renderItem?: (
    item: Issue | IssueWithPriority,
    index: number,
    isSelected: boolean
  ) => React.ReactNode;
  getItemKey?: (item: Issue | IssueWithPriority, index: number) => string;
  height?: number;
  windowSize?: number;
  itemHeight?: number;
}

interface VirtualizedItem {
  item: Issue | IssueWithPriority;
  index: number;
  key: string;
}

export const VirtualizedNavigatorList: React.FC<VirtualizedNavigatorListProps> = ({
  items,
  selectedIndex,
  onSelect,
  renderItem,
  getItemKey,
  height = 20,
  windowSize = 10,
  itemHeight = 2,
}) => {
  const [scrollTop, setScrollTop] = React.useState(0);
  const [isNavigating, setIsNavigating] = React.useState(false);

  // Calculate visible window
  const startIndex = items.length === 0 ? 0 : Math.floor(scrollTop / itemHeight);
  const endIndex = items.length === 0 ? 0 : Math.min(startIndex + windowSize, items.length - 1);
  const visibleItems = items.length === 0 ? [] : items.slice(startIndex, endIndex + 1);

  // Default item key generator
  const defaultGetItemKey = (item: Issue | IssueWithPriority, index: number): string => {
    return item.id || `item-${index}`;
  };

  const keyGenerator = getItemKey ?? defaultGetItemKey;

  // Default render item
  const defaultRenderItem = (
    item: Issue | IssueWithPriority,
    index: number,
    isSelected: boolean
  ): React.ReactNode => {
    const isPriorityIssue = 'priorityScore' in item;
    const issueNumber = startIndex + index + 1;
    const truncatedMessage =
      item.message.length > 50 ? item.message.slice(0, 50) + '...' : item.message;

    return (
      <Box key={keyGenerator(item, startIndex + index)}>
        <Box flexDirection="row" justifyContent="space-between" paddingX={1}>
          <Box>
            <Text color={isSelected ? 'blue' : 'white'}>
              {issueNumber}. {truncatedMessage}
            </Text>
          </Box>
          <Box flexDirection="row" gap={2}>
            <Text color={getSeverityColor(item.type)}>{item.type.toUpperCase()}</Text>
            {isPriorityIssue && item.priorityScore && (
              <Text color={getPriorityColor(item.priorityScore)}>
                P:{item.priorityScore.toFixed(1)}
              </Text>
            )}
            <Text color="gray">{item.toolName}</Text>
          </Box>
        </Box>
      </Box>
    );
  };

  const itemRenderer = renderItem ?? defaultRenderItem;

  // Handle keyboard navigation
  useInput((input, key) => {
    if (isNavigating) return;

    setIsNavigating(true);

    if (key.upArrow && selectedIndex > 0) {
      const newIndex = selectedIndex - 1;
      const newScrollTop = Math.max(0, newIndex * itemHeight - (windowSize * itemHeight) / 2);
      setScrollTop(newScrollTop);
      const selectedItem = items[newIndex];
      if (selectedItem) onSelect(selectedItem, newIndex);
    } else if (key.downArrow && selectedIndex < items.length - 1) {
      const newIndex = selectedIndex + 1;
      const newScrollTop = Math.max(0, newIndex * itemHeight - (windowSize * itemHeight) / 2);
      setScrollTop(newScrollTop);
      const selectedItem = items[newIndex];
      if (selectedItem) onSelect(selectedItem, newIndex);
    } else if (key.pageUp && selectedIndex > 0) {
      const newIndex = Math.max(0, selectedIndex - windowSize);
      const newScrollTop = Math.max(0, newIndex * itemHeight - (windowSize * itemHeight) / 2);
      setScrollTop(newScrollTop);
      const selectedItem = items[newIndex];
      if (selectedItem) onSelect(selectedItem, newIndex);
    } else if (key.pageDown && selectedIndex < items.length - 1) {
      const newIndex = Math.min(items.length - 1, selectedIndex + windowSize);
      const newScrollTop = Math.max(0, newIndex * itemHeight - (windowSize * itemHeight) / 2);
      setScrollTop(newScrollTop);
      const selectedItem = items[newIndex];
      if (selectedItem) onSelect(selectedItem, newIndex);
    } else if (key.return) {
      const selectedItem = items[selectedIndex];
      if (selectedItem) onSelect(selectedItem, selectedIndex);
    } else if (input >= '1' && input <= '9') {
      const index = parseInt(input) - 1;
      if (index < items.length) {
        const newScrollTop = Math.max(0, index * itemHeight - (windowSize * itemHeight) / 2);
        setScrollTop(newScrollTop);
        const selectedItem = items[index];
        if (selectedItem) onSelect(selectedItem, index);
      }
    }

    // Reset navigation flag after a short delay
    setTimeout(() => setIsNavigating(false), 100);
  });

  const renderVirtualizedItem = (item: VirtualizedItem, index: number) => {
    const isSelected = startIndex + index === selectedIndex;
    return itemRenderer(item.item, startIndex + index, isSelected);
  };

  return (
    <Box flexDirection="column" height={height}>
      {/* Header with stats */}
      <Box flexDirection="row" justifyContent="space-between" marginBottom={1} paddingX={1}>
        <Text color="gray">
          Showing {items.length === 0 ? 0 : startIndex + 1}-{items.length === 0 ? 0 : endIndex + 1}{' '}
          of {items.length} items
        </Text>
        <Text color="gray">
          Selected: {items.length === 0 ? 0 : selectedIndex + 1}/{items.length}
        </Text>
      </Box>

      {/* Virtualized list */}
      <Box flexDirection="column" borderStyle="round" borderColor="gray">
        {visibleItems.map((item, index) => {
          const virtualItem: VirtualizedItem = {
            item,
            index: startIndex + index,
            key: keyGenerator(item, startIndex + index),
          };
          return renderVirtualizedItem(virtualItem, index);
        })}
      </Box>

      {/* Scroll indicator */}
      {items.length > windowSize && (
        <Box marginTop={1}>
          <Text color="gray">
            Scroll: {Math.round((scrollTop / (items.length * itemHeight - height)) * 100)}%
          </Text>
        </Box>
      )}

      {/* Navigation help */}
      <Box marginTop={1}>
        <Text color="gray" italic>
          Navigation: ↑↓ Page↑↓ Home End [1-9] | Enter to select
        </Text>
      </Box>
    </Box>
  );
};

/**
 * Get color for severity level
 */
function getSeverityColor(severity: string): string {
  switch (severity) {
    case 'error':
      return 'red';
    case 'warning':
      return 'yellow';
    case 'info':
      return 'blue';
    default:
      return 'gray';
  }
}

/**
 * Get color for priority score
 */
function getPriorityColor(score: number): string {
  if (score >= 8) return 'red';
  if (score >= 6) return 'yellow';
  if (score >= 4) return 'blue';
  return 'green';
}

export default VirtualizedNavigatorList;

/**
 * Widget Registry for dynamic widget loading and management
 */

import type { WidgetConfig, WidgetRegistration, WidgetFactory } from './base-widget';
import { BaseWidget } from './base-widget';
import type { ReactElement } from 'react';

class WidgetRegistryImpl {
  private widgets = new Map<string, WidgetRegistration>();
  private instances = new Map<string, WidgetFactory>();

  /**
   * Register a new widget type
   */
  register(registration: WidgetRegistration): void {
    this.widgets.set(registration.type, registration);
  }

  /**
   * Get widget registration by type
   */
  getRegistration(type: string): WidgetRegistration | undefined {
    return this.widgets.get(type);
  }

  /**
   * Get all registered widget types
   */
  getAllRegistrations(): WidgetRegistration[] {
    return Array.from(this.widgets.values());
  }

  /**
   * Create a widget instance
   */
  createWidget(
    config: WidgetConfig,
    isSelected: boolean,
    onSelect: (widgetId: string) => void,
    onUpdate: (widgetId: string, updates: Partial<WidgetConfig>) => void
  ): ReactElement | null {
    const registration = this.widgets.get(config.type);
    if (!registration) {
      return null;
    }

    const factory = registration.factory;
    return factory(config, isSelected, onSelect, onUpdate);
  }

  /**
   * Get default configuration for a widget type
   */
  getDefaultConfig(type: string, overrides: Partial<WidgetConfig> = {}): WidgetConfig | null {
    const registration = this.widgets.get(type);
    if (!registration) {
      return null;
    }

    return {
      id: `widget-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type: type as WidgetConfig['type'],
      position: { x: 0, y: 0, width: 60, height: 15 },
      config: {},
      visible: true,
      ...registration.defaultConfig,
      ...overrides,
    };
  }

  /**
   * Validate widget configuration
   */
  validateConfig(config: WidgetConfig): { isValid: boolean; errors: string[] } {
    const errors: string[] = [];
    const registration = this.widgets.get(config.type);

    if (!registration) {
      errors.push(`Unknown widget type: ${config.type}`);
      return { isValid: false, errors };
    }

    // Validate position
    if (config.position.width < registration.minSize.width) {
      errors.push(`Width must be at least ${registration.minSize.width}`);
    }
    if (config.position.height < registration.minSize.height) {
      errors.push(`Height must be at least ${registration.minSize.height}`);
    }
    if (config.position.width > registration.maxSize.width) {
      errors.push(`Width must not exceed ${registration.maxSize.width}`);
    }
    if (config.position.height > registration.maxSize.height) {
      errors.push(`Height must not exceed ${registration.maxSize.height}`);
    }

    // Validate position coordinates
    if (config.position.x < 0) {
      errors.push('X position cannot be negative');
    }
    if (config.position.y < 0) {
      errors.push('Y position cannot be negative');
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }

  /**
   * Get available widget types for user selection
   */
  getAvailableWidgetTypes(): Array<{
    type: string;
    name: string;
    description: string;
  }> {
    return this.getAllRegistrations().map(reg => ({
      type: reg.type,
      name: reg.name,
      description: reg.description,
    }));
  }
}

