import React from 'react';
import { Box, Text, useInput } from 'ink';
import { WizardStepProps } from './wizard-container';

export interface ValidationResult {
  tool: string;
  status: 'success' | 'warning' | 'error';
  message: string;
  configPath?: string;
}

export interface SummaryScreenProps extends WizardStepProps {
  validationResults: ValidationResult[];
  generatedFiles: string[];
  onRunAnalysis?: () => Promise<void>;
}

export function SummaryScreen({
  validationResults,
  generatedFiles,
  onNext,
  onRunAnalysis,
}: Omit<SummaryScreenProps, 'data'>): React.ReactElement {
  const [isRunningAnalysis, setIsRunningAnalysis] = React.useState(false);

  useInput(async input => {
    if (input === 'y' || input === 'Y') {
      if (onRunAnalysis) {
        setIsRunningAnalysis(true);
        await onRunAnalysis();
      }
      onNext();
    } else if (input === 'n' || input === 'N') {
      onNext();
    }
  });

  const hasErrors = validationResults.some(result => result.status === 'error');
  const hasWarnings = validationResults.some(result => result.status === 'warning');

  return (
    <Box flexDirection="column">
      <Box marginBottom={1}>
        <Text bold color="green">
          🎉 Setup Wizard Completed!
        </Text>
      </Box>

      <Box marginBottom={1}>
        <Text dimColor>{'─'.repeat(50)}</Text>
      </Box>

      <Box flexDirection="column" marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold>Configuration Summary:</Text>
        </Box>

        {validationResults.map(result => (
          <Box key={result.tool} marginBottom={1} flexDirection="column">
            <Box>
              <Text>
                {result.status === 'success' && <Text color="green">✓</Text>}
                {result.status === 'warning' && <Text color="yellow">⚠</Text>}
                {result.status === 'error' && <Text color="red">✗</Text>}
                <Text> {result.tool}</Text>
              </Text>
            </Box>
            <Box marginLeft={2}>
              <Text dimColor>{result.message}</Text>
            </Box>
            {result.configPath && (
              <Box marginLeft={2}>
                <Text dimColor>Config: {result.configPath}</Text>
              </Box>
            )}
          </Box>
        ))}
      </Box>

      <Box marginBottom={1}>
        <Text dimColor>{'─'.repeat(50)}</Text>
      </Box>

      <Box flexDirection="column" marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold>Generated Files:</Text>
        </Box>

        {generatedFiles.length > 0 ? (
          generatedFiles.map(file => (
            <Box key={file} marginLeft={2}>
              <Text dimColor>• {file}</Text>
            </Box>
          ))
        ) : (
          <Box marginLeft={2}>
            <Text dimColor>No new files generated</Text>
          </Box>
        )}
      </Box>

      <Box marginBottom={1}>
        <Text dimColor>{'─'.repeat(50)}</Text>
      </Box>

      {hasErrors && (
        <Box flexDirection="column" marginBottom={1}>
          <Box marginBottom={1}>
            <Text color="red" bold>
              ⚠ Some configurations failed validation
            </Text>
          </Box>
          <Box>
            <Text>Please review the errors above and fix them manually.</Text>
          </Box>
        </Box>
      )}

      {hasWarnings && !hasErrors && (
        <Box flexDirection="column" marginBottom={1}>
          <Box marginBottom={1}>
            <Text color="yellow" bold>
              ⚠ Some configurations have warnings
            </Text>
          </Box>
          <Box>
            <Text>The setup completed, but you may want to review the warnings above.</Text>
          </Box>
        </Box>
      )}

      {!hasErrors && !hasWarnings && (
        <Box flexDirection="column" marginBottom={1}>
          <Box>
            <Text color="green">✓ All configurations validated successfully!</Text>
          </Box>
        </Box>
      )}

      <Box flexDirection="column" marginTop={1} marginBottom={1}>
        <Box marginBottom={1}>
          <Text bold>Next Steps:</Text>
        </Box>
        <Box marginLeft={2}>
          <Text>1. Review the generated configuration files</Text>
        </Box>
        <Box marginLeft={2}>
          <Text>2. Customize configurations as needed for your project</Text>
        </Box>
        <Box marginLeft={2}>
          <Text>3. Run 'dev-quality analyze' to analyze your project</Text>
        </Box>
        <Box marginLeft={2}>
          <Text>4. Run 'dev-quality report' to generate quality reports</Text>
        </Box>
      </Box>

      {!isRunningAnalysis && !hasErrors && onRunAnalysis && (
        <Box marginTop={1}>
          <Text>
            Run initial analysis now?{' '}
            <Text bold color="green">
              (Y)es
            </Text>{' '}
            /{' '}
            <Text bold color="yellow">
              (N)o
            </Text>
          </Text>
        </Box>
      )}

      {isRunningAnalysis && (
        <Box marginTop={1}>
          <Text color="cyan">⏳ Running initial analysis...</Text>
        </Box>
      )}

      {(hasErrors || !onRunAnalysis) && (
        <Box marginTop={1}>
          <Text>
            Press <Text bold>(Y)</Text> to exit
          </Text>
        </Box>
      )}
    </Box>
  );
}

import React from 'react';
import { Box, Text, useInput } from 'ink';
import { WizardStepProps } from './wizard-container';
import { DetectionResult } from '@dev-quality/core';

export interface WelcomeScreenProps extends WizardStepProps {
  detectionResult?: DetectionResult;
}

export function WelcomeScreen({
  onNext,
  onCancel,
  detectionResult,
}: Omit<WelcomeScreenProps, 'data'>): React.ReactElement {
  const [isReady, setIsReady] = React.useState(false);

  useInput(input => {
    if (input === 'y' || input === 'Y') {
      setIsReady(true);
      onNext({ detectionResult });
    } else if (input === 'n' || input === 'N') {
      onCancel();
    }
  });

  return (
    <Box flexDirection="column">
      <Box marginBottom={1}>
        <Text>Welcome to the DevQuality Setup Wizard!</Text>
      </Box>

      <Box marginBottom={1}>
        <Text>
          This wizard will guide you through configuring the Bun-based tool stack for your project.
        </Text>
      </Box>

      {detectionResult && (
        <Box flexDirection="column" marginBottom={1}>
          <Box marginBottom={1}>
            <Text bold color="cyan">
              Project Detection Summary:
            </Text>
          </Box>

          <Box marginBottom={1}>
            <Text>
              • Project: <Text bold>{detectionResult.project.name}</Text>
            </Text>
          </Box>

          <Box marginBottom={1}>
            <Text>
              • Type: <Text bold>{detectionResult.project.type}</Text>
            </Text>
          </Box>

          {detectionResult.project.frameworks.length > 0 && (
            <Box marginBottom={1}>
              <Text>
                • Frameworks: <Text bold>{detectionResult.project.frameworks.join(', ')}</Text>
              </Text>
            </Box>
          )}

          <Box marginBottom={1}>
            <Text>
              • Tools Found: <Text bold>{detectionResult.tools.length}</Text>
            </Text>
          </Box>

          {detectionResult.tools.length > 0 && (
            <Box flexDirection="column" marginLeft={2}>
              {detectionResult.tools.map(tool => (
                <Box key={tool.name}>
                  <Text>
                    - {tool.name} <Text dimColor>({tool.version})</Text>
                  </Text>
                </Box>
              ))}
            </Box>
          )}

          <Box marginBottom={1} marginTop={1}>
            <Text>
              • Source Directories:{' '}
              <Text bold>{detectionResult.structure.sourceDirectories.join(', ')}</Text>
            </Text>
          </Box>

          <Box marginBottom={1}>
            <Text>
              • Test Directories:{' '}
              <Text bold>{detectionResult.structure.testDirectories.join(', ')}</Text>
            </Text>
          </Box>
        </Box>
      )}

      <Box marginTop={1} marginBottom={1}>
        <Text>The wizard will configure the following tools:</Text>
      </Box>

      <Box flexDirection="column" marginLeft={2} marginBottom={1}>
        <Box>
          <Text>• Bun Test (test runner with coverage)</Text>
        </Box>
        <Box>
          <Text>• ESLint (code linting)</Text>
        </Box>
        <Box>
          <Text>• Prettier (code formatting)</Text>
        </Box>
        <Box>
          <Text>• TypeScript (type checking)</Text>
        </Box>
      </Box>

      <Box marginTop={1}>
        <Text>
          Continue with setup?{' '}
          <Text bold color="green">
            (Y)es
          </Text>{' '}
          /{' '}
          <Text bold color="red">
            (N)o
          </Text>
        </Text>
      </Box>

      {isReady && (
        <Box marginTop={1}>
          <Text color="cyan">Starting configuration...</Text>
        </Box>
      )}
    </Box>
  );
}

import React from 'react';
import { Box, Text, useInput, useApp } from 'ink';

export interface WizardStep {
  id: string;
  title: string;
  component: React.ComponentType<WizardStepProps>;
}

export interface WizardStepProps {
  current: number;
  total: number;
  onNext: (stepData?: Record<string, unknown>) => void;
  onBack: () => void;
  onCancel: () => void;
  data?: Record<string, unknown>;
}

export interface WizardContainerProps {
  steps: WizardStep[];
  onComplete: (wizardData: Record<string, unknown>) => void;
  onCancel: () => void;
}

export function WizardContainer({
  steps,
  onComplete,
  onCancel,
}: WizardContainerProps): React.ReactElement {
  const [currentStep, setCurrentStep] = React.useState(0);
  const [wizardData, setWizardData] = React.useState<Record<string, unknown>>({});
  const { exit } = useApp();

  const handleNext = React.useCallback(
    (stepData?: Record<string, unknown>) => {
      const newData = { ...wizardData, ...stepData };
      setWizardData(newData);

      if (currentStep < steps.length - 1) {
        setCurrentStep(currentStep + 1);
      } else {
        onComplete(newData);
      }
    },
    [currentStep, steps.length, wizardData, onComplete]
  );

  const handleBack = React.useCallback(() => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  }, [currentStep]);

  const handleCancel = React.useCallback(() => {
    onCancel();
    exit();
  }, [onCancel, exit]);

  useInput((input, key) => {
    if (key.escape || (input === 'c' && key.ctrl)) {
      handleCancel();
    }
  });

  const currentStepData = steps[currentStep];
  const StepComponent = currentStepData?.component;

  if (!StepComponent) {
    return (
      <Box>
        <Text color="red">Error: Invalid wizard step</Text>
      </Box>
    );
  }

  return (
    <Box flexDirection="column" padding={1}>
      <Box marginBottom={1}>
        <Text bold color="cyan">
          Setup Wizard - {currentStepData.title}
        </Text>
      </Box>

      <Box marginBottom={1}>
        <Text dimColor>
          Step {currentStep + 1} of {steps.length}
        </Text>
      </Box>

      <Box marginBottom={1}>
        <Text dimColor>{'─'.repeat(50)}</Text>
      </Box>

      <StepComponent
        current={currentStep}
        total={steps.length}
        onNext={handleNext}
        onBack={handleBack}
        onCancel={handleCancel}
        data={wizardData}
      />

      <Box marginTop={1}>
        <Text dimColor>{'─'.repeat(50)}</Text>
      </Box>

      <Box marginTop={1}>
        <Text dimColor>Press ESC or Ctrl+C to cancel</Text>
      </Box>
    </Box>
  );
}

/**
 * Hook for managing analysis results in the dashboard
 */

import { useState, useEffect, useCallback } from 'react';
import { useDashboardStore } from './useDashboardStore';
import { DashboardEngineIntegration } from '../services/dashboard/dashboard-engine-integration';
import { MockAnalysisEngine } from '../services/analysis/mock-analysis-engine';
import type { AnalysisResult } from '../types';
import type { AnalysisProgress, ToolResult, AnalysisEngine } from '@dev-quality/core';
import type { ProjectConfiguration } from '@dev-quality/types';
import type { DashboardData } from '../types/dashboard';

export function useAnalysisResults() {
  const { setAnalysisResult, setAnalysisProgress, setAnalyzing, updateFilteredIssues } =
    useDashboardStore();

  const [integration] = useState(() => new DashboardEngineIntegration());
  const [analysisError, setAnalysisError] = useState<Error | null>(null);
  const [lastAnalysisData, setLastAnalysisData] = useState<DashboardData | null>(null);

  // Initialize analysis engine if available
  useEffect(() => {
    // Initialize with mock engine for development
    const initializeEngine = async () => {
      try {
        const mockEngine = new MockAnalysisEngine();
        await mockEngine.initialize();
        integration.setAnalysisEngine(mockEngine as unknown as AnalysisEngine);
      } catch (error) {
        setAnalysisError(error instanceof Error ? error : new Error(String(error)));
      }
    };

    initializeEngine();
  }, [integration]);

  // Execute analysis with real-time updates
  const executeAnalysis = useCallback(
    async (
      projectId: string,
      config: ProjectConfiguration,
      options: {
        plugins?: string[];
        incremental?: boolean;
        timeout?: number;
      } = {}
    ): Promise<{
      success: boolean;
      result?: AnalysisResult;
      error?: Error;
    }> => {
      setAnalysisError(null);
      setAnalyzing(true);
      setAnalysisProgress(null);

      try {
        // Set up progress tracking
        const onProgress = (progress: AnalysisProgress) => {
          setAnalysisProgress(progress);
        };

        // Execute analysis with dashboard integration
        const result = await integration.executeAnalysisWithDashboard(projectId, config, {
          ...options,
          onProgress,
          onPluginComplete: (_toolName: string, _toolResult: ToolResult) => {
            // Plugin ${_toolName} completed
          },
          onPluginError: (_toolName: string, _error: Error) => {
            // Plugin ${_toolName} failed: ${_error.message}
          },
        });

        if (result.success && result.result) {
          // Update dashboard with results
          const dashboardData = integration.transformAnalysisResult(result.result);
          setAnalysisResult(result.result);
          updateFilteredIssues(dashboardData.filteredIssues);
          setLastAnalysisData(dashboardData);
        } else {
          setAnalysisError(result.error ?? new Error('Analysis failed'));
        }

        return result;
      } catch (error) {
        const analysisError = error instanceof Error ? error : new Error(String(error));
        setAnalysisError(analysisError);
        return {
          success: false,
          error: analysisError,
        };
      } finally {
        setAnalyzing(false);
        setAnalysisProgress(null);
      }
    },
    [integration, setAnalysisResult, setAnalysisProgress, setAnalyzing, updateFilteredIssues]
  );

  // Cancel ongoing analysis
  const cancelAnalysis = useCallback(
    async (projectId: string): Promise<boolean> => {
      try {
        const cancelled = await integration.cancelAnalysis(projectId);
        if (cancelled) {
          setAnalyzing(false);
          setAnalysisProgress(null);
        }
        return cancelled;
      } catch (_error) {
        return false;
      }
    },
    [integration, setAnalyzing, setAnalysisProgress]
  );

  // Load existing analysis results
  const loadResults = useCallback(
    (result: AnalysisResult) => {
      const dashboardData = integration.transformAnalysisResult(result);
      setAnalysisResult(result);
      updateFilteredIssues(dashboardData.filteredIssues);
      setLastAnalysisData(dashboardData);
      setAnalysisError(null);
    },
    [integration, setAnalysisResult, updateFilteredIssues]
  );

  // Clear results
  const clearResults = useCallback(() => {
    setAnalysisResult(null);
    updateFilteredIssues([]);
    setLastAnalysisData(null);
    setAnalysisError(null);
    setAnalysisProgress(null);
    setAnalyzing(false);
  }, [setAnalysisResult, updateFilteredIssues]);

  // Subscribe to real-time updates
  useEffect(() => {
    const handleProgress = (progress: AnalysisProgress) => {
      setAnalysisProgress(progress);
    };

    const handleComplete = (dashboardData: DashboardData) => {
      setLastAnalysisData(dashboardData);
      setAnalyzing(false);
    };

    const handleError = (error: Error) => {
      setAnalysisError(error);
      setAnalyzing(false);
    };

    integration.on('progress', handleProgress);
    integration.on('analysis-complete', handleComplete);
    integration.on('analysis-error', handleError);

    return () => {
      integration.off('progress', handleProgress);
      integration.off('analysis-complete', handleComplete);
      integration.off('analysis-error', handleError);
    };
  }, [integration, setAnalysisProgress, setAnalyzing]);

  return {
    // State
    analysisError,
    lastAnalysisData,
    isAnalyzing: useDashboardStore(state => state.isAnalyzing),

    // Actions
    executeAnalysis,
    cancelAnalysis,
    loadResults,
    clearResults,

    // Integration access
    integration,
  };
}

/**
 * Comparison Store Hook
 * Manages comparison analysis state for dashboard comparisons
 */

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { Issue } from '../types/analysis';

export interface AnalysisRun {
  id: string;
  timestamp: Date;
  version?: string;
  commitHash?: string;
  branch?: string;
  metadata: {
    totalIssues: number;
    criticalIssues: number;
    highIssues: number;
    mediumIssues: number;
    lowIssues: number;
    fixableIssues: number;
    score: number;
    executionTime: number;
    tools: string[];
  };
  issues: Issue[];
  metrics: {
    coverage: number;
    duplicates: number;
    newIssues: number;
    resolvedIssues: number;
    trends: {
      severity: Record<string, number>;
      tools: Record<string, number>;
      categories: Record<string, number>;
    };
  };
}

export interface ComparisonConfig {
  baselineRunId: string;
  comparisonRunId: string;
  metrics: string[];
  filters: {
    showNewIssues: boolean;
    showResolvedIssues: boolean;
    showUnchangedIssues: boolean;
    severityFilter: string[];
    toolFilter: string[];
  };
  visualization: {
    showCharts: boolean;
    showDiffs: boolean;
    showTrends: boolean;
  };
}

export interface ComparisonResult {
  config: ComparisonConfig;
  baseline: AnalysisRun;
  comparison: AnalysisRun;
  summary: {
    totalIssuesDiff: number;
    criticalIssuesDiff: number;
    scoreDiff: number;
    newIssuesCount: number;
    resolvedIssuesCount: number;
    unchangedIssuesCount: number;
    improvementRate: number;
  };
  differences: {
    newIssues: Issue[];
    resolvedIssues: Issue[];
    unchangedIssues: Issue[];
    severityChanges: Array<{
      issue: Issue;
      oldSeverity: string;
      newSeverity: string;
    }>;
    scoreChanges: Array<{
      issue: Issue;
      oldScore: number;
      newScore: number;
      diff: number;
    }>;
  };
  trends: {
    severity: Array<{
      type: string;
      baseline: number;
      comparison: number;
      diff: number;
      trend: 'up' | 'down' | 'stable';
    }>;
    tools: Array<{
      tool: string;
      baseline: number;
      comparison: number;
      diff: number;
      trend: 'up' | 'down' | 'stable';
    }>;
    categories: Array<{
      category: string;
      baseline: number;
      comparison: number;
      diff: number;
      trend: 'up' | 'down' | 'stable';
    }>;
  };
  generatedAt: Date;
}

export interface ComparisonState {
  // Data
  runs: AnalysisRun[];
  comparisons: ComparisonResult[];
  currentComparison?: ComparisonResult;

  // UI state
  isComparing: boolean;
  showRunSelector: boolean;
  selectedBaselineRun?: string;
  selectedComparisonRun?: string;

  // Config
  comparisonConfig: ComparisonConfig;

  // Actions
  addRun: (run: AnalysisRun) => void;
  removeRun: (runId: string) => void;
  getRun: (runId: string) => AnalysisRun | undefined;
  updateRun: (runId: string, updates: Partial<AnalysisRun>) => void;

  // Comparison operations
  compareRuns: (baselineRunId: string, comparisonRunId: string) => ComparisonResult;
  setCurrentComparison: (comparison: ComparisonResult) => void;
  clearComparison: () => void;
  deleteComparison: (comparisonId: string) => void;

  // Config management
  updateComparisonConfig: (config: Partial<ComparisonConfig>) => void;
  setFilters: (filters: Partial<ComparisonConfig['filters']>) => void;
  setVisualization: (visualization: Partial<ComparisonConfig['visualization']>) => void;

  // UI actions
  toggleRunSelector: () => void;
  setRunSelectorOpen: (open: boolean) => void;
  selectBaselineRun: (runId: string) => void;
  selectComparisonRun: (runId: string) => void;

  // Export functionality
  exportComparison: (format: 'json' | 'csv' | 'markdown') => string;
  exportRuns: (format: 'json' | 'csv') => string;

  // Utility methods
  getRecentRuns: (limit?: number) => AnalysisRun[];
  getRunById: (runId: string) => AnalysisRun | undefined;
  calculateTrends: (runIds: string[]) => ComparisonResult['trends'];
}

const defaultConfig: ComparisonConfig = {
  baselineRunId: '',
  comparisonRunId: '',
  metrics: ['totalIssues', 'criticalIssues', 'score', 'fixableIssues'],
  filters: {
    showNewIssues: true,
    showResolvedIssues: true,
    showUnchangedIssues: false,
    severityFilter: [],
    toolFilter: [],
  },
  visualization: {
    showCharts: true,
    showDiffs: true,
    showTrends: true,
  },
};

export const useComparisonStore = create<ComparisonState>()(
  persist(
    (set, get) => ({
      // Initial state
      runs: [],
      comparisons: [],
      isComparing: false,
      showRunSelector: false,
      comparisonConfig: defaultConfig,

      // Run management
      addRun: run =>
        set(state => {
          // Check if run already exists
          const existingIndex = state.runs.findIndex(r => r.id === run.id);
          if (existingIndex >= 0) {
            // Update existing run
            const updatedRuns = [...state.runs];
            updatedRuns[existingIndex] = run;
            return { runs: updatedRuns };
          }
          // Add new run, sorted by timestamp (newest first)
          const sortedRuns = [run, ...state.runs].sort(
            (a, b) => b.timestamp.getTime() - a.timestamp.getTime()
          );
          return { runs: sortedRuns };
        }),

      removeRun: runId =>
        set(state => {
          const filteredRuns = state.runs.filter(r => r.id !== runId);
          const filteredComparisons = state.comparisons.filter(
            c => c.baseline.id !== runId && c.comparison.id !== runId
          );
          return {
            runs: filteredRuns,
            comparisons: filteredComparisons,
            currentComparison:
              state.currentComparison?.baseline.id === runId ||
              state.currentComparison?.comparison.id === runId
                ? undefined
                : state.currentComparison,
          };
        }),

      getRun: runId => get().runs.find(r => r.id === runId),

      updateRun: (runId, updates) =>
        set(state => ({
          runs: state.runs.map(run => (run.id === runId ? { ...run, ...updates } : run)),
        })),

      // Comparison operations
      compareRuns: (baselineRunId, comparisonRunId) => {
        const state = get();
        const baseline = state.getRun(baselineRunId);
        const comparison = state.getRun(comparisonRunId);

        if (!baseline || !comparison) {
          throw new Error('One or both runs not found');
        }

        // Calculate comparison result
        const result = generateComparisonResult(baseline, comparison, state.comparisonConfig);

        set(prevState => ({
          comparisons: [...prevState.comparisons, result],
          currentComparison: result,
          isComparing: false,
        }));

        return result;
      },

      setCurrentComparison: comparison => set({ currentComparison: comparison }),

      clearComparison: () => set({ currentComparison: undefined }),

      deleteComparison: comparisonId =>
        set(state => ({
          comparisons: state.comparisons.filter(c => c.generatedAt.toISOString() !== comparisonId),
          currentComparison:
            state.currentComparison?.generatedAt.toISOString() === comparisonId
              ? undefined
              : state.currentComparison,
        })),

      // Config management
      updateComparisonConfig: config =>
        set(state => ({
          comparisonConfig: { ...state.comparisonConfig, ...config },
        })),

      setFilters: filters =>
        set(state => ({
          comparisonConfig: {
            ...state.comparisonConfig,
            filters: { ...state.comparisonConfig.filters, ...filters },
          },
        })),

      setVisualization: visualization =>
        set(state => ({
          comparisonConfig: {
            ...state.comparisonConfig,
            visualization: { ...state.comparisonConfig.visualization, ...visualization },
          },
        })),

      // UI actions
      toggleRunSelector: () => set(state => ({ showRunSelector: !state.showRunSelector })),

      setRunSelectorOpen: open => set({ showRunSelector: open }),

      selectBaselineRun: runId =>
        set(state => ({
          selectedBaselineRun: runId,
          comparisonConfig: { ...state.comparisonConfig, baselineRunId: runId },
        })),

      selectComparisonRun: runId =>
        set(state => ({
          selectedComparisonRun: runId,
          comparisonConfig: { ...state.comparisonConfig, comparisonRunId: runId },
        })),

      // Export functionality
      exportComparison: format => {
        const state = get();
        if (!state.currentComparison) {
          throw new Error('No comparison to export');
        }

        switch (format) {
          case 'json':
            return JSON.stringify(state.currentComparison, null, 2);
          case 'csv':
            return exportComparisonAsCSV(state.currentComparison);
          case 'markdown':
            return exportComparisonAsMarkdown(state.currentComparison);
          default:
            throw new Error(`Unsupported export format: ${format}`);
        }
      },

      exportRuns: format => {
        const state = get();
        switch (format) {
          case 'json':
            return JSON.stringify(state.runs, null, 2);
          case 'csv':
            return exportRunsAsCSV(state.runs);
          default:
            throw new Error(`Unsupported export format: ${format}`);
        }
      },

      // Utility methods
      getRecentRuns: (limit = 10) => {
        return get().runs.slice(0, limit);
      },

      getRunById: runId => {
        return get().runs.find(r => r.id === runId);
      },

      calculateTrends: runIds => {
        const state = get();
        const runs = runIds.map(id => state.getRunById(id)).filter(Boolean) as AnalysisRun[];

        if (runs.length < 2) {
          return { severity: [], tools: [], categories: [] };
        }

        const oldest = runs[runs.length - 1];
        const newest = runs[0];

        if (!oldest || !newest) {
          return { severity: [], tools: [], categories: [] };
        }

        return generateTrends(oldest, newest);
      },
    }),
    {
      name: 'comparison-store',
      partialize: state => ({
        runs: state.runs.slice(0, 50), // Limit stored runs
        comparisonConfig: state.comparisonConfig,
      }),
    }
  )
);

/**
 * Generate comparison result between two runs
 */
function generateComparisonResult(
  baseline: AnalysisRun,
  comparison: AnalysisRun,
  config: ComparisonConfig
): ComparisonResult {
  const baselineIssues = new Map(baseline.issues.map(issue => [issue.id, issue]));
  const comparisonIssues = new Map(comparison.issues.map(issue => [issue.id, issue]));

  const newIssues: Issue[] = [];
  const resolvedIssues: Issue[] = [];
  const unchangedIssues: Issue[] = [];
  const severityChanges: Array<{
    issue: Issue;
    oldSeverity: string;
    newSeverity: string;
  }> = [];
  const scoreChanges: Array<{
    issue: Issue;
    oldScore: number;
    newScore: number;
    diff: number;
  }> = [];

  // Find new and changed issues
  for (const [id, issue] of comparisonIssues) {
    const baselineIssue = baselineIssues.get(id);
    if (!baselineIssue) {
      newIssues.push(issue);
    } else {
      // Check for changes
      if (baselineIssue.type !== issue.type) {
        severityChanges.push({
          issue,
          oldSeverity: baselineIssue.type,
          newSeverity: issue.type,
        });
      }

      if (baselineIssue.score !== issue.score) {
        scoreChanges.push({
          issue,
          oldScore: baselineIssue.score,
          newScore: issue.score,
          diff: issue.score - baselineIssue.score,
        });
      }

      unchangedIssues.push(issue);
    }
  }

  // Find resolved issues
  for (const [id, issue] of baselineIssues) {
    if (!comparisonIssues.has(id)) {
      resolvedIssues.push(issue);
    }
  }

  // Calculate summary
  const totalIssuesDiff = comparison.metadata.totalIssues - baseline.metadata.totalIssues;
  const criticalIssuesDiff = comparison.metadata.criticalIssues - baseline.metadata.criticalIssues;
  const scoreDiff = comparison.metadata.score - baseline.metadata.score;

  const improvementRate =
    totalIssuesDiff === 0
      ? 0
      : ((resolvedIssues.length - newIssues.length) / baseline.metadata.totalIssues) * 100;

  return {
    config,
    baseline,
    comparison,
    summary: {
      totalIssuesDiff,
      criticalIssuesDiff,
      scoreDiff,
      newIssuesCount: newIssues.length,
      resolvedIssuesCount: resolvedIssues.length,
      unchangedIssuesCount: unchangedIssues.length,
      improvementRate,
    },
    differences: {
      newIssues,
      resolvedIssues,
      unchangedIssues,
      severityChanges,
      scoreChanges,
    },
    trends: generateTrends(baseline, comparison),
    generatedAt: new Date(),
  };
}

/**
 * Generate trend analysis between two runs
 */
function generateTrends(
  baseline: AnalysisRun,
  comparison: AnalysisRun
): ComparisonResult['trends'] {
  const severity = Object.keys(baseline.metrics.trends.severity).map(type => ({
    type,
    baseline: baseline.metrics.trends.severity[type] ?? 0,
    comparison: comparison.metrics.trends.severity[type] ?? 0,
    diff:
      (comparison.metrics.trends.severity[type] ?? 0) -
      (baseline.metrics.trends.severity[type] ?? 0),
    trend: 'stable' as 'up' | 'down' | 'stable',
  }));

  const tools = Object.keys(baseline.metrics.trends.tools).map(tool => ({
    tool,
    baseline: baseline.metrics.trends.tools[tool] ?? 0,
    comparison: comparison.metrics.trends.tools[tool] ?? 0,
    diff: (comparison.metrics.trends.tools[tool] ?? 0) - (baseline.metrics.trends.tools[tool] ?? 0),
    trend: 'stable' as 'up' | 'down' | 'stable',
  }));

  const categories = Object.keys(baseline.metrics.trends.categories).map(category => ({
    category,
    baseline: baseline.metrics.trends.categories[category] ?? 0,
    comparison: comparison.metrics.trends.categories[category] ?? 0,
    diff:
      (comparison.metrics.trends.categories[category] ?? 0) -
      (baseline.metrics.trends.categories[category] ?? 0),
    trend: 'stable' as 'up' | 'down' | 'stable',
  }));

  // Determine trends
  const updatedSeverity = severity.map(
    (item): (typeof severity)[0] & { trend: 'up' | 'down' | 'stable' } => ({
      ...item,
      trend: item.diff > 0 ? 'up' : item.diff < 0 ? 'down' : 'stable',
    })
  );

  const updatedTools = tools.map(
    (item): (typeof tools)[0] & { trend: 'up' | 'down' | 'stable' } => ({
      ...item,
      trend: item.diff > 0 ? 'up' : item.diff < 0 ? 'down' : 'stable',
    })
  );

  const updatedCategories = categories.map(
    (item): (typeof categories)[0] & { trend: 'up' | 'down' | 'stable' } => ({
      ...item,
      trend: item.diff > 0 ? 'up' : item.diff < 0 ? 'down' : 'stable',
    })
  );

  return {
    severity: updatedSeverity,
    tools: updatedTools,
    categories: updatedCategories,
  };
}

/**
 * Export comparison as CSV
 */
function exportComparisonAsCSV(comparison: ComparisonResult): string {
  const headers = ['Metric', 'Baseline', 'Comparison', 'Difference', 'Trend'];

  const rows = [
    headers.join(','),
    `Total Issues,${comparison.baseline.metadata.totalIssues},${comparison.comparison.metadata.totalIssues},${comparison.summary.totalIssuesDiff},${comparison.summary.totalIssuesDiff > 0 ? 'up' : 'down'}`,
    `Critical Issues,${comparison.baseline.metadata.criticalIssues},${comparison.comparison.metadata.criticalIssues},${comparison.summary.criticalIssuesDiff},${comparison.summary.criticalIssuesDiff > 0 ? 'up' : 'down'}`,
    `Score,${comparison.baseline.metadata.score},${comparison.comparison.metadata.score},${comparison.summary.scoreDiff},${comparison.summary.scoreDiff > 0 ? 'up' : 'down'}`,
    `New Issues,0,${comparison.summary.newIssuesCount},${comparison.summary.newIssuesCount},new`,
    `Resolved Issues,0,${comparison.summary.resolvedIssuesCount},${-comparison.summary.resolvedIssuesCount},resolved`,
    `Improvement Rate,0,${comparison.summary.improvementRate.toFixed(2)}%,${comparison.summary.improvementRate.toFixed(2)}%,${comparison.summary.improvementRate > 0 ? 'improvement' : 'degradation'}`,
  ];

  return rows.join('\n');
}

/**
 * Export comparison as Markdown
 */
function exportComparisonAsMarkdown(comparison: ComparisonResult): string {
  const { baseline, comparison: comp, summary } = comparison;

  return `# Comparison Report

**Generated:** ${comparison.generatedAt.toISOString()}

## Overview

| Metric | ${baseline.version ?? 'Baseline'} (${baseline.timestamp.toISOString().split('T')[0]}) | ${comp.version ?? 'Comparison'} (${comp.timestamp.toISOString().split('T')[0]}) | Difference |
|--------|--------|--------|------------|
| Total Issues | ${baseline.metadata.totalIssues} | ${comp.metadata.totalIssues} | ${summary.totalIssuesDiff > 0 ? '+' : ''}${summary.totalIssuesDiff} |
| Critical Issues | ${baseline.metadata.criticalIssues} | ${comp.metadata.criticalIssues} | ${summary.criticalIssuesDiff > 0 ? '+' : ''}${summary.criticalIssuesDiff} |
| Score | ${baseline.metadata.score} | ${comp.metadata.score} | ${summary.scoreDiff > 0 ? '+' : ''}${summary.scoreDiff} |
| New Issues | 0 | ${summary.newIssuesCount} | +${summary.newIssuesCount} |
| Resolved Issues | 0 | ${summary.resolvedIssuesCount} | -${summary.resolvedIssuesCount} |
| Improvement Rate | - | ${summary.improvementRate.toFixed(2)}% | ${summary.improvementRate > 0 ? '✅' : '❌'} |

## Summary

${
  summary.improvementRate > 0
    ? `🟢 **Improvement**: ${summary.improvementRate.toFixed(2)}% improvement rate`
    : `🔴 **Degradation**: ${Math.abs(summary.improvementRate).toFixed(2)}% degradation rate`
}

## Issues Changes

- **New Issues**: ${summary.newIssuesCount}
- **Resolved Issues**: ${summary.resolvedIssuesCount}
- **Unchanged Issues**: ${summary.unchangedIssuesCount}

## Severity Trends

${comparison.trends.severity
  .map(
    trend =>
      `- **${trend.type}**: ${trend.baseline} → ${trend.comparison} (${trend.diff > 0 ? '+' : ''}${trend.diff}) ${trend.trend === 'up' ? '📈' : trend.trend === 'down' ? '📉' : '➡️'}`
  )
  .join('\n')}
`;
}

/**
 * Export runs as CSV
 */
function exportRunsAsCSV(runs: AnalysisRun[]): string {
  const headers = [
    'ID',
    'Timestamp',
    'Version',
    'Total Issues',
    'Critical Issues',
    'Score',
    'Fixable Issues',
    'Execution Time',
    'Tools',
  ];

  const rows = [
    headers.join(','),
    ...runs.map(run =>
      [
        run.id,
        run.timestamp.toISOString(),
        run.version ?? '',
        run.metadata.totalIssues,
        run.metadata.criticalIssues,
        run.metadata.score,
        run.metadata.fixableIssues,
        run.metadata.executionTime,
        run.metadata.tools.join(';'),
      ].join(',')
    ),
  ];

  return rows.join('\n');
}

import { create } from 'zustand';
import type { CoverageReport, EnhancedCoverageData } from '@dev-quality/core';

interface CoverageState {
  // Current data
  currentReport: CoverageReport | null;
  currentCoverage: EnhancedCoverageData | null;
  isLoading: boolean;
  error: string | null;

  // View state
  currentView: 'summary' | 'files' | 'critical-paths' | 'recommendations';
  sortBy: 'coverage' | 'risk' | 'path';
  filterOptions: {
    minCoverage: number;
    maxRisk: number;
    showUncoveredOnly: boolean;
  };

  // Historical data
  historicalReports: CoverageReport[];
  trends: Array<{
    date: string;
    totalCoverage: number;
    qualityScore: number;
    riskScore: number;
  }>;

  // Actions
  setReport: (report: CoverageReport) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  setCurrentView: (view: CoverageState['currentView']) => void;
  setSortBy: (sortBy: CoverageState['sortBy']) => void;
  setFilterOptions: (options: Partial<CoverageState['filterOptions']>) => void;
  addHistoricalReport: (report: CoverageReport) => void;
  clearHistoricalData: () => void;
  refreshData: () => Promise<void>;
  exportReport: (
    format: 'json' | 'html' | 'markdown' | 'csv',
    outputPath?: string
  ) => Promise<string>;
}

export const useCoverageStore = create<CoverageState>((set, get) => ({
  // Initial state
  currentReport: null,
  currentCoverage: null,
  isLoading: false,
  error: null,

  currentView: 'summary',
  sortBy: 'coverage',
  filterOptions: {
    minCoverage: 0,
    maxRisk: 10,
    showUncoveredOnly: false,
  },

  historicalReports: [],
  trends: [],

  // Actions
  setReport: report => {
    set({
      currentReport: report,
      currentCoverage: report.coverage,
      error: null,
    });
  },

  setLoading: loading => {
    set({ isLoading: loading });
  },

  setError: error => {
    set({ error, isLoading: false });
  },

  setCurrentView: view => {
    set({ currentView: view });
  },

  setSortBy: sortBy => {
    set({ sortBy });
  },

  setFilterOptions: options => {
    set(state => ({
      filterOptions: { ...state.filterOptions, ...options },
    }));
  },

  addHistoricalReport: report => {
    set(state => ({
      historicalReports: [...state.historicalReports.slice(-29), report], // Keep last 30
    }));
  },

  clearHistoricalData: () => {
    set({
      historicalReports: [],
      trends: [],
    });
  },

  refreshData: async () => {
    const state = get();
    if (!state.currentReport) return;

    try {
      state.setLoading(true);

      // Re-run analysis with current configuration
      const { CoverageAnalysisEngine } = await import('@dev-quality/core');
      const _engine = new CoverageAnalysisEngine();

      // This would need to be implemented to get the current context
      // For now, we'll just simulate a refresh
      setTimeout(() => {
        state.setLoading(false);
      }, 1000);
    } catch (error) {
      state.setError(error instanceof Error ? error.message : 'Failed to refresh data');
    }
  },

  exportReport: async (format, outputPath) => {
    const state = get();
    if (!state.currentReport) {
      throw new Error('No report data available to export');
    }

    try {
      const { CoverageAnalysisEngine } = await import('@dev-quality/core');
      const engine = new CoverageAnalysisEngine();

      return await engine.exportReport(state.currentReport, format, outputPath);
    } catch (error) {
      throw new Error(`Failed to export report: ${error}`);
    }
  },
}));

/**
 * Use Dashboard Navigation Hook
 * Manages dashboard navigation state and breadcrumb history
 */

import React, { useCallback, useEffect } from 'react';
import { useDashboardStore } from './useDashboardStore';
import type { DashboardView, NavigationBreadcrumb } from '../types/dashboard';
import type { Issue } from '../types/analysis';

interface NavigationContext {
  selectedIssue?: Issue;
  selectedFile?: string;
  selectedModule?: string;
  selectedTool?: string;
  selectedSeverity?: string;
  searchTerm?: string;
}

interface NavigationState {
  currentView: DashboardView;
  breadcrumbs: NavigationBreadcrumb[];
  context: NavigationContext;
  canGoBack: boolean;
  canGoForward: boolean;
}

export const useDashboardNavigation = () => {
  const { currentView, setCurrentView, setSelectedIssue } = useDashboardStore();

  const [navigationContext, setNavigationContext] = React.useState<NavigationContext>({});
  const [navigationStack, setNavigationStack] = React.useState<NavigationState[]>([]);

  /**
   * Navigate to a specific view with context
   */
  const navigate = useCallback(
    (view: DashboardView, context?: NavigationContext) => {
      // Create breadcrumb for current view
      const breadcrumb: NavigationBreadcrumb = {
        id: `${view}-${Date.now()}`,
        label: getViewLabel(view, context),
        view,
        data: context as Record<string, unknown>,
      };

      // Store current state in stack
      const lastState = navigationStack[navigationStack.length - 1];
      const currentState: NavigationState = {
        currentView,
        breadcrumbs: [...(lastState?.breadcrumbs ?? []), breadcrumb],
        context: { ...navigationContext, ...context },
        canGoBack: navigationStack.length > 0 || currentView !== 'dashboard',
        canGoForward: false,
      };

      setNavigationStack(prev => [...prev, currentState]);
      setNavigationContext(prev => ({ ...prev, ...context }));

      // Update store
      setCurrentView(view);
      setSelectedIssue(context?.selectedIssue ?? null);
    },
    [currentView, navigationContext, navigationStack, setCurrentView, setSelectedIssue]
  );

  /**
   * Navigate to issue details
   */
  const navigateToIssue = useCallback(
    (issue: Issue) => {
      const context: NavigationContext = {
        selectedIssue: issue,
        selectedFile: issue.filePath,
        selectedTool: issue.toolName,
      };

      navigate('issue-details', context);
    },
    [navigate]
  );

  /**
   * Navigate to file view
   */
  const navigateToFile = useCallback(
    (filePath: string, context?: Partial<NavigationContext>) => {
      const navContext: NavigationContext = {
        selectedFile: filePath,
        ...context,
      };

      navigate('issue-list', navContext);
    },
    [navigate]
  );

  /**
   * Navigate to module view
   */
  const navigateToModule = useCallback(
    (module: string, context?: Partial<NavigationContext>) => {
      const navContext: NavigationContext = {
        selectedModule: module,
        ...context,
      };

      navigate('issue-list', navContext);
    },
    [navigate]
  );

  /**
   * Navigate back
   */
  const navigateBack = useCallback(() => {
    if (navigationStack.length > 1) {
      // Remove current state and go to previous
      const newStack = navigationStack.slice(0, -1);
      const previousState = newStack[newStack.length - 1];

      if (previousState) {
        setNavigationStack(newStack);
        setNavigationContext(previousState.context);
        setCurrentView(previousState.currentView);
        setSelectedIssue(previousState.context.selectedIssue ?? null);
      }
    } else {
      // Go to dashboard if at root
      navigate('dashboard');
    }
  }, [navigationStack, navigate, setCurrentView, setSelectedIssue]);

  /**
   * Navigate forward (if available)
   */
  const navigateForward = useCallback(() => {
    // This would require storing forward history
    // For now, implement as placeholder
    // TODO: Implement forward navigation
  }, []);

  /**
   * Clear navigation history
   */
  const clearNavigationHistory = useCallback(() => {
    setNavigationStack([
      {
        currentView: 'dashboard',
        breadcrumbs: [],
        context: {},
        canGoBack: false,
        canGoForward: false,
      },
    ]);
    setNavigationContext({});
    setCurrentView('dashboard');
    setSelectedIssue(null);
  }, [setCurrentView, setSelectedIssue]);

  /**
   * Get current navigation state
   */
  const getNavigationState = useCallback((): NavigationState => {
    return (
      navigationStack[navigationStack.length - 1] ?? {
        currentView: 'dashboard',
        breadcrumbs: [],
        context: {},
        canGoBack: false,
        canGoForward: false,
      }
    );
  }, [navigationStack]);

  /**
   * Filter issues by current context
   */
  const getFilteredIssues = useCallback(
    (allIssues: Issue[]): Issue[] => {
      let filteredIssues = allIssues;

      // Filter by selected file
      if (navigationContext.selectedFile) {
        filteredIssues = filteredIssues.filter(
          issue => issue.filePath === navigationContext.selectedFile
        );
      }

      // Filter by selected module
      if (navigationContext.selectedModule) {
        const selectedModule = navigationContext.selectedModule;
        filteredIssues = filteredIssues.filter(issue => issue.filePath.includes(selectedModule));
      }

      // Filter by selected tool
      if (navigationContext.selectedTool) {
        filteredIssues = filteredIssues.filter(
          issue => issue.toolName === navigationContext.selectedTool
        );
      }

      // Filter by selected severity
      if (navigationContext.selectedSeverity) {
        filteredIssues = filteredIssues.filter(
          issue => issue.type === navigationContext.selectedSeverity
        );
      }

      // Filter by search term
      if (navigationContext.searchTerm) {
        const searchTerm = navigationContext.searchTerm.toLowerCase();
        filteredIssues = filteredIssues.filter(
          issue =>
            issue.message.toLowerCase().includes(searchTerm) ||
            issue.filePath.toLowerCase().includes(searchTerm) ||
            issue.toolName.toLowerCase().includes(searchTerm)
        );
      }

      return filteredIssues;
    },
    [navigationContext]
  );

  // Auto-navigate to dashboard if no state exists
  useEffect(() => {
    if (navigationStack.length === 0 && currentView === 'dashboard') {
      setNavigationStack([
        {
          currentView: 'dashboard',
          breadcrumbs: [],
          context: {},
          canGoBack: false,
          canGoForward: false,
        },
      ]);
    }
  }, [navigationStack.length, currentView]);

  return {
    // Current state
    currentView,
    navigationContext,
    navigationState: getNavigationState(),

    // Navigation methods
    navigate,
    navigateToIssue,
    navigateToFile,
    navigateToModule,
    navigateBack,
    navigateForward,
    clearNavigationHistory,

    // Context setters
    setNavigationContext,

    // Utility methods
    getFilteredIssues,
  };
};

/**
 * Get human-readable label for view
 */
function getViewLabel(view: DashboardView, context?: NavigationContext): string {
  const baseLabels: Record<DashboardView, string> = {
    dashboard: 'Dashboard',
    'issue-list': 'Issues',
    'issue-details': 'Issue Details',
    comparison: 'Compare Runs',
    trends: 'Trends',
    'layout-customization': 'Layout',
  };

  let label = baseLabels[view];

  // Add context-specific information
  if (context?.selectedIssue) {
    const issue = context.selectedIssue;
    const shortMessage =
      issue.message.length > 30 ? `${issue.message.slice(0, 27)}...` : issue.message;
    label = `Issue: ${shortMessage}`;
  }

  if (context?.selectedFile) {
    const fileName = context.selectedFile.split('/').pop() ?? 'Unknown File';
    label = `File: ${fileName}`;
  }

  if (context?.selectedModule) {
    label = `Module: ${context.selectedModule}`;
  }

  if (context?.selectedTool) {
    label = `${label} (${context.selectedTool})`;
  }

  return label;
}

/**
 * Dashboard state management using Zustand
 */

import { create } from 'zustand';
import type {
  CLIDashboardState,
  DashboardView,
  FilterState,
  RealTimeUpdateEvent,
  DashboardLayout,
  PerformanceMetrics,
  NavigationBreadcrumb,
  // NavigationState,
  // DashboardUIState,
  // DashboardResultsState,
  SortField,
  SortOrder,
} from '../types/dashboard';
import type { AnalysisResult, Issue, AnalysisProgress } from '../types/analysis';
import { transformCoreIssuesToCLI as _transformCoreIssuesToCLI } from '../utils/type-transformers';

interface DashboardStore extends CLIDashboardState {
  // Direct access properties for backward compatibility
  currentView: DashboardView;
  filteredIssues: Issue[];
  selectedIssue: Issue | null;
  isAnalyzing: boolean;
  analysisProgress: AnalysisProgress | null;
  filters: FilterState;
  currentPage: number;
  itemsPerPage: number;
  sortBy: SortField;
  sortOrder: SortOrder;
  selectedIndex: number;
  currentResult: AnalysisResult | null;

  // Prioritization state
  prioritizedIssues: import('@dev-quality/types').IssuePrioritization[];
  isProcessingPrioritization: boolean;
  prioritizationProgress: number;
  prioritizationError: string | null;
  lastPrioritizedAt: Date | null;

  // Enhanced features state
  realTimeUpdates: RealTimeUpdateEvent[];
  currentLayout: DashboardLayout | null;
  availableLayouts: DashboardLayout[];
  navigationBreadcrumbs: NavigationBreadcrumb[];
  performanceMetrics: PerformanceMetrics | null;

  // Results actions
  setAnalysisResult: (result: AnalysisResult | null) => void;
  updateFilteredIssues: (issues: Issue[]) => void;
  setSelectedIssue: (issue: Issue | null) => void;
  updateFilters: (filters: Partial<FilterState>) => void;
  setAnalysisProgress: (progress: AnalysisProgress | null) => void;
  setAnalyzing: (isAnalyzing: boolean) => void;

  // UI actions
  setCurrentView: (view: DashboardView) => void;
  setCurrentPage: (page: number) => void;
  setSortOrder: (field: SortField, order: SortOrder) => void;
  setItemsPerPage: (count: number) => void;
  toggleFilterMenu: () => void;
  toggleExportMenu: () => void;

  // Navigation actions
  setSelectedIndex: (index: number) => void;
  addToNavigationHistory: (view: DashboardView, selectedIndex: number) => void;
  goBack: () => void;

  // Prioritization actions
  setPrioritizationData: (
    prioritizations: import('@dev-quality/types').IssuePrioritization[]
  ) => void;
  setProcessingPrioritization: (isProcessing: boolean) => void;
  setPrioritizationProgress: (progress: number) => void;
  setPrioritizationError: (error: string | null) => void;
  filterByPriority: (priorityLevels: string[]) => void;
  sortByPriority: (order: SortOrder) => void;

  // Real-time update actions
  addRealTimeUpdate: (update: RealTimeUpdateEvent) => void;
  clearRealTimeUpdates: () => void;

  // Layout management actions
  setCurrentLayout: (layout: DashboardLayout) => void;
  addAvailableLayout: (layout: DashboardLayout) => void;
  updateLayoutWidget: (
    widgetId: string,
    updates: Partial<import('../types/dashboard').WidgetConfig>
  ) => void;

  // Navigation actions
  addNavigationBreadcrumb: (breadcrumb: NavigationBreadcrumb) => void;
  removeNavigationBreadcrumb: (breadcrumbId: string) => void;
  clearNavigationBreadcrumbs: () => void;

  // Performance monitoring actions
  updatePerformanceMetrics: (metrics: Partial<PerformanceMetrics>) => void;

  // Utility actions
  resetDashboard: () => void;
  clearFilters: () => void;
}

const initialState: CLIDashboardState = {
  results: {
    currentResult: null,
    filteredIssues: [],
    selectedIssue: null,
    filters: {
      severity: ['error', 'warning', 'info'],
      tools: [],
      filePaths: [],
      fixable: null,
      minScore: null,
      maxScore: null,
      searchQuery: '',
      // Priority-based filtering defaults
      priorityLevels: ['critical', 'high', 'medium', 'low'],
      minPriorityScore: null,
      maxPriorityScore: null,
      triageActions: [],
      classificationCategories: [],
    },
    isAnalyzing: false,
    analysisProgress: null,
  },
  ui: {
    currentView: 'dashboard',
    currentPage: 1,
    itemsPerPage: 10,
    sortBy: 'score',
    sortOrder: 'desc',
    isFilterMenuOpen: false,
    isExportMenuOpen: false,
  },
  navigation: {
    selectedIndex: 0,
    navigationHistory: [],
  },
};

export const useDashboardStore = create<DashboardStore>((set, get) => ({
  // Initialize with direct access properties from nested state
  currentView: initialState.ui.currentView,
  filteredIssues: initialState.results.filteredIssues,
  selectedIssue: initialState.results.selectedIssue,
  isAnalyzing: initialState.results.isAnalyzing,
  analysisProgress: initialState.results.analysisProgress,
  filters: initialState.results.filters,
  currentPage: initialState.ui.currentPage,
  itemsPerPage: initialState.ui.itemsPerPage,
  sortBy: initialState.ui.sortBy,
  sortOrder: initialState.ui.sortOrder,
  selectedIndex: initialState.navigation.selectedIndex,
  currentResult: initialState.results.currentResult,

  // Initialize prioritization state
  prioritizedIssues: [],
  isProcessingPrioritization: false,
  prioritizationProgress: 0,
  prioritizationError: null,
  lastPrioritizedAt: null,

  // Initialize enhanced features state
  realTimeUpdates: [],
  currentLayout: null,
  availableLayouts: [],
  navigationBreadcrumbs: [],
  performanceMetrics: null,

  ...initialState,

  // Results actions
  setAnalysisResult: (result: AnalysisResult | null) =>
    set(state => {
      if (!result) {
        return {
          results: {
            ...state.results,
            currentResult: null,
            filteredIssues: [],
          },
          currentResult: null,
          filteredIssues: [],
        };
      }
      const transformedIssues = result.toolResults.flatMap(toolResult => toolResult.issues);
      return {
        results: {
          ...state.results,
          currentResult: result,
          filteredIssues: transformedIssues,
        },
        currentResult: result,
        filteredIssues: transformedIssues,
      };
    }),

  updateFilteredIssues: (issues: Issue[]) =>
    set(state => ({
      results: {
        ...state.results,
        filteredIssues: issues,
      },
      filteredIssues: issues,
    })),

  setSelectedIssue: (issue: Issue | null) =>
    set(state => ({
      results: {
        ...state.results,
        selectedIssue: issue,
      },
      selectedIssue: issue,
    })),

  updateFilters: (filters: Partial<FilterState>) =>
    set(state => ({
      results: {
        ...state.results,
        filters: {
          ...state.results.filters,
          ...filters,
        },
      },
      filters: {
        ...state.filters,
        ...filters,
      },
    })),

  setAnalysisProgress: (progress: AnalysisProgress | null) =>
    set(state => ({
      results: {
        ...state.results,
        analysisProgress: progress,
      },
      analysisProgress: progress,
    })),

  setAnalyzing: (isAnalyzing: boolean) =>
    set(state => ({
      results: {
        ...state.results,
        isAnalyzing,
      },
      isAnalyzing,
    })),

  // UI actions
  setCurrentView: (view: DashboardView) =>
    set(state => ({
      ui: {
        ...state.ui,
        currentView: view,
      },
      currentView: view,
    })),

  setCurrentPage: (page: number) =>
    set(state => ({
      ui: {
        ...state.ui,
        currentPage: page,
      },
      currentPage: page,
    })),

  setSortOrder: (field: SortField, order: SortOrder) =>
    set(state => ({
      ui: {
        ...state.ui,
        sortBy: field,
        sortOrder: order,
      },
      sortBy: field,
      sortOrder: order,
    })),

  setItemsPerPage: (count: number) =>
    set(state => ({
      ui: {
        ...state.ui,
        itemsPerPage: count,
      },
      itemsPerPage: count,
    })),

  toggleFilterMenu: () =>
    set(state => ({
      ui: {
        ...state.ui,
        isFilterMenuOpen: !state.ui.isFilterMenuOpen,
      },
    })),

  toggleExportMenu: () =>
    set(state => ({
      ui: {
        ...state.ui,
        isExportMenuOpen: !state.ui.isExportMenuOpen,
      },
    })),

  // Navigation actions
  setSelectedIndex: (index: number) =>
    set(state => ({
      navigation: {
        ...state.navigation,
        selectedIndex: index,
      },
      selectedIndex: index,
    })),

  addToNavigationHistory: (view: DashboardView, selectedIndex: number) =>
    set(state => ({
      navigation: {
        ...state.navigation,
        navigationHistory: [
          ...state.navigation.navigationHistory,
          {
            view,
            selectedIndex,
            timestamp: new Date(),
          },
        ],
      },
    })),

  goBack: () => {
    const { navigationHistory } = get().navigation;
    if (navigationHistory.length > 0) {
      const previousState = navigationHistory[navigationHistory.length - 1];
      if (previousState) {
        set(state => ({
          ui: {
            ...state.ui,
            currentView: previousState.view,
          },
          navigation: {
            selectedIndex: previousState.selectedIndex,
            navigationHistory: navigationHistory.slice(0, -1),
          },
          currentView: previousState.view,
          selectedIndex: previousState.selectedIndex,
        }));
      }
    }
  },

  // Utility actions
  resetDashboard: () => set(initialState),

  clearFilters: () =>
    set(state => ({
      results: {
        ...state.results,
        filters: initialState.results.filters,
      },
    })),

  // Prioritization actions
  setPrioritizationData: (prioritizations: import('@dev-quality/types').IssuePrioritization[]) =>
    set(_state => ({
      prioritizedIssues: prioritizations,
      lastPrioritizedAt: new Date(),
      prioritizationError: null,
    })),

  setProcessingPrioritization: (isProcessing: boolean) =>
    set(state => ({
      isProcessingPrioritization: isProcessing,
      prioritizationProgress: isProcessing ? 0 : state.prioritizationProgress,
    })),

  setPrioritizationProgress: (progress: number) =>
    set(_state => ({
      prioritizationProgress: Math.min(100, Math.max(0, progress)),
    })),

  setPrioritizationError: (error: string | null) =>
    set(_state => ({
      prioritizationError: error,
      isProcessingPrioritization: false,
    })),

  filterByPriority: (priorityLevels: string[]) =>
    set(_state => {
      const updatedFilters = {
        ...get().results.filters,
        priorityLevels,
      };
      return {
        results: {
          ...get().results,
          filters: updatedFilters,
        },
        filters: updatedFilters,
      };
    }),

  sortByPriority: (order: SortOrder) =>
    set(_state => ({
      ui: {
        ...get().ui,
        sortBy: 'priority',
        sortOrder: order,
      },
      sortBy: 'priority',
      sortOrder: order,
    })),

  // Real-time update actions
  addRealTimeUpdate: (update: RealTimeUpdateEvent) =>
    set(_state => ({
      realTimeUpdates: [update, ...get().realTimeUpdates.slice(0, 99)], // Keep last 100 updates
    })),

  clearRealTimeUpdates: () =>
    set(_state => ({
      realTimeUpdates: [],
    })),

  // Layout management actions
  setCurrentLayout: (layout: DashboardLayout) =>
    set(_state => ({
      currentLayout: layout,
    })),

  addAvailableLayout: (layout: DashboardLayout) =>
    set(_state => ({
      availableLayouts: [...get().availableLayouts.filter(l => l.id !== layout.id), layout],
    })),

  updateLayoutWidget: (
    widgetId: string,
    updates: Partial<import('../types/dashboard').WidgetConfig>
  ) =>
    set(state => {
      if (!state.currentLayout) return state;

      const updatedLayout = {
        ...state.currentLayout,
        widgets: state.currentLayout.widgets.map(widget =>
          widget.id === widgetId ? { ...widget, ...updates } : widget
        ),
        updatedAt: new Date(),
      };

      return {
        currentLayout: updatedLayout,
        availableLayouts: state.availableLayouts.map(layout =>
          layout.id === updatedLayout.id ? updatedLayout : layout
        ),
      };
    }),

  // Navigation actions
  addNavigationBreadcrumb: (breadcrumb: NavigationBreadcrumb) =>
    set(state => ({
      navigationBreadcrumbs: [...state.navigationBreadcrumbs, breadcrumb],
    })),

  removeNavigationBreadcrumb: (breadcrumbId: string) =>
    set(state => ({
      navigationBreadcrumbs: state.navigationBreadcrumbs.filter(b => b.id !== breadcrumbId),
    })),

  clearNavigationBreadcrumbs: () =>
    set(_state => ({
      navigationBreadcrumbs: [],
    })),

  // Performance monitoring actions
  updatePerformanceMetrics: (metrics: Partial<PerformanceMetrics>) =>
    set(state => ({
      performanceMetrics: {
        ...state.performanceMetrics,
        ...metrics,
        timestamp: new Date(),
      } as PerformanceMetrics,
    })),
}));

/**
 * Export functionality hook
 */

import { useState, useCallback } from 'react';
import { useDashboardStore } from './useDashboardStore';
import { ExportService } from '../services/export/export-service';
import {
  getFormatById,
  getOptionsForFormat,
  validateExportOptions,
} from '../services/export/report-formats';
import type { ExportRequest, ExportResult, ExportProgress, ExportOptions } from '../types/export';

export function useExport() {
  const { currentResult, filteredIssues } = useDashboardStore();
  const [isExporting, setIsExporting] = useState(false);
  const exportService = new ExportService();
  const [exportProgress, setExportProgress] = useState<ExportProgress | null>(null);
  const [lastExportResult, setLastExportResult] = useState<ExportResult | null>(null);
  const [exportError, setExportError] = useState<string | null>(null);

  const exportResults = useCallback(
    async (formatId: string, options: Partial<ExportOptions> = {}): Promise<ExportResult> => {
      if (!currentResult) {
        const error = 'No analysis results available for export';
        setExportError(error);
        const fallbackFormat = exportService.getSupportedFormats()[0];
        if (!fallbackFormat) {
          throw new Error('No export formats available');
        }
        return {
          success: false,
          outputPath: '',
          size: 0,
          format: getFormatById(formatId) ?? fallbackFormat,
          timestamp: new Date(),
          error,
        };
      }

      setIsExporting(true);
      setExportError(null);
      setExportProgress(null);

      try {
        const format = getFormatById(formatId);
        if (!format) {
          throw new Error(`Unknown export format: ${formatId}`);
        }

        // Get default options for format and merge with user options
        const defaultOptions = getOptionsForFormat(formatId);
        const exportOptions = { ...defaultOptions, ...options };

        // Validate options
        const validation = validateExportOptions(formatId, exportOptions);
        if (!validation.valid) {
          throw new Error(`Invalid export options: ${validation.errors.join(', ')}`);
        }

        // Calculate metrics for export
        const metrics = {
          totalIssues: filteredIssues.length,
          errorCount: filteredIssues.filter(issue => issue.type === 'error').length,
          warningCount: filteredIssues.filter(issue => issue.type === 'warning').length,
          infoCount: filteredIssues.filter(issue => issue.type === 'info').length,
          fixableCount: filteredIssues.filter(issue => issue.fixable).length,
          overallScore: currentResult.overallScore,
          coverage: currentResult.toolResults.find(result => result.coverage)?.coverage ?? null,
          toolsAnalyzed: currentResult.toolResults.length,
          duration: currentResult.duration,
        };

        const exportRequest: ExportRequest = {
          format,
          data: {
            analysisResult: currentResult,
            filteredIssues,
            metrics,
          },
          options: exportOptions,
        };

        const result = await exportService.exportResults(
          exportRequest,
          (progress: ExportProgress) => {
            setExportProgress(progress);
          }
        );

        setLastExportResult(result);
        if (!result.success) {
          setExportError(result.error ?? 'Export failed');
        }

        return result;
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        setExportError(errorMessage);

        const fallbackFormat = exportService.getSupportedFormats()[0];
        if (!fallbackFormat) {
          throw new Error('No export formats available');
        }

        const result: ExportResult = {
          success: false,
          outputPath: '',
          size: 0,
          format: getFormatById(formatId) ?? fallbackFormat,
          timestamp: new Date(),
          error: errorMessage,
        };

        setLastExportResult(result);
        return result;
      } finally {
        setIsExporting(false);
        setExportProgress(null);
      }
    },
    [currentResult, filteredIssues, exportService]
  );

  const exportToJSON = useCallback(
    (outputPath?: string) => {
      return exportResults('json', { outputPath });
    },
    [exportResults]
  );

  const exportToText = useCallback(
    (outputPath?: string) => {
      return exportResults('txt', { outputPath });
    },
    [exportResults]
  );

  const exportToCSV = useCallback(
    (outputPath?: string) => {
      return exportResults('csv', { outputPath });
    },
    [exportResults]
  );

  const exportToMarkdown = useCallback(
    (outputPath?: string) => {
      return exportResults('md', { outputPath });
    },
    [exportResults]
  );

  const exportToJUnit = useCallback(
    (outputPath?: string) => {
      return exportResults('junit', { outputPath });
    },
    [exportResults]
  );

  const resetExportState = useCallback(() => {
    setIsExporting(false);
    setExportProgress(null);
    setLastExportResult(null);
    setExportError(null);
  }, []);

  return {
    // State
    isExporting,
    exportProgress,
    lastExportResult,
    exportError,

    // Actions
    exportResults,
    exportToJSON,
    exportToText,
    exportToCSV,
    exportToMarkdown,
    exportToJUnit,
    resetExportState,

    // Helpers
    supportedFormats: exportService.getSupportedFormats(),
    canExport: !!currentResult,
  };
}

/**
 * Filters hook for dashboard
 */

import { useCallback, useMemo } from 'react';
import { useDashboardStore } from './useDashboardStore';
import { DashboardService } from '../services/dashboard/dashboard-service';
import type { IssueSeverity } from '../types/dashboard';
import type { Issue } from '@dev-quality/core';

export function useFilters(_originalIssues: Issue[] = []) {
  const {
    filteredIssues,
    filters,
    updateFilters,
    clearFilters,
    ui: { sortBy, sortOrder },
  } = useDashboardStore();

  const dashboardService = useMemo(() => new DashboardService(), []);

  // Apply filters and sorting
  const processedIssues = useMemo(() => {
    if (_originalIssues.length === 0) {
      return dashboardService.sortIssues(filteredIssues, sortBy, sortOrder);
    }

    // Apply filters
    const filtered = dashboardService.applyFilters(_originalIssues, filters);

    // Apply sorting
    return dashboardService.sortIssues(filtered, sortBy, sortOrder);
  }, [_originalIssues, filteredIssues, filters, sortBy, sortOrder, dashboardService]);

  // Filter management functions
  const setSeverityFilter = useCallback(
    (severity: IssueSeverity[]) => {
      updateFilters({ severity });
    },
    [updateFilters]
  );

  const setToolFilter = useCallback(
    (tools: string[]) => {
      updateFilters({ tools });
    },
    [updateFilters]
  );

  const setFilePathFilter = useCallback(
    (filePaths: string[]) => {
      updateFilters({ filePaths });
    },
    [updateFilters]
  );

  const setFixableFilter = useCallback(
    (fixable: boolean | null) => {
      updateFilters({ fixable });
    },
    [updateFilters]
  );

  const setScoreRange = useCallback(
    (minScore: number | null, maxScore: number | null) => {
      updateFilters({ minScore, maxScore });
    },
    [updateFilters]
  );

  const setSearchQuery = useCallback(
    (searchQuery: string) => {
      updateFilters({ searchQuery });
    },
    [updateFilters]
  );

  const toggleSeverity = useCallback(
    (severity: IssueSeverity) => {
      const currentSeverities = filters.severity;
      const newSeverities = currentSeverities.includes(severity)
        ? currentSeverities.filter(s => s !== severity)
        : [...currentSeverities, severity];

      // Ensure at least one severity is selected
      if (newSeverities.length > 0) {
        setSeverityFilter(newSeverities);
      }
    },
    [filters.severity, setSeverityFilter]
  );

  const toggleTool = useCallback(
    (tool: string) => {
      const currentTools = filters.tools;
      const newTools = currentTools.includes(tool)
        ? currentTools.filter(t => t !== tool)
        : [...currentTools, tool];

      setToolFilter(newTools);
    },
    [filters.tools, setToolFilter]
  );

  const addFilePath = useCallback(
    (filePath: string) => {
      const currentPaths = filters.filePaths;
      if (!currentPaths.includes(filePath)) {
        setFilePathFilter([...currentPaths, filePath]);
      }
    },
    [filters.filePaths, setFilePathFilter]
  );

  const removeFilePath = useCallback(
    (filePath: string) => {
      const currentPaths = filters.filePaths;
      const newPaths = currentPaths.filter(path => path !== filePath);
      setFilePathFilter(newPaths);
    },
    [filters.filePaths, setFilePathFilter]
  );

  const toggleFixable = useCallback(() => {
    const currentFixable = filters.fixable;
    const newFixable = currentFixable === null ? true : currentFixable === true ? false : null;
    setFixableFilter(newFixable);
  }, [filters.fixable, setFixableFilter]);

  const clearAllFilters = useCallback(() => {
    clearFilters();
  }, [clearFilters]);

  // Get available options for filters
  const getAvailableSeverities = useCallback((): IssueSeverity[] => {
    return ['error', 'warning', 'info'];
  }, []);

  const getAvailableTools = useCallback((): string[] => {
    const tools = new Set<string>();
    const issuesToCheck = _originalIssues.length > 0 ? _originalIssues : filteredIssues;

    issuesToCheck.forEach(issue => {
      tools.add(issue.toolName);
    });

    return Array.from(tools).sort();
  }, [_originalIssues, filteredIssues]);

  const getAvailableFilePaths = useCallback((): string[] => {
    const paths = new Set<string>();
    const issuesToCheck = _originalIssues.length > 0 ? _originalIssues : filteredIssues;

    issuesToCheck.forEach(issue => {
      paths.add(issue.filePath);
    });

    return Array.from(paths).sort();
  }, [_originalIssues, filteredIssues]);

  // Get filter statistics
  const filterStatistics = useMemo(() => {
    const baseIssues = _originalIssues.length > 0 ? _originalIssues : filteredIssues;
    return dashboardService.getFilterStatistics(baseIssues, processedIssues, filters);
  }, [_originalIssues, filteredIssues, processedIssues, filters, dashboardService]);

  // Check if any filters are active
  const hasActiveFilters = useMemo(() => {
    return (
      filters.severity.length < 3 ||
      filters.tools.length > 0 ||
      filters.filePaths.length > 0 ||
      filters.fixable !== null ||
      filters.minScore !== null ||
      filters.maxScore !== null ||
      filters.searchQuery.trim() !== ''
    );
  }, [filters]);

  return {
    // State
    filters,
    processedIssues,
    hasActiveFilters,
    filterStatistics,

    // Severity filters
    availableSeverities: getAvailableSeverities(),
    setSeverityFilter,
    toggleSeverity,

    // Tool filters
    availableTools: getAvailableTools(),
    setToolFilter,
    toggleTool,

    // File path filters
    availableFilePaths: getAvailableFilePaths(),
    setFilePathFilter,
    addFilePath,
    removeFilePath,

    // Score filters
    setScoreRange,

    // Fixable filter
    toggleFixable,

    // Search filter
    setSearchQuery,

    // Filter management
    clearAllFilters,
  };
}

/**
 * Filter Store Hook
 * Manages filter state for dashboard issue filtering and search
 */

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { Issue } from '../types/analysis';
import {
  sanitizeSearchQuery,
  validateRegexPattern,
  sanitizeFilterValue,
  validateScoreRange,
  sanitizePresetName,
  sanitizePresetDescription,
  sanitizeInput,
  RateLimiter,
} from '../utils/input-validation';

export interface FilterCriteria {
  severity?: string[];
  tools?: string[];
  priority?: string[];
  files?: string[];
  modules?: string[];
  scoreRange?: [number, number];
  hasFix?: boolean;
  isAssigned?: boolean;
}

export interface SearchCriteria {
  query: string;
  fields: ('message' | 'filePath' | 'ruleId' | 'toolName')[];
  caseSensitive: boolean;
  useRegex: boolean;
}

export interface FilterPreset {
  id: string;
  name: string;
  description: string;
  criteria: FilterCriteria;
  search: SearchCriteria;
  createdAt: Date;
  isDefault: boolean;
}

export interface FilterState {
  // Filter criteria
  filters: FilterCriteria;
  search: SearchCriteria;

  // UI state
  isFilterPanelOpen: boolean;
  activeFilters: string[];
  filterResults: Issue[];
  totalResults: number;
  isLoading: boolean;
  lastError?: string;

  // Presets
  presets: FilterPreset[];
  currentPresetId?: string;

  // Rate limiting
  searchRateLimiter: RateLimiter;
  filterRateLimiter: RateLimiter;

  // Actions
  setFilters: (filters: Partial<FilterCriteria>) => void;
  setSearch: (search: Partial<SearchCriteria>) => void;
  clearFilters: () => void;
  clearSearch: () => void;
  resetAll: () => void;

  // Filter panel UI
  toggleFilterPanel: () => void;
  setFilterPanelOpen: (open: boolean) => void;

  // Preset management
  savePreset: (name: string, description: string) => { success: boolean; error?: string };
  loadPreset: (presetId: string) => { success: boolean; error?: string };
  deletePreset: (presetId: string) => { success: boolean; error?: string };
  setDefaultPreset: (presetId: string) => { success: boolean; error?: string };

  // Filter application
  applyFilters: (issues: Issue[]) => Issue[];
  setActiveFilters: (filters: string[]) => void;
  setFilterResults: (results: Issue[]) => void;
  setIsLoading: (loading: boolean) => void;

  // Performance optimization
  debouncedApplyFilters: (issues: Issue[]) => void;

  // Validation
  validateSearchQuery: (query: string) => { isValid: boolean; error?: string };
  validateFilterValue: (value: string, type: string) => { isValid: boolean; sanitized: string };
}

const defaultFilters: FilterCriteria = {
  severity: [],
  tools: [],
  priority: [],
  files: [],
  modules: [],
  scoreRange: [1, 10],
  hasFix: undefined,
  isAssigned: undefined,
};

const defaultSearch: SearchCriteria = {
  query: '',
  fields: ['message', 'filePath', 'ruleId', 'toolName'],
  caseSensitive: false,
  useRegex: false,
};

const defaultPresets: FilterPreset[] = [
  {
    id: 'critical-security',
    name: 'Critical Security Issues',
    description: 'High-priority security vulnerabilities',
    criteria: {
      severity: ['error'],
      priority: ['critical', 'high'],
      scoreRange: [8, 10],
    },
    search: defaultSearch,
    createdAt: new Date('2025-01-01'),
    isDefault: false,
  },
  {
    id: 'performance-issues',
    name: 'Performance Issues',
    description: 'Performance-related problems',
    criteria: {
      tools: ['eslint', 'typescript'],
      priority: ['high', 'medium'],
      scoreRange: [6, 10],
    },
    search: defaultSearch,
    createdAt: new Date('2025-01-01'),
    isDefault: false,
  },
  {
    id: 'fixable-issues',
    name: 'Fixable Issues',
    description: 'Issues that can be automatically fixed',
    criteria: {
      hasFix: true,
      scoreRange: [5, 10],
    },
    search: defaultSearch,
    createdAt: new Date('2025-01-01'),
    isDefault: true,
  },
];

/**
 * Validate preset data structure
 */
function validatePresetData(preset: FilterPreset): { isValid: boolean; error?: string } {
  if (!preset || typeof preset !== 'object') {
    return { isValid: false, error: 'Invalid preset data' };
  }

  if (!preset.name || typeof preset.name !== 'string') {
    return { isValid: false, error: 'Preset name is required' };
  }

  if (!preset.criteria || typeof preset.criteria !== 'object') {
    return { isValid: false, error: 'Invalid filter criteria' };
  }

  if (!preset.search || typeof preset.search !== 'object') {
    return { isValid: false, error: 'Invalid search criteria' };
  }

  // Validate score range if present
  if (preset.criteria.scoreRange) {
    const validation = validateScoreRange(
      preset.criteria.scoreRange[0],
      preset.criteria.scoreRange[1]
    );
    if (!validation.isValid) {
      return { isValid: false, error: 'Invalid score range in preset' };
    }
  }

  // Validate search query if present
  if (preset.search.query) {
    const sanitized = sanitizeSearchQuery(preset.search.query);
    if (!sanitized) {
      return { isValid: false, error: 'Invalid search query in preset' };
    }
  }

  return { isValid: true };
}

// Create a debounce function
function debounce<T extends unknown[]>(func: (...args: T) => void, wait: number) {
  let timeout: ReturnType<typeof setTimeout> | undefined;
  return (...args: T) => {
    if (timeout) {
      clearTimeout(timeout);
    }
    timeout = setTimeout(() => func(...args), wait);
  };
}

export const useFilterStore = create<FilterState>()(
  persist(
    (set, get) => ({
      // Initial state
      filters: defaultFilters,
      search: defaultSearch,
      isFilterPanelOpen: false,
      activeFilters: [],
      filterResults: [],
      totalResults: 0,
      isLoading: false,
      presets: defaultPresets,
      currentPresetId: 'fixable-issues',
      searchRateLimiter: new RateLimiter(100), // 100ms between searches
      filterRateLimiter: new RateLimiter(50), // 50ms between filter changes

      // Filter actions
      setFilters: newFilters => {
        const state = get();

        // Rate limiting check
        if (!state.filterRateLimiter.canMakeRequest()) {
          set({ lastError: 'Filter changes are rate limited. Please wait a moment.' });
          return;
        }

        // Validate and sanitize filter values
        const sanitizedFilters: Partial<FilterCriteria> = {};

        if (newFilters.severity) {
          sanitizedFilters.severity = newFilters.severity
            .map(s => sanitizeFilterValue(s, 'severity'))
            .filter(Boolean);
        }

        if (newFilters.tools) {
          sanitizedFilters.tools = newFilters.tools
            .map(t => sanitizeFilterValue(t, 'tool'))
            .filter(Boolean);
        }

        if (newFilters.priority) {
          sanitizedFilters.priority = newFilters.priority
            .map(p => sanitizeFilterValue(p, 'priority'))
            .filter(Boolean);
        }

        if (newFilters.files) {
          sanitizedFilters.files = newFilters.files
            .map(f => sanitizeFilterValue(f, 'file'))
            .filter(Boolean);
        }

        if (newFilters.modules) {
          sanitizedFilters.modules = newFilters.modules
            .map(m => sanitizeFilterValue(m, 'module'))
            .filter(Boolean);
        }

        if (newFilters.scoreRange) {
          const validation = validateScoreRange(newFilters.scoreRange[0], newFilters.scoreRange[1]);
          if (validation.isValid) {
            sanitizedFilters.scoreRange = validation.sanitized;
          }
        }

        if (newFilters.hasFix !== undefined) {
          sanitizedFilters.hasFix = Boolean(newFilters.hasFix);
        }

        set(prevState => ({
          filters: { ...prevState.filters, ...sanitizedFilters },
          currentPresetId: undefined, // Clear preset when manually changing filters
          lastError: undefined,
        }));
      },

      setSearch: newSearch => {
        const state = get();

        // Rate limiting check for search queries
        if (newSearch.query && !state.searchRateLimiter.canMakeRequest()) {
          set({ lastError: 'Search queries are rate limited. Please wait a moment.' });
          return;
        }

        // Validate and sanitize search criteria
        const sanitizedSearch: Partial<SearchCriteria> = {};

        if (newSearch.query !== undefined) {
          sanitizedSearch.query = sanitizeSearchQuery(newSearch.query);
        }

        if (newSearch.fields) {
          // Ensure fields are valid and remove duplicates
          const validFields = ['message', 'filePath', 'ruleId', 'toolName'];
          sanitizedSearch.fields = [
            ...new Set(newSearch.fields.filter(f => validFields.includes(f))),
          ];
        }

        if (newSearch.caseSensitive !== undefined) {
          sanitizedSearch.caseSensitive = Boolean(newSearch.caseSensitive);
        }

        if (newSearch.useRegex !== undefined) {
          // Validate regex pattern if enabled
          if (newSearch.useRegex && state.search.query) {
            const validation = validateRegexPattern(state.search.query);
            if (!validation.isValid) {
              set({ lastError: `Invalid regex pattern: ${validation.error}` });
              return;
            }
          }
          sanitizedSearch.useRegex = Boolean(newSearch.useRegex);
        }

        set(prevState => ({
          search: { ...prevState.search, ...sanitizedSearch },
          currentPresetId: undefined, // Clear preset when manually changing search
          lastError: undefined,
        }));
      },

      clearFilters: () =>
        set({
          filters: defaultFilters,
          currentPresetId: undefined,
        }),

      clearSearch: () =>
        set({
          search: defaultSearch,
          currentPresetId: undefined,
        }),

      resetAll: () =>
        set({
          filters: defaultFilters,
          search: defaultSearch,
          currentPresetId: 'fixable-issues',
          activeFilters: [],
          filterResults: [],
          totalResults: 0,
        }),

      // UI actions
      toggleFilterPanel: () => set(state => ({ isFilterPanelOpen: !state.isFilterPanelOpen })),

      setFilterPanelOpen: open => set({ isFilterPanelOpen: open }),

      // Preset management
      savePreset: (name, description) => {
        try {
          // Validate and sanitize inputs
          const sanitizedName = sanitizePresetName(name);
          const sanitizedDescription = sanitizePresetDescription(description);

          if (!sanitizedName) {
            return { success: false, error: 'Invalid preset name' };
          }

          const state = get();
          const newPreset: FilterPreset = {
            id: `custom-${Date.now()}`,
            name: sanitizedName,
            description: sanitizedDescription,
            criteria: { ...state.filters },
            search: { ...state.search },
            createdAt: new Date(),
            isDefault: false,
          };

          set(prevState => ({
            presets: [...prevState.presets, newPreset],
            currentPresetId: newPreset.id,
            lastError: undefined,
          }));

          return { success: true };
        } catch (error) {
          return {
            success: false,
            error: error instanceof Error ? error.message : 'Failed to save preset',
          };
        }
      },

      loadPreset: presetId => {
        try {
          const preset = get().presets.find(p => p.id === presetId);
          if (!preset) {
            return { success: false, error: 'Preset not found' };
          }

          // Validate preset data before loading
          const validation = validatePresetData(preset);
          if (!validation.isValid) {
            return { success: false, error: validation.error };
          }

          set({
            filters: { ...preset.criteria },
            search: { ...preset.search },
            currentPresetId: presetId,
            lastError: undefined,
          });

          return { success: true };
        } catch (error) {
          return {
            success: false,
            error: error instanceof Error ? error.message : 'Failed to load preset',
          };
        }
      },

      deletePreset: presetId => {
        try {
          const state = get();
          const isDefaultPreset = defaultPresets.some(p => p.id === presetId);

          if (isDefaultPreset) {
            return { success: false, error: 'Cannot delete default presets' };
          }

          const newPresets = state.presets.filter(p => p.id !== presetId);
          const newCurrentPreset =
            state.currentPresetId === presetId ? 'fixable-issues' : state.currentPresetId;

          set({
            presets: newPresets,
            currentPresetId: newCurrentPreset,
            lastError: undefined,
          });

          return { success: true };
        } catch (error) {
          return {
            success: false,
            error: error instanceof Error ? error.message : 'Failed to delete preset',
          };
        }
      },

      setDefaultPreset: presetId => {
        try {
          const preset = get().presets.find(p => p.id === presetId);
          if (!preset) {
            return { success: false, error: 'Preset not found' };
          }

          set(state => ({
            presets: state.presets.map(p => ({
              ...p,
              isDefault: p.id === presetId,
            })),
            lastError: undefined,
          }));

          return { success: true };
        } catch (error) {
          return {
            success: false,
            error: error instanceof Error ? error.message : 'Failed to set default preset',
          };
        }
      },

      // Filter application
      applyFilters: issues => {
        const state = get();
        let filteredIssues = [...issues];

        // Apply filter criteria
        const { filters, search } = state;

        // Filter by severity
        if (filters.severity && filters.severity.length > 0) {
          filteredIssues = filteredIssues.filter(
            issue => filters.severity?.includes(issue.type) ?? false
          );
        }

        // Filter by tools
        if (filters.tools && filters.tools.length > 0) {
          filteredIssues = filteredIssues.filter(
            issue => filters.tools?.includes(issue.toolName) ?? false
          );
        }

        // Filter by priority (if we have priority information)
        if (filters.priority && filters.priority.length > 0) {
          filteredIssues = filteredIssues.filter(issue => {
            const priority = getPriorityFromScore(issue.score);
            return filters.priority?.includes(priority) ?? false;
          });
        }

        // Filter by files
        if (filters.files && filters.files.length > 0) {
          filteredIssues = filteredIssues.filter(
            issue => filters.files?.some(file => issue.filePath.includes(file)) ?? false
          );
        }

        // Filter by modules
        if (filters.modules && filters.modules.length > 0) {
          filteredIssues = filteredIssues.filter(
            issue => filters.modules?.some(module => issue.filePath.includes(module)) ?? false
          );
        }

        // Filter by score range
        if (filters.scoreRange) {
          const [minScore, maxScore] = filters.scoreRange;
          filteredIssues = filteredIssues.filter(
            issue => issue.score >= minScore && issue.score <= maxScore
          );
        }

        // Filter by fixable status
        if (filters.hasFix !== undefined) {
          filteredIssues = filteredIssues.filter(issue => issue.fixable === filters.hasFix);
        }

        // Apply search criteria
        if (search.query.trim()) {
          const searchFields = search.fields;
          const query = search.caseSensitive ? search.query : search.query.toLowerCase();

          filteredIssues = filteredIssues.filter(issue => {
            return searchFields.some(field => {
              const value = String(issue[field as keyof Issue] ?? '');
              const searchValue = search.caseSensitive ? value : value.toLowerCase();

              if (search.useRegex) {
                try {
                  const regex = new RegExp(query, search.caseSensitive ? 'g' : 'gi');
                  return regex.test(searchValue);
                } catch {
                  // Invalid regex, fall back to contains search
                  return searchValue.includes(query);
                }
              }

              return searchValue.includes(query);
            });
          });
        }

        set({
          filterResults: filteredIssues,
          totalResults: filteredIssues.length,
          isLoading: false,
        });

        return filteredIssues;
      },

      setActiveFilters: filters => set({ activeFilters: filters }),

      setFilterResults: results => set({ filterResults: results }),

      setIsLoading: loading => set({ isLoading: loading }),

      // Debounced version for performance
      debouncedApplyFilters: debounce((issues: Issue[]) => {
        get().applyFilters(issues);
      }, 300),

      // Validation methods
      validateSearchQuery: (query: string) => {
        const sanitized = sanitizeSearchQuery(query);
        if (!sanitized && query.trim()) {
          return { isValid: false, error: 'Invalid search query' };
        }
        return { isValid: true };
      },

      validateFilterValue: (value: string, type: string) => {
        let sanitized = '';

        switch (type) {
          case 'severity':
            sanitized = sanitizeFilterValue(value, 'severity');
            break;
          case 'tool':
            sanitized = sanitizeFilterValue(value, 'tool');
            break;
          case 'priority':
            sanitized = sanitizeFilterValue(value, 'priority');
            break;
          case 'file':
            sanitized = sanitizeFilterValue(value, 'file');
            break;
          case 'module':
            sanitized = sanitizeFilterValue(value, 'module');
            break;
          default:
            sanitized = sanitizeInput(value, 'filter');
        }

        return {
          isValid: sanitized.length > 0,
          sanitized,
        };
      },
    }),
    {
      name: 'filter-store',
      partialize: state => ({
        filters: state.filters,
        search: state.search,
        presets: state.presets,
        currentPresetId: state.currentPresetId,
        isFilterPanelOpen: state.isFilterPanelOpen,
      }),
    }
  )
);

/**
 * Helper function to get priority level from score
 */
function getPriorityFromScore(score: number): string {
  if (score >= 8) return 'critical';
  if (score >= 6) return 'high';
  if (score >= 4) return 'medium';
  return 'low';
}

/**
 * Navigation hooks for dashboard
 */

import React, { useCallback } from 'react';
import { useInput } from 'ink';
import { useDashboardStore } from './useDashboardStore';
import { createListNavigation, createMenuNavigation } from '../utils/keyboard-navigation';

export function useNavigation() {
  const {
    currentView,
    filteredIssues,
    selectedIssue,
    selectedIndex,
    setCurrentView,
    setSelectedIssue,
    setSelectedIndex,
    addToNavigationHistory,
    goBack,
  } = useDashboardStore();

  // Handle issue list navigation
  const issueListNavigation = createListNavigation(
    filteredIssues.length,
    index => {
      const issue = filteredIssues[index];
      if (issue) {
        setSelectedIssue(issue);
        setCurrentView('issue-details');
        addToNavigationHistory('issue-details', index);
      }
    },
    { wrapAround: true, skipDisabled: true, pageSize: 5 }
  );

  // Handle keyboard shortcuts
  const _handleKeyDown = useCallback(
    (key: string) => {
      switch (key) {
        case 'escape':
          if (currentView === 'issue-details') {
            goBack();
          }
          break;
        case 'q':
          process.exit(0);
          break;
        case 'f':
          // Toggle filter menu - will be implemented later
          break;
        case 'e':
          // Toggle export menu - will be implemented later
          break;
      }
    },
    [currentView, goBack]
  );

  useInput((_input, key) => {
    let handled = false;

    // Handle special keys
    if (key.escape) {
      _handleKeyDown('escape');
      handled = true;
    } else if (_input === 'q') {
      _handleKeyDown('q');
      handled = true;
    } else if (_input === 'f') {
      _handleKeyDown('f');
      handled = true;
    } else if (_input === 'e') {
      _handleKeyDown('e');
      handled = true;
    }

    // Handle navigation based on current view
    if (!handled) {
      if (currentView === 'dashboard' || currentView === 'issue-list') {
        let newIndex = selectedIndex;

        if (key.upArrow || _input === 'k') {
          newIndex = issueListNavigation.handleKeyDown('up', selectedIndex);
        } else if (key.downArrow || _input === 'j') {
          newIndex = issueListNavigation.handleKeyDown('down', selectedIndex);
        } else if (key.ctrl && _input === 'a') {
          newIndex = issueListNavigation.handleKeyDown('home', selectedIndex);
        } else if (key.ctrl && _input === 'e') {
          newIndex = issueListNavigation.handleKeyDown('end', selectedIndex);
        } else if (key.pageUp) {
          newIndex = issueListNavigation.handleKeyDown('pageup', selectedIndex);
        } else if (key.pageDown) {
          newIndex = issueListNavigation.handleKeyDown('pagedown', selectedIndex);
        } else if (key.return) {
          issueListNavigation.handleKeyDown('enter', selectedIndex);
          handled = true;
        } else if (_input >= '1' && _input <= '9') {
          const numericIndex = parseInt(_input) - 1;
          if (numericIndex < filteredIssues.length) {
            newIndex = numericIndex;
            issueListNavigation.handleKeyDown('enter', numericIndex);
            handled = true;
          }
        }

        if (newIndex !== selectedIndex) {
          setSelectedIndex(newIndex);
          if (filteredIssues[newIndex]) {
            setSelectedIssue(filteredIssues[newIndex] ?? null);
          }
        }
      }
    }
  });

  return {
    currentView,
    selectedIssue,
    selectedIndex,
    setCurrentView,
    setSelectedIssue,
    navigateToIssue: (index: number) => {
      if (index >= 0 && index < filteredIssues.length) {
        setSelectedIndex(index);
        setSelectedIssue(filteredIssues[index] ?? null);
        setCurrentView('issue-details');
        addToNavigationHistory('issue-details', index);
      }
    },
    goBack,
  };
}

export function useMenuNavigation(
  itemCount: number,
  onSelect: (index: number) => void,
  onCancel: () => void,
  isOpen: boolean
) {
  const [selectedIndex, setSelectedIndex] = React.useState(0);

  const menuNavigation = createMenuNavigation(itemCount, onSelect, onCancel);

  const _handleKeyDown = useCallback(
    (key: string, currentIndex: number) => {
      const result = menuNavigation.handleKeyDown(key, currentIndex);

      if (result.action === 'select') {
        onSelect(result.index);
        return result.index;
      } else if (result.action === 'cancel') {
        onCancel();
        return currentIndex;
      } else {
        return result.index;
      }
    },
    [menuNavigation, onSelect, onCancel]
  );

  useInput((_input, key) => {
    if (!isOpen) return;

    let newIndex = selectedIndex;

    if (key.upArrow || _input === 'k') {
      newIndex = Math.max(0, selectedIndex - 1);
    } else if (key.downArrow || _input === 'j') {
      newIndex = Math.min(itemCount - 1, selectedIndex + 1);
    } else if (key.ctrl && _input === 'a') {
      newIndex = 0;
    } else if (key.ctrl && _input === 'e') {
      newIndex = itemCount - 1;
    } else if (key.return || _input === ' ') {
      onSelect(selectedIndex);
      return;
    } else if (key.escape) {
      onCancel();
      return;
    } else if (_input >= '1' && _input <= '9') {
      const numericIndex = parseInt(_input) - 1;
      if (numericIndex < itemCount) {
        newIndex = numericIndex;
        onSelect(numericIndex);
        return;
      }
    }

    if (newIndex !== selectedIndex) {
      setSelectedIndex(newIndex);
    }
  });

  // Reset selection when menu opens
  React.useEffect(() => {
    if (isOpen) {
      setSelectedIndex(0);
    }
  }, [isOpen]);

  return {
    selectedIndex,
    setSelectedIndex,
  };
}

/**
 * Use Prioritization Hook
 * Integrates Issue Prioritization Engine with dashboard
 */

import { useCallback, useEffect } from 'react';
import { useDashboardStore } from './useDashboardStore';
import { prioritizationService } from '../services/prioritization-service';
import type { Issue } from '../types/analysis';
import type { IssueWithPriority } from '../types/dashboard';
import type { IssuePrioritization } from '@dev-quality/types';

export const usePrioritization = () => {
  const {
    currentResult,
    filteredIssues,
    prioritizedIssues,
    isProcessingPrioritization,
    prioritizationProgress,
    prioritizationError,
    setPrioritizationData,
    setProcessingPrioritization,
    setPrioritizationProgress,
    setPrioritizationError,
    updateFilteredIssues,
  } = useDashboardStore();

  /**
   * Process all issues through prioritization engine
   */
  const processPrioritization = useCallback(async () => {
    if (!currentResult || isProcessingPrioritization) return;

    try {
      setProcessingPrioritization(true);
      setPrioritizationProgress(0);
      setPrioritizationError(null);

      const allIssues = currentResult.toolResults.flatMap(toolResult => toolResult.issues);
      const totalIssues = allIssues.length;

      if (totalIssues === 0) {
        setPrioritizationProgress(100);
        setProcessingPrioritization(false);
        return;
      }

      // Process issues in batches for better progress tracking
      const batchSize = 10;
      const allPrioritizations: IssuePrioritization[] = [];

      for (let i = 0; i < allIssues.length; i += batchSize) {
        const batch = allIssues.slice(i, i + batchSize);
        const batchPrioritizations = await prioritizationService.processIssues(
          batch,
          currentResult
        );
        allPrioritizations.push(...batchPrioritizations);

        // Update progress
        const progress = Math.min(100, ((i + batch.length) / totalIssues) * 100);
        setPrioritizationProgress(progress);
      }

      // Store prioritization data
      setPrioritizationData(allPrioritizations);

      // Enrich current issues with priority data
      const enrichedIssues = prioritizationService.enrichIssuesWithPriority(
        filteredIssues,
        allPrioritizations
      );
      updateFilteredIssues(enrichedIssues as Issue[]);

      setPrioritizationProgress(100);
    } catch (error) {
      setPrioritizationError(error instanceof Error ? error.message : 'Unknown error occurred');
    } finally {
      setProcessingPrioritization(false);
    }
  }, [
    currentResult,
    filteredIssues,
    isProcessingPrioritization,
    setPrioritizationData,
    setProcessingPrioritization,
    setPrioritizationProgress,
    setPrioritizationError,
    updateFilteredIssues,
  ]);

  /**
   * Filter issues by priority levels
   */
  const filterByPriorityLevels = useCallback(
    (priorityLevels: string[]) => {
      if (!prioritizedIssues.length) return;

      const enrichedIssues = prioritizationService.enrichIssuesWithPriority(
        filteredIssues,
        prioritizedIssues
      );
      const filteredByPriority = prioritizationService.filterByPriority(
        enrichedIssues,
        priorityLevels
      );
      updateFilteredIssues(filteredByPriority as Issue[]);
    },
    [filteredIssues, prioritizedIssues, updateFilteredIssues]
  );

  /**
   * Sort issues by priority
   */
  const sortIssuesByPriority = useCallback(
    (order: 'asc' | 'desc' = 'desc') => {
      if (!prioritizedIssues.length) return;

      const enrichedIssues = prioritizationService.enrichIssuesWithPriority(
        filteredIssues,
        prioritizedIssues
      );
      const sortedByPriority = prioritizationService.sortByPriority(enrichedIssues, order);
      updateFilteredIssues(sortedByPriority as Issue[]);
    },
    [filteredIssues, prioritizedIssues, updateFilteredIssues]
  );

  /**
   * Get priority statistics for current issues
   */
  const getPriorityStatistics = useCallback(() => {
    if (!prioritizedIssues.length) {
      return {
        critical: 0,
        high: 0,
        medium: 0,
        low: 0,
        total: 0,
        averageScore: 0,
      };
    }

    const enrichedIssues = prioritizationService.enrichIssuesWithPriority(
      filteredIssues,
      prioritizedIssues
    );
    return prioritizationService.getPriorityStatistics(enrichedIssues);
  }, [filteredIssues, prioritizedIssues]);

  /**
   * Check if issues have priority data
   */
  const hasPriorityData = useCallback(
    (issue: Issue | IssueWithPriority): issue is IssueWithPriority => {
      return 'priority' in issue || 'priorityScore' in issue;
    },
    []
  );

  /**
   * Get issues enriched with priority data
   */
  const getEnrichedIssues = useCallback((): IssueWithPriority[] => {
    if (!prioritizedIssues.length) return filteredIssues as IssueWithPriority[];

    return prioritizationService.enrichIssuesWithPriority(filteredIssues, prioritizedIssues);
  }, [filteredIssues, prioritizedIssues]);

  /**
   * Auto-trigger prioritization when new analysis results are available
   */
  useEffect(() => {
    if (currentResult && !isProcessingPrioritization && prioritizedIssues.length === 0) {
      processPrioritization();
    }
  }, [currentResult, isProcessingPrioritization, prioritizedIssues.length, processPrioritization]);

  return {
    // Data
    prioritizedIssues,
    enrichedIssues: getEnrichedIssues(),

    // State
    isProcessingPrioritization,
    prioritizationProgress,
    prioritizationError,

    // Actions
    processPrioritization,
    filterByPriorityLevels,
    sortIssuesByPriority,

    // Utilities
    getPriorityStatistics,
    hasPriorityData,
  };
};

#!/usr/bin/env node

import { Command } from 'commander';
import { render } from 'ink';
import React from 'react';
import { version } from '../package.json';
import { SetupCommand } from './commands/setup';
import { ConfigCommand } from './commands/config';
import { AnalyzeCommand } from './commands/analyze';
import { ReportCommand } from './commands/report';
import { App } from './components/app';

const program = new Command();

program
  .name('dev-quality')
  .description('DevQuality CLI tool for code quality analysis and reporting')
  .version(version, '-v, --version', 'Display the version number')
  .helpOption('-h, --help', 'Display help for command')
  .allowUnknownOption(false)
  .configureHelp({
    sortSubcommands: true,
    subcommandTerm: command => command.name(),
  });

program.option('--verbose', 'Enable verbose output', false);
program.option('--quiet', 'Suppress all output except errors', false);
program.option('--json', 'Output results as JSON', false);
program.option('--config <path>', 'Path to configuration file', '.dev-quality.json');
program.option('--no-cache', 'Disable caching', false);

program
  .command('setup')
  .description('Initialize DevQuality for your project')
  .option('-f, --force', 'Force overwrite existing configuration', false)
  .option('-i, --interactive', 'Interactive setup mode', true)
  .action(async options => {
    try {
      const setupCommand = new SetupCommand(options);
      await setupCommand.execute();
    } catch (error) {
      process.stderr.write(`Setup failed: ${error instanceof Error ? error.message : error}\n`);
      process.exit(1);
    }
  });

program
  .command('config')
  .description('Manage DevQuality configuration')
  .option('-s, --show', 'Show current configuration', false)
  .option('-e, --edit', 'Edit configuration', false)
  .option('-r, --reset', 'Reset to default configuration', false)
  .action(async options => {
    try {
      const configCommand = new ConfigCommand(options);
      await configCommand.execute();
    } catch (error) {
      process.stderr.write(
        `Config command failed: ${error instanceof Error ? error.message : error}\n`
      );
      process.exit(1);
    }
  });

program
  .command('analyze')
  .alias('a')
  .description('Analyze code quality using configured tools')
  .option('-t, --tools <tools>', 'Comma-separated list of tools to run')
  .option('-o, --output <path>', 'Output file path for results')
  .option('-f, --format <format>', 'Output format (json, html, md)', 'json')
  .option('--fail-on-error', 'Exit with error code on analysis failures', false)
  .option('-d, --dashboard', 'Show interactive dashboard', false)
  .option('--no-dashboard', 'Disable interactive dashboard')
  .option('--export <format>', 'Export results to specified format (json, txt, csv, md, junit)')
  .option('--filter <filter>', 'Apply filter to results (e.g., severity:error)')
  .option('--sort-by <field>', 'Sort results by field (score, severity, file, tool)')
  .option('--max-items <number>', 'Maximum number of items to display')
  .option('--quick', 'Quick analysis with minimal output', false)
  .action(async options => {
    try {
      const analyzeCommand = new AnalyzeCommand(options);
      await analyzeCommand.execute();
    } catch (error) {
      process.stderr.write(`Analysis failed: ${error instanceof Error ? error.message : error}\n`);
      process.exit(1);
    }
  });

program
  .command('report')
  .alias('r')
  .description('Generate comprehensive quality reports')
  .option('-t, --type <type>', 'Report type (summary, detailed, comparison)', 'summary')
  .option('-o, --output <path>', 'Output file path for report')
  .option('-f, --format <format>', 'Report format (html, md, json)', 'html')
  .option('--include-history', 'Include historical data in report', false)
