                    <th>Time (ms)</th>
                </tr>
            </thead>
            <tbody>
                ${analysisResult.toolResults?.map(tool => `
                <tr>
                    <td>${this.escapeHtml(tool.toolName)}</td>
                    <td class="status-${tool.status}">${tool.status}</td>
                    <td>${tool.issues.length}</td>
