        </table>

        ${metrics.coverage ? `
        <h3 class="subsection-title">Code Coverage</h3>
        <div class="metrics-grid">
            <div class="metric-box">
                <div class="metric-value">${metrics.coverage.lines.percentage}%</div>
                <div class="metric-label">Lines</div>
