  ): Promise<GitHubResult> {
    const url = `${this.apiUrl}/repos/${this.config.owner}/${this.config.repo}/statuses/${commitSha}`;
    let retryCount = 0;

    while (retryCount <= this.maxRetries) {
      try {
        const response = await fetch(url, {
