    };
  }

  /**
   * Create or update check run for commit
   */
  async createCheckRun(
    commitSha: string,
    checkData: {
      name: string;
      title: string;
      summary: string;
      text?: string;
      conclusion?: 'success' | 'failure' | 'neutral' | 'cancelled' | 'timed_out' | 'action_required';
      detailsUrl?: string;
    }
  ): Promise<GitHubResult> {
    const url = `${this.apiUrl}/repos/${this.config.owner}/${this.config.repo}/check-runs`;
    let retryCount = 0;

    while (retryCount <= this.maxRetries) {
      try {
        const response = await fetch(url, {
          method: 'POST',
          headers: {
            'Authorization': `token ${this.config.token}`,
            'Accept': 'application/vnd.github.v3+json',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            name: checkData.name,
            head_sha: commitSha,
            status: 'completed',
            conclusion: checkData.conclusion || 'success',
            output: {
              title: checkData.title,
              summary: checkData.summary,
              text: checkData.text
            },
            details_url: checkData.detailsUrl
          })
        });

        if (response.ok) {
          const data = await response.json();
          return {
            success: true,
            data: {
              checkRunId: data.id,
              checkRunUrl: data.html_url
            }
          };
        }

        // Handle rate limiting
        if (response.status === 403) {
          const rateLimitRemaining = response.headers.get('X-RateLimit-Remaining');
          if (rateLimitRemaining === '0') {
            const resetTime = response.headers.get('X-RateLimit-Reset');
            if (resetTime) {
              const waitTime = parseInt(resetTime) * 1000 - Date.now();
              if (waitTime > 0) {
                await this.sleep(Math.max(waitTime, 1000));
                retryCount++;
                continue;
              }
            }
          }
        }

        const errorText = await response.text();
        throw new Error(`HTTP ${response.status}: ${errorText}`);

      } catch (error) {
        retryCount++;

        if (retryCount > this.maxRetries) {
          return {
            success: false,
            error: error instanceof Error ? error.message : 'Unknown error',
            retryCount
          };
        }

        await this.sleep(this.calculateRetryDelay(retryCount));
      }
    }

    return {
      success: false,
      error: 'Max retries exceeded',
      retryCount
    };
  }

  /**
   * Format quality issue for GitHub
   */
  private formatIssueForGitHub(issue: {
    title: string;
    description: string;
    severity: 'error' | 'warning' | 'info';
    filePath?: string;
    lineNumber?: number;
    ruleId?: string;
    suggestedFix?: string;
  }): GitHubIssue {
    let body = issue.description;

    // Add file location if available
    if (issue.filePath) {
      const location = issue.lineNumber
        ? `${issue.filePath}:${issue.lineNumber}`
        : issue.filePath;
      body += `\n\n**Location:** \`${location}\``;
    }

    // Add rule ID if available
    if (issue.ruleId) {
      body += `\n\n**Rule:** \`${issue.ruleId}\``;
    }

    // Add suggested fix if available
    if (issue.suggestedFix) {
      body += `\n\n**Suggested Fix:**\n\`\`\`\n${issue.suggestedFix}\n\`\`\``;
    }

    // Add footer
    body += `\n\n---\n*This issue was automatically created by DevQuality CLI*`;

    const labels = [
      ...this.getDefaultLabelsForSeverity(issue.severity),
      ...(this.config.defaultLabels || [])
    ];

    const assignees = this.config.defaultAssignee ? [this.config.defaultAssignee] : [];

    return {
      title: issue.title,
      body,
      labels: [...new Set(labels)], // Remove duplicates
      assignees
    };
  }

  /**
   * Get default labels based on severity
   */
  private getDefaultLabelsForSeverity(severity: 'error' | 'warning' | 'info'): string[] {
    const baseLabels = ['dev-quality-cli'];

    switch (severity) {
      case 'error':
        return [...baseLabels, 'bug', 'high-priority'];
      case 'warning':
        return [...baseLabels, 'enhancement', 'medium-priority'];
      case 'info':
        return [...baseLabels, 'documentation', 'low-priority'];
      default:
        return baseLabels;
    }
  }

  /**
   * Validate GitHub configuration
   */
  private validateConfig(): void {
    if (!this.config.token) {
      throw new Error('GitHub token is required');
    }

    if (!this.config.owner) {
      throw new Error('GitHub repository owner is required');
    }

    if (!this.config.repo) {
      throw new Error('GitHub repository name is required');
    }

    // Validate token format (GitHub tokens start with certain patterns)
    if (!this.config.token.startsWith('ghp_') && !this.config.token.startsWith('github_pat_')) {
      console.warn('Warning: GitHub token format may be invalid. Expected token to start with "ghp_" or "github_pat_"');
    }
  }

  /**
   * Calculate retry delay with exponential backoff
   */
  private calculateRetryDelay(attempt: number): number {
    return this.retryDelay * Math.pow(2, attempt - 1);
  }

  /**
   * Sleep for specified milliseconds
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Test GitHub API connection
   */
  async testConnection(): Promise<{ success: boolean; error?: string; userInfo?: any }> {
    try {
      const response = await fetch(`${this.apiUrl}/user`, {
        headers: {
          'Authorization': `token ${this.config.token}`,
          'Accept': 'application/vnd.github.v3+json'
        }
      });

      if (response.ok) {
        const userInfo = await response.json();
        return {
          success: true,
          userInfo: {
            login: userInfo.login,
            name: userInfo.name,
            email: userInfo.email
          }
        };
      } else {
        const errorText = await response.text();
        return {
          success: false,
          error: `GitHub API error: ${response.status} - ${errorText}`
        };
      }
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }

  /**
   * Get repository information
   */
  async getRepositoryInfo(): Promise<GitHubResult> {
    try {
      const response = await fetch(`${this.apiUrl}/repos/${this.config.owner}/${this.config.repo}`, {
        headers: {
          'Authorization': `token ${this.config.token}`,
          'Accept': 'application/vnd.github.v3+json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        return {
          success: true,
          data: {
            name: data.name,
            fullName: data.full_name,
            description: data.description,
            private: data.private,
            defaultBranch: data.default_branch,
            language: data.language
          }
        };
      } else {
        const errorText = await response.text();
        return {
          success: false,
          error: `GitHub API error: ${response.status} - ${errorText}`
        };
      }
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }

  /**
   * Update configuration
   */
  updateConfig(newConfig: Partial<GitHubConfig>): void {
    this.config = { ...this.config, ...newConfig };
    this.validateConfig();
  }

  /**
   * Get current configuration (without sensitive data)
   */
  getConfig(): Omit<GitHubConfig, 'token'> {
    const { token, ...safeConfig } = this.config;
    return safeConfig;
  }
}

/**
 * Slack Integration Service
 *
 * Provides Slack webhook integration for report delivery as required by Story 2.4 AC4.
 * Includes security validation, retry mechanisms, and proper error handling.
 */

declare const fetch: (input: string | globalThis.Request, init?: globalThis.RequestInit) => Promise<globalThis.Response>;
declare const URL: typeof globalThis.URL;

export interface SlackConfig {
  webhookUrl: string;
  channel?: string;
  username?: string;
  iconEmoji?: string;
  mentionUsers?: string[];
  mentionChannel?: boolean;
}

export interface SlackMessage {
  text?: string;
  attachments: SlackAttachment[];
  channel?: string;
  username?: string;
  icon_emoji?: string;
}

export interface SlackAttachment {
  color: 'good' | 'warning' | 'danger';
  title: string;
  title_link?: string;
  text: string;
  fields?: SlackField[];
  footer?: string;
  ts?: number;
}

export interface SlackField {
  title: string;
  value: string;
  short?: boolean;
}

export interface SlackDeliveryResult {
  success: boolean;
  messageId?: string;
  error?: string;
  retryCount?: number;
}

export class SlackService {
  private readonly MAX_RETRIES = 3;
  private readonly RETRY_DELAY_BASE = 1000; // 1 second
  private readonly MAX_MESSAGE_LENGTH = 4000; // Slack message limit

  /**
   * Escape HTML content to prevent XSS attacks
   */
  private escapeHtml(text: string): string {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  /**
   * Send a report to Slack via webhook
   */
  async sendReport(config: SlackConfig, reportData: {
    title: string;
    summary: string;
    reportUrl?: string;
    metrics: Record<string, unknown>;
    priority: 'low' | 'medium' | 'high' | 'critical';
  }): Promise<SlackDeliveryResult> {
    this.validateConfig(config);

    const message = this.buildSlackMessage(config, reportData);
    return this.sendWithRetry(config.webhookUrl, message, 0);
  }

  /**
   * Validate Slack configuration
   */
  private validateConfig(config: SlackConfig): void {
    if (!config.webhookUrl) {
      throw new Error('Slack webhook URL is required');
    }

    if (!this.isValidWebhookUrl(config.webhookUrl)) {
      throw new Error('Invalid Slack webhook URL format');
    }

    if (config.channel !== undefined && !this.isValidChannel(config.channel)) {
      throw new Error('Invalid Slack channel format');
    }
  }

  /**
   * Build Slack message from report data
   */
  private buildSlackMessage(config: SlackConfig, reportData: {
    title: string;
    summary: string;
    reportUrl?: string;
    metrics: Record<string, unknown>;
    priority: 'low' | 'medium' | 'high' | 'critical';
  }): SlackMessage {
    const color = this.getColorByPriority(reportData.priority);
    const text = this.buildMessageText(config, reportData);

    const attachment: SlackAttachment = {
      color,
      title: this.escapeHtml(reportData.title),
      title_link: reportData.reportUrl,
      text: this.truncateText(this.escapeHtml(reportData.summary), 2000),
      fields: this.buildFields(reportData.metrics),
      footer: 'Quality Tracking CLI',
      ts: Math.floor(Date.now() / 1000)
    };

    return {
      text,
      attachments: [attachment],
      channel: config.channel,
      username: config.username ?? 'Quality Tracking',
      icon_emoji: config.iconEmoji ?? ':bar_chart:'
    };
  }

  /**
   * Build message text with mentions
   */
  private buildMessageText(config: SlackConfig, reportData: {
    title: string;
    summary: string;
    metrics: Record<string, unknown>;
    priority: 'low' | 'medium' | 'high' | 'critical';
  }): string {
    let text = '';

    if (config.mentionChannel) {
      text += '<!channel> ';
    }

    if (config.mentionUsers && config.mentionUsers.length > 0) {
      const mentions = config.mentionUsers.map(user => `<@${user}>`).join(' ');
      text += `${mentions} `;
    }

    const priorityEmoji = this.getPriorityEmoji(reportData.priority);
    text += `${priorityEmoji} *${this.escapeHtml(reportData.title)}*`;

    return text;
  }

  /**
   * Build fields from metrics
   */
  private buildFields(metrics: Record<string, unknown>): SlackField[] {
    const fields: SlackField[] = [];

    Object.entries(metrics).forEach(([key, value]) => {
      if (typeof value === 'number') {
        fields.push({
          title: this.formatFieldName(key),
          value: this.formatMetricValue(key, value),
          short: true
        });
      } else if (typeof value === 'string') {
        fields.push({
          title: this.formatFieldName(key),
          value: this.truncateText(this.escapeHtml(value), 100),
          short: true
        });
      }
    });

    return fields;
  }

  /**
   * Send message with retry logic
   */
  private async sendWithRetry(
    webhookUrl: string,
    message: SlackMessage,
    retryCount: number
  ): Promise<SlackDeliveryResult> {
    try {
      const response = await fetch(webhookUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(message)
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const result = await response.json() as { ts: string };
      return {
        success: true,
        messageId: result.ts || Date.now().toString(),
        retryCount
      };

    } catch (error) {
      if (retryCount < this.MAX_RETRIES) {
        const delay = this.RETRY_DELAY_BASE * Math.pow(2, retryCount);
        await this.sleepForTest(delay);
        return this.sendWithRetry(webhookUrl, message, retryCount + 1);
      }

      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
        retryCount
      };
    }
  }

  /**
   * Validate webhook URL format and security
   */
  private isValidWebhookUrl(url: string): boolean {
    try {
      const parsed = new URL(url);

      // Must be HTTPS for security
      if (parsed.protocol !== 'https:') {
        return false;
      }

      // Must be Slack domain
      if (!parsed.hostname.endsWith('.slack.com') && !parsed.hostname.includes('hooks.slack.com')) {
        return false;
      }

      // Must contain expected path pattern
      if (!parsed.pathname.includes('/services/') && !parsed.pathname.includes('/hooks/')) {
        return false;
      }

      return true;
    } catch {
      return false;
    }
  }

  /**
   * Validate channel format
   */
  private isValidChannel(channel: string): boolean {
    // Channel can be #channel-name or @username
    return /^#?[\w-]+$|^@[\w.-]+$/.test(channel);
  }

  /**
   * Get color based on priority
   */
  private getColorByPriority(priority: string): 'good' | 'warning' | 'danger' {
    switch (priority) {
      case 'low':
        return 'good';
      case 'medium':
        return 'warning';
      case 'high':
      case 'critical':
        return 'danger';
      default:
        return 'warning';
    }
  }

  /**
   * Get emoji based on priority
   */
  private getPriorityEmoji(priority: string): string {
    switch (priority) {
      case 'low':
        return ':large_green_circle:';
      case 'medium':
        return ':large_yellow_circle:';
      case 'high':
        return ':large_orange_circle:';
      case 'critical':
        return ':red_circle:';
      default:
        return ':large_yellow_circle:';
    }
  }

  /**
   * Format field name for display
   */
  private formatFieldName(key: string): string {
    return key
      .split(/(?=[A-Z])|[_-]/)
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }

  /**
   * Format metric value for display
   */
  private formatMetricValue(key: string, value: number): string {
    if (key.toLowerCase().includes('percentage')) {
      return `${value.toFixed(1)}%`;
    }

    if (key.toLowerCase().includes('rate')) {
      // Convert decimal rate (0.85) to percentage (85.0%)
      return `${(value * 100).toFixed(1)}%`;
    }

    if (key.toLowerCase().includes('time') || key.toLowerCase().includes('duration')) {
      return `${value}ms`;
    }

    if (key.toLowerCase().includes('memory')) {
      return `${(value / 1024 / 1024).toFixed(1)}MB`;
    }

    return value.toLocaleString();
  }

  /**
   * Truncate text to fit within limits
   */
  private truncateText(text: string, maxLength: number): string {
    if (text.length <= maxLength) {
      return text;
    }
    return text.substring(0, maxLength - 3) + '...';
  }

  /**
   * Sleep for specified milliseconds
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Test mode sleep - shorter delays for testing
   */
  private sleepForTest(ms: number): Promise<void> {
    // Use shorter delays in test environment
    const isTest = process.env.NODE_ENV === 'test' || process.env.CLAUDECODE === '1';
    return new Promise(resolve => setTimeout(resolve, isTest ? Math.min(ms, 100) : ms));
  }

  /**
   * Test webhook connectivity
   */
  async testConnection(config: SlackConfig): Promise<{ success: boolean; error?: string }> {
    try {
      this.validateConfig(config);

      const testMessage: SlackMessage = {
        text: '🧪 Test message from Quality Tracking CLI',
        attachments: [{
          color: 'good',
          title: 'Connection Test',
          text: 'If you can see this, Slack integration is working correctly!',
          footer: 'Quality Tracking CLI',
          ts: Math.floor(Date.now() / 1000)
        }],
        channel: config.channel,
        username: config.username ?? 'Quality Tracking',
        icon_emoji: config.iconEmoji ?? ':bar_chart:'
      };

      const result = await this.sendWithRetry(config.webhookUrl, testMessage, 0);
      return { success: result.success, error: result.error };

    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }
}

/**
 * Microsoft Teams Integration Service
 *
 * Provides integration with Microsoft Teams for report notifications and sharing.
 * Supports adaptive cards, channel notifications, and message formatting.
 */

import fetch from 'node-fetch';

export interface TeamsConfig {
  webhookUrl: string;
  tenantId?: string;
  serviceUrl?: string;
  appId?: string;
  appPassword?: string;
}

export interface TeamsMessage {
  type: 'message' | 'adaptiveCard';
  title?: string;
  text: string;
  summary?: string;
  themeColor?: string;
  sections?: TeamsMessageSection[];
  potentialAction?: TeamsAction[];
}

export interface TeamsMessageSection {
  activityTitle?: string;
  activitySubtitle?: string;
  activityImage?: string;
  facts?: TeamsFact[];
  markdown?: boolean;
}

export interface TeamsFact {
  name: string;
  value: string;
}

export interface TeamsAction {
  '@type': 'OpenUri' | 'PostBack' | 'ActionCard';
  name: string;
  targets?: Array<{ os: 'default'; uri: string }>;
  data?: Record<string, unknown>;
}

export interface TeamsNotificationResult {
  success: boolean;
  messageId?: string;
  error?: string;
  retryCount?: number;
}

/**
 * Microsoft Teams Service
 * Handles sending report notifications to Microsoft Teams channels
 */
export class TeamsService {
  private maxRetries = 3;
  private retryDelay = 1000; // 1 second base delay

  constructor(private config: TeamsConfig) {
    this.validateConfig();
  }

  /**
   * Send report notification to Teams
   */
  async sendReportNotification(
    reportData: {
      title: string;
      summary: string;
      reportUrl?: string;
      metrics: Record<string, any>;
      projectName: string;
    }
  ): Promise<TeamsNotificationResult> {
    const message = this.createReportMessage(reportData);
    return this.sendMessage(message);
  }

  /**
   * Send failure notification to Teams
   */
  async sendFailureNotification(
    failureData: {
      projectName: string;
      error: string;
      timestamp: Date;
      retryAttempt?: number;
    }
  ): Promise<TeamsNotificationResult> {
    const message = this.createFailureMessage(failureData);
    return this.sendMessage(message);
  }

  /**
   * Send trend alert to Teams
   */
  async sendTrendAlert(
    trendData: {
      projectName: string;
      metric: string;
      direction: 'up' | 'down';
      changePercentage: number;
      alertLevel: 'info' | 'warning' | 'critical';
    }
  ): Promise<TeamsNotificationResult> {
    const message = this.createTrendMessage(trendData);
    return this.sendMessage(message);
  }

  /**
   * Create report notification message
   */
  private createReportMessage(reportData: {
    title: string;
    summary: string;
    reportUrl?: string;
    metrics: Record<string, any>;
    projectName: string;
  }): TeamsMessage {
    const themeColor = this.getThemeColorForScore(reportData.metrics.overallScore || 0);

    const facts: TeamsFact[] = [
      { name: 'Project', value: reportData.projectName },
      { name: 'Overall Score', value: `${reportData.metrics.overallScore || 0}/100` },
      { name: 'Total Issues', value: reportData.metrics.totalIssues || 0 },
      { name: 'Errors', value: reportData.metrics.errorCount || 0 },
      { name: 'Warnings', value: reportData.metrics.warningCount || 0 }
    ];

    // Add fixable count if available
    if (reportData.metrics.fixableCount !== undefined) {
      facts.push({ name: 'Fixable Issues', value: reportData.metrics.fixableCount });
    }

    // Add duration if available
    if (reportData.metrics.duration) {
      facts.push({ name: 'Analysis Duration', value: `${(reportData.metrics.duration / 1000).toFixed(1)}s` });
    }

    const sections: TeamsMessageSection[] = [
      {
        activityTitle: reportData.title,
        activitySubtitle: new Date().toLocaleString(),
        facts,
        markdown: true
      }
    ];

    const actions: TeamsAction[] = [];

    if (reportData.reportUrl) {
      actions.push({
        '@type': 'OpenUri',
        name: 'View Full Report',
        targets: [
          {
            os: 'default',
            uri: reportData.reportUrl
          }
        ]
      });
    }

    return {
      type: 'message',
      title: reportData.title,
      text: reportData.summary,
      summary: `Quality report for ${reportData.projectName}`,
      themeColor,
      sections,
      potentialAction: actions.length > 0 ? actions : undefined
    };
  }

  /**
   * Create failure notification message
   */
  private createFailureMessage(failureData: {
    projectName: string;
    error: string;
    timestamp: Date;
    retryAttempt?: number;
  }): TeamsMessage {
    const sections: TeamsMessageSection[] = [
      {
        activityTitle: `❌ Report Generation Failed`,
        activitySubtitle: failureData.timestamp.toLocaleString(),
        facts: [
          { name: 'Project', value: failureData.projectName },
          { name: 'Error', value: this.truncateMessage(failureData.error, 300) },
          { name: 'Retry Attempt', value: failureData.retryAttempt?.toString() || '1' }
        ],
        markdown: false
      }
    ];

    return {
      type: 'message',
      title: 'Quality Report Generation Failed',
      text: `Failed to generate quality report for ${failureData.projectName}`,
      summary: `Report generation failed for ${failureData.projectName}`,
      themeColor: 'FF0000', // Red for failures
      sections
    };
  }

  /**
   * Create trend alert message
   */
  private createTrendMessage(trendData: {
    projectName: string;
    metric: string;
    direction: 'up' | 'down';
    changePercentage: number;
    alertLevel: 'info' | 'warning' | 'critical';
  }): TeamsMessage {
    const trendIcon = trendData.direction === 'up' ? '📈' : '📉';
    const themeColor = this.getThemeColorForAlert(trendData.alertLevel);

    const sections: TeamsMessageSection[] = [
      {
        activityTitle: `${trendIcon} Trend Alert`,
        activitySubtitle: new Date().toLocaleString(),
        facts: [
          { name: 'Project', value: trendData.projectName },
          { name: 'Metric', value: trendData.metric },
          { name: 'Direction', value: `${trendData.direction === 'up' ? 'Improving' : 'Declining'} (${trendData.changePercentage.toFixed(1)}%)` },
          { name: 'Alert Level', value: trendData.alertLevel.toUpperCase() }
        ],
        markdown: true
      }
    ];

    return {
      type: 'message',
      title: 'Quality Trend Alert',
      text: `${trendData.metric} is ${trendData.direction === 'up' ? 'improving' : 'declining'} by ${trendData.changePercentage.toFixed(1)}%`,
      summary: `Trend alert for ${trendData.projectName}`,
      themeColor,
      sections
    };
  }

  /**
   * Send message to Teams with retry logic
   */
  private async sendMessage(message: TeamsMessage): Promise<TeamsNotificationResult> {
    let retryCount = 0;

    while (retryCount <= this.maxRetries) {
      try {
        const response = await fetch(this.config.webhookUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(message)
        });

        if (response.ok) {
          return {
            success: true,
            messageId: `teams-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
          };
        }

        // Handle rate limiting (429)
        if (response.status === 429) {
          const retryAfter = response.headers.get('Retry-After');
          const delay = retryAfter ? parseInt(retryAfter) * 1000 : this.calculateRetryDelay(retryCount);
          await this.sleep(delay);
          retryCount++;
          continue;
        }

        // Handle other HTTP errors
        const errorText = await response.text();
        throw new Error(`HTTP ${response.status}: ${errorText}`);

      } catch (error) {
        retryCount++;

        if (retryCount > this.maxRetries) {
          return {
            success: false,
            error: error instanceof Error ? error.message : 'Unknown error',
            retryCount
          };
        }

        // Wait before retry
        await this.sleep(this.calculateRetryDelay(retryCount));
      }
    }

    return {
      success: false,
      error: 'Max retries exceeded',
      retryCount
    };
  }

  /**
   * Validate Teams configuration
   */
  private validateConfig(): void {
    if (!this.config.webhookUrl) {
      throw new Error('Teams webhook URL is required');
    }

    try {
      new URL(this.config.webhookUrl);
    } catch {
      throw new Error('Invalid Teams webhook URL format');
    }

    // Validate URL format for Teams webhook
    if (!this.config.webhookUrl.includes('office.com/webhook')) {
      throw new Error('Invalid Teams webhook URL - must be a valid Microsoft Teams webhook URL');
    }
  }

  /**
   * Get theme color based on score
   */
  private getThemeColorForScore(score: number): string {
    if (score >= 80) return '00FF00'; // Green
    if (score >= 60) return 'FFA500'; // Orange
    return 'FF0000'; // Red
  }

  /**
   * Get theme color based on alert level
   */
  private getThemeColorForAlert(alertLevel: 'info' | 'warning' | 'critical'): string {
    switch (alertLevel) {
      case 'info': return '0080FF'; // Blue
      case 'warning': return 'FFA500'; // Orange
      case 'critical': return 'FF0000'; // Red
      default: return '808080'; // Gray
    }
  }

  /**
   * Calculate retry delay with exponential backoff
   */
  private calculateRetryDelay(attempt: number): number {
    return this.retryDelay * Math.pow(2, attempt - 1);
  }

  /**
   * Truncate message to prevent overly long messages
   */
  private truncateMessage(message: string, maxLength: number): string {
    if (message.length <= maxLength) return message;
    return message.substring(0, maxLength - 3) + '...';
  }

  /**
   * Sleep for specified milliseconds
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Test Teams connection
   */
  async testConnection(): Promise<{ success: boolean; error?: string }> {
    try {
      const testMessage: TeamsMessage = {
        type: 'message',
        title: 'Connection Test',
        text: 'Testing DevQuality CLI Teams integration',
        summary: 'Connection test message',
        themeColor: '00FF00'
      };

      const result = await this.sendMessage(testMessage);
      return {
        success: result.success,
        error: result.error
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }

  /**
   * Update configuration
   */
  updateConfig(newConfig: Partial<TeamsConfig>): void {
    this.config = { ...this.config, ...newConfig };
    this.validateConfig();
  }

  /**
   * Get current configuration
   */
  getConfig(): Omit<TeamsConfig, 'appPassword'> {
    const { appPassword, ...safeConfig } = this.config;
    return safeConfig;
  }
}

/**
 * Comprehensive Report Generator Service
 * Extends existing export functionality with advanced reporting capabilities
 */

import { randomUUID } from 'node:crypto';
import { writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

import type { AnalysisResult, Issue } from '../../types/analysis';
import type { DashboardMetrics } from '../../types/dashboard';
// import type { ExportFormat, ExportOptions } from '../../types/export'; // Not used

import { ExportService } from '../export/export-service';
