  outputPath: string;
  format: ReportFormat;
  size: number;
  generatedAt: Date;
  duration: number;
  error?: string;
  metadata: ReportMetadata;
}

export interface ReportProgress {
  reportId: string;
  currentStep: string;
  percentage: number;
  estimatedTimeRemaining?: number;
  bytesWritten?: number;
  currentOperation?: string;
}

export interface ReportMetadata {
  title: string;
  description?: string;
  author?: string;
  version: string;
  tags?: string[];
  category?: string;
  sensitivity?: 'public' | 'internal' | 'confidential';
}

export interface HistoricalData {
  timestamp: Date;
  overallScore: number;
  totalIssues: number;
  errorCount: number;
  warningCount: number;
  infoCount: number;
  fixableCount: number;
  toolResults: Array<{
    toolName: string;
    score: number;
    issuesCount: number;
  }>;
}

export interface TrendAnalysis {
  period: string;
  direction: 'improving' | 'declining' | 'stable';
  changePercentage: number;
  confidence: number;
  insights: string[];
}

export interface ExecutiveSummary {
  overview: string;
  keyMetrics: Array<{
    label: string;
    value: string | number;
    trend: 'up' | 'down' | 'stable';
    significance: 'high' | 'medium' | 'low';
  }>;
  priorities: Array<{
    title: string;
    description: string;
    impact: 'high' | 'medium' | 'low';
    effort: 'high' | 'medium' | 'low';
  }>;
  recommendations: string[];
  nextSteps: string[];
}

/**
 * Main Report Generator Service
 * Orchestrates comprehensive report generation with multiple formats and templates
 */
export class ReportGenerator {
  private exportService: ExportService;
  private formatters: Map<ReportFormat, { format(data: unknown, template: TemplateDefinition | ReportTemplate): Promise<string> }>;
  private templateService: TemplateService;
  private activeReports: Map<string, ReportProgress>;

  constructor() {
    this.exportService = new ExportService();
    this.formatters = new Map();
    this.templateService = new TemplateService();
    this.activeReports = new Map();

    this.initializeFormatters();
  }

  /**
   * Initialize format-specific formatters
   */
  private initializeFormatters(): void {
    this.formatters.set('json', new JSONFormatter());
    this.formatters.set('html', new HTMLFormatter());
    this.formatters.set('markdown', new MarkdownFormatter());
    this.formatters.set('pdf', new PDFFormatter());
  }


  /**
   * Generate comprehensive report
   */
  async generateReport(request: ReportRequest): Promise<ReportResult> {
    const reportId = randomUUID();
    const startTime = performance.now();

    const {
      configuration,
      analysisResult,
      issues,
      metrics,
      historicalData,
      onProgress,
    } = request;

    try {
      // Initialize progress tracking
      this.updateProgress(reportId, {
        reportId,
        currentStep: 'Initializing report generation',
        percentage: 0,
        currentOperation: 'setup',
      });

      onProgress?.(this.activeReports.get(reportId) ?? { reportId, currentStep: '', percentage: 0 });

      // Validate configuration
      this.validateConfiguration(configuration);

      this.updateProgress(reportId, {
        reportId,
        currentStep: 'Preparing data',
        percentage: 10,
        currentOperation: 'data-preparation',
      });
      onProgress?.(this.activeReports.get(reportId) ?? { reportId, currentStep: '', percentage: 0 });

      // Get template
      const template = this.templateService.getTemplate(configuration.templateId);
      if (!template) {
        throw new Error(`Template not found: ${configuration.templateId}`);
      }

      // Apply filters to issues
      const filteredIssues = this.applyFilters(issues, configuration.filters);

      // Generate executive summary if needed
      let executiveSummary: ExecutiveSummary | undefined;
      if (this.sectionEnabled(template, 'summary')) {
        executiveSummary = await this.generateExecutiveSummary(
          analysisResult,
          filteredIssues,
          metrics,
          historicalData
        );

        this.updateProgress(reportId, {
          reportId,
          currentStep: 'Generating executive summary',
          percentage: 30,
          currentOperation: 'summary-generation',
        });
        onProgress?.(this.activeReports.get(reportId) ?? { reportId, currentStep: '', percentage: 0 });
      }

      // Generate trend analysis if historical data available
      let trendAnalysis: TrendAnalysis | undefined;
      if (historicalData && historicalData.length > 0 && this.sectionEnabled(template, 'trends')) {
        trendAnalysis = this.generateTrendAnalysis(historicalData);

        this.updateProgress(reportId, {
          reportId,
          currentStep: 'Analyzing trends',
          percentage: 50,
          currentOperation: 'trend-analysis',
        });
        onProgress?.(this.activeReports.get(reportId) ?? { reportId, currentStep: '', percentage: 0 });
      }

      // Get formatter for the requested format
      const formatter = this.formatters.get(configuration.format);
      if (!formatter) {
        throw new Error(`Unsupported format: ${configuration.format}`);
      }

      this.updateProgress(reportId, {
        reportId,
        currentStep: 'Formatting report',
        percentage: 70,
        currentOperation: 'formatting',
      });
      onProgress?.(this.activeReports.get(reportId) ?? { reportId, currentStep: '', percentage: 0 });

      // Prepare report data
      const reportData = {
        metadata: {
          title: configuration.name,
          description: configuration.description,
          version: '1.0.0',
          generatedAt: new Date().toISOString(),
          reportId,
        },
        analysisResult,
        issues: filteredIssues,
        metrics,
        executiveSummary,
        trendAnalysis,
        historicalData,
        template,
        configuration,
      };

      // Generate report content
      const content = await formatter.format(reportData, template);

      this.updateProgress(reportId, {
        reportId,
        currentStep: 'Writing report file',
        percentage: 90,
        currentOperation: 'file-write',
        bytesWritten: content.length,
      });
      onProgress?.(this.activeReports.get(reportId) ?? { reportId, currentStep: '', percentage: 0 });

      // Determine output path and write file
      const outputPath = this.getOutputPath(configuration, analysisResult, reportId);

      // Ensure directory exists
      const outputDir = dirname(outputPath);
      if (!existsSync(outputDir)) {
        mkdirSync(outputDir, { recursive: true });
      }

      // Write report file
      writeFileSync(outputPath, content, 'utf-8');

      const endTime = performance.now();
      const duration = endTime - startTime;

      // Complete progress
      this.updateProgress(reportId, {
        reportId,
        currentStep: 'Complete',
        percentage: 100,
        currentOperation: 'complete',
        bytesWritten: content.length,
      });
      onProgress?.(this.activeReports.get(reportId) ?? { reportId, currentStep: '', percentage: 0 });

      // Clean up progress tracking
      this.activeReports.delete(reportId);

      return {
        success: true,
        reportId,
        configurationId: configuration.id,
        outputPath,
        format: configuration.format,
        size: Buffer.byteLength(content, 'utf-8'),
        generatedAt: new Date(),
        duration,
        metadata: {
          title: configuration.name,
          description: configuration.description,
          version: '1.0.0',
        },
      };
    } catch (error) {
      this.activeReports.delete(reportId);

      return {
        success: false,
        reportId,
        configurationId: configuration.id,
        outputPath: '',
        format: configuration.format,
        size: 0,
        generatedAt: new Date(),
        duration: performance.now() - startTime,
        error: error instanceof Error ? error.message : String(error),
        metadata: {
          title: configuration.name,
          description: configuration.description,
          version: '1.0.0',
        },
      };
    }
  }

  /**
   * Validate report configuration
   */
  private validateConfiguration(configuration: ReportConfiguration): void {
    if (!configuration.name || configuration.name.trim() === '') {
      throw new Error('Report name is required');
    }

    if (!configuration.templateId) {
      throw new Error('Template ID is required');
    }

    const validFormats: ReportFormat[] = ['json', 'html', 'markdown', 'pdf'];
    if (!validFormats.includes(configuration.format)) {
      throw new Error(`Invalid format: ${configuration.format}`);
    }

    if (!this.templateService.hasTemplate(configuration.templateId)) {
      throw new Error(`Template not found: ${configuration.templateId}`);
    }
  }

  /**
   * Apply filters to issues
   */
  private applyFilters(issues: Issue[], filters: ReportFilters): Issue[] {
    return issues.filter(issue => {
      // Severity filter
      if (filters.severity && !filters.severity.includes(issue.type)) {
        return false;
      }

      // Tool filter
      if (filters.tools && !filters.tools.includes(issue.toolName)) {
        return false;
      }

      // Score range filter
      if (filters.scoreRange) {
        const { min, max } = filters.scoreRange;
        if (issue.score < min || issue.score > max) {
          return false;
        }
      }

      // Fixable only filter
      if (filters.fixableOnly && !issue.fixable) {
        return false;
      }

      return true;
    });
  }

  /**
   * Check if a section is enabled in the template
   */
  private sectionEnabled(template: TemplateDefinition | ReportTemplate, sectionType: string): boolean {
    return template.sections.some(section =>
      section.type === sectionType && section.enabled
    );
  }

  /**
   * Generate executive summary using AI-like analysis
   */
  private async generateExecutiveSummary(
    analysisResult: AnalysisResult,
    issues: Issue[],
    metrics: DashboardMetrics,
    historicalData?: HistoricalData[]
  ): Promise<ExecutiveSummary> {
    const errorCount = issues.filter(i => i.type === 'error').length;
    const warningCount = issues.filter(i => i.type === 'warning').length;
    const fixableCount = issues.filter(i => i.fixable).length;

    // Calculate trend if historical data available
    const trend = historicalData && historicalData.length > 1
      ? this.calculateTrend(historicalData)
      : { direction: 'stable' as const, changePercentage: 0 };

    // Generate overview
    const overview = `The codebase has achieved an overall quality score of ${analysisResult.overallScore}/100 with ${metrics.totalIssues} total issues identified. ${errorCount} errors require immediate attention, while ${warningCount} warnings suggest areas for improvement. ${fixableCount} issues can be automatically resolved.`;

    // Generate key metrics
    const keyMetrics: Array<{
      label: string;
      value: string | number;
      trend: 'up' | 'down' | 'stable';
      significance: 'high' | 'medium' | 'low';
    }> = [
      {
        label: 'Overall Score',
        value: `${analysisResult.overallScore}/100`,
        trend: trend.direction === 'improving' ? 'up' : trend.direction === 'declining' ? 'down' : 'stable',
        significance: analysisResult.overallScore >= 80 ? 'low' : analysisResult.overallScore >= 60 ? 'medium' : 'high',
      },
      {
        label: 'Total Issues',
        value: metrics.totalIssues,
        trend: trend.direction === 'declining' ? 'up' : trend.direction === 'improving' ? 'down' : 'stable',
        significance: metrics.totalIssues <= 10 ? 'low' : metrics.totalIssues <= 50 ? 'medium' : 'high',
      },
      {
        label: 'Fixable Issues',
        value: `${fixableCount} (${Math.round((fixableCount / metrics.totalIssues) * 100)}%)`,
        trend: 'stable',
        significance: fixableCount / metrics.totalIssues >= 0.7 ? 'low' : 'medium',
      },
    ];

    // Generate priorities based on issue analysis
    const priorities = this.generatePriorities(issues);

    // Generate recommendations
    const recommendations = this.generateRecommendations(issues, metrics);

    // Generate next steps
    const nextSteps = [
      'Address high-priority security vulnerabilities',
      'Fix critical build-breaking errors',
      'Implement automated testing for uncovered areas',
      'Set up code review processes for quality gates',
    ];

    return {
      overview,
      keyMetrics,
      priorities,
      recommendations,
      nextSteps,
    };
  }

  /**
   * Calculate trend from historical data
   */
  private calculateTrend(historicalData: HistoricalData[]): { direction: 'improving' | 'declining' | 'stable'; changePercentage: number } {
    if (historicalData.length < 2) {
      return { direction: 'stable', changePercentage: 0 };
    }

    const latest = historicalData[historicalData.length - 1];
    const previous = historicalData[historicalData.length - 2];

    if (!latest || !previous) {
      return { direction: 'stable', changePercentage: 0 };
    }

    const scoreChange = latest.overallScore - previous.overallScore;
    const changePercentage = previous.overallScore > 0 ? (scoreChange / previous.overallScore) * 100 : 0;

    if (Math.abs(changePercentage) < 5) {
      return { direction: 'stable', changePercentage };
    }

    return {
      direction: changePercentage > 0 ? 'improving' : 'declining',
      changePercentage: Math.abs(changePercentage),
    };
  }

  /**
   * Generate priorities from issues
   */
  private generatePriorities(issues: Issue[]): Array<{ title: string; description: string; impact: 'high' | 'medium' | 'low'; effort: 'high' | 'medium' | 'low' }> {
    const errorIssues = issues.filter(i => i.type === 'error');
    const fixableErrors = errorIssues.filter(i => i.fixable);

    const priorities: Array<{ title: string; description: string; impact: 'high' | 'medium' | 'low'; effort: 'high' | 'medium' | 'low' }> = [];

    if (fixableErrors.length > 0) {
      priorities.push({
        title: 'Fix Auto-correctable Errors',
        description: `Resolve ${fixableErrors.length} errors that can be automatically fixed`,
        impact: 'high',
        effort: 'low',
      });
    }

    if (errorIssues.length > fixableErrors.length) {
      priorities.push({
        title: 'Address Manual Error Resolution',
        description: `Manually fix ${errorIssues.length - fixableErrors.length} remaining errors`,
        impact: 'high',
        effort: 'medium',
      });
    }

    const securityIssues = issues.filter(i =>
      i.toolName === 'eslint' && i.ruleId?.startsWith('security/')
    );

    if (securityIssues.length > 0) {
      priorities.push({
        title: 'Security Vulnerabilities',
        description: `Address ${securityIssues.length} security-related issues`,
        impact: 'high',
        effort: 'medium',
      });
    }

    return priorities.slice(0, 5); // Limit to top 5 priorities
  }

  /**
   * Generate recommendations based on analysis
   */
  private generateRecommendations(issues: Issue[], metrics: DashboardMetrics): string[] {
    const recommendations = [];

    // Coverage recommendations
    if (metrics.coverage) {
      const { coverage } = metrics;
      if (coverage.lines.percentage < 80) {
        recommendations.push(`Increase test coverage to at least 80%. Current: ${coverage.lines.percentage}%`);
      }
    }

    // Tool-specific recommendations
    const toolStats = new Map<string, number>();
    issues.forEach(issue => {
      toolStats.set(issue.toolName, (toolStats.get(issue.toolName) ?? 0) + 1);
    });

    for (const [tool, count] of toolStats.entries()) {
      if (count > 10) {
        recommendations.push(`Focus on ${tool} improvements to reduce ${count} issues`);
      }
    }

    // Fixability recommendations
    const fixableCount = issues.filter(i => i.fixable).length;
    if (fixableCount > 0) {
      recommendations.push(`Enable auto-fix for ${fixableCount} resolveable issues`);
    }

    return recommendations.slice(0, 5); // Limit to top 5 recommendations
  }

  /**
   * Generate trend analysis
   */
  private generateTrendAnalysis(historicalData: HistoricalData[]): TrendAnalysis {
    const recent = historicalData.slice(-4); // Last 4 data points
    const older = historicalData.slice(-8, -4); // Previous 4 data points

    if (recent.length < 2 || older.length < 2) {
      return {
        period: 'insufficient-data',
        direction: 'stable',
        changePercentage: 0,
        confidence: 0,
        insights: ['Insufficient historical data for trend analysis'],
      };
    }

    const recentAvg = recent.reduce((sum, d) => sum + d.overallScore, 0) / recent.length;
    const olderAvg = older.reduce((sum, d) => sum + d.overallScore, 0) / older.length;

    const changePercentage = ((recentAvg - olderAvg) / olderAvg) * 100;
    const direction = changePercentage > 5 ? 'improving' : changePercentage < -5 ? 'declining' : 'stable';

    const insights = [];
    if (direction === 'improving') {
      insights.push(`Quality score improved by ${Math.abs(changePercentage).toFixed(1)}%`);
    } else if (direction === 'declining') {
      insights.push(`Quality score declined by ${Math.abs(changePercentage).toFixed(1)}%`);
    } else {
      insights.push('Quality score remains stable');
    }

    return {
      period: 'last-4-periods',
      direction,
      changePercentage: Math.abs(changePercentage),
      confidence: Math.min(recent.length / 4, 1) * 100,
      insights,
    };
  }

  /**
   * Get output path for report
   */
  private getOutputPath(
    configuration: ReportConfiguration,
    analysisResult: AnalysisResult,
    _reportId: string
  ): string {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const filename = `${configuration.name.toLowerCase().replace(/\s+/g, '-')}-${analysisResult.projectId}-${timestamp}.${configuration.format}`;

    return resolve(process.cwd(), 'reports', filename);
  }

  /**
   * Update progress tracking
   */
  private updateProgress(reportId: string, progress: Partial<ReportProgress>): void {
    const existing = this.activeReports.get(reportId) ?? {
      reportId,
      currentStep: '',
      percentage: 0,
    };

    this.activeReports.set(reportId, { ...existing, ...progress });
  }

  /**
   * Get available templates
   */
  getAvailableTemplates(): TemplateDefinition[] {
    return this.templateService.getTemplates();
  }

  /**
   * Get template by ID
   */
  getTemplate(id: string): TemplateDefinition | undefined {
    return this.templateService.getTemplate(id);
  }

  /**
   * Get template service for advanced operations
   */
  getTemplateService(): TemplateService {
    return this.templateService;
  }

  /**
   * Add custom template (backward compatibility)
   */
  addTemplate(template: ReportTemplate): void {
    // If template has an ID and exists, update it; otherwise create new
    if (template.id && this.templateService.hasTemplate(template.id)) {
      this.templateService.updateTemplate(template.id, template);
    } else {
      // Convert ReportTemplate to TemplateDefinition for createTemplate
      const templateDef: Omit<TemplateDefinition, 'id' | 'createdAt' | 'updatedAt'> = {
        name: template.name,
        description: template.description,
        format: template.format,
        templateType: template.templateType,
        content: template.content,
        sections: template.sections,
        styles: template.styles,
        version: template.version ?? '1.0.0',
        author: template.author ?? 'Custom',
        tags: template.tags ?? [],
        category: template.category ?? 'custom',
        variables: [],
        metadata: template.metadata ?? {},
      };

      const createdTemplate = this.templateService.createTemplate(templateDef);
      // Update the original template with the generated ID if needed
      if (createdTemplate.id !== template.id) {
        // If ID was generated, update the template in the registry
        this.templateService.updateTemplate(createdTemplate.id, template);
      }
    }
  }

  /**
   * Create custom template
   */
  createTemplate(templateData: Omit<TemplateDefinition, 'id' | 'createdAt' | 'updatedAt'>): TemplateDefinition {
    return this.templateService.createTemplate(templateData);
  }

  /**
   * Update template
   */
  updateTemplate(id: string, updates: Partial<TemplateDefinition>): TemplateDefinition {
    return this.templateService.updateTemplate(id, updates);
  }

  /**
   * Delete template
   */
  deleteTemplate(id: string): boolean {
    return this.templateService.deleteTemplate(id);
  }

  /**
   * Clone template
   */
  cloneTemplate(id: string, newName?: string): TemplateDefinition {
    return this.templateService.cloneTemplate(id, newName);
  }

  /**
   * Get templates by format
   */
  getTemplatesByFormat(format: ReportFormat): TemplateDefinition[] {
    return this.templateService.getTemplatesByFormat(format);
  }

  /**
   * Get templates by category
   */
  getTemplatesByCategory(category: string): TemplateDefinition[] {
    return this.templateService.getTemplatesByCategory(category);
  }

  /**
   * Get available categories
   */
  getTemplateCategories(): string[] {
    return this.templateService.getCategories();
  }

  /**
   * Get template statistics
   */
  getTemplateStatistics() {
    return this.templateService.getStatistics();
  }

  /**
   * Validate a template (for performance testing)
   */
  validateTemplate(templateContent: string): { valid: boolean; errors?: string[] } {
    try {
      const errors: string[] = [];

      // Check for basic template structure
      const hasHtmlTags = /<[^>]+>/.test(templateContent);
      const hasTemplateVars = /\{\{[^}]+\}\}/.test(templateContent);

      if (!hasHtmlTags && !hasTemplateVars) {
        errors.push('Template must contain HTML structure or template variables');
      }

      // Check for required template variables
      const requiredVars = ['reportTitle', 'timestamp'];
      for (const varName of requiredVars) {
        if (!templateContent.includes(`{{${varName}}}`)) {
          errors.push(`Missing required template variable: ${varName}`);
        }
      }

      // Basic HTML structure check if it contains HTML
      if (hasHtmlTags) {
        const hasOpenTags = (templateContent.match(/</g) || []).length;
        const hasCloseTags = (templateContent.match(/>/g) || []).length;

        if (hasOpenTags !== hasCloseTags) {
          errors.push('Template has mismatched HTML tags');
        }
      }

      return {
        valid: errors.length === 0,
        errors: errors.length > 0 ? errors : undefined
      };
    } catch (error) {
      return {
        valid: false,
        errors: [error instanceof Error ? error.message : String(error)]
      };
    }
  }

  /**
   * Get supported formats
   */
  getSupportedFormats(): ReportFormat[] {
    return ['json', 'html', 'markdown', 'pdf'];
  }
}

/**
 * Report Generation Scheduler
 *
 * Provides automated report generation and scheduling as required by Story 2.4 AC3.
 * Includes cron scheduling, queue management, retry mechanisms, and notifications.
 */

import { CronJob } from 'cron';
import { EventEmitter } from 'events';
import { ReportGenerator, type ReportRequest } from './report-generator';
import { SlackService, SlackConfig } from './integrations/slack-service';
import { EmailService, EmailConfig } from './integrations/email-service';
import type { AnalysisResult as CoreAnalysisResult } from '@dev-quality/core';
import type { AnalysisResult, Issue } from '../../types/analysis';
import type { DashboardMetrics } from '../../types/dashboard';

export interface ReportSchedule {
  id: string;
  name: string;
  description?: string;
  cronExpression: string;
  enabled: boolean;
  timezone?: string;
  projectId: string;
  reportConfig: ReportConfiguration;
  notifications: NotificationConfig[];
  createdAt: Date;
  updatedAt: Date;
  lastRun?: Date;
  nextRun?: Date;
  runCount: number;
  failureCount: number;
}

export interface ReportConfiguration {
  format: 'json' | 'html' | 'markdown' | 'pdf';
  template?: string;
  outputPath?: string;
  filters?: ReportFilters;
  includeTrends?: boolean;
  includeExecutiveSummary?: boolean;
}

export interface ReportFilters {
  severity?: Array<'error' | 'warning' | 'info'>;
  tools?: string[];
  dateRange?: {
    from: Date;
    to: Date;
  };
  minScore?: number;
  maxScore?: number;
}

export interface NotificationConfig {
  type: 'slack' | 'email';
  enabled: boolean;
  config: SlackConfig | EmailConfig;
  recipients: string[];
  conditions: NotificationConditions;
}

export interface NotificationConditions {
  onSuccess: boolean;
  onFailure: boolean;
  onThreshold?: {
    metric: string;
    operator: 'gt' | 'lt' | 'eq';
    value: number;
  };
}

export interface ScheduledReportResult {
  scheduleId: string;
  success: boolean;
  reportPath?: string;
  metrics?: ReportMetrics;
  error?: string;
  duration: number;
  timestamp: Date;
  notificationsSent: number;
}

export interface ReportMetrics {
  totalIssues: number;
  criticalIssues: number;
  overallScore: number;
  duration: number;
  reportSize: number;
}

export interface QueueItem {
  id: string;
  type: 'scheduled' | 'immediate';
  priority: 'low' | 'medium' | 'high' | 'critical';
  scheduleId?: string;
  projectId: string;
  reportConfig: ReportConfiguration;
  scheduledAt: Date;
  attempts: number;
  maxAttempts: number;
  createdAt: Date;
}

export class ReportScheduler extends EventEmitter {
  private jobs: Map<string, CronJob> = new Map();
  private queue: QueueItem[] = [];
  private processing = false;
  private maxConcurrentJobs = 3;
  private currentJobs = 0;

  constructor(
    private reportGenerator: ReportGenerator,
    private slackService?: SlackService,
    private emailService?: EmailService
  ) {
    super();
    this.startQueueProcessor();
  }

  /**
   * Add a new report schedule
   */
  async addSchedule(schedule: Omit<ReportSchedule, 'id' | 'createdAt' | 'updatedAt' | 'runCount' | 'failureCount'>): Promise<ReportSchedule> {
    this.validateCronExpression(schedule.cronExpression);

    const newSchedule: ReportSchedule = {
      ...schedule,
      id: this.generateId(),
      createdAt: new Date(),
      updatedAt: new Date(),
      runCount: 0,
      failureCount: 0,
      nextRun: this.getNextRunTime(schedule.cronExpression)
    };

    if (schedule.enabled) {
      this.scheduleJob(newSchedule);
    }

    this.emit('scheduleAdded', newSchedule);
    return newSchedule;
  }

  /**
   * Update an existing schedule
   */
  async updateSchedule(scheduleId: string, updates: Partial<ReportSchedule>): Promise<ReportSchedule> {
    const existingSchedule = await this.getSchedule(scheduleId);
    if (!existingSchedule) {
      throw new Error(`Schedule ${scheduleId} not found`);
    }

    // Stop existing job if it's running
    const existingJob = this.jobs.get(scheduleId);
    if (existingJob) {
      existingJob.stop();
      this.jobs.delete(scheduleId);
    }

    const updatedSchedule: ReportSchedule = {
      ...existingSchedule,
      ...updates,
      updatedAt: new Date(),
      nextRun: updates.cronExpression ? this.getNextRunTime(updates.cronExpression) : existingSchedule.nextRun
    };

    if (updatedSchedule.enabled) {
      this.scheduleJob(updatedSchedule);
    }

    this.emit('scheduleUpdated', updatedSchedule);
    return updatedSchedule;
  }

  /**
   * Delete a schedule
   */
  async deleteSchedule(scheduleId: string): Promise<void> {
    const jobToDelete = this.jobs.get(scheduleId);
    if (jobToDelete) {
      jobToDelete.stop();
      this.jobs.delete(scheduleId);
    }

    // Remove queued items for this schedule
    this.queue = this.queue.filter(item => item.scheduleId !== scheduleId);

    this.emit('scheduleDeleted', scheduleId);
  }

  /**
   * Get schedule by ID
   */
  async getSchedule(_scheduleId: string): Promise<ReportSchedule | null> {
    // This would typically fetch from database
    // For now, return null as placeholder
    return null;
  }

  /**
   * List all schedules
   */
  async listSchedules(): Promise<ReportSchedule[]> {
    // This would typically fetch from database
    // For now, return empty array as placeholder
    return [];
  }

  /**
   * Run a report immediately
   */
  async runReportImmediately(
    projectId: string,
    reportConfig: ReportConfiguration,
    priority: 'low' | 'medium' | 'high' | 'critical' = 'medium'
  ): Promise<string> {
    const queueItem: QueueItem = {
      id: this.generateId(),
      type: 'immediate',
      priority,
      projectId,
      reportConfig,
      scheduledAt: new Date(),
      attempts: 0,
      maxAttempts: 3,
      createdAt: new Date()
    };

    this.addToQueue(queueItem);
    return queueItem.id;
  }

  /**
   * Schedule a cron job
   */
  private scheduleJob(schedule: ReportSchedule): void {
    const job = new CronJob(
      schedule.cronExpression,
      () => this.handleScheduledRun(schedule.id),
      null,
      false,
      schedule.timezone ?? 'UTC'
    );

    this.jobs.set(schedule.id, job);
    job.start();
  }

  /**
   * Handle scheduled report run
   */
  private async handleScheduledRun(_scheduleId: string): Promise<void> {
    const schedule = await this.getSchedule(_scheduleId);
    if (!schedule?.enabled) {
      return;
    }

    const queueItem: QueueItem = {
      id: this.generateId(),
      type: 'scheduled',
      priority: 'medium',
      projectId: schedule.projectId,
      reportConfig: schedule.reportConfig,
      scheduleId: _scheduleId,
      scheduledAt: new Date(),
      attempts: 0,
      maxAttempts: 3,
      createdAt: new Date()
    };

    this.addToQueue(queueItem);
  }

  /**
   * Add item to queue with priority ordering
   */
  private addToQueue(item: QueueItem): void {
    const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
    const insertIndex = this.queue.findIndex(
      existing => priorityOrder[existing.priority] > priorityOrder[item.priority]
    );

    if (insertIndex === -1) {
      this.queue.push(item);
    } else {
      this.queue.splice(insertIndex, 0, item);
    }

    this.emit('itemQueued', item);
  }

  /**
   * Start queue processor
   */
  private startQueueProcessor(): void {
    setInterval(() => {
      if (!this.processing && this.queue.length > 0 && this.currentJobs < this.maxConcurrentJobs) {
        this.processQueue();
      }
    }, 1000); // Check every second
  }

  /**
   * Process queue items
   */
  private async processQueue(): Promise<void> {
    if (this.processing || this.queue.length === 0 || this.currentJobs >= this.maxConcurrentJobs) {
      return;
    }

    this.processing = true;

    while (this.queue.length > 0 && this.currentJobs < this.maxConcurrentJobs) {
      const item = this.queue.shift();
    if (!item) return;

    this.currentJobs++;

      // Process item asynchronously
      this.processQueueItem(item).finally(() => {
        this.currentJobs--;
      });
    }

    this.processing = false;
  }

  /**
   * Process individual queue item
   */
  private async processQueueItem(item: QueueItem): Promise<void> {
    const startTime = Date.now();

    try {
      const result = await this.generateReport(item);
      const duration = Date.now() - startTime;

      await this.sendNotifications(item, result);

      this.emit('reportGenerated', {
        scheduleId: item.scheduleId,
        success: true,
        duration,
        reportPath: result.reportPath,
        metrics: result.metrics
      });

      // Update schedule statistics
      if (item.scheduleId) {
        await this.updateScheduleStats(item.scheduleId, true, duration);
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      // Retry logic
      if (item.attempts < item.maxAttempts) {
        item.attempts++;
        item.scheduledAt = new Date(Date.now() + Math.pow(2, item.attempts) * 1000); // Exponential backoff
        this.addToQueue(item);

        this.emit('reportRetry', {
          scheduleId: item.scheduleId,
          attempt: item.attempts,
          error: errorMessage
        });
      } else {
        this.emit('reportFailed', {
          scheduleId: item.scheduleId,
          error: errorMessage,
          duration
        });

        // Update schedule statistics
        if (item.scheduleId) {
          await this.updateScheduleStats(item.scheduleId, false, duration, errorMessage);
        }

        // Send failure notifications
        await this.sendFailureNotifications(item, errorMessage);
      }
    }
  }

  /**
   * Generate report
   */
  private async generateReport(item: QueueItem): Promise<{
    reportPath: string;
    metrics: ReportMetrics;
  }> {
    // Get analysis data (this would typically fetch from database)
    const analysisData = await this.getAnalysisData(item.projectId);

    const _outputPath = item.reportConfig.outputPath ??
      `/tmp/reports/${item.id}.${item.reportConfig.format}`;

    // Create mock issues and metrics for the report request
    const issues: Issue[] = []; // This would typically come from analysisData
    const metrics: DashboardMetrics = {
      totalIssues: analysisData.summary.totalIssues,
      errorCount: analysisData.summary.totalErrors,
      warningCount: analysisData.summary.totalWarnings,
      infoCount: Math.max(0, analysisData.summary.totalIssues - analysisData.summary.totalErrors - analysisData.summary.totalWarnings), // Calculate info count
      fixableCount: analysisData.summary.totalFixable,
      overallScore: analysisData.overallScore,
      coverage: null, // This would be populated from actual analysis data
      toolsAnalyzed: analysisData.summary.toolCount,
      duration: analysisData.summary.executionTime
    };

    // Convert core AnalysisResult to CLI AnalysisResult (timestamp: Date -> string)
    const cliAnalysisResult: AnalysisResult = {
      id: analysisData.id,
      projectId: analysisData.projectId,
      timestamp: analysisData.timestamp.toISOString(),
      duration: analysisData.duration,
      overallScore: analysisData.overallScore,
      toolResults: analysisData.toolResults.map(result => ({
        toolName: result.toolName,
        executionTime: result.executionTime,
        status: result.status,
        issues: result.issues,
        metrics: result.metrics,
        coverage: result.coverage
      })),
      summary: analysisData.summary,
      aiPrompts: analysisData.aiPrompts
    };

    // Create a proper ReportRequest object
    const reportRequest: ReportRequest = {
      configuration: {
        id: item.id,
        name: `Scheduled Report ${item.id}`,
        description: 'Automatically generated scheduled report',
        templateId: item.reportConfig.template ?? 'default',
        format: item.reportConfig.format,
        recipients: [], // This would be populated from schedule configuration
        filters: {
          severity: item.reportConfig.filters?.severity,
          tools: item.reportConfig.filters?.tools,
          scoreRange: item.reportConfig.filters?.minScore || item.reportConfig.filters?.maxScore ? {
            min: item.reportConfig.filters?.minScore ?? 0,
            max: item.reportConfig.filters?.maxScore ?? 100
          } : undefined,
          fixableOnly: false,
          dateRange: item.reportConfig.filters?.dateRange ? {
            start: item.reportConfig.filters.dateRange.from,
            end: item.reportConfig.filters.dateRange.to
          } : undefined
        },
        createdAt: new Date(),
        updatedAt: new Date(),
        isActive: true
      },
      analysisResult: cliAnalysisResult,
      issues: issues,
      metrics: metrics
    };

    const result = await this.reportGenerator.generateReport(reportRequest);

    if (!result.success) {
      throw new Error(result.error ?? 'Report generation failed');
    }

    const reportMetrics: ReportMetrics = {
      totalIssues: analysisData.summary.totalIssues,
      criticalIssues: analysisData.summary.totalErrors,
      overallScore: analysisData.overallScore,
      duration: result.duration ?? 0,
      reportSize: result.size ?? 0
    };

    return {
      reportPath: result.outputPath,
      metrics: reportMetrics
    };
  }

  /**
   * Send notifications for successful report
   */
  private async sendNotifications(item: QueueItem, result: {
    reportPath: string;
    metrics: ReportMetrics;
  }): Promise<void> {
    // This would fetch notification configs from database
    // For now, just emit event
    this.emit('notificationsQueued', {
      scheduleId: item.scheduleId,
      reportPath: result.reportPath,
      metrics: result.metrics
    });
  }

  /**
   * Send failure notifications
   */
  private async sendFailureNotifications(item: QueueItem, error: string): Promise<void> {
    this.emit('failureNotificationsQueued', {
      scheduleId: item.scheduleId,
      error,
      attempts: item.attempts
    });
  }

  /**
   * Update schedule statistics
   */
  private async updateScheduleStats(
    scheduleId: string,
    success: boolean,
    duration: number,
    error?: string
  ): Promise<void> {
    // This would typically update database
    this.emit('scheduleStatsUpdated', {
      scheduleId,
      success,
      duration,
      error
    });
  }

  /**
   * Get analysis data for project
   */
  private async getAnalysisData(projectId: string): Promise<CoreAnalysisResult> {
    // This would typically fetch from database
    // For now, return mock data with correct ResultSummary properties
    return {
      id: `analysis-${Date.now()}`,
      projectId,
      timestamp: new Date(),
      duration: 5000,
      overallScore: 85,
      toolResults: [],
      summary: {
        totalIssues: 10,
        totalErrors: 2,
        totalWarnings: 5,
        totalFixable: 7,
        overallScore: 85,
        toolCount: 3,
        executionTime: 5000
      },
      aiPrompts: []
    };
  }

  /**
   * Validate cron expression
   */
  private validateCronExpression(expression: string): void {
    try {
      new CronJob(expression, () => {}, null, false);
    } catch (_error) {
      throw new Error(`Invalid cron expression: ${expression}`);
    }
  }

  /**
   * Get next run time for cron expression
   */
  private getNextRunTime(cronExpression: string): Date {
    try {
      const job = new CronJob(cronExpression, () => {}, null, false);
      return job.nextDate().toJSDate();
    } catch {
      return new Date();
    }
  }

  /**
   * Generate unique ID
   */
  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Get queue status
   */
  getQueueStatus(): {
    pending: number;
    processing: number;
    maxConcurrent: number;
    nextItem?: QueueItem;
  } {
    return {
      pending: this.queue.length,
      processing: this.currentJobs,
      maxConcurrent: this.maxConcurrentJobs,
      nextItem: this.queue[0]
    };
  }

  /**
   * Shutdown scheduler
   */
  async shutdown(): Promise<void> {
    // Stop all cron jobs
    for (const job of this.jobs.values()) {
      job.stop();
    }
    this.jobs.clear();

    // Wait for current jobs to complete
    while (this.currentJobs > 0) {
      await this.sleep(1000);
    }

    this.emit('shutdown');
  }

  /**
   * Sleep for specified milliseconds
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

/**
 * Template Service
 * Manages custom report templates with validation, storage, and rendering
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { randomUUID } from 'node:crypto';

import type { ReportSection, TemplateStyles, ReportFormat } from './report-generator';

export interface TemplateDefinition {
  id: string;
  name: string;
  description?: string;
  format: ReportFormat;
  author?: string;
  version: string;
  tags?: string[];
  category?: string;
  templateType: 'builtin' | 'custom';
  content?: string;
  sections: ReportSection[];
  styles?: TemplateStyles;
  variables?: TemplateVariable[];
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

export interface TemplateVariable {
  id: string;
  name: string;
  type: 'string' | 'number' | 'boolean' | 'array' | 'object';
  description?: string;
  defaultValue?: unknown;
  required?: boolean;
  validation?: {
    pattern?: string;
    min?: number;
    max?: number;
    options?: string[];
  };
}

export interface TemplateValidationError {
  field: string;
  message: string;
  code: string;
}

export interface TemplateValidationResult {
  valid: boolean;
  errors: TemplateValidationError[];
  warnings: TemplateValidationError[];
  securityIssues?: TemplateValidationError[];
}

export interface TemplateRegistry {
  templates: Map<string, TemplateDefinition>;
  categories: Map<string, string[]>;
  formats: Map<ReportFormat, TemplateDefinition[]>;
}

/**
 * Template Service
 * Manages the creation, validation, and storage of report templates
 */
export class TemplateService {
  private registry: TemplateRegistry;
  private templatesDir: string;
  private configDir: string;

  constructor(templatesDir?: string) {
    this.registry = {
      templates: new Map(),
      categories: new Map(),
      formats: new Map(),
    };

    this.templatesDir = templatesDir ?? resolve(process.cwd(), 'templates');
    this.configDir = resolve(this.templatesDir, 'config');

    // Initialize directories
    this.initializeDirectories();

    // Load templates
    this.loadTemplates();
  }

  /**
   * Initialize template directories
   */
  private initializeDirectories(): void {
    const dirs = [
      this.templatesDir,
      this.configDir,
      resolve(this.templatesDir, 'html'),
      resolve(this.templatesDir, 'markdown'),
      resolve(this.templatesDir, 'json'),
      resolve(this.templatesDir, 'pdf'),
      resolve(this.templatesDir, 'partials'),
    ];

    dirs.forEach(dir => {
      if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }
    });
  }

  /**
   * Load all templates from file system
   */
  private loadTemplates(): void {
    // Load built-in templates
    this.loadBuiltinTemplates();

    // Load custom templates from config files
    this.loadCustomTemplates();

    // Load template partials
    this.loadTemplatePartials();
