  { key: '1-9', description: 'Quick jump', context: ['dashboard', 'issue-list'] },
  { key: 'Home', description: 'First issue', context: ['dashboard', 'issue-list'] },
  { key: 'End', description: 'Last issue', context: ['dashboard', 'issue-list'] },
  { key: 'Page Up/Down', description: 'Navigate page', context: ['dashboard', 'issue-list'] },
];

/**
 * Create keyboard shortcut handler
 */
export function createKeyboardHandler(shortcuts: KeyboardShortcut[], currentView: DashboardView) {
  return (key: string): boolean => {
    const applicableShortcuts = shortcuts.filter(
      shortcut => !shortcut.context || shortcut.context.includes(currentView)
    );

    for (const shortcut of applicableShortcuts) {
      if (shortcut.key.toLowerCase() === key.toLowerCase()) {
        shortcut.action();
        return true;
      }
    }

    return false;
  };
}

/**
 * Logging utility for CLI applications
 */

export interface Logger {
  info: (message: string, ...args: unknown[]) => void;
  success: (message: string, ...args: unknown[]) => void;
  warning: (message: string, ...args: unknown[]) => void;
  error: (message: string, ...args: unknown[]) => void;
}

/**
 * CLI Logger implementation
 */
export class CliLogger implements Logger {
  info(message: string, ...args: unknown[]): void {
    process.stdout.write(`${message} ${args.map(String).join(' ')}\n`);
  }

  success(message: string, ...args: unknown[]): void {
    process.stdout.write(`${message} ${args.map(String).join(' ')}\n`);
  }

  warning(message: string, ...args: unknown[]): void {
    process.stderr.write(`${message} ${args.map(String).join(' ')}\n`);
  }

  error(message: string, ...args: unknown[]): void {
    process.stderr.write(`${message} ${args.map(String).join(' ')}\n`);
  }
}

/**
 * Default logger instance
 */
export const logger = new CliLogger();

/**
 * Performance monitoring utilities for dashboard operations
 */

interface PerformanceMetrics {
  renderTime: number;
  updateTime: number;
  memoryUsage: number;
  operationCount: number;
  lastUpdate: number;
}

interface PerformanceAlert {
  type: 'render' | 'memory' | 'update' | 'operation';
  message: string;
  threshold: number;
  actual: number;
  timestamp: number;
}

export class PerformanceMonitor {
  private metrics: PerformanceMetrics;
  private alerts: PerformanceAlert[];
  private listeners: Set<(alert: PerformanceAlert) => void>;
  private thresholds: {
    maxRenderTime: number;
    maxUpdateTime: number;
    maxMemoryUsage: number;
    maxOperationRate: number;
  };

  constructor() {
    this.metrics = {
      renderTime: 0,
      updateTime: 0,
      memoryUsage: 0,
      operationCount: 0,
      lastUpdate: Date.now()
    };
    this.alerts = [];
    this.listeners = new Set();
    this.thresholds = {
      maxRenderTime: 100,    // 100ms
      maxUpdateTime: 50,    // 50ms
      maxMemoryUsage: 512,  // 512MB
      maxOperationRate: 10   // 10 ops/sec
    };
  }

  /**
   * Start measuring a render operation
   */
  startRenderMeasurement(): () => void {
    const startTime = globalThis.performance.now();

    return () => {
      const endTime = globalThis.performance.now();
      const renderTime = endTime - startTime;

      this.metrics.renderTime = renderTime;
      this.metrics.lastUpdate = Date.now();
      this.metrics.operationCount++;

      if (renderTime > this.thresholds.maxRenderTime) {
        this.createAlert('render',
          `Render time exceeded threshold: ${renderTime.toFixed(2)}ms > ${this.thresholds.maxRenderTime}ms`,
          this.thresholds.maxRenderTime,
          renderTime
        );
      }
    };
  }

  /**
   * Start measuring an update operation
   */
  startUpdateMeasurement(): () => void {
    const startTime = globalThis.performance.now();

    return () => {
      const endTime = globalThis.performance.now();
      const updateTime = endTime - startTime;

      this.metrics.updateTime = updateTime;
      this.metrics.lastUpdate = Date.now();
      this.metrics.operationCount++;

      if (updateTime > this.thresholds.maxUpdateTime) {
        this.createAlert('update',
          `Update time exceeded threshold: ${updateTime.toFixed(2)}ms > ${this.thresholds.maxUpdateTime}ms`,
          this.thresholds.maxUpdateTime,
          updateTime
        );
      }
    };
  }

  /**
   * Check memory usage and alert if necessary
   */
  checkMemoryUsage(): void {
    if (typeof globalThis.performance !== 'undefined' && (globalThis.performance as unknown as { memory?: { usedJSHeapSize: number } }).memory) {
      const memoryInfo = (globalThis.performance as unknown as { memory: { usedJSHeapSize: number } }).memory;
      const memoryUsageMB = memoryInfo.usedJSHeapSize / (1024 * 1024);

      this.metrics.memoryUsage = memoryUsageMB;

      if (memoryUsageMB > this.thresholds.maxMemoryUsage) {
        this.createAlert('memory',
          `Memory usage exceeded threshold: ${memoryUsageMB.toFixed(2)}MB > ${this.thresholds.maxMemoryUsage}MB`,
          this.thresholds.maxMemoryUsage,
          memoryUsageMB
        );
      }
    }
  }

  /**
   * Check operation rate and alert if too high
   */
  checkOperationRate(): void {
    const _now = Date.now();
    const timeWindow = 1000; // 1 second
    const recentOperations = this.getOperationCountInTimeWindow(timeWindow);

    if (recentOperations > this.thresholds.maxOperationRate) {
      this.createAlert('operation',
        `Operation rate exceeded threshold: ${recentOperations} > ${this.thresholds.maxOperationRate}/sec`,
        this.thresholds.maxOperationRate,
        recentOperations
      );
    }
  }

  /**
   * Get current metrics
   */
  getMetrics(): PerformanceMetrics {
    return { ...this.metrics };
  }

  /**
   * Get recent alerts
   */
  getAlerts(timeWindow?: number): PerformanceAlert[] {
    if (!timeWindow) {
      return [...this.alerts];
    }

    const cutoff = Date.now() - timeWindow;
    return this.alerts.filter(alert => alert.timestamp > cutoff);
  }

  /**
   * Subscribe to performance alerts
   */
  onAlert(listener: (alert: PerformanceAlert) => void): () => void {
    this.listeners.add(listener);

    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Update performance thresholds
   */
  updateThresholds(newThresholds: Partial<typeof this.thresholds>): void {
    this.thresholds = { ...this.thresholds, ...newThresholds };
  }

  /**
   * Reset metrics
   */
  reset(): void {
    this.metrics = {
      renderTime: 0,
      updateTime: 0,
      memoryUsage: 0,
      operationCount: 0,
      lastUpdate: Date.now()
    };
    this.alerts = [];
  }

  /**
   * Generate performance report
   */
  generateReport(): string {
    const now = Date.now();
    const recentAlerts = this.getAlerts(60000); // Last minute

    return `
Performance Report (Generated: ${new Date(now).toISOString()})
================================================================

Current Metrics:
- Render Time: ${this.metrics.renderTime.toFixed(2)}ms
- Update Time: ${this.metrics.updateTime.toFixed(2)}ms
- Memory Usage: ${this.metrics.memoryUsage.toFixed(2)}MB
- Total Operations: ${this.metrics.operationCount}
- Last Update: ${new Date(this.metrics.lastUpdate).toISOString()}

Thresholds:
- Max Render Time: ${this.thresholds.maxRenderTime}ms
- Max Update Time: ${this.thresholds.maxUpdateTime}ms
- Max Memory Usage: ${this.thresholds.maxMemoryUsage}MB
- Max Operation Rate: ${this.thresholds.maxOperationRate}/sec

Recent Alerts (Last Minute): ${recentAlerts.length}
${recentAlerts.map(alert =>
  `- [${alert.type.toUpperCase()}] ${alert.message} (${alert.actual.toFixed(2)} vs ${alert.threshold})`
).join('\n')}

Status: ${recentAlerts.length === 0 ? 'HEALTHY' : 'WARNING'}
    `.trim();
  }

  private createAlert(type: PerformanceAlert['type'], message: string, threshold: number, actual: number): void {
    const alert: PerformanceAlert = {
      type,
      message,
      threshold,
      actual,
      timestamp: Date.now()
    };

    this.alerts.push(alert);

    // Keep only last 100 alerts to prevent memory leak
    if (this.alerts.length > 100) {
      this.alerts = this.alerts.slice(-100);
    }

    // Notify listeners
    this.listeners.forEach(listener => {
      try {
        listener(alert);
      } catch (_error) {
        // console.error('Error in performance alert listener:', _error);
      }
    });
  }

  private getOperationCountInTimeWindow(timeWindow: number): number {
    // This is a simplified implementation
    // In a real scenario, you'd track operation timestamps
    const timeSinceLastUpdate = Date.now() - this.metrics.lastUpdate;

    if (timeSinceLastUpdate > timeWindow) {
      return 0;
    }

    // Estimate rate based on recent activity
    return Math.min(this.metrics.operationCount, this.thresholds.maxOperationRate);
  }
}

/**
 * Performance monitoring hook for components
 */
export function usePerformanceMonitor(componentName: string) {
  const monitor = new PerformanceMonitor();

  const measureRender = () => {
    const stopMeasurement = monitor.startRenderMeasurement();

    return () => {
      stopMeasurement();
      monitor.checkMemoryUsage();
      monitor.checkOperationRate();
    };
  };

  const measureUpdate = (_operationName: string) => {
    const stopMeasurement = monitor.startUpdateMeasurement();

    return () => {
      stopMeasurement();
      monitor.checkOperationRate();
    };
  };

  return {
    monitor,
    measureRender,
    measureUpdate,
    componentName
  };
}

/**
 * Search debouncing utility
 */
export class SearchDebouncer {
  private timeout: ReturnType<typeof setTimeout> | null = null;
  private lastSearchTime: number = 0;
  private searchCount: number = 0;

  constructor(private debounceTime: number = 300) {}

  /**
   * Debounce a search function
   */
  debounce<T extends unknown[]>(
    searchFunction: (...args: T) => Promise<unknown>,
    onDebounceStart?: () => void,
    onDebounceEnd?: () => void
  ): (...args: T) => Promise<unknown> {
    return (...args: T): Promise<unknown> => {
      return new Promise<unknown>((resolve, reject) => {
        // Clear existing timeout
        if (this.timeout) {
          clearTimeout(this.timeout);
        }

        // Notify debounce start
        onDebounceStart?.();

        // Set new timeout
        this.timeout = setTimeout(async () => {
          try {
            this.lastSearchTime = Date.now();
            this.searchCount++;

            const result = await searchFunction(...args);
            onDebounceEnd?.();
            resolve(result);
          } catch (error) {
            onDebounceEnd?.();
            reject(error);
          } finally {
            this.timeout = null;
          }
        }, this.debounceTime);
      });
    };
  }

  /**
   * Cancel pending search
   */
  cancel(): void {
    if (this.timeout) {
      clearTimeout(this.timeout);
      this.timeout = null;
    }
  }

  /**
   * Get search statistics
   */
  getStats() {
    return {
      lastSearchTime: this.lastSearchTime,
      searchCount: this.searchCount,
      debounceTime: this.debounceTime,
      isPending: this.timeout !== null
    };
  }

  /**
   * Reset statistics
   */
  reset(): void {
    this.cancel();
    this.lastSearchTime = 0;
    this.searchCount = 0;
  }
}

/**
 * Create a debounced search function
 */
export function createDebouncedSearch<T extends unknown[]>(
  searchFunction: (...args: T) => Promise<unknown>,
  debounceTime: number = 300,
  onDebounceStart?: () => void,
  onDebounceEnd?: () => void
) {
  const debouncer = new SearchDebouncer(debounceTime);

  return {
    search: debouncer.debounce(searchFunction, onDebounceStart, onDebounceEnd),
    cancel: () => debouncer.cancel(),
    getStats: () => debouncer.getStats(),
    reset: () => debouncer.reset()
  };
}

/**
 * Global performance monitor instance
 */
export const globalPerformanceMonitor = new PerformanceMonitor();

/**
 * Setup global performance monitoring
 */
export function setupGlobalPerformanceMonitoring() {
  // Monitor memory usage periodically
  setInterval(() => {
    globalPerformanceMonitor.checkMemoryUsage();
  }, 5000); // Every 5 seconds

  // Monitor operation rate periodically
  setInterval(() => {
    globalPerformanceMonitor.checkOperationRate();
  }, 1000); // Every second

  // Log alerts to console in development
  if (process.env.NODE_ENV === 'development') {
    globalPerformanceMonitor.onAlert((alert) => {
      // eslint-disable-next-line no-console
      console.warn(`[Performance Alert] ${alert.message}`);
    });
  }
}

/**
 * Type transformation utilities for bridging core and CLI types
 */

import type {
  Issue as CLIIssue,
  AnalysisResult as CLIAnalysisResult,
  ExtendedToolResult,
  AIPrompt,
} from '../types/analysis';
import type { Issue as CoreIssue, AnalysisResult as CoreAnalysisResult } from '@dev-quality/core';

// Proper type definitions instead of any
type _any = unknown;

/**
 * Transform a Core Issue to CLI Issue with strict type checking
 */
export function transformCoreIssueToCLI(coreIssue: CoreIssue): CLIIssue {
  // Validate and transform the type field
  const validTypes = ['error', 'warning', 'info'] as const;
  const type = coreIssue.type.toLowerCase();

  if (!validTypes.includes(type as 'error' | 'warning' | 'info')) {
    throw new Error(
      `Invalid issue type: ${coreIssue.type}. Must be one of: ${validTypes.join(', ')}`
    );
  }

  return {
    ...coreIssue,
    type: type as 'error' | 'warning' | 'info',
  };
}

/**
 * Transform an array of Core Issues to CLI Issues
 */
export function transformCoreIssuesToCLI(coreIssues: CoreIssue[]): CLIIssue[] {
  return coreIssues.map(transformCoreIssueToCLI);
}

/**
 * Type guard to check if a string is a valid issue type
 */
export function isValidIssueType(type: string): type is 'error' | 'warning' | 'info' {
  return ['error', 'warning', 'info'].includes(type.toLowerCase());
}

/**
 * Safe transformation that filters out invalid issues
 */
export function safeTransformCoreIssuesToCLI(coreIssues: CoreIssue[]): CLIIssue[] {
  return coreIssues
    .filter(issue => isValidIssueType(issue.type))
    .map(issue => ({
      ...issue,
      type: issue.type.toLowerCase() as 'error' | 'warning' | 'info',
    }));
}

/**
 * Transform a Core AnalysisResult to CLI AnalysisResult
 */
export function transformCoreAnalysisResultToCLI(
  coreResult: CoreAnalysisResult
): CLIAnalysisResult {
  // Handle the interface differences between core and CLI AnalysisResult
  // Use type assertions to access properties that may not exist in the interface
  const coreResultUnknown = coreResult as unknown as Record<string, unknown>;

  return {
    id: (coreResultUnknown?.['id'] as string) ?? `analysis-${Date.now()}`,
    projectId: (coreResultUnknown?.['projectId'] as string) ?? 'unknown-project',
    timestamp:
      typeof coreResult.timestamp === 'string' ? coreResult.timestamp : new Date().toISOString(),
    duration: (coreResultUnknown?.['duration'] as number) ?? 0,
    overallScore: (coreResultUnknown?.['overallScore'] as number) ?? 0,
    toolResults: ((coreResultUnknown?.['toolResults'] as Array<Record<string, unknown>>) ?? []).map(
      (toolResult: Record<string, unknown>) => ({
        ...toolResult,
        issues: transformCoreIssuesToCLI(toolResult['issues'] as CoreIssue[]),
      })
    ) as ExtendedToolResult[],
    summary: (coreResultUnknown?.['summary'] as {
      totalIssues: number;
      totalErrors: number;
      totalWarnings: number;
      totalFixable: number;
      overallScore: number;
      toolCount: number;
      executionTime: number;
    }) ?? {
      totalIssues: 0,
      totalErrors: 0,
      totalWarnings: 0,
      totalFixable: 0,
      overallScore: 0,
      toolCount: 0,
      executionTime: 0,
    },
    aiPrompts: (coreResultUnknown?.['aiPrompts'] as AIPrompt[]) ?? [],
  };
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'bun:test';
import { SetupCommand } from '../src/commands/setup';
import { ConfigCommand } from '../src/commands/config';
