          timestamp: new Date().toISOString(),
          duration: 10,
          overallScore: 85,
          toolResults: [
            {
              toolName,
              executionTime: 10,
              status: 'success',
              issues: [],
              metrics: {
                issuesCount: 0,
                errorsCount: 0,
                warningsCount: 0,
                infoCount: 0,
                fixableCount: 0,
                score: 85,
              },
            },
          ],
          summary: {
            totalIssues: 0,
            totalErrors: 0,
            totalWarnings: 0,
            totalFixable: 0,
            overallScore: 85,
            toolCount: 1,
            executionTime: 10,
          },
          aiPrompts: [],
        };
      }
    );

    writeFileSync(testConfigPath, JSON.stringify(mockConfig), 'utf-8');
