    priority: 'normal' as const
  };
}

import { describe, it, expect, beforeEach, afterEach } from 'bun:test';
import { WizardService } from '../../../src/services/wizard/wizard-service';
import {
  BunTestConfigGenerator,
  ESLintConfigGenerator,
  PrettierConfigGenerator,
  TypeScriptConfigGenerator,
} from '../../../src/services/wizard/config-generator';
import {
  BunTestValidator,
  ESLintValidator,
  PrettierValidator,
  TypeScriptValidator,
} from '../../../src/services/wizard/validator';
import { RollbackService } from '../../../src/services/wizard/rollback';
import { writeFileSync, existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createTestDir, cleanupTestDir } from '../../test-utils';

describe('Complete Wizard Workflow', () => {
  let testDir: string;
  let wizardService: WizardService;
  let rollbackService: RollbackService;

  beforeEach(() => {
    testDir = createTestDir('wizard-workflow-test');
    wizardService = new WizardService(testDir);
    rollbackService = new RollbackService(testDir);

    // Create a minimal package.json for testing
    writeFileSync(
      join(testDir, 'package.json'),
      JSON.stringify({
        name: 'test-project',
        version: '1.0.0',
        description: 'Test project',
      })
    );
  });

  afterEach(() => {
    cleanupTestDir(testDir);
  });

  it('should complete full workflow: generate, validate, no rollback needed', async () => {
    // Step 1: Create backup
    await rollbackService.createBackup(
      ['bunfig.toml', 'eslint.config.js', '.prettierrc.json', 'tsconfig.json'],
      'configuration'
    );

    // Step 2: Generate all configurations
    const bunGenerator = new BunTestConfigGenerator({ projectPath: testDir });
    const eslintGenerator = new ESLintConfigGenerator({ projectPath: testDir });
    const prettierGenerator = new PrettierConfigGenerator({ projectPath: testDir });
    const tsGenerator = new TypeScriptConfigGenerator({ projectPath: testDir });

    const bunResult = await bunGenerator.generate('create');
    const eslintResult = await eslintGenerator.generate('create');
    const prettierResult = await prettierGenerator.generate('create');
    const tsResult = await tsGenerator.generate('create');

    wizardService.addGeneratedFile(bunResult.filePath);
    wizardService.addGeneratedFile(eslintResult.filePath);
    wizardService.addGeneratedFile(prettierResult.filePath);
    wizardService.addGeneratedFile(tsResult.filePath);

    // Step 3: Validate all configurations
    const bunValidator = new BunTestValidator({
      projectPath: testDir,
      configPath: 'bunfig.toml',
    });
    const eslintValidator = new ESLintValidator({
      projectPath: testDir,
      configPath: 'eslint.config.js',
    });
    const prettierValidator = new PrettierValidator({
      projectPath: testDir,
      configPath: '.prettierrc.json',
    });
    const tsValidator = new TypeScriptValidator({
      projectPath: testDir,
      configPath: 'tsconfig.json',
    });

    const bunValidation = await bunValidator.validate();
    const eslintValidation = await eslintValidator.validate();
    const prettierValidation = await prettierValidator.validate();
    const tsValidation = await tsValidator.validate();

    // Verify all validations
    expect(bunValidation.isValid).toBe(true);
    expect(eslintValidation.isValid).toBe(true);
    expect(prettierValidation.isValid).toBe(true);
    expect(tsValidation.isValid).toBe(true);

    // Step 4: Verify all files exist
    expect(existsSync(join(testDir, 'bunfig.toml'))).toBe(true);
    expect(existsSync(join(testDir, 'eslint.config.js'))).toBe(true);
    expect(existsSync(join(testDir, '.prettierrc.json'))).toBe(true);
    expect(existsSync(join(testDir, 'tsconfig.json'))).toBe(true);

    // Step 5: Cleanup backup
    await rollbackService.cleanupBackup();

    const generatedFiles = wizardService.getGeneratedFiles();
    expect(generatedFiles).toHaveLength(4);
  });

  it('should handle existing configurations with merge', async () => {
    // Create existing configs
    writeFileSync(join(testDir, 'bunfig.toml'), '[install]\nfrozen = true');
    writeFileSync(join(testDir, '.prettierrc.json'), '{"semi": false}');
    writeFileSync(
      join(testDir, 'tsconfig.json'),
      JSON.stringify({ compilerOptions: { target: 'ES2020' } })
    );

    // Create backup
    await rollbackService.createBackup(
      ['bunfig.toml', '.prettierrc.json', 'tsconfig.json'],
      'merge-test'
    );

    // Generate with merge
    const bunGenerator = new BunTestConfigGenerator({ projectPath: testDir });
    const prettierGenerator = new PrettierConfigGenerator({ projectPath: testDir });
    const tsGenerator = new TypeScriptConfigGenerator({ projectPath: testDir });

    await bunGenerator.generate('merge');
    await prettierGenerator.generate('merge');
    await tsGenerator.generate('merge');

    // Verify merge preserved existing settings
    const bunContent = readFileSync(join(testDir, 'bunfig.toml'), 'utf-8');
    expect(bunContent).toContain('[install]');
    expect(bunContent).toContain('[test]');

    const prettierContent = readFileSync(join(testDir, '.prettierrc.json'), 'utf-8');
    const prettierConfig = JSON.parse(prettierContent);
    expect(prettierConfig.semi).toBe(false); // Preserved

    const tsContent = readFileSync(join(testDir, 'tsconfig.json'), 'utf-8');
    const tsConfig = JSON.parse(tsContent);
    expect(tsConfig.compilerOptions.target).toBe('ES2020'); // Preserved
  });

  it('should rollback on validation failure', async () => {
    // Create existing config
    const originalContent = '{"compilerOptions": {"target": "ES2020"}}';
    writeFileSync(join(testDir, 'tsconfig.json'), originalContent);

    // Create backup
    await rollbackService.createBackup(['tsconfig.json'], 'validation-test');

    // Corrupt the config
    writeFileSync(join(testDir, 'tsconfig.json'), '{invalid json}');

    // Validate (should fail)
    const validator = new TypeScriptValidator({
      projectPath: testDir,
      configPath: 'tsconfig.json',
    });
    const validation = await validator.validate();

    expect(validation.isValid).toBe(false);

    // Rollback
    const rollbackResult = await rollbackService.rollback();
    expect(rollbackResult.success).toBe(true);

    // Verify original content restored
    const restoredContent = readFileSync(join(testDir, 'tsconfig.json'), 'utf-8');
    expect(restoredContent).toBe(originalContent);
  });

  it('should handle wizard cancellation with complete rollback', async () => {
    // Step 1: Generate some configs
    await rollbackService.createBackup(['bunfig.toml', 'tsconfig.json'], 'cancellation-test');

    const bunGenerator = new BunTestConfigGenerator({ projectPath: testDir });
    const tsGenerator = new TypeScriptConfigGenerator({ projectPath: testDir });

    await bunGenerator.generate('create');
    await tsGenerator.generate('create');

    expect(existsSync(join(testDir, 'bunfig.toml'))).toBe(true);
    expect(existsSync(join(testDir, 'tsconfig.json'))).toBe(true);

    // Step 2: User cancels wizard - rollback everything
    const rollbackResult = await rollbackService.rollback();

    expect(rollbackResult.success).toBe(true);
    expect(existsSync(join(testDir, 'bunfig.toml'))).toBe(false);
    expect(existsSync(join(testDir, 'tsconfig.json'))).toBe(false);
  });

  it('should handle JavaScript-only project', async () => {
    // Update package.json to be JavaScript-only
    writeFileSync(
      join(testDir, 'package.json'),
      JSON.stringify({
        name: 'js-project',
        version: '1.0.0',
        main: 'index.js',
      })
    );

    // Generate configs (TypeScript optional for JS projects)
    const bunGenerator = new BunTestConfigGenerator({ projectPath: testDir });
    const eslintGenerator = new ESLintConfigGenerator({ projectPath: testDir });
    const prettierGenerator = new PrettierConfigGenerator({ projectPath: testDir });

    await bunGenerator.generate('create');
    await eslintGenerator.generate('create');
    await prettierGenerator.generate('create');

    // Verify configs exist
    expect(existsSync(join(testDir, 'bunfig.toml'))).toBe(true);
    expect(existsSync(join(testDir, 'eslint.config.js'))).toBe(true);
    expect(existsSync(join(testDir, '.prettierrc.json'))).toBe(true);
  });

  it('should persist configuration to context', async () => {
    const bunGenerator = new BunTestConfigGenerator({ projectPath: testDir });
    const result = await bunGenerator.generate('create');

    wizardService.addGeneratedFile(result.filePath);

    const context = wizardService.getContext();
    expect(context.generatedFiles).toContain(result.filePath);
  });
});

/**
 * Dashboard Navigation Performance Tests
 * Tests performance requirements for 10K+ items
 */

import { describe, it, expect } from 'bun:test';
import { performance } from 'perf_hooks';

// Mock components for performance testing
const createMockIssue = (id: number): any => ({
  id: `issue-${id}`,
  type: id % 3 === 0 ? 'error' : id % 3 === 1 ? 'warning' : 'info',
  toolName: ['eslint', 'typescript', 'prettier'][id % 3],
  filePath: `/src/components/Component${id}.tsx`,
  lineNumber: (id % 100) + 1,
  message: `Test message ${id} - This is a sample issue message for performance testing`,
  ruleId: `rule-${id}`,
  fixable: id % 2 === 0,
  score: Math.random() * 10,
  priorityScore: Math.random() * 10,
  priorityLevel: ['critical', 'high', 'medium', 'low'][Math.floor(Math.random() * 4)] as any,
});

// Mock virtualized list implementation
const mockVirtualizedList = {
  render: (items: any[], windowSize: number) => {
    const startTime = performance.now();

    // Simulate virtualization - only process visible items
    const visibleItems = items.slice(0, windowSize);

    // Simulate rendering time
    for (const item of visibleItems) {
      JSON.stringify(item); // Simulate item processing
    }

    const endTime = performance.now();
    return endTime - startTime;
  },

  navigate: (items: any[], fromIndex: number, toIndex: number) => {
    const startTime = performance.now();

    // Simulate navigation calculation
    const distance = Math.abs(toIndex - fromIndex);
    for (let i = 0; i < distance; i++) {
      JSON.stringify(items[Math.min(fromIndex + i, items.length - 1)]);
    }

    const endTime = performance.now();
    return endTime - startTime;
  },
};

// Mock navigation state management
const mockNavigationState = {
  createState: (items: any[]) => {
    const startTime = performance.now();

    const state = {
      items: [...items],
      selectedIndex: 0,
      breadcrumbs: [],
      context: {},
      canGoBack: false,
      canGoForward: false,
    };

    // Deep copy to simulate real state management
    JSON.parse(JSON.stringify(state));

    const endTime = performance.now();
    return endTime - startTime;
  },

  updateState: (state: any, updates: any) => {
    const startTime = performance.now();

    // Simulate state update
    const newState = { ...state, ...updates };
    JSON.parse(JSON.stringify(newState));

    const endTime = performance.now();
    return endTime - startTime;
  },
};

describe('Dashboard Navigation Performance', () => {
  // Performance requirements from story
  const MAX_ITEMS = 10000;
  const MAX_RENDER_TIME = 100; // ms
  const MAX_NAVIGATION_TIME = 50; // ms
  const MAX_STATE_UPDATE_TIME = 10; // ms
  const MAX_MEMORY_USAGE = 512; // MB

  it('should handle 10K items within render time limit', () => {
    const largeDataSet = Array.from({ length: MAX_ITEMS }, (_, index) => createMockIssue(index));

    const renderTime = mockVirtualizedList.render(largeDataSet, 10); // Window size of 10

    expect(renderTime).toBeLessThan(MAX_RENDER_TIME);
    console.log(`✓ 10K items rendered in ${renderTime.toFixed(2)}ms`);
  });

  it('should handle navigation between distant items quickly', () => {
    const largeDataSet = Array.from({ length: MAX_ITEMS }, (_, index) => createMockIssue(index));

    // Navigate from first to last item
    const navigationTime = mockVirtualizedList.navigate(largeDataSet, 0, MAX_ITEMS - 1);

    expect(navigationTime).toBeLessThan(MAX_NAVIGATION_TIME);
    console.log(`✓ Navigation between distant items completed in ${navigationTime.toFixed(2)}ms`);
  });

  it('should handle state updates efficiently', () => {
    const largeDataSet = Array.from({ length: MAX_ITEMS }, (_, index) => createMockIssue(index));

    const createTime = mockNavigationState.createState(largeDataSet);
    const updateTime = mockNavigationState.updateState(
      { items: largeDataSet, selectedIndex: 0 },
      { selectedIndex: 5000 }
    );

    expect(createTime).toBeLessThan(MAX_STATE_UPDATE_TIME * 50); // Allow more time for large dataset
    expect(updateTime).toBeLessThan(MAX_STATE_UPDATE_TIME * 20); // Allow more time for updates
    console.log(`✓ State creation: ${createTime.toFixed(2)}ms, update: ${updateTime.toFixed(2)}ms`);
  });

  it('should maintain performance with window size changes', () => {
    const largeDataSet = Array.from({ length: MAX_ITEMS }, (_, index) => createMockIssue(index));

    const windowSizes = [5, 10, 20, 50, 100];
    const renderTimes: number[] = [];

    for (const windowSize of windowSizes) {
      const renderTime = mockVirtualizedList.render(largeDataSet, windowSize);
      renderTimes.push(renderTime);
      expect(renderTime).toBeLessThan(MAX_RENDER_TIME);
    }

    const averageRenderTime = renderTimes.reduce((a, b) => a + b, 0) / renderTimes.length;
    expect(averageRenderTime).toBeLessThan(MAX_RENDER_TIME);
    console.log(`✓ Average render time across window sizes: ${averageRenderTime.toFixed(2)}ms`);
  });

  it('should handle rapid keyboard navigation', () => {
    const largeDataSet = Array.from({ length: 1000 }, (_, index) => createMockItem(index)); // Smaller dataset for rapid testing

    const navigationTimes: number[] = [];
    let currentIndex = 0;

    // Simulate rapid navigation
    for (let i = 0; i < 100; i++) {
      currentIndex = (currentIndex + 10) % largeDataSet.length;
      const navTime = mockVirtualizedList.navigate(
        largeDataSet,
        Math.max(0, currentIndex - 10),
        currentIndex
      );
      navigationTimes.push(navTime);
    }

    const averageNavTime = navigationTimes.reduce((a, b) => a + b, 0) / navigationTimes.length;
    expect(averageNavTime).toBeLessThan(MAX_NAVIGATION_TIME / 2); // Should be faster for rapid navigation
    console.log(`✓ Rapid keyboard navigation: ${averageNavTime.toFixed(2)}ms average`);
  });

  it('should handle breadcrumb management efficiently', () => {
    const startTime = performance.now();

    // Create a deep breadcrumb trail
    const breadcrumbs = [];
    for (let i = 0; i < 100; i++) {
      breadcrumbs.push({
        id: `breadcrumb-${i}`,
        label: `Breadcrumb ${i}`,
        view: 'issue-list' as any,
        data: { depth: i },
      });
    }

    // Simulate breadcrumb rendering time
    let breadcrumbRenderTime = 0;
    for (const breadcrumb of breadcrumbs) {
      const start = performance.now();
      JSON.stringify(breadcrumb);
      breadcrumbRenderTime += performance.now() - start;
    }

    const totalTime = performance.now() - startTime;

    expect(breadcrumbRenderTime).toBeLessThan(10); // Breadcrumb rendering should be very fast
    expect(totalTime).toBeLessThan(50); // Total breadcrumb processing should be fast
    console.log(`✓ 100 breadcrumbs processed in ${breadcrumbRenderTime.toFixed(2)}ms`);
  });

  it('should maintain performance under memory pressure', () => {
    // This test simulates memory usage by tracking object creation
    const startTime = performance.now();
    let objectCount = 0;

    // Simulate creating many navigation states
    for (let i = 0; i < 1000; i++) {
      const state = {
        items: Array.from({ length: 100 }, () => createMockIssue(Math.random() * 1000)),
        selectedIndex: Math.floor(Math.random() * 100),
        breadcrumbs: Array.from({ length: 5 }, (_, index) => ({
          id: `bc-${i}-${index}`,
          label: `Breadcrumb ${index}`,
        })),
        context: {},
      };

      // Force object creation (simulates memory allocation)
      JSON.stringify(state);
      objectCount++;
    }

    const totalTime = performance.now() - startTime;
    const avgTimePerState = totalTime / 1000;

    expect(avgTimePerState).toBeLessThan(1); // Should be very fast
    console.log(`✓ Created ${objectCount} navigation states in ${totalTime.toFixed(2)}ms`);
  });

  it('should handle concurrent navigation operations', async () => {
    const largeDataSet = Array.from({ length: 5000 }, (_, index) => createMockIssue(index));

    const startTime = performance.now();

    // Simulate concurrent operations
    const operations = [];
    for (let i = 0; i < 10; i++) {
      operations.push(mockVirtualizedList.render(largeDataSet.slice(i * 500, (i + 1) * 500), 10));
    }

    const results = await Promise.all(operations);
    const totalTime = performance.now() - startTime;

    const maxRenderTime = Math.max(...results);
    const avgRenderTime = results.reduce((a, b) => a + b, 0) / results.length;

    expect(maxRenderTime).toBeLessThan(MAX_RENDER_TIME);
    expect(avgRenderTime).toBeLessThan(MAX_RENDER_TIME);
    console.log(
      `✓ Concurrent operations: max ${maxRenderTime.toFixed(2)}ms, avg ${avgRenderTime.toFixed(2)}ms`
    );
  });

  // Helper function for creating mock items
  function createMockItem(id: number): any {
    return {
      id: `item-${id}`,
      message: `Mock item ${id}`,
      type: ['error', 'warning', 'info'][id % 3],
      priority: Math.random() * 10,
      data: Array.from({ length: 10 }, (_, index) => ({
        key: `data-${index}`,
        value: Math.random(),
      })),
    };
  }
});

/**
 * Performance Tests for Report Generation
 *
 * Tests report generation performance with large datasets to ensure
 * compliance with Story 2.4 performance requirements:
 * - JSON export: Must complete within 5 seconds for 10K issues
 * - HTML export: Must complete within 15 seconds for 10K issues
 * - Markdown export: Must complete within 10 seconds for 10K issues
 * - PDF export: Must complete within 30 seconds for 10K issues
 * - Memory usage must stay under 1GB during report generation
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { ReportGenerator, type ReportRequest } from '../../src/services/reporting/report-generator';
import type { AnalysisResult as CoreAnalysisResult, Issue } from '@dev-quality/core';
import type { DashboardMetrics } from '../../src/types/dashboard';
import type { AnalysisResult } from '../../src/types/analysis';
import { performance } from 'perf_hooks';

describe('Report Generation Performance', () => {
  let reportGenerator: ReportGenerator;
  let largeDataset: CoreAnalysisResult;
  const memoryUsageHistory: NodeJS.MemoryUsage[] = [];

  beforeEach(() => {
    reportGenerator = new ReportGenerator();
    largeDataset = generateLargeDataset(10000); // 10K issues as required
    memoryUsageHistory.length = 0; // Clear memory history
  });

  afterEach(() => {
    // Cleanup to prevent memory leaks
    reportGenerator = null as any;
    largeDataset = null as any;
    if (global.gc) {
      global.gc(); // Force garbage collection if available
    }
  });

  describe('AC1: Multiple Export Formats Performance', () => {
    it('JSON export completes within 5 seconds for 10K issues', async () => {
      const startTime = performance.now();
      const startMemory = process.memoryUsage();

      const result = await reportGenerator.generateReport(
        createPerformanceTestReportRequest(largeDataset, 'json', 'executive-summary')
      );

      const endTime = performance.now();
      const endMemory = process.memoryUsage();
      const duration = endTime - startTime;
      const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;

      memoryUsageHistory.push(endMemory);

      expect(result.success).toBe(true);
      expect(duration).toBeLessThan(5000); // 5 seconds in milliseconds
      expect(memoryUsed).toBeLessThan(1024 * 1024 * 1024); // 1GB in bytes

      console.log(`JSON export performance: ${duration.toFixed(2)}ms, Memory: ${(memoryUsed / 1024 / 1024).toFixed(2)}MB`);
    });

    it('HTML export completes within 15 seconds for 10K issues', async () => {
      const startTime = performance.now();
      const startMemory = process.memoryUsage();

      const result = await reportGenerator.generateReport(
        createPerformanceTestReportRequest(largeDataset, 'html', 'executive-summary')
      );

      const endTime = performance.now();
      const endMemory = process.memoryUsage();
      const duration = endTime - startTime;
      const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;

      memoryUsageHistory.push(endMemory);

      expect(result.success).toBe(true);
      expect(duration).toBeLessThan(15000); // 15 seconds in milliseconds
      expect(memoryUsed).toBeLessThan(1024 * 1024 * 1024); // 1GB in bytes

      console.log(`HTML export performance: ${duration.toFixed(2)}ms, Memory: ${(memoryUsed / 1024 / 1024).toFixed(2)}MB`);
    });

    it('Markdown export completes within 10 seconds for 10K issues', async () => {
      const startTime = performance.now();
      const startMemory = process.memoryUsage();

      const result = await reportGenerator.generateReport(
        createPerformanceTestReportRequest(largeDataset, 'markdown', 'technical-report')
      );

      const endTime = performance.now();
      const endMemory = process.memoryUsage();
      const duration = endTime - startTime;
      const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;

      memoryUsageHistory.push(endMemory);

      expect(result.success).toBe(true);
      expect(duration).toBeLessThan(10000); // 10 seconds in milliseconds
      expect(memoryUsed).toBeLessThan(1024 * 1024 * 1024); // 1GB in bytes

      console.log(`Markdown export performance: ${duration.toFixed(2)}ms, Memory: ${(memoryUsed / 1024 / 1024).toFixed(2)}MB`);
    });

    it('PDF export completes within 30 seconds for 10K issues', async () => {
      const startTime = performance.now();
      const startMemory = process.memoryUsage();

      const result = await reportGenerator.generateReport(
        createPerformanceTestReportRequest(largeDataset, 'pdf', 'detailed-analysis')
      );

      const endTime = performance.now();
      const endMemory = process.memoryUsage();
      const duration = endTime - startTime;
      const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;

      memoryUsageHistory.push(endMemory);

      expect(result.success).toBe(true);
      expect(duration).toBeLessThan(30000); // 30 seconds in milliseconds
      expect(memoryUsed).toBeLessThan(1024 * 1024 * 1024); // 1GB in bytes

      console.log(`PDF export performance: ${duration.toFixed(2)}ms, Memory: ${(memoryUsed / 1024 / 1024).toFixed(2)}MB`);
    });
  });

  describe('Memory Management', () => {
    it('Memory usage stays under 1GB during report generation', async () => {
      const formats = ['json', 'html', 'markdown', 'pdf'] as const;

      for (const format of formats) {
        const startMemory = process.memoryUsage();

        await reportGenerator.generateReport(
          createPerformanceTestReportRequest(largeDataset, format, format === 'json' ? 'executive-summary' : format === 'html' ? 'executive-summary' : format === 'markdown' ? 'technical-report' : 'detailed-analysis')
        );

        const endMemory = process.memoryUsage();
        const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;

        expect(memoryUsed).toBeLessThan(1024 * 1024 * 1024); // 1GB in bytes

        if (global.gc) {
          global.gc(); // Force garbage collection between tests
        }
      }
    });

    it('Memory usage does not grow excessively with multiple reports', async () => {
      const initialMemory = process.memoryUsage();
      const memorySnapshots: NodeJS.MemoryUsage[] = [initialMemory];

      // Generate 5 reports consecutively
      for (let i = 0; i < 5; i++) {
        await reportGenerator.generateReport(
          createPerformanceTestReportRequest(largeDataset, 'json', 'executive-summary')
        );

        const currentMemory = process.memoryUsage();
        memorySnapshots.push(currentMemory);

        if (global.gc) {
          global.gc();
        }
      }

      // Check that memory growth is reasonable (less than 500MB growth)
      const memoryGrowth = memorySnapshots[memorySnapshots.length - 1].heapUsed - initialMemory.heapUsed;
      expect(memoryGrowth).toBeLessThan(500 * 1024 * 1024); // 500MB

      console.log(`Memory growth over 5 reports: ${(memoryGrowth / 1024 / 1024).toFixed(2)}MB`);
    });
  });

  describe('Concurrent Report Generation', () => {
    it('Supports up to 3 simultaneous reports', async () => {
      const concurrentReports = 3;
      const startTime = performance.now();
      const startMemory = process.memoryUsage();

      const promises = Array.from({ length: concurrentReports }, (_, i) =>
        reportGenerator.generateReport(
          createPerformanceTestReportRequest(largeDataset, 'json', 'executive-summary')
        )
      );

      const results = await Promise.all(promises);

      const endTime = performance.now();
      const endMemory = process.memoryUsage();
      const duration = endTime - startTime;
      const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;

      expect(results.every(result => result.success)).toBe(true);
      expect(memoryUsed).toBeLessThan(1024 * 1024 * 1024); // 1GB in bytes
      expect(duration).toBeLessThan(15000); // Should complete faster than sequential

      console.log(`Concurrent reports (${concurrentReports}): ${duration.toFixed(2)}ms, Memory: ${(memoryUsed / 1024 / 1024).toFixed(2)}MB`);
    });

    it('Handles concurrent report generation with different formats', async () => {
      const formats = ['json', 'html', 'markdown'] as const;
      const startTime = performance.now();
      const startMemory = process.memoryUsage();

      const promises = formats.map((format, index) =>
        reportGenerator.generateReport(
          createPerformanceTestReportRequest(largeDataset, format, format === 'json' ? 'executive-summary' : format === 'html' ? 'executive-summary' : format === 'markdown' ? 'technical-report' : 'detailed-analysis')
        )
      );

      const results = await Promise.all(promises);

      const endTime = performance.now();
      const endMemory = process.memoryUsage();
      const duration = endTime - startTime;
      const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;

      expect(results.every(result => result.success)).toBe(true);
      expect(memoryUsed).toBeLessThan(1024 * 1024 * 1024); // 1GB in bytes

      console.log(`Mixed format concurrent reports: ${duration.toFixed(2)}ms, Memory: ${(memoryUsed / 1024 / 1024).toFixed(2)}MB`);
    });
  });

  describe('AC2: Template Processing Performance', () => {
    it('Template rendering completes within 2 seconds per report', async () => {
      const templates = [
        { id: 'executive-summary', format: 'html' },
        { id: 'technical-report', format: 'markdown' },
        { id: 'detailed-analysis', format: 'pdf' }
      ];

      for (const template of templates) {
        const startTime = performance.now();

        const result = await reportGenerator.generateReport(
          createPerformanceTestReportRequest(largeDataset, template.format, template.id)
        );

        const endTime = performance.now();
        const duration = endTime - startTime;

        expect(result.success).toBe(true);
        expect(duration).toBeLessThan(2000); // 2 seconds in milliseconds

        console.log(`Template '${template.id}' (${template.format}) rendering: ${duration.toFixed(2)}ms`);
      }
    });

    it('Template validation completes within 500ms', async () => {
      const customTemplate = `
        <html>
          <head><title>{{reportTitle}}</title></head>
          <body>
            <h1>{{reportTitle}}</h1>
            <p>Generated: {{timestamp}}</p>
            <ul>
              {{#each issues}}
              <li>{{this.message}} ({{this.severity}})</li>
              {{/each}}
            </ul>
          </body>
        </html>
      `;

      const startTime = performance.now();

      const validation = await reportGenerator.validateTemplate(customTemplate);

      const endTime = performance.now();
      const duration = endTime - startTime;

      expect(validation.valid).toBe(true);
      expect(duration).toBeLessThan(500); // 500ms in milliseconds

      console.log(`Template validation: ${duration.toFixed(2)}ms`);
    });
  });

  describe('Performance Regression Detection', () => {
    it('Establishes performance baseline for regression testing', async () => {
      const testCases = [
        { format: 'json', expectedMax: 5000, description: 'JSON export' },
        { format: 'html', expectedMax: 15000, description: 'HTML export' },
        { format: 'markdown', expectedMax: 10000, description: 'Markdown export' },
        { format: 'pdf', expectedMax: 30000, description: 'PDF export' }
      ];

      const results: Array<{
        format: string;
        duration: number;
        memoryUsed: number;
        passed: boolean;
      }> = [];

      for (const testCase of testCases) {
        const startTime = performance.now();
        const startMemory = process.memoryUsage();

        await reportGenerator.generateReport(
          createPerformanceTestReportRequest(largeDataset, testCase.format, testCase.format === 'json' ? 'executive-summary' : testCase.format === 'html' ? 'executive-summary' : testCase.format === 'markdown' ? 'technical-report' : 'detailed-analysis')
        );

        const endTime = performance.now();
        const endMemory = process.memoryUsage();
        const duration = endTime - startTime;
        const memoryUsed = endMemory.heapUsed - startMemory.heapUsed;
        const passed = duration <= testCase.expectedMax && memoryUsed <= 1024 * 1024 * 1024;

        results.push({
          format: testCase.format,
          duration,
          memoryUsed,
          passed
        });

        console.log(`${testCase.description}: ${duration.toFixed(2)}ms (${testCase.expectedMax}ms max), Memory: ${(memoryUsed / 1024 / 1024).toFixed(2)}MB`);
      }

      // All tests should pass for baseline
      expect(results.every(result => result.passed)).toBe(true);

      // Store baseline for future regression testing
      console.log('Performance baseline established:', results);
    });
  });
});

/**
 * Generates a large dataset for performance testing
 */
function generateLargeDataset(issueCount: number): CoreAnalysisResult {
  const issues: Issue[] = [];
  const severities: Array<'error' | 'warning' | 'info'> = ['error', 'warning', 'info'];
  const tools = ['eslint', 'typescript', 'prettier', 'bun-test'];

  for (let i = 0; i < issueCount; i++) {
    issues.push({
      id: `issue-${i}`,
      type: severities[i % severities.length],
      toolName: tools[i % tools.length],
      filePath: `src/file-${i % 100}.ts`,
      lineNumber: Math.floor(Math.random() * 500) + 1,
      message: `Performance test issue ${i}: ${'Lorem ipsum dolor sit amet, consectetur adipiscing elit. '.repeat(5)}`,
      ruleId: `rule-${i % 50}`,
      fixable: i % 3 !== 0,
      suggestion: `Fix suggestion for issue ${i}`,
      score: Math.floor(Math.random() * 100) + 1
    });
  }

  return {
    id: `perf-test-${Date.now()}`,
    projectId: 'performance-test-project',
    timestamp: new Date(),
    duration: issueCount * 10, // 10ms per issue
    overallScore: Math.floor(Math.random() * 100) + 1,
    toolResults: [
      {
        toolName: 'eslint',
        version: '8.0.0',
        executionTime: issueCount * 2,
        issuesFound: issues.filter(i => i.toolName === 'eslint').length,
        issuesFixed: 0,
        configuration: { rules: {} }
      },
      {
        toolName: 'typescript',
        version: '5.0.0',
        executionTime: issueCount * 3,
        issuesFound: issues.filter(i => i.toolName === 'typescript').length,
        issuesFixed: 0,
        configuration: { compilerOptions: {} }
      }
    ],
    summary: {
      totalIssues: issues.length,
      criticalIssues: issues.filter(i => i.type === 'error').length,
      warningIssues: issues.filter(i => i.type === 'warning').length,
      infoIssues: issues.filter(i => i.type === 'info').length,
      fixableIssues: issues.filter(i => i.fixable).length,
      overallScore: Math.floor(Math.random() * 100) + 1,
      topIssues: issues.slice(0, 10)
    },
    aiPrompts: []
  };
}

// Helper function to convert CoreAnalysisResult to ReportRequest for performance tests
function createPerformanceTestReportRequest(coreData: CoreAnalysisResult, format: string, template?: string): ReportRequest {
  // Convert core AnalysisResult to CLI AnalysisResult (timestamp: Date -> string)
  const cliAnalysisResult: AnalysisResult = {
    id: coreData.id,
    projectId: coreData.projectId,
    timestamp: coreData.timestamp.toISOString(),
    duration: coreData.duration,
    overallScore: coreData.overallScore,
    toolResults: coreData.toolResults.map(result => ({
      toolName: result.toolName,
      executionTime: result.executionTime,
      status: 'completed' as const,
      issues: [], // Performance tests don't need detailed issues
      metrics: {
        totalIssues: result.issuesFound,
        criticalIssues: 0, // Simplified for performance tests
        warningIssues: result.issuesFound,
        infoIssues: 0,
        fixableIssues: result.issuesFixed,
        overallScore: 80
      },
      coverage: null
    })),
    summary: coreData.summary,
    aiPrompts: coreData.aiPrompts
  };

  const metrics: DashboardMetrics = {
    totalIssues: coreData.summary.totalIssues,
    errorCount: coreData.summary.criticalIssues,
    warningCount: coreData.summary.warningIssues,
    infoCount: coreData.summary.infoIssues,
    fixableCount: coreData.summary.fixableIssues,
    overallScore: coreData.overallScore,
    coverage: null,
    toolsAnalyzed: coreData.toolResults.length,
    duration: coreData.duration
  };

  return {
    configuration: {
      id: `perf-test-${Date.now()}`,
      name: 'Performance Test Report',
      description: 'Performance test report',
      templateId: template ?? 'default',
      format: format as any,
      recipients: [],
      filters: {
        severity: ['error', 'warning', 'info'],
        tools: [],
        scoreRange: { min: 0, max: 100 },
        fixableOnly: false,
        dateRange: undefined
      },
      createdAt: new Date(),
      updatedAt: new Date(),
      isActive: true
    },
    analysisResult: cliAnalysisResult,
    issues: [], // Performance tests don't need detailed issues
    metrics
  };
}

import { mkdirSync, mkdtempSync, rmSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Test utilities for managing temporary directories
 */

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const PROJECT_ROOT = join(__dirname, '../../..');
const TEMP_DIR = join(PROJECT_ROOT, 'temp');

/**
 * Ensure temp directory exists
 */
export function ensureTempDir(): void {
  if (!existsSync(TEMP_DIR)) {
    mkdirSync(TEMP_DIR, { recursive: true });
  }
}

/**
 * Create a temporary directory for tests in the project's temp folder
 * @param prefix - Prefix for the temporary directory name
 * @returns Absolute path to the created temporary directory
 */
export function createTestDir(prefix: string): string {
  ensureTempDir();
  return mkdtempSync(join(TEMP_DIR, `${prefix}-`));
}

/**
 * Clean up a test directory
 * @param testDir - Directory to remove
 */
export function cleanupTestDir(testDir: string): void {
  try {
    if (existsSync(testDir)) {
      rmSync(testDir, { recursive: true, force: true });
    }
  } catch (error) {
    // Ignore cleanup errors in tests
    console.warn(`Warning: Failed to cleanup test directory ${testDir}:`, error);
  }
}

/**
 * Clean up all test directories in temp folder
 */
export function cleanupAllTestDirs(): void {
  try {
    if (existsSync(TEMP_DIR)) {
      rmSync(TEMP_DIR, { recursive: true, force: true });
    }
  } catch (error) {
    console.warn('Warning: Failed to cleanup temp directory:', error);
  }
}

/**
 * Get the temp directory path
 */
export function getTempDir(): string {
  return TEMP_DIR;
}

import { describe, it, expect, beforeEach } from 'vitest';

// Mock data structures for comparative analysis
interface AnalysisRun {
  id: string;
  timestamp: Date;
  projectId: string;
  overallScore: number;
  issueCount: number;
  issues: AnalysisIssue[];
  metrics: {
    coverage: number;
    maintainability: number;
    reliability: number;
    security: number;
  };
}

interface AnalysisIssue {
  id: string;
  type: 'error' | 'warning' | 'info';
  severity: number;
  toolName: string;
  filePath: string;
  lineNumber: number;
  message: string;
  score: number;
}

interface ComparisonResult {
  run1: AnalysisRun;
  run2: AnalysisRun;
  differences: {
    addedIssues: AnalysisIssue[];
    removedIssues: AnalysisIssue[];
    modifiedIssues: Array<{ old: AnalysisIssue; new: AnalysisIssue }>;
  };
  metricChanges: {
    overallScore: number;
    coverage: number;
    maintainability: number;
    reliability: number;
    security: number;
    issueCount: number;
  };
  trend: 'improved' | 'degraded' | 'stable';
}

describe('2.3-UNIT-009: Diff Calculation Algorithm', () => {
  let generateMockRun: (id: string, baseScore: number) => AnalysisRun;

  beforeEach(() => {
    generateMockRun = (id: string, baseScore: number): AnalysisRun => {
      // Create deterministic base issues for consistent testing
      const baseIssues = Array.from({ length: 10 }, (_, i) => ({
        id: `base-issue-${i}`,
        type: ['error', 'warning', 'info'][i % 3] as 'error' | 'warning' | 'info',
        severity: (i % 5) + 5,
        toolName: ['eslint', 'typescript', 'prettier'][i % 3],
        filePath: `src/components/component${i}.tsx`,
        lineNumber: i + 1,
        message: `Base issue ${i}`,
        score: (i % 5) + 5
      }));

      return {
        id,
        timestamp: new Date(`2025-01-${id.padStart(2, '0')}`),
        projectId: 'test-project',
        overallScore: baseScore,
        issueCount: baseIssues.length,
        issues: baseIssues,
        metrics: {
          coverage: baseScore + 5,
          maintainability: baseScore - 5,
          reliability: baseScore + 10,
          security: baseScore
        }
      };
    };
  });

  const calculateDiff = (run1: AnalysisRun, run2: AnalysisRun): ComparisonResult => {
    // Find added issues (present in run2 but not run1)
    const addedIssues = run2.issues.filter(issue2 =>
      !run1.issues.some(issue1 =>
        issue1.id === issue2.id
      )
    );

    // Find removed issues (present in run1 but not run2)
    const removedIssues = run1.issues.filter(issue1 =>
      !run2.issues.some(issue2 =>
        issue1.id === issue2.id
      )
    );

    // Find modified issues (same ID but different details)
    const modifiedIssues = run1.issues.flatMap(issue1 => {
      const matchingIssue = run2.issues.find(issue2 =>
        issue1.id === issue2.id
      );

      if (matchingIssue &&
          (issue1.message !== matchingIssue.message ||
           issue1.severity !== matchingIssue.severity ||
           issue1.score !== matchingIssue.score)) {
        return [{ old: issue1, new: matchingIssue }];
      }
      return [];
    });

    // Calculate metric changes - use actual issue array lengths
    const metricChanges = {
      overallScore: run2.overallScore - run1.overallScore,
      coverage: run2.metrics.coverage - run1.metrics.coverage,
      maintainability: run2.metrics.maintainability - run1.metrics.maintainability,
      reliability: run2.metrics.reliability - run1.metrics.reliability,
      security: run2.metrics.security - run1.metrics.security,
      issueCount: run2.issues.length - run1.issues.length
    };

    // Determine trend
    let trend: 'improved' | 'degraded' | 'stable' = 'stable';
    const significantChanges = Object.values(metricChanges).filter(change =>
      Math.abs(change) > 5
    ).length;

    if (significantChanges > 0) {
      const positiveChanges = Object.values(metricChanges).filter(change =>
        change > 5
      ).length;
      const negativeChanges = Object.values(metricChanges).filter(change =>
        change < -5
      ).length;

      if (positiveChanges > negativeChanges) {
        trend = 'improved';
      } else if (negativeChanges > positiveChanges) {
        trend = 'degraded';
      }
    }

    return {
      run1,
      run2,
      differences: {
        addedIssues,
        removedIssues,
        modifiedIssues
      },
      metricChanges,
      trend
    };
  };

  it('should detect added issues correctly', () => {
    const run1 = generateMockRun('01', 75);
    const run2 = generateMockRun('02', 75);

    // Add a new issue to run2
    const newIssue: AnalysisIssue = {
      id: 'new-issue',
      type: 'error',
      severity: 8,
      toolName: 'eslint',
      filePath: 'src/components/NewComponent.tsx',
      lineNumber: 15,
      message: 'New issue introduced',
      score: 8
    };
    run2.issues.push(newIssue);

    const result = calculateDiff(run1, run2);

    expect(result.differences.addedIssues).toHaveLength(1);
    expect(result.differences.addedIssues[0]).toEqual(newIssue);
    expect(result.differences.removedIssues).toHaveLength(0);
    expect(result.metricChanges.issueCount).toBe(1);
  });

  it('should detect removed issues correctly', () => {
    const run1 = generateMockRun('01', 75);
    const run2 = generateMockRun('02', 75);

    // Remove an issue from run2
    const removedIssue = run1.issues[0];
    run2.issues = run1.issues.filter(issue => issue.id !== removedIssue.id);

    const result = calculateDiff(run1, run2);

    expect(result.differences.removedIssues).toHaveLength(1);
    expect(result.differences.removedIssues[0]).toEqual(removedIssue);
    expect(result.differences.addedIssues).toHaveLength(0);
    expect(result.metricChanges.issueCount).toBe(-1);
  });

  it('should detect modified issues correctly', () => {
    const run1 = generateMockRun('01', 75);
    const run2 = generateMockRun('02', 75);

    // Modify an issue in run2
    const modifiedIssue = { ...run2.issues[0] };
    modifiedIssue.severity = 9; // Changed from original
    modifiedIssue.message = 'Modified message'; // Changed message
    run2.issues[0] = modifiedIssue;

    const result = calculateDiff(run1, run2);

    expect(result.differences.modifiedIssues).toHaveLength(1);
    expect(result.differences.modifiedIssues[0].old).toEqual(run1.issues[0]);
    expect(result.differences.modifiedIssues[0].new).toEqual(modifiedIssue);
  });

  it('should handle complex diff scenarios', () => {
    const run1 = generateMockRun('01', 75);
    const run2 = generateMockRun('02', 80);

    // Add 2 new issues
    run2.issues.push(
      {
        id: 'added-1',
        type: 'error',
        severity: 7,
        toolName: 'typescript',
        filePath: 'src/added/file1.ts',
        lineNumber: 10,
        message: 'Added issue 1',
        score: 7
      },
      {
        id: 'added-2',
        type: 'warning',
        severity: 5,
        toolName: 'eslint',
        filePath: 'src/added/file2.ts',
        lineNumber: 20,
        message: 'Added issue 2',
        score: 5
      }
    );

    // Remove 1 issue
    const removedIssue = run1.issues[2];
    run2.issues = run2.issues.filter(issue => issue.id !== removedIssue.id);

    // Modify 1 issue
    const modifiedIndex = 1;
    run2.issues[modifiedIndex] = {
      ...run2.issues[modifiedIndex],
      severity: 8,
      message: 'Modified severity and message'
    };

    const result = calculateDiff(run1, run2);

    expect(result.differences.addedIssues).toHaveLength(2);
    expect(result.differences.removedIssues).toHaveLength(1);
    expect(result.differences.modifiedIssues).toHaveLength(1);
    expect(result.metricChanges.issueCount).toBe(1); // 2 added - 1 removed
  });

  it('should handle identical runs', () => {
    const run1 = generateMockRun('01', 75);
    const run2 = { ...run1, id: '02' }; // Same data, different ID

    const result = calculateDiff(run1, run2);

    expect(result.differences.addedIssues).toHaveLength(0);
    expect(result.differences.removedIssues).toHaveLength(0);
    expect(result.differences.modifiedIssues).toHaveLength(0);
    expect(result.trend).toBe('stable');
    expect(Object.values(result.metricChanges).every(change => change === 0)).toBe(true);
  });

  it('should handle empty issue lists', () => {
    const run1: AnalysisRun = {
      id: '01',
      timestamp: new Date('2025-01-01'),
      projectId: 'test-project',
      overallScore: 100,
      issueCount: 0,
      issues: [],
      metrics: { coverage: 100, maintainability: 100, reliability: 100, security: 100 }
    };

    const run2: AnalysisRun = {
      id: '02',
      timestamp: new Date('2025-01-02'),
      projectId: 'test-project',
      overallScore: 80,
      issueCount: 3,
      issues: [
        {
          id: 'issue-1',
          type: 'error',
          severity: 8,
          toolName: 'eslint',
          filePath: 'src/file.ts',
          lineNumber: 10,
          message: 'New error',
          score: 8
        }
      ],
      metrics: { coverage: 90, maintainability: 85, reliability: 80, security: 90 }
    };

    const result = calculateDiff(run1, run2);

    expect(result.differences.addedIssues).toHaveLength(1);
    expect(result.differences.removedIssues).toHaveLength(0);
    expect(result.differences.modifiedIssues).toHaveLength(0);
    expect(result.metricChanges.overallScore).toBe(-20);
    expect(result.trend).toBe('degraded');
  });
});

describe('2.3-UNIT-010: Metric Comparison Logic', () => {
  const calculateMetricComparison = (run1: AnalysisRun, run2: AnalysisRun) => {
    const metrics = ['coverage', 'maintainability', 'reliability', 'security'] as const;

    const roundToTwo = (num: number): number => Math.round(num * 100) / 100;

    return {
      changes: metrics.reduce((acc, metric) => {
        acc[metric] = {
          previous: run1.metrics[metric],
          current: run2.metrics[metric],
          change: run2.metrics[metric] - run1.metrics[metric],
          percentageChange: run1.metrics[metric] !== 0
            ? roundToTwo(((run2.metrics[metric] - run1.metrics[metric]) / run1.metrics[metric]) * 100)
            : 0
        };
        return acc;
      }, {} as Record<string, any>),

      overallScoreChange: run2.overallScore - run1.overallScore,
      overallScorePercentageChange: roundToTwo(((run2.overallScore - run1.overallScore) / run1.overallScore) * 100),

      issueCountChange: run2.issueCount - run1.issueCount,
      issueCountPercentageChange: run1.issueCount !== 0
        ? roundToTwo(((run2.issueCount - run1.issueCount) / run1.issueCount) * 100)
        : 0
    };
  };

  const defaultMetrics = {
    coverage: 80,
    maintainability: 75,
    reliability: 85,
    security: 90
  };

  const generateMockRunWithMetrics = (overallScore: number, metrics: Partial<typeof defaultMetrics>): AnalysisRun => {
    return {
      id: 'test',
      timestamp: new Date(),
      projectId: 'test',
      overallScore,
      issueCount: 10,
      issues: [],
      metrics: { ...defaultMetrics, ...metrics }
    };
  };

  it('should calculate metric changes correctly', () => {
    const run1 = generateMockRunWithMetrics(75, { coverage: 80, maintainability: 70 });
    const run2 = generateMockRunWithMetrics(85, { coverage: 85, maintainability: 75 });

    const comparison = calculateMetricComparison(run1, run2);

    expect(comparison.changes.coverage.change).toBe(5);
    expect(comparison.changes.coverage.percentageChange).toBe(6.25);
    expect(comparison.changes.maintainability.change).toBe(5);
    expect(comparison.changes.maintainability.percentageChange).toBe(7.14);
    expect(comparison.overallScoreChange).toBe(10);
    expect(comparison.overallScorePercentageChange).toBe(13.33);
  });

  it('should handle negative changes', () => {
    const run1 = generateMockRunWithMetrics(85, { coverage: 90, maintainability: 80 });
    const run2 = generateMockRunWithMetrics(75, { coverage: 85, maintainability: 70 });

    const comparison = calculateMetricComparison(run1, run2);

    expect(comparison.changes.coverage.change).toBe(-5);
    expect(comparison.changes.coverage.percentageChange).toBe(-5.56);
    expect(comparison.changes.maintainability.change).toBe(-10);
    expect(comparison.changes.maintainability.percentageChange).toBe(-12.5);
    expect(comparison.overallScoreChange).toBe(-10);
    expect(comparison.overallScorePercentageChange).toBe(-11.76);
  });

  it('should handle zero division safely', () => {
    const run1 = generateMockRunWithMetrics(0, { coverage: 0, maintainability: 0 });
    const run2 = generateMockRunWithMetrics(50, { coverage: 50, maintainability: 50 });

    const comparison = calculateMetricComparison(run1, run2);

    expect(comparison.changes.coverage.change).toBe(50);
    expect(comparison.changes.coverage.percentageChange).toBe(0); // Should handle zero division
    expect(comparison.overallScorePercentageChange).toBe(Infinity); // This is expected for zero base
  });

  it('should provide detailed metric analysis', () => {
    const run1 = generateMockRunWithMetrics(70, {
      coverage: 75,
      maintainability: 80,
      reliability: 65,
      security: 60
    });
    const run2 = generateMockRunWithMetrics(80, {
      coverage: 85,
      maintainability: 75,
      reliability: 70,
      security: 90
    });

    const comparison = calculateMetricComparison(run1, run2);

    // Verify all metrics are calculated
    expect(Object.keys(comparison.changes)).toHaveLength(4);
    expect(comparison.changes.coverage.previous).toBe(75);
    expect(comparison.changes.coverage.current).toBe(85);
    expect(comparison.changes.maintainability.previous).toBe(80);
    expect(comparison.changes.maintainability.current).toBe(75);
    expect(comparison.changes.reliability.previous).toBe(65);
    expect(comparison.changes.reliability.current).toBe(70);
    expect(comparison.changes.security.previous).toBe(60);
    expect(comparison.changes.security.current).toBe(90);
  });
});

describe('2.3-UNIT-011: Trend Analysis Calculations', () => {
  interface TrendData {
    runs: AnalysisRun[];
    trends: {
      overallScore: 'improving' | 'declining' | 'stable';
      issueCount: 'improving' | 'declining' | 'stable';
      metrics: Record<string, 'improving' | 'declining' | 'stable'>;
    };
  }

  const calculateTrendAnalysis = (runs: AnalysisRun[]): TrendData => {
    if (runs.length < 2) {
      return {
        runs,
        trends: {
          overallScore: 'stable',
          issueCount: 'stable',
          metrics: {}
        }
      };
    }

    const calculateTrend = (values: number[]): 'improving' | 'declining' | 'stable' => {
      if (values.length < 2) return 'stable';

      // Calculate linear regression slope
      const n = values.length;
      const x = Array.from({ length: n }, (_, i) => i);
      const y = values;

      const sumX = x.reduce((sum, val) => sum + val, 0);
      const sumY = y.reduce((sum, val) => sum + val, 0);
      const sumXY = x.reduce((sum, val, i) => sum + val * y[i], 0);
      const sumXX = x.reduce((sum, val) => sum + val * val, 0);

      const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);

      if (Math.abs(slope) < 0.1) return 'stable';
      return slope > 0 ? 'improving' : 'declining';
    };

    const overallScores = runs.map(run => run.overallScore);
    const issueCounts = runs.map(run => run.issueCount);

    const metricTrends = {
      coverage: calculateTrend(runs.map(run => run.metrics.coverage)),
      maintainability: calculateTrend(runs.map(run => run.metrics.maintainability)),
      reliability: calculateTrend(runs.map(run => run.metrics.reliability)),
      security: calculateTrend(runs.map(run => run.metrics.security))
    };

    return {
      runs,
      trends: {
        overallScore: calculateTrend(overallScores),
        issueCount: calculateTrend(issueCounts.map(count => -count)), // Invert - fewer issues is better
        metrics: metricTrends
      }
    };
  };

  const generateMockRuns = (count: number, startScore: number, trend: 'improving' | 'declining' | 'stable'): AnalysisRun[] => {
    const runs: AnalysisRun[] = [];

    for (let i = 0; i < count; i++) {
      let score: number;
      if (trend === 'improving') {
        score = startScore + (i * 2);
      } else if (trend === 'declining') {
        score = startScore - (i * 2);
      } else {
        score = startScore + (Math.sin(i * 0.5) * 0.2); // Very small deterministic variations
      }

      const baseIssueCount = 20;
      let issueCount: number;
      if (trend === 'improving') {
        issueCount = Math.max(0, baseIssueCount - i); // Fewer issues over time
      } else if (trend === 'declining') {
        issueCount = baseIssueCount + i; // More issues over time
      } else {
        issueCount = baseIssueCount + Math.floor(Math.sin(i * 0.3) * 1); // Stable with very small deterministic variations
      }

      runs.push({
        id: `run-${i + 1}`,
        timestamp: new Date(`2025-01-${(i + 1).toString().padStart(2, '0')}`),
        projectId: 'test-project',
        overallScore: Math.max(0, Math.min(100, score)),
        issueCount,
        issues: [],
        metrics: {
          coverage: Math.max(0, Math.min(100, 80 + (trend === 'improving' ? i * 1 : trend === 'declining' ? -i * 1 : Math.sin(i * 0.4) * 0.5))),
          maintainability: Math.max(0, Math.min(100, 75 + (trend === 'improving' ? i * 1.5 : trend === 'declining' ? -i * 1.5 : Math.sin(i * 0.3) * 0.5))),
          reliability: Math.max(0, Math.min(100, 85 + (trend === 'improving' ? i * 0.5 : trend === 'declining' ? -i * 0.5 : Math.sin(i * 0.6) * 0.3))),
          security: Math.max(0, Math.min(100, 90 + (trend === 'improving' ? i * 0.3 : trend === 'declining' ? -i * 0.3 : Math.sin(i * 0.2) * 0.2)))
        }
      });
    }

    return runs;
  };

  it('should detect improving trend', () => {
    const runs = generateMockRuns(10, 70, 'improving');
    const trendData = calculateTrendAnalysis(runs);

    expect(trendData.trends.overallScore).toBe('improving');
    expect(trendData.trends.issueCount).toBe('improving'); // Fewer issues is better
    expect(trendData.trends.metrics.coverage).toBe('improving');
    expect(trendData.trends.metrics.maintainability).toBe('improving');
  });

  it('should detect declining trend', () => {
    const runs = generateMockRuns(10, 80, 'declining');
    const trendData = calculateTrendAnalysis(runs);

    expect(trendData.trends.overallScore).toBe('declining');
    expect(trendData.trends.issueCount).toBe('declining'); // More issues is worse
    expect(trendData.trends.metrics.coverage).toBe('declining');
    expect(trendData.trends.metrics.maintainability).toBe('declining');
  });

  it('should detect stable trend', () => {
    const runs = generateMockRuns(10, 75, 'stable');
    const trendData = calculateTrendAnalysis(runs);

    expect(trendData.trends.overallScore).toBe('stable');
    expect(trendData.trends.issueCount).toBe('stable');
  });

  it('should handle insufficient data', () => {
    const singleRun = generateMockRuns(1, 75, 'stable');
    const trendData = calculateTrendAnalysis(singleRun);

    expect(trendData.trends.overallScore).toBe('stable');
    expect(trendData.trends.issueCount).toBe('stable');
    expect(Object.keys(trendData.trends.metrics)).toHaveLength(0);
  });

  it('should calculate mixed trends correctly', () => {
    // Create runs with different trends for different metrics
    const runs: AnalysisRun[] = [
      {
        id: 'run-1',
        timestamp: new Date('2025-01-01'),
        projectId: 'test',
        overallScore: 70,
        issueCount: 20,
        issues: [],
        metrics: { coverage: 80, maintainability: 60, reliability: 85, security: 90 }
      },
      {
        id: 'run-2',
        timestamp: new Date('2025-01-02'),
        projectId: 'test',
        overallScore: 75,
        issueCount: 18,
        issues: [],
        metrics: { coverage: 82, maintainability: 65, reliability: 83, security: 88 }
      },
      {
        id: 'run-3',
        timestamp: new Date('2025-01-03'),
        projectId: 'test',
        overallScore: 80,
        issueCount: 15,
        issues: [],
        metrics: { coverage: 85, maintainability: 70, reliability: 80, security: 85 }
      }
    ];

    const trendData = calculateTrendAnalysis(runs);

    expect(trendData.trends.overallScore).toBe('improving');
    expect(trendData.trends.issueCount).toBe('improving');
    expect(trendData.trends.metrics.coverage).toBe('improving');
    expect(trendData.trends.metrics.maintainability).toBe('improving');
    expect(trendData.trends.metrics.reliability).toBe('declining');
    expect(trendData.trends.metrics.security).toBe('declining');
  });
});

/**
 * Breadcrumb Navigation Component Tests
 */

import { describe, it, expect, jest } from 'bun:test';
import React from 'react';
import { render } from 'ink-testing-library';
import { BreadcrumbNavigation } from '../../../src/components/dashboard/breadcrumb-navigation';
import type { NavigationBreadcrumb } from '../../../src/types/dashboard';

describe('BreadcrumbNavigation', () => {
  const mockBreadcrumbs: NavigationBreadcrumb[] = [
    {
      id: '1',
      label: 'Dashboard',
      view: 'dashboard',
    },
    {
      id: '2',
      label: 'Issues',
      view: 'issue-list',
    },
    {
      id: '3',
      label: 'Issue Details',
      view: 'issue-details',
    },
  ];

  it('should display all breadcrumbs', () => {
    const { lastFrame } = render(<BreadcrumbNavigation breadcrumbs={mockBreadcrumbs} />);

    expect(lastFrame()).toContain('Dashboard');
    expect(lastFrame()).toContain('Issues');
    expect(lastFrame()).toContain('Issue Details');
  });

  it('should show separators when enabled', () => {
    const { lastFrame } = render(
      <BreadcrumbNavigation breadcrumbs={mockBreadcrumbs} showSeparator={true} />
    );

    expect(lastFrame()).toContain('›');
  });

  it('should not show separators when disabled', () => {
    const { lastFrame } = render(
      <BreadcrumbNavigation breadcrumbs={mockBreadcrumbs} showSeparator={false} />
    );

    expect(lastFrame()).not.toContain('›');
  });

  it('should limit breadcrumbs to maxItems', () => {
    const manyBreadcrumbs: NavigationBreadcrumb[] = [
      ...mockBreadcrumbs,
      {
        id: '4',
        label: 'Additional View',
        view: 'trends',
      },
      {
        id: '5',
        label: 'Another View',
        view: 'comparison',
      },
    ];

    const { lastFrame } = render(
      <BreadcrumbNavigation breadcrumbs={manyBreadcrumbs} maxItems={3} />
    );

    expect(lastFrame()).toContain('...');
    expect(lastFrame()).toContain('Another View');
  });

  it('should handle empty breadcrumb list', () => {
    const { lastFrame } = render(<BreadcrumbNavigation breadcrumbs={[]} />);

    expect(lastFrame()).toBe('');
  });

  it('should truncate long labels', () => {
    const longBreadcrumbs: NavigationBreadcrumb[] = [
      {
        id: '1',
        label: 'This is a very long breadcrumb label that should be truncated',
        view: 'dashboard',
      },
    ];

    const { lastFrame } = render(<BreadcrumbNavigation breadcrumbs={longBreadcrumbs} />);

    expect(lastFrame()).toContain('...');
    expect(lastFrame()).not.toContain('very long breadcrumb label');
  });

  it('should handle breadcrumb selection', () => {
    const onSelect = jest.fn();
    const { lastFrame } = render(
      <BreadcrumbNavigation breadcrumbs={mockBreadcrumbs} onSelect={onSelect} />
    );

    expect(lastFrame()).toContain('Use arrow keys to select, Enter to navigate');
  });

  it('should not show navigation help when no onSelect provided', () => {
    const { lastFrame } = render(<BreadcrumbNavigation breadcrumbs={mockBreadcrumbs} />);

    expect(lastFrame()).not.toContain('Use arrow keys to select, Enter to navigate');
  });

  it('should handle keyboard navigation', () => {
    const onSelect = jest.fn();
    const { stdin } = render(
      <BreadcrumbNavigation breadcrumbs={mockBreadcrumbs} onSelect={onSelect} />
    );

    // Simulate right arrow key
    stdin.write('\u001B[C');

    // Simulate Enter key
    stdin.write('\r');

    // Verify selection is handled (implementation details depend on component logic)
    expect(onSelect).toBeDefined();
  });
});

