  it('should render comparison summary header', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Overview');
    expect(output).toContain('v1.0.0');
    expect(output).toContain('v1.1.0');
  });

  it('should display key metrics correctly', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Total Issues');
    expect(output).toContain('10');
    expect(output).toContain('8');
    expect(output).toContain('Critical Issues');
    expect(output).toContain('3');
    expect(output).toContain('2');
    expect(output).toContain('Quality Score');
    expect(output).toContain('75');
    expect(output).toContain('80');
  });

  it('should show issues changes', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Issues Changes');
    expect(output).toContain('New Issues:');
    expect(output).toContain('+1');
    expect(output).toContain('Resolved Issues:');
    expect(output).toContain('-3');
    expect(output).toContain('Unchanged Issues:');
    expect(output).toContain('5');
  });

  it('should display severity breakdown', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Severity Breakdown');
    expect(output).toContain('ERROR:');
    expect(output).toContain('3');
    expect(output).toContain('2');
    expect(output).toContain('WARNING:');
    expect(output).toContain('INFO:');
  });

  it('should show overall status with improvement rate', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Overall Status');
    expect(output).toContain('Improvement Rate: 20.00%');
    expect(output).toContain('Significant Improvement');
  });

  it('should display tool analysis', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Tool Analysis');
    expect(output).toContain('eslint:');
    expect(output).toContain('typescript:');
  });

  it('should handle negative improvement rate', () => {
    const negativeComparison = {
      ...mockComparison,
      summary: {
        ...mockComparison.summary,
        improvementRate: -15,
      },
    };

    const { lastFrame } = render(<ComparisonSummary comparison={negativeComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Significant Degradation');
    expect(output).toContain('Improvement Rate: -15.00%');
  });

  it('should show trend indicators correctly', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('📉'); // Down trend for total issues
    expect(output).toContain('📈'); // Up trend for score
  });

  it('should display relative time information', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('1/1/2025');
    expect(output).toContain('1/2/2025');
  });

  it('should show descriptive status messages', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('🟢 Good progress!');
    expect(output).toContain('3 issues resolved');
    expect(output).toContain('1 new issues introduced');
  });

  it('should handle comparison without version numbers', () => {
    const noVersionComparison = {
      ...mockComparison,
      baseline: { ...mockComparison.baseline, version: undefined },
      comparison: { ...mockComparison.comparison, version: undefined },
    };

    const { lastFrame } = render(<ComparisonSummary comparison={noVersionComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('baseline'); // Shows first 8 chars of ID
    expect(output).toContain('comparis'); // Shows first 8 chars of ID
    expect(output).not.toContain('v1.0.0');
  });

  it('should not display category trends (not implemented in this component)', () => {
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).not.toContain('Security:');
    expect(output).not.toContain('Performance:');
    expect(output).not.toContain('Maintainability:');
  });

  it('should show appropriate colors for different trend types', () => {
    // This test checks that the component includes trend indicators
    const { lastFrame } = render(<ComparisonSummary comparison={mockComparison} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    // The component should show some form of trend indication
    expect(output).toContain('10             →  8'); // Total issues trend
  });
});

/**
 * Dashboard Navigator Component Tests
 */

import { describe, it, expect, jest } from 'bun:test';
import React from 'react';
import { render } from 'ink-testing-library';
import { DashboardNavigator } from '../../../src/components/dashboard/dashboard-navigator';
import type { DashboardView } from '../../../src/types/dashboard';

describe('DashboardNavigator', () => {
  const mockNavigate = jest.fn();
  const mockGoBack = jest.fn();

  it('should display current view information', () => {
    const { lastFrame } = render(
      <DashboardNavigator currentView="dashboard" onNavigate={mockNavigate} onGoBack={mockGoBack} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, ''); // Remove ANSI color codes
    expect(output).toContain('Navigator');
    expect(output).toContain('Current: Dashboard Overview');
  });

  it('should show navigation shortcuts', () => {
    const { lastFrame } = render(
      <DashboardNavigator currentView="dashboard" onNavigate={mockNavigate} onGoBack={mockGoBack} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, ''); // Remove ANSI color codes
    expect(output).toContain('Quick Nav:');
    expect(output).toContain('[Ctrl+D] Dashboard');
    expect(output).toContain('[Ctrl+I] Issues');
  });

  it('should show path as root when no navigation history', () => {
    const { lastFrame } = render(
      <DashboardNavigator currentView="dashboard" onNavigate={mockNavigate} onGoBack={mockGoBack} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, ''); // Remove ANSI color codes
    expect(output).toContain('Path: Root');
  });

  it('should show back navigation when available', () => {
    const { lastFrame } = render(
      <DashboardNavigator
        currentView="issue-details"
        onNavigate={mockNavigate}
        onGoBack={mockGoBack}
      />
    );

    expect(lastFrame()).toContain('[Esc] Back');
  });

  it('should handle available views', () => {
    const customViews: DashboardView[] = ['dashboard', 'issue-list'];
    const { lastFrame } = render(
      <DashboardNavigator
        currentView="dashboard"
        onNavigate={mockNavigate}
        onGoBack={mockGoBack}
        availableViews={customViews}
      />
    );

    // Should not crash and still show basic navigation
    expect(lastFrame()).toContain('Navigator');
  });

  it('should render keyboard shortcuts', () => {
    const { lastFrame } = render(
      <DashboardNavigator currentView="dashboard" onNavigate={mockNavigate} onGoBack={mockGoBack} />
    );

    expect(lastFrame()).toContain('[Ctrl+D]');
    expect(lastFrame()).toContain('[Ctrl+I]');
    expect(lastFrame()).toContain('[Ctrl+C]');
    expect(lastFrame()).toContain('[Ctrl+T]');
  });

  it('should show back navigation when available', () => {
    const { lastFrame } = render(
      <DashboardNavigator
        currentView="issue-details"
        onNavigate={mockNavigate}
        onGoBack={mockGoBack}
      />
    );

    expect(lastFrame()).toContain('[Esc] Back');
  });
});

/**
 * Unit tests for BaseWidget component
 */

import { render } from 'ink-testing-library';
import { Box, Text } from 'ink';
import { describe, it, expect, vi } from 'vitest';
import { BaseWidget } from '../../../../src/components/dashboard/base-widget';
import type { WidgetConfig } from '../../../../src/types/dashboard';

describe('BaseWidget', () => {
  const mockConfig: WidgetConfig = {
    id: 'test-widget',
    type: 'summary',
    position: { x: 0, y: 0, width: 50, height: 15 },
    config: {},
    visible: true,
  };

  const mockOnSelect = vi.fn();
  const mockOnUpdate = vi.fn();
  const mockChildren = <Text>Test Content</Text>;

  it('should render widget with correct properties', () => {
    const { lastFrame } = render(
      <BaseWidget
        config={mockConfig}
        isSelected={false}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    expect(lastFrame()).toContain('SUMMARY');
    expect(lastFrame()).toContain('50×15');
    expect(lastFrame()).toContain('Test Content');
  });

  it('should render selected widget with double border', () => {
    const { lastFrame } = render(
      <BaseWidget
        config={mockConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    expect(lastFrame()).toContain('SUMMARY');
    expect(lastFrame()).toContain('Ctrl+R:Resize Ctrl+M:Move Ctrl+H:Hide +/-:Size');
  });

  it('should not render widget when visible is false', () => {
    const invisibleConfig = { ...mockConfig, visible: false };
    const { lastFrame } = render(
      <BaseWidget
        config={invisibleConfig}
        isSelected={false}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    expect(lastFrame()).toBe('');
  });

  it('should handle resize functionality', () => {
    const { stdin } = render(
      <BaseWidget
        config={mockConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    // Simulate Ctrl+R for resize
    stdin.write('\x12'); // Ctrl+R
    stdin.write('r');
    stdin.write('\x0d'); // Enter to confirm

    // Should call onUpdate with new size
    expect(mockOnUpdate).toHaveBeenCalledWith(
      mockConfig.id,
      expect.objectContaining({
        position: expect.objectContaining({
          width: expect.any(Number),
          height: expect.any(Number),
        }),
      })
    );
  });

  it('should handle move functionality', () => {
    const { stdin } = render(
      <BaseWidget
        config={mockConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    // Simulate Ctrl+M for move
    stdin.write('\x0d'); // Ctrl+M
    stdin.write('m');
    stdin.write('\x0d'); // Enter to confirm

    // Should call onUpdate with new position
    expect(mockOnUpdate).toHaveBeenCalledWith(
      mockConfig.id,
      expect.objectContaining({
        position: expect.objectContaining({
          x: expect.any(Number),
          y: expect.any(Number),
        }),
      })
    );
  });

  it('should handle toggle visibility functionality', () => {
    const { stdin } = render(
      <BaseWidget
        config={mockConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    // Simulate Ctrl+H for hide
    stdin.write('\x08'); // Ctrl+H
    stdin.write('h');

    // Should call onUpdate with visibility toggled
    expect(mockOnUpdate).toHaveBeenCalledWith(
      mockConfig.id,
      expect.objectContaining({
        position: expect.objectContaining({
          width: 40,
          height: 10,
          x: 0,
          y: 0,
        }),
      })
    );
  });

  it('should handle increase size functionality', () => {
    const { stdin } = render(
      <BaseWidget
        config={mockConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    // Simulate Ctrl++ for increase size
    stdin.write('\x2b'); // Ctrl++
    stdin.write('+');

    // Should call onUpdate with increased size
    expect(mockOnUpdate).toHaveBeenCalledWith(
      mockConfig.id,
      expect.objectContaining({
        position: expect.objectContaining({
          width: 40,
          height: 10,
          x: 0,
          y: 0,
        }),
      })
    );
  });

  it('should handle decrease size functionality', () => {
    const { stdin } = render(
      <BaseWidget
        config={mockConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    // Simulate Ctrl+- for decrease size
    stdin.write('\x2d'); // Ctrl+-
    stdin.write('-');

    // Should call onUpdate with decreased size
    expect(mockOnUpdate).toHaveBeenCalledWith(
      mockConfig.id,
      expect.objectContaining({
        position: expect.objectContaining({
          width: expect.any(Number),
          height: expect.any(Number),
        }),
      })
    );
  });

  it('should respect minimum size constraints', () => {
    const smallConfig = {
      ...mockConfig,
      position: { x: 0, y: 0, width: 20, height: 5 },
    };

    const { stdin } = render(
      <BaseWidget
        config={smallConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    // Simulate Ctrl+- for decrease size
    stdin.write('\x2d'); // Ctrl+-
    stdin.write('-');

    // Should call onUpdate with size at minimum
    expect(mockOnUpdate).toHaveBeenCalledWith(
      smallConfig.id,
      expect.objectContaining({
        position: expect.objectContaining({
          width: expect.any(Number),
          height: expect.any(Number),
        }),
      })
    );
  });

  it('should respect maximum size constraints', () => {
    const largeConfig = {
      ...mockConfig,
      position: { x: 0, y: 0, width: 120, height: 30 },
    };

    const { stdin } = render(
      <BaseWidget
        config={largeConfig}
        isSelected={true}
        onSelect={mockOnSelect}
        onUpdate={mockOnUpdate}
      >
        {mockChildren}
      </BaseWidget>
    );

    // Simulate Ctrl++ for increase size
    stdin.write('\x2b'); // Ctrl++
    stdin.write('+');

    // Should call onUpdate with size at maximum
    expect(mockOnUpdate).toHaveBeenCalledWith(
      largeConfig.id,
      expect.objectContaining({
        position: expect.objectContaining({
          width: expect.any(Number),
          height: expect.any(Number),
        }),
      })
    );
  });
});

/**
 * Unit tests for WidgetRegistry component
 */

import { render } from 'ink-testing-library';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { WidgetRegistry } from '../../../../src/components/dashboard/widget-registry';
import type { WidgetConfig } from '../../../../src/types/dashboard';

describe('WidgetRegistry', () => {
  beforeEach(() => {
    // Reset the registry before each test
    WidgetRegistry.getAllRegistrations().forEach(reg => {
      // Note: We can't directly unregister widgets in the current implementation
      // This is a limitation that could be addressed in a future iteration
    });
  });

  describe('Registration', () => {
    it('should register built-in widget types', () => {
      const registrations = WidgetRegistry.getAllRegistrations();
      const widgetTypes = registrations.map(reg => reg.type);

      expect(widgetTypes).toContain('summary');
      expect(widgetTypes).toContain('issues');
      expect(widgetTypes).toContain('coverage');
      expect(widgetTypes).toContain('trends');
    });

    it('should get registration by type', () => {
      const summaryReg = WidgetRegistry.getRegistration('summary');

      expect(summaryReg).toBeDefined();
      expect(summaryReg?.name).toBe('Summary');
      expect(summaryReg?.description).toBe('Overall metrics and key insights');
    });

    it('should return undefined for unknown widget type', () => {
      const unknownReg = WidgetRegistry.getRegistration('unknown');

      expect(unknownReg).toBeUndefined();
    });

    it('should get available widget types for user selection', () => {
      const availableTypes = WidgetRegistry.getAvailableWidgetTypes();

      expect(availableTypes).toHaveLength(4);
      expect(availableTypes.some(type => type.name === 'Summary')).toBe(true);
      expect(availableTypes.some(type => type.name === 'Issues')).toBe(true);
      expect(availableTypes.some(type => type.name === 'Coverage')).toBe(true);
      expect(availableTypes.some(type => type.name === 'Trends')).toBe(true);
    });
  });

  describe('Widget Creation', () => {
    const mockConfig: WidgetConfig = {
      id: 'test-widget',
      type: 'summary',
      position: { x: 0, y: 0, width: 50, height: 15 },
      config: {},
      visible: true,
    };

    const mockOnSelect = vi.fn();
    const mockOnUpdate = vi.fn();

    it('should create widget for known type', () => {
      const widget = WidgetRegistry.createWidget(
        mockConfig,
        false,
        mockOnSelect,
        mockOnUpdate
      );

      expect(widget).toBeDefined();
    });

    it('should return null for unknown widget type', () => {
      const unknownConfig = { ...mockConfig, type: 'unknown' as WidgetConfig['type'] };
      const widget = WidgetRegistry.createWidget(
        unknownConfig,
        false,
        mockOnSelect,
        mockOnUpdate
      );

      expect(widget).toBeNull();
    });

    it('should pass props correctly to widget factory', () => {
      const selectedConfig = { ...mockConfig, id: 'selected-widget' };
      const widget = WidgetRegistry.createWidget(
        selectedConfig,
        true,
        mockOnSelect,
        mockOnUpdate
      );

      expect(widget).toBeDefined();
      // The widget should be rendered with selected state
    });
  });

  describe('Default Configuration', () => {
    it('should get default config for known widget type', () => {
      const defaultConfig = WidgetRegistry.getDefaultConfig('summary');

      expect(defaultConfig).toBeDefined();
      expect(defaultConfig?.type).toBe('summary');
      expect(defaultConfig?.position).toEqual(
        expect.objectContaining({
          x: expect.any(Number),
          y: expect.any(Number),
          width: expect.any(Number),
          height: expect.any(Number),
        })
      );
      expect(defaultConfig?.visible).toBe(true);
    });

    it('should apply overrides to default config', () => {
      const overrides = {
        position: { x: 10, y: 20, width: 60, height: 25 },
        config: { customOption: true },
      };

      const defaultConfig = WidgetRegistry.getDefaultConfig('summary', overrides);

      expect(defaultConfig?.position).toEqual(overrides.position);
      expect(defaultConfig?.config).toEqual(overrides.config);
    });

    it('should return null for unknown widget type', () => {
      const defaultConfig = WidgetRegistry.getDefaultConfig('unknown');

      expect(defaultConfig).toBeNull();
    });
  });

  describe('Configuration Validation', () => {
    it('should validate correct widget configuration', () => {
      const validConfig: WidgetConfig = {
        id: 'valid-widget',
        type: 'summary',
        position: { x: 0, y: 0, width: 50, height: 15 },
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(validConfig);

      expect(validation.isValid).toBe(true);
      expect(validation.errors).toHaveLength(0);
    });

    it('should reject configuration for unknown widget type', () => {
      const invalidConfig = {
        id: 'invalid-widget',
        type: 'unknown' as WidgetConfig['type'],
        position: { x: 0, y: 0, width: 50, height: 15 },
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(invalidConfig);

      expect(validation.isValid).toBe(false);
      expect(validation.errors).toContain('Unknown widget type: unknown');
    });

    it('should reject configuration with width below minimum', () => {
      const invalidConfig: WidgetConfig = {
        id: 'invalid-widget',
        type: 'summary',
        position: { x: 0, y: 0, width: 20, height: 15 }, // Below min width of 30
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(invalidConfig);

      expect(validation.isValid).toBe(false);
      expect(validation.errors.some(error => error.includes('Width must be at least'))).toBe(true);
    });

    it('should reject configuration with height below minimum', () => {
      const invalidConfig: WidgetConfig = {
        id: 'invalid-widget',
        type: 'summary',
        position: { x: 0, y: 0, width: 50, height: 5 }, // Below min height of 8
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(invalidConfig);

      expect(validation.isValid).toBe(false);
      expect(validation.errors.some(error => error.includes('Height must be at least'))).toBe(true);
    });

    it('should reject configuration with width above maximum', () => {
      const invalidConfig: WidgetConfig = {
        id: 'invalid-widget',
        type: 'summary',
        position: { x: 0, y: 0, width: 150, height: 15 }, // Above max width of 120
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(invalidConfig);

      expect(validation.isValid).toBe(false);
      expect(validation.errors.some(error => error.includes('Width must not exceed'))).toBe(true);
    });

    it('should reject configuration with height above maximum', () => {
      const invalidConfig: WidgetConfig = {
        id: 'invalid-widget',
        type: 'summary',
        position: { x: 0, y: 0, width: 50, height: 30 }, // Above max height of 20
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(invalidConfig);

      expect(validation.isValid).toBe(false);
      expect(validation.errors.some(error => error.includes('Height must not exceed'))).toBe(true);
    });

    it('should reject configuration with negative coordinates', () => {
      const invalidConfig: WidgetConfig = {
        id: 'invalid-widget',
        type: 'summary',
        position: { x: -1, y: 0, width: 50, height: 15 },
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(invalidConfig);

      expect(validation.isValid).toBe(false);
      expect(validation.errors.some(error => error.includes('X position cannot be negative'))).toBe(true);
    });

    it('should reject configuration with negative Y coordinate', () => {
      const invalidConfig: WidgetConfig = {
        id: 'invalid-widget',
        type: 'summary',
        position: { x: 0, y: -1, width: 50, height: 15 },
        config: {},
        visible: true,
      };

      const validation = WidgetRegistry.validateConfig(invalidConfig);

      expect(validation.isValid).toBe(false);
      expect(validation.errors.some(error => error.includes('Y position cannot be negative'))).toBe(true);
    });
  });

  describe('Widget Rendering', () => {
    it('should render summary widget correctly', () => {
      const config = WidgetRegistry.getDefaultConfig('summary');
      if (!config) return;

      const { lastFrame } = render(
        WidgetRegistry.createWidget(config, false, vi.fn(), vi.fn())!
      );

      expect(lastFrame()).toContain('Summary Widget');
      expect(lastFrame()).toContain('Overall metrics and key insights');
    });

    it('should render issues widget correctly', () => {
      const config = WidgetRegistry.getDefaultConfig('issues');
      if (!config) return;

      const { lastFrame } = render(
        WidgetRegistry.createWidget(config, false, vi.fn(), vi.fn())!
      );

      expect(lastFrame()).toContain('Issues Widget');
      expect(lastFrame()).toContain('Top issues and filtering options');
    });

    it('should render coverage widget correctly', () => {
      const config = WidgetRegistry.getDefaultConfig('coverage');
      if (!config) return;

      const { lastFrame } = render(
        WidgetRegistry.createWidget(config, false, vi.fn(), vi.fn())!
      );

      expect(lastFrame()).toContain('Coverage Widget');
      expect(lastFrame()).toContain('Code coverage visualization');
    });

    it('should render trends widget correctly', () => {
      const config = WidgetRegistry.getDefaultConfig('trends');
      if (!config) return;

      const { lastFrame } = render(
        WidgetRegistry.createWidget(config, false, vi.fn(), vi.fn())!
      );

      expect(lastFrame()).toContain('Trends Widget');
      expect(lastFrame()).toContain('Historical trend charts');
    });
  });
});

