/**
 * Trend Chart Component Tests
 */

import { describe, it, expect, jest } from 'bun:test';
import React from 'react';
import { render } from 'ink-testing-library';
import { TrendChart } from '../../../src/components/dashboard/trend-chart';

describe('TrendChart', () => {
  const mockTrends = {
    severity: [
      { type: 'error', baseline: 3, comparison: 2, diff: -1, trend: 'down' as const },
      { type: 'warning', baseline: 4, comparison: 4, diff: 0, trend: 'stable' as const },
      { type: 'info', baseline: 3, comparison: 2, diff: -1, trend: 'down' as const },
    ],
    tools: [
      { tool: 'eslint', baseline: 6, comparison: 5, diff: -1, trend: 'down' as const },
      { tool: 'typescript', baseline: 4, comparison: 3, diff: -1, trend: 'down' as const },
    ],
    categories: [
      { category: 'security', baseline: 2, comparison: 1, diff: -1, trend: 'down' as const },
      { category: 'performance', baseline: 3, comparison: 3, diff: 0, trend: 'stable' as const },
      { category: 'maintainability', baseline: 5, comparison: 4, diff: -1, trend: 'down' as const },
    ],
  };

  it('should render trend charts when enabled', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Severity Trends');
    expect(output).toContain('Tool Trends');
    expect(output).toContain('Category Trends');
  });

  it('should show disabled message when charts are disabled', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={false} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Charts are disabled');
    expect(output).toContain('Enable them with [C] key');
  });

  it('should display severity data correctly', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={false} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('error');
    expect(output).toContain('warning');
    expect(output).toContain('info');
  });

  it('should display tool data correctly', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={false} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('eslint');
    expect(output).toContain('typescript');
  });

  it('should display category data correctly', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={false} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('security');
    expect(output).toContain('performance');
    expect(output).toContain('maintainabil'); // Wrapped at 12 chars
  });

  it('should show diff details when enabled', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Type');
    expect(output).toContain('Values');
    expect(output).toContain('Change');
    expect(output).toContain('3 → 2');
    expect(output).toContain('-1');
  });

  it('should hide diff details when disabled', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={false} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).not.toContain('Type');
    expect(output).not.toContain('Values');
    expect(output).not.toContain('Change');
  });

  it('should display sparkline visualizations', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    // Sparklines use special Unicode characters
    expect(output).toMatch(/[▁▂▃▄▅▆▇█]/);
  });

  it('should show trend indicators', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('📉'); // Down trend
    expect(output).toContain('➡️'); // Stable trend
  });

  it('should display legend', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('█ Baseline');
    expect(output).toContain('░ Comparison');
    expect(output).toContain('📈 Up');
    expect(output).toContain('📉 Down');
    expect(output).toContain('➡️ Stable');
  });

  it('should show keyboard shortcuts', () => {
    const { lastFrame } = render(
      <TrendChart trends={mockTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('[C] Toggle Charts');
    expect(output).toContain('[D] Toggle Details');
  });

  it('should handle empty trends data', () => {
    const emptyTrends = {
      severity: [],
      tools: [],
      categories: [],
    };

    const { lastFrame } = render(
      <TrendChart trends={emptyTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('Severity Trends');
    expect(output).toContain('Tool Trends');
    expect(output).toContain('Category Trends');
  });

  it('should handle single trend data points', () => {
    const singleTrend = {
      severity: [{ type: 'error', baseline: 5, comparison: 5, diff: 0, trend: 'stable' as const }],
      tools: [{ tool: 'eslint', baseline: 5, comparison: 5, diff: 0, trend: 'stable' as const }],
      categories: [
        { category: 'security', baseline: 5, comparison: 5, diff: 0, trend: 'stable' as const },
      ],
    };

    const { lastFrame } = render(
      <TrendChart trends={singleTrend} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('error');
    expect(output).toContain('eslint');
    expect(output).toContain('security');
  });

  it('should handle increasing trends correctly', () => {
    const increasingTrends = {
      severity: [{ type: 'error', baseline: 2, comparison: 5, diff: 3, trend: 'up' as const }],
      tools: [],
      categories: [],
    };

    const { lastFrame } = render(
      <TrendChart trends={increasingTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('2 → 5');
    expect(output).toContain('+3');
    expect(output).toContain('📈');
  });

  it('should handle large values correctly', () => {
    const largeTrends = {
      severity: [
        { type: 'error', baseline: 100, comparison: 200, diff: 100, trend: 'up' as const },
      ],
      tools: [],
      categories: [],
    };

    const { lastFrame } = render(
      <TrendChart trends={largeTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('100 → 200');
    expect(output).toContain('+100');
  });

  it('should handle zero values correctly', () => {
    const zeroTrends = {
      severity: [{ type: 'error', baseline: 0, comparison: 0, diff: 0, trend: 'stable' as const }],
      tools: [],
      categories: [],
    };

    const { lastFrame } = render(
      <TrendChart trends={zeroTrends} showCharts={true} showDiffs={true} />
    );

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, '');
    expect(output).toContain('0 → 0');
    expect(output).toContain('➡️ 0'); // Zero values don't show +0
  });
});

/**
 * Triage Suggestion Component Tests
 */

import { describe, it, expect, jest } from 'bun:test';
import React from 'react';
import { render } from 'ink-testing-library';
import { TriageSuggestion } from '../../../src/components/dashboard/triage-suggestion';

describe('TriageSuggestion', () => {
  const mockSuggestion = {
    action: 'fix-now' as const,
    priority: 9,
    estimatedEffort: 4,
    assignee: 'john.doe@example.com',
    deadline: new Date('2025-01-15'),
    reasoning: 'Critical security vulnerability detected in authentication module',
    confidence: 0.95,
  };

  it('should display triage suggestion details', () => {
    const { lastFrame } = render(<TriageSuggestion suggestion={mockSuggestion} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, ''); // Remove ANSI color codes
    expect(output).toContain('FIX-NOW');
    expect(output).toContain('Priority: 9/10');
    expect(output).toContain(
      'Reasoning: Critical security vulnerability detected in authentication module'
    );
    expect(output).toContain('Effort: 4h');
    expect(output).toContain('Confidence: 95%');
    expect(output).toContain('Assignee: john.doe@example.com');
    expect(output).toContain('Deadline: 1/15/2025');
  });

  it('should display suggestion without optional fields', () => {
    const minimalSuggestion = {
      action: 'schedule' as const,
      priority: 5,
      estimatedEffort: 2,
      reasoning: 'Minor performance improvement needed',
      confidence: 0.7,
    };

    const { lastFrame } = render(<TriageSuggestion suggestion={minimalSuggestion} />);

    const output = lastFrame().replace(/\x1b\[[0-9;]*m/g, ''); // Remove ANSI color codes
    expect(output).toContain('SCHEDULE');
    expect(output).toContain('Priority: 5/10');
    expect(output).toContain('Effort: 2h');
    expect(output).toContain('Confidence: 70%'); // Use stripped output
    expect(output).not.toContain('Assignee:');
    expect(output).not.toContain('Deadline:');
  });

  it('should display interactive mode with actions', () => {
    const { lastFrame } = render(
      <TriageSuggestion
        suggestion={mockSuggestion}
        interactive={true}
        onAccept={jest.fn()}
        onReject={jest.fn()}
      />
    );

    expect(lastFrame()).toContain('[ACCEPT]');
    expect(lastFrame()).toContain('[REJECT]');
    expect(lastFrame()).toContain('(Use arrow keys and Enter to select)');
  });

  it('should not show interactive controls when not interactive', () => {
    const { lastFrame } = render(
      <TriageSuggestion suggestion={mockSuggestion} interactive={false} />
    );

    expect(lastFrame()).not.toContain('[ACCEPT]');
    expect(lastFrame()).not.toContain('[REJECT]');
    expect(lastFrame()).not.toContain('(Use arrow keys and Enter to select)');
  });

  it('should handle different action types', () => {
    const monitorSuggestion = {
      ...mockSuggestion,
      action: 'monitor' as const,
    };

    const { lastFrame } = render(<TriageSuggestion suggestion={monitorSuggestion} />);

    expect(lastFrame()).toContain('MONITOR');
  });
});

/**
 * Virtualized Navigator List Component Tests
 */

import { describe, it, expect, jest } from 'bun:test';
import React from 'react';
import { Text } from 'ink';
import { render } from 'ink-testing-library';
import { VirtualizedNavigatorList } from '../../../src/components/dashboard/virtualized-navigator-list';
import type { Issue } from '../../../src/types/analysis';
import type { IssueWithPriority } from '../../../src/types/dashboard';

describe('VirtualizedNavigatorList', () => {
  const mockIssues: Issue[] = [
    {
      id: '1',
      type: 'error',
      toolName: 'eslint',
      filePath: '/src/components/Button.tsx',
      lineNumber: 23,
      message: 'Missing semicolon',
      ruleId: 'semi',
      fixable: true,
      score: 5,
    },
    {
      id: '2',
      type: 'warning',
      toolName: 'typescript',
      filePath: '/src/utils/helpers.ts',
      lineNumber: 45,
      message: 'Unused variable',
      ruleId: 'no-unused-vars',
      fixable: false,
      score: 3,
    },
    {
      id: '3',
      type: 'info',
      toolName: 'prettier',
      filePath: '/src/services/api.ts',
      lineNumber: 67,
      message: 'Format issue',
      fixable: true,
      score: 2,
    },
  ];

  const mockPriorityIssues: IssueWithPriority[] = [
    {
      ...mockIssues[0],
      priorityScore: 7.5,
      priorityLevel: 'high',
      priority: {
        id: 'p1',
        issueId: '1',
        severity: 8,
        impact: 7,
        effort: 3,
        businessValue: 9,
        finalScore: 7.5,
        context: {} as any,
        classification: {} as any,
        triageSuggestion: {} as any,
        scoringFactors: {} as any,
        metadata: {} as any,
      },
    },
    {
      ...mockIssues[1],
      priorityScore: 4.2,
      priorityLevel: 'medium',
      priority: {
        id: 'p2',
        issueId: '2',
        severity: 5,
        impact: 4,
        effort: 3,
        businessValue: 6,
        finalScore: 4.2,
        context: {} as any,
        classification: {} as any,
        triageSuggestion: {} as any,
        scoringFactors: {} as any,
        metadata: {} as any,
      },
    },
  ];

  const mockOnSelect = jest.fn();

  it('should render virtualized list', () => {
    const { lastFrame } = render(
      <VirtualizedNavigatorList items={mockIssues} selectedIndex={0} onSelect={mockOnSelect} />
    );

    expect(lastFrame()).toContain('Showing 1-3 of 3 items');
    expect(lastFrame()).toContain('Selected: 1/3');
    expect(lastFrame()).toContain('1. Missing semicolon');
    expect(lastFrame()).toContain('ERROR');
    expect(lastFrame()).toContain('eslint');
  });

  it('should render priority issues with priority score', () => {
    const { lastFrame } = render(
      <VirtualizedNavigatorList
        items={mockPriorityIssues}
        selectedIndex={0}
        onSelect={mockOnSelect}
      />
    );

    expect(lastFrame()).toContain('P:7.5');
    expect(lastFrame()).toContain('1. Missing semicolon');
    expect(lastFrame()).toContain('P:4.2');
    expect(lastFrame()).toContain('2. Unused variable');
  });

  it('should truncate long messages', () => {
    const longMessageIssues: Issue[] = [
      {
        ...mockIssues[0],
        message:
          'This is a very long error message that should be truncated because it exceeds the display limit for the virtualized list component in the CLI dashboard',
      },
    ];

    const { lastFrame } = render(
      <VirtualizedNavigatorList
        items={longMessageIssues}
        selectedIndex={0}
        onSelect={mockOnSelect}
      />
    );

    expect(lastFrame()).toContain('...');
    expect(lastFrame()).not.toContain('display limit for the virtualized list');
  });

  it('should handle empty item list', () => {
    const { lastFrame } = render(
      <VirtualizedNavigatorList items={[]} selectedIndex={0} onSelect={mockOnSelect} />
    );

    expect(lastFrame()).toContain('Showing 0-0 of 0 items');
  });

  it('should display navigation help', () => {
    const { lastFrame } = render(
      <VirtualizedNavigatorList items={mockIssues} selectedIndex={0} onSelect={mockOnSelect} />
    );

    expect(lastFrame()).toContain('Navigation: ↑↓ Page↑↓ Home End [1-9] | Enter to select');
  });

  it('should use custom item renderer', () => {
    const customRenderer = jest.fn().mockReturnValue(<Text>Custom Item</Text>);

    render(
      <VirtualizedNavigatorList
        items={mockIssues}
        selectedIndex={0}
        onSelect={mockOnSelect}
        renderItem={customRenderer}
      />
    );

    expect(customRenderer).toHaveBeenCalled();
  });

  it('should use custom item key generator', () => {
    const customKeyGenerator = jest.fn().mockReturnValue('custom-key');

    render(
      <VirtualizedNavigatorList
        items={mockIssues}
        selectedIndex={0}
        onSelect={mockOnSelect}
        getItemKey={customKeyGenerator}
      />
    );

    expect(customKeyGenerator).toHaveBeenCalled();
  });

  it('should show scroll indicator for large lists', () => {
    // Create a large list that would require scrolling
    const largeIssues: Issue[] = Array.from({ length: 100 }, (_, index) => ({
      ...mockIssues[0],
      id: `issue-${index}`,
      message: `Issue ${index + 1}`,
      lineNumber: index + 1,
    }));

    const { lastFrame } = render(
      <VirtualizedNavigatorList
        items={largeIssues}
        selectedIndex={50}
        onSelect={mockOnSelect}
        windowSize={5}
        height={10}
      />
    );

    expect(lastFrame()).toContain('Scroll:');
  });
});

/**
 * Comparison Store Hook Tests
 */

import { describe, it, expect, beforeEach, afterEach } from 'bun:test';
import { renderHook, act } from '@testing-library/react';
import { useComparisonStore } from '../../../src/hooks/useComparisonStore';
import type { Issue } from '@dev-quality/types';

describe('useComparisonStore', () => {
  const mockBaselineRun = {
    id: 'baseline-1',
    timestamp: new Date('2025-01-01T10:00:00Z'),
    version: 'v1.0.0',
    commitHash: 'abc123',
    branch: 'main',
    metadata: {
      totalIssues: 10,
      criticalIssues: 3,
      highIssues: 4,
      mediumIssues: 2,
      lowIssues: 1,
      fixableIssues: 7,
      score: 75,
      executionTime: 5000,
      tools: ['eslint', 'typescript'],
    },
    issues: [
      {
        id: 'issue-1',
        type: 'error',
        toolName: 'eslint',
        filePath: '/src/test.ts',
        lineNumber: 10,
        message: 'Test issue',
        ruleId: 'test-rule',
        fixable: true,
        score: 8,
      },
    ],
    metrics: {
      coverage: 85,
      duplicates: 2,
      newIssues: 0,
      resolvedIssues: 0,
      trends: {
        severity: { error: 3, warning: 4, info: 3 },
        tools: { eslint: 6, typescript: 4 },
        categories: { security: 2, performance: 3, maintainability: 5 },
      },
    },
  };

  const mockComparisonRun = {
    id: 'comparison-1',
    timestamp: new Date('2025-01-02T10:00:00Z'),
    version: 'v1.1.0',
    commitHash: 'def456',
    branch: 'main',
    metadata: {
      totalIssues: 8,
      criticalIssues: 2,
      highIssues: 3,
      mediumIssues: 2,
      lowIssues: 1,
      fixableIssues: 6,
      score: 80,
      executionTime: 4500,
      tools: ['eslint', 'typescript'],
    },
    issues: [
      {
        id: 'issue-1',
        type: 'error',
        toolName: 'eslint',
        filePath: '/src/test.ts',
        lineNumber: 10,
        message: 'Test issue',
        ruleId: 'test-rule',
        fixable: true,
        score: 8,
      },
      {
        id: 'issue-2',
        type: 'warning',
        toolName: 'typescript',
        filePath: '/src/new.ts',
        lineNumber: 5,
        message: 'New issue',
        ruleId: 'new-rule',
        fixable: false,
        score: 5,
      },
    ],
    metrics: {
      coverage: 88,
      duplicates: 1,
      newIssues: 1,
      resolvedIssues: 3,
      trends: {
        severity: { error: 2, warning: 4, info: 2 },
        tools: { eslint: 5, typescript: 3 },
        categories: { security: 1, performance: 3, maintainability: 4 },
      },
    },
  };

  beforeEach(() => {
    // Reset store state before each test
    const { result } = renderHook(() => useComparisonStore());
    act(() => {
      result.current.clearComparison();
    });
  });

  afterEach(() => {
    // Clean up any store state
    const { result } = renderHook(() => useComparisonStore());
    act(() => {
      result.current.clearComparison();
    });
  });

  describe('run management', () => {
    it('should initialize with empty state', () => {
      const { result } = renderHook(() => useComparisonStore());

      expect(result.current.runs).toEqual([]);
      expect(result.current.comparisons).toEqual([]);
      expect(result.current.currentComparison).toBeUndefined();
      expect(result.current.isComparing).toBe(false);
    });

    it('should add a new run', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
      });

      expect(result.current.runs).toHaveLength(1);
      expect(result.current.runs[0].id).toBe('baseline-1');
    });

    it('should update existing run', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
      });

      const updatedRun = { ...mockBaselineRun, version: 'v1.0.1' };
      act(() => {
        result.current.addRun(updatedRun);
      });

      expect(result.current.runs).toHaveLength(1);
      expect(result.current.runs[0].version).toBe('v1.0.1');
    });

    it('should remove a run', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      expect(result.current.runs).toHaveLength(2);

      act(() => {
        result.current.removeRun('baseline-1');
      });

      expect(result.current.runs).toHaveLength(1);
      expect(result.current.runs[0].id).toBe('comparison-1');
    });

    it('should get run by ID', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
      });

      const foundRun = result.current.getRun('baseline-1');
      expect(foundRun).toBeDefined();
      expect(foundRun?.id).toBe('baseline-1');

      const notFoundRun = result.current.getRun('non-existent');
      expect(notFoundRun).toBeUndefined();
    });

    it('should update run properties', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
      });

      act(() => {
        result.current.updateRun('baseline-1', { version: 'v2.0.0' });
      });

      const updatedRun = result.current.getRun('baseline-1');
      expect(updatedRun?.version).toBe('v2.0.0');
    });
  });

  describe('comparison operations', () => {
    it('should compare two runs', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const comparisonResult = act(() => {
        return result.current.compareRuns('baseline-1', 'comparison-1');
      });

      expect(comparisonResult).toBeDefined();
      expect(comparisonResult.summary.totalIssuesDiff).toBe(-2);
      expect(comparisonResult.summary.criticalIssuesDiff).toBe(-1);
      expect(comparisonResult.summary.newIssuesCount).toBe(1);
      expect(comparisonResult.summary.resolvedIssuesCount).toBe(3);
    });

    it('should throw error when comparing non-existent runs', () => {
      const { result } = renderHook(() => useComparisonStore());

      expect(() => {
        result.current.compareRuns('non-existent-1', 'non-existent-2');
      }).toThrow('One or both runs not found');
    });

    it('should set current comparison', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const comparisonResult = result.current.compareRuns('baseline-1', 'comparison-1');

      act(() => {
        result.current.setCurrentComparison(comparisonResult);
      });

      expect(result.current.currentComparison).toBe(comparisonResult);
    });

    it('should clear comparison', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const comparisonResult = result.current.compareRuns('baseline-1', 'comparison-1');
      act(() => {
        result.current.setCurrentComparison(comparisonResult);
      });

      act(() => {
        result.current.clearComparison();
      });

      expect(result.current.currentComparison).toBeUndefined();
    });
  });

  describe('configuration management', () => {
    it('should update comparison config', () => {
      const { result } = renderHook(() => useComparisonStore());

      const newConfig = {
        baselineRunId: 'test-baseline',
        comparisonRunId: 'test-comparison',
        metrics: ['totalIssues', 'score'],
      };

      act(() => {
        result.current.updateComparisonConfig(newConfig);
      });

      expect(result.current.comparisonConfig.baselineRunId).toBe('test-baseline');
      expect(result.current.comparisonConfig.comparisonRunId).toBe('test-comparison');
      expect(result.current.comparisonConfig.metrics).toEqual(['totalIssues', 'score']);
    });

    it('should update filters', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.setFilters({
          showNewIssues: false,
          severityFilter: ['error'],
        });
      });

      expect(result.current.comparisonConfig.filters.showNewIssues).toBe(false);
      expect(result.current.comparisonConfig.filters.severityFilter).toEqual(['error']);
    });

    it('should update visualization settings', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.setVisualization({
          showCharts: false,
          showTrends: true,
        });
      });

      expect(result.current.comparisonConfig.visualization.showCharts).toBe(false);
      expect(result.current.comparisonConfig.visualization.showTrends).toBe(true);
    });
  });

  describe('export functionality', () => {
    it('should export comparison as JSON', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const comparisonResult = result.current.compareRuns('baseline-1', 'comparison-1');
      act(() => {
        result.current.setCurrentComparison(comparisonResult);
      });

      const exportedJSON = result.current.exportComparison('json');
      const parsed = JSON.parse(exportedJSON);

      expect(parsed.summary.totalIssuesDiff).toBe(-2);
      expect(parsed.baseline.id).toBe('baseline-1');
      expect(parsed.comparison.id).toBe('comparison-1');
    });

    it('should export comparison as CSV', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const comparisonResult = result.current.compareRuns('baseline-1', 'comparison-1');
      act(() => {
        result.current.setCurrentComparison(comparisonResult);
      });

      const exportedCSV = result.current.exportComparison('csv');

      expect(exportedCSV).toContain('Metric,Baseline,Comparison,Difference,Trend');
      expect(exportedCSV).toContain('Total Issues,10,8,-2,down');
      expect(exportedCSV).toContain('Critical Issues,3,2,-1,down');
    });

    it('should export comparison as Markdown', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const comparisonResult = result.current.compareRuns('baseline-1', 'comparison-1');
      act(() => {
        result.current.setCurrentComparison(comparisonResult);
      });

      const exportedMD = result.current.exportComparison('markdown');

      expect(exportedMD).toContain('# Comparison Report');
      expect(exportedMD).toContain('Total Issues');
      expect(exportedMD).toContain('10');
      expect(exportedMD).toContain('8');
    });

    it('should export runs as JSON', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const exportedJSON = result.current.exportRuns('json');
      const parsed = JSON.parse(exportedJSON);

      expect(parsed).toHaveLength(2);
      expect(parsed[0].id).toBe('comparison-1'); // Should be sorted by timestamp
      expect(parsed[1].id).toBe('baseline-1');
    });

    it('should export runs as CSV', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      const exportedCSV = result.current.exportRuns('csv');

      expect(exportedCSV).toContain('ID,Timestamp,Version,Total Issues');
      expect(exportedCSV).toContain('comparison-1');
      expect(exportedCSV).toContain('baseline-1');
    });

    it('should throw error when exporting without comparison', () => {
      const { result } = renderHook(() => useComparisonStore());

      expect(() => {
        result.current.exportComparison('json');
      }).toThrow('No comparison to export');
    });
  });

  describe('utility methods', () => {
    it('should get recent runs', () => {
      const { result } = renderHook(() => useComparisonStore());

      // Add runs with different timestamps
      const oldRun = { ...mockBaselineRun, id: 'old-run', timestamp: new Date('2024-12-01') };
      const newRun = { ...mockComparisonRun, id: 'new-run', timestamp: new Date('2025-01-02') };

      act(() => {
        result.current.addRun(oldRun);
        result.current.addRun(newRun);
      });

      const recentRuns = result.current.getRecentRuns(1);
      expect(recentRuns).toHaveLength(1);
      expect(recentRuns[0].id).toBe('new-run');
    });

    it('should get run by ID', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
      });

      const foundRun = result.current.getRunById('baseline-1');
      expect(foundRun).toBeDefined();
      expect(foundRun?.id).toBe('baseline-1');
    });

    it('should calculate trends for multiple runs', () => {
      const { result } = renderHook(() => useComparisonStore());

      const thirdRun = {
        ...mockComparisonRun,
        id: 'third-run',
        metadata: { ...mockComparisonRun.metadata, totalIssues: 5 },
        metrics: {
          ...mockComparisonRun.metrics,
          trends: {
            severity: { error: 1, warning: 3, info: 1 },
            tools: { eslint: 3, typescript: 2 },
            categories: { security: 0, performance: 2, maintainability: 3 },
          },
        },
      };

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
        result.current.addRun(thirdRun);
      });

      const trends = result.current.calculateTrends(['baseline-1', 'comparison-1', 'third-run']);

      expect(trends.severity).toHaveLength(3);
      expect(trends.tools).toHaveLength(2);
      expect(trends.categories).toHaveLength(3);
    });
  });

  describe('UI state management', () => {
    it('should toggle run selector', () => {
      const { result } = renderHook(() => useComparisonStore());

      expect(result.current.showRunSelector).toBe(false);

      act(() => {
        result.current.toggleRunSelector();
      });

      expect(result.current.showRunSelector).toBe(true);

      act(() => {
        result.current.toggleRunSelector();
      });

      expect(result.current.showRunSelector).toBe(false);
    });

    it('should set run selector open state', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.setRunSelectorOpen(true);
      });

      expect(result.current.showRunSelector).toBe(true);

      act(() => {
        result.current.setRunSelectorOpen(false);
      });

      expect(result.current.showRunSelector).toBe(false);
    });

    it('should select baseline and comparison runs', () => {
      const { result } = renderHook(() => useComparisonStore());

      act(() => {
        result.current.addRun(mockBaselineRun);
        result.current.addRun(mockComparisonRun);
      });

      act(() => {
        result.current.selectBaselineRun('baseline-1');
      });

      expect(result.current.selectedBaselineRun).toBe('baseline-1');
      expect(result.current.comparisonConfig.baselineRunId).toBe('baseline-1');

      act(() => {
        result.current.selectComparisonRun('comparison-1');
      });

      expect(result.current.selectedComparisonRun).toBe('comparison-1');
      expect(result.current.comparisonConfig.comparisonRunId).toBe('comparison-1');
    });
  });
});

