        return JSON.stringify({
          id: mockLayout.id,
          name: mockLayout.name,
          description: mockLayout.description,
          isPreset: mockLayout.isPreset,
          widgets: mockLayout.widgets,
          createdAt: mockLayout.createdAt.toISOString(),
          updatedAt: mockLayout.updatedAt.toISOString(),
        });
      }
      if (path.includes('another-layout.json')) {
        return JSON.stringify({
          id: 'another-layout',
          name: 'Another Layout',
          description: 'Another test layout',
          isPreset: false,
          widgets: [],
          createdAt: new Date('2023-01-01T00:00:00.000Z').toISOString(),
          updatedAt: new Date('2023-01-02T00:00:00.000Z').toISOString(),
        });
      }
      return '{}';
    });

    (fs.unlinkSync as any).mockImplementation(() => undefined);

    // Create a new service instance to use our mocks
    // Note: We can't reset the singleton, so we'll work with the existing one
  });

  afterEach(() => {
    layoutPersistenceService.close();
    vi.restoreAllMocks();
    vi.clearAllMocks();
  });

  describe('Initialization', () => {
    it('should create app directory if it does not exist', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('.dev-quality') && !path.includes('layouts') && !path.includes('filter-presets')) {
          return false;
        }
        return true;
      });

      // Create a new service instance to test initialization
      const { LayoutPersistenceService } = require('../../../src/services/layout-persistence-service');
      const _service = new LayoutPersistenceService();

      expect(fs.mkdirSync).toHaveBeenCalledWith(
        expect.stringContaining('.dev-quality'),
        { recursive: true }
      );
    });

    it('should create layouts directory if it does not exist', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('.dev-quality/layouts')) {
          return false;
        }
        return true;
      });

      // Create a new service instance to test initialization
      const { LayoutPersistenceService } = require('../../../src/services/layout-persistence-service');
      const _service = new LayoutPersistenceService();

      expect(fs.mkdirSync).toHaveBeenCalledWith(
        expect.stringContaining('.dev-quality/layouts'),
        { recursive: true }
      );
    });

    it('should create filter presets directory if it does not exist', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('.dev-quality/filter-presets')) {
          return false;
        }
        return true;
      });

      // Create a new service instance to test initialization
      const { LayoutPersistenceService } = require('../../../src/services/layout-persistence-service');
      const _service = new LayoutPersistenceService();

      expect(fs.mkdirSync).toHaveBeenCalledWith(
        expect.stringContaining('.dev-quality/filter-presets'),
        { recursive: true }
      );
    });
  });

  describe('Layout Operations', () => {
    it('should save a layout to file', () => {
      const result = layoutPersistenceService.saveLayout(mockLayout);

      expect(result).toBe(true);
      expect(fs.writeFileSync).toHaveBeenCalledWith(
        expect.stringContaining('Test Layout.json'),
        expect.stringContaining('"name": "Test Layout"')
      );
    });

    it('should load a layout from file', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('Test Layout.json')) return true;
        return false;
      });

      const layout = layoutPersistenceService.loadLayout('Test Layout');

      expect(layout).toEqual(mockLayout);
      expect(fs.readFileSync).toHaveBeenCalledWith(
        expect.stringContaining('Test Layout.json'),
        'utf-8'
      );
    });

    it('should return null when loading non-existent layout', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('non-existent.json')) return false;
        return true;
      });

      const layout = layoutPersistenceService.loadLayout('non-existent');

      expect(layout).toBeNull();
    });

    it('should get all layouts', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('Test Layout.json')) return true;
        if (path.includes('another-layout.json')) return true;
        return false;
      });

      const layouts = layoutPersistenceService.getAllLayouts();

      expect(layouts).toHaveLength(1);
      expect(layouts[0].name).toBe('Another Layout');
      expect(fs.readdirSync).toHaveBeenCalledWith(
        expect.stringContaining('layouts')
      );
    });

    it('should delete a layout', () => {
      const result = layoutPersistenceService.deleteLayout('Test Layout');

      expect(result).toBe(true);
      expect(fs.unlinkSync).toHaveBeenCalledWith(
        expect.stringContaining('Test Layout.json')
      );
    });

    it('should return false when deleting non-existent layout', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('non-existent.json')) return false;
        return true;
      });

      const result = layoutPersistenceService.deleteLayout('non-existent');

      expect(result).toBe(false);
    });
  });

  describe('Import/Export Operations', () => {
    it('should export layout to JSON string', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('Test Layout.json')) return true;
        return false;
      });

      const exported = layoutPersistenceService.exportLayout('Test Layout');

      expect(exported).toContain('"name": "Test Layout"');
      expect(exported).toContain('"id": "test-layout"');
    });

    it('should return null when exporting non-existent layout', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('non-existent.json')) return false;
        return true;
      });

      const exported = layoutPersistenceService.exportLayout('non-existent');

      expect(exported).toBeNull();
    });

    it('should import layout from JSON string', () => {
      const layoutJson = JSON.stringify(mockLayout);

      const imported = layoutPersistenceService.importLayout(layoutJson);

      expect(imported).toEqual(mockLayout);
      expect(fs.writeFileSync).toHaveBeenCalled();
    });

    it('should throw error when importing invalid JSON', () => {
      expect(() => {
        layoutPersistenceService.importLayout('invalid json');
      }).toThrow('Failed to import layout');
    });

    it('should throw error when importing layout with invalid structure', () => {
      const invalidLayout = {
        // Missing required fields
        name: 'Invalid Layout',
      };

      expect(() => {
        layoutPersistenceService.importLayout(JSON.stringify(invalidLayout));
      }).toThrow('Invalid layout structure');
    });
  });

  describe('Filter Preset Operations', () => {
    it('should save a filter preset', () => {
      const filterConfig = {
        severity: ['error', 'warning'],
        tools: ['eslint', 'typescript'],
      };

      const result = layoutPersistenceService.saveFilterPreset(
        'test-preset',
        'Test filter preset',
        filterConfig,
        false
      );

      expect(result).toBe(true);
      expect(fs.writeFileSync).toHaveBeenCalledWith(
        expect.stringContaining('test-preset.json'),
        expect.stringContaining('"name": "test-preset"')
      );
    });

    it('should load a filter preset', () => {
      const filterConfig = {
        severity: ['error', 'warning'],
        tools: ['eslint', 'typescript'],
      };

      (fs.readFileSync as any).mockImplementation((path: string) => {
        if (path.includes('test-preset.json')) {
          return JSON.stringify({
            name: 'test-preset',
            description: 'Test filter preset',
            config: filterConfig,
            isGlobal: false,
            createdAt: new Date().toISOString(),
          });
        }
        return '{}';
      });

      const preset = layoutPersistenceService.loadFilterPreset('test-preset');

      expect(preset).toEqual(filterConfig);
    });

    it('should return null when loading non-existent filter preset', () => {
      (fs.existsSync as any).mockImplementation((path: string) => {
        if (path.includes('non-existent.json')) return false;
        return true;
      });

      const preset = layoutPersistenceService.loadFilterPreset('non-existent');

      expect(preset).toBeNull();
    });

    it('should delete a filter preset', () => {
      const result = layoutPersistenceService.deleteFilterPreset('test-preset');

      expect(result).toBe(true);
      expect(fs.unlinkSync).toHaveBeenCalledWith(
        expect.stringContaining('test-preset.json')
      );
    });
  });

  describe('Statistics', () => {
    it('should get storage statistics', () => {
      (fs.readdirSync as any).mockImplementation((path: string) => {
        if (path.includes('layouts')) {
          return ['layout1.json', 'layout2.json', 'layout3.json'];
        }
        if (path.includes('filter-presets')) {
          return ['preset1.json', 'preset2.json'];
        }
        return [];
      });

      const stats = layoutPersistenceService.getStats();

      expect(stats.layouts).toBe(3);
      expect(stats.filterPresets).toBe(2);
    });
  });
});

/**
 * Unit tests for PresetLayoutsService
 */

import { describe, it, expect, beforeEach } from 'vitest';
import { presetLayoutsService } from '../../../src/services/preset-layouts-service';

describe('PresetLayoutsService', () => {
  beforeEach(() => {
    // Reset the service before each test
    // Note: The service is already initialized in the constructor
  });

  describe('Preset Layouts', () => {
    it('should have developer preset layout', () => {
      const layout = presetLayoutsService.getPresetLayout('developer');

      expect(layout).toBeDefined();
      expect(layout?.name).toBe('Developer Layout');
      expect(layout?.description).toBe('Focused on code quality, issues, and coverage for developers');
      expect(layout?.isPreset).toBe(true);
      expect(layout?.widgets).toHaveLength(4);
    });

    it('should have manager preset layout', () => {
      const layout = presetLayoutsService.getPresetLayout('manager');

      expect(layout).toBeDefined();
      expect(layout?.name).toBe('Manager Layout');
      expect(layout?.description).toBe('High-level overview focusing on trends and team metrics');
      expect(layout?.isPreset).toBe(true);
      expect(layout?.widgets).toHaveLength(3);
    });

    it('should have CI/CD preset layout', () => {
      const layout = presetLayoutsService.getPresetLayout('cicd');

      expect(layout).toBeDefined();
      expect(layout?.name).toBe('CI/CD Layout');
      expect(layout?.description).toBe('Optimized for build pipelines and deployment monitoring');
      expect(layout?.isPreset).toBe(true);
      expect(layout?.widgets).toHaveLength(4);
    });

    it('should have security preset layout', () => {
      const layout = presetLayoutsService.getPresetLayout('security');

      expect(layout).toBeDefined();
      expect(layout?.name).toBe('Security Layout');
      expect(layout?.description).toBe('Focused on security vulnerabilities and compliance metrics');
      expect(layout?.isPreset).toBe(true);
      expect(layout?.widgets).toHaveLength(4);
    });

    it('should have performance preset layout', () => {
      const layout = presetLayoutsService.getPresetLayout('performance');

      expect(layout).toBeDefined();
      expect(layout?.name).toBe('Performance Layout');
      expect(layout?.description).toBe('Optimized for performance monitoring and bottlenecks');
      expect(layout?.isPreset).toBe(true);
      expect(layout?.widgets).toHaveLength(4);
    });

    it('should have minimal preset layout', () => {
      const layout = presetLayoutsService.getPresetLayout('minimal');

      expect(layout).toBeDefined();
      expect(layout?.name).toBe('Minimal Layout');
      expect(layout?.description).toBe('Clean, minimal layout showing only essential information');
      expect(layout?.isPreset).toBe(true);
      expect(layout?.widgets).toHaveLength(2);
    });
  });

  describe('Layout Retrieval', () => {
    it('should return null for unknown preset layout', () => {
      const layout = presetLayoutsService.getPresetLayout('unknown');

      expect(layout).toBeNull();
    });

    it('should get all preset layouts', () => {
      const layouts = presetLayoutsService.getAllPresetLayouts();

      expect(layouts).toHaveLength(6);
      expect(layouts.map(l => l.name)).toContain('Developer Layout');
      expect(layouts.map(l => l.name)).toContain('Manager Layout');
      expect(layouts.map(l => l.name)).toContain('CI/CD Layout');
      expect(layouts.map(l => l.name)).toContain('Security Layout');
      expect(layouts.map(l => l.name)).toContain('Performance Layout');
      expect(layouts.map(l => l.name)).toContain('Minimal Layout');
    });

    it('should get preset layout descriptions', () => {
      const descriptions = presetLayoutsService.getPresetLayoutDescriptions();

      expect(descriptions).toHaveLength(6);
      expect(descriptions.some(d => d.name === 'Developer Layout')).toBe(true);
      expect(descriptions.some(d => d.description?.includes('code quality'))).toBe(true);
    });
  });

  describe('Layout Validation', () => {
    it('should have valid widget configurations in developer layout', () => {
      const layout = presetLayoutsService.getPresetLayout('developer');

      expect(layout).toBeDefined();
      expect(layout?.widgets).toHaveLength(4);

      // Check that all widgets have valid positions
      layout?.widgets.forEach(widget => {
        expect(widget.position.x).toBeGreaterThanOrEqual(0);
        expect(widget.position.y).toBeGreaterThanOrEqual(0);
        expect(widget.position.width).toBeGreaterThan(0);
        expect(widget.position.height).toBeGreaterThan(0);
        expect(widget.id).toBeDefined();
        expect(widget.type).toBeDefined();
        expect(widget.visible).toBe(true);
      });
    });

    it('should have non-overlapping widget positions in developer layout', () => {
      const layout = presetLayoutsService.getPresetLayout('developer');

      expect(layout).toBeDefined();

      const positions = layout?.widgets.map(w => w.position) || [];

      // Check that widgets don't overlap (simplified check)
      for (let i = 0; i < positions.length; i++) {
        for (let j = i + 1; j < positions.length; j++) {
          const pos1 = positions[i];
          const pos2 = positions[j];

          // Simple check: widgets should not have the exact same position
          if (pos1.x === pos2.x && pos1.y === pos2.y) {
            expect.fail(`Widgets ${i} and ${j} have the same position`);
          }
        }
      }
    });
  });

  describe('Layout Customization', () => {
    it('should create custom layout based on preset', () => {
      const customLayout = presetLayoutsService.createFromPreset(
        'developer',
        'My Custom Layout',
        'A custom layout based on developer preset'
      );

      expect(customLayout).toBeDefined();
      expect(customLayout?.name).toBe('My Custom Layout');
      expect(customLayout?.description).toBe('A custom layout based on developer preset');
      expect(customLayout?.isPreset).toBe(false);
      expect(customLayout?.widgets).toHaveLength(4); // Same number of widgets as preset
    });

    it('should return null when creating from unknown preset', () => {
      const customLayout = presetLayoutsService.createFromPreset(
        'unknown',
        'My Custom Layout'
      );

      expect(customLayout).toBeNull();
    });
  });

  describe('Layout Recommendations', () => {
    it('should recommend security layout for high security issues', () => {
      const recommendation = presetLayoutsService.getRecommendedPreset({
        totalIssues: 20,
        criticalIssues: 2,
        coverage: 85,
        securityIssues: 15,
        performanceIssues: 5,
        teamSize: 5,
      });

      expect(recommendation).toBe('security');
    });

    it('should recommend performance layout for high performance issues', () => {
      const recommendation = presetLayoutsService.getRecommendedPreset({
        totalIssues: 25,
        criticalIssues: 3,
        coverage: 80,
        securityIssues: 5,
        performanceIssues: 12,
        teamSize: 6,
      });

      expect(recommendation).toBe('performance');
    });

    it('should recommend manager layout for large teams', () => {
      const recommendation = presetLayoutsService.getRecommendedPreset({
        totalIssues: 30,
        criticalIssues: 2,
        coverage: 75,
        securityIssues: 4,
        performanceIssues: 6,
        teamSize: 15,
      });

      expect(recommendation).toBe('manager');
    });

    it('should recommend developer layout for low coverage', () => {
      const recommendation = presetLayoutsService.getRecommendedPreset({
        totalIssues: 20,
        criticalIssues: 3,
        coverage: 65,
        securityIssues: 5,
        performanceIssues: 5,
        teamSize: 4,
      });

      expect(recommendation).toBe('developer');
    });

    it('should recommend CI/CD layout for many critical issues', () => {
      const recommendation = presetLayoutsService.getRecommendedPreset({
        totalIssues: 35,
        criticalIssues: 8,
        coverage: 80,
        securityIssues: 5,
        performanceIssues: 5,
        teamSize: 5,
      });

      expect(recommendation).toBe('cicd');
    });

    it('should recommend minimal layout as default', () => {
      const recommendation = presetLayoutsService.getRecommendedPreset({
        totalIssues: 15,
        criticalIssues: 1,
        coverage: 85,
        securityIssues: 3,
        performanceIssues: 2,
        teamSize: 5,
      });

      expect(recommendation).toBe('minimal');
    });
  });

  describe('Layout Identification', () => {
    it('should identify preset layouts correctly', () => {
      expect(presetLayoutsService.isPresetLayout('developer')).toBe(true);
      expect(presetLayoutsService.isPresetLayout('manager')).toBe(true);
      expect(presetLayoutsService.isPresetLayout('cicd')).toBe(true);
      expect(presetLayoutsService.isPresetLayout('security')).toBe(true);
      expect(presetLayoutsService.isPresetLayout('performance')).toBe(true);
      expect(presetLayoutsService.isPresetLayout('minimal')).toBe(true);
    });

    it('should not identify custom layouts as presets', () => {
      expect(presetLayoutsService.isPresetLayout('custom-layout')).toBe(false);
      expect(presetLayoutsService.isPresetLayout('my-layout')).toBe(false);
    });
  });
});

/**
 * Prioritization Service Tests
 */

import { describe, it, expect, jest } from 'bun:test';
import { prioritizationService } from '../../../src/services/prioritization-service';
import type { AnalysisResult, Issue } from '../../../src/types/analysis';

// Tests will use the mock fallback engine in the service

describe('PrioritizationService', () => {
  const mockIssue: Issue = {
    id: 'issue-1',
    type: 'error',
    toolName: 'eslint',
    filePath: '/src/components/Button.tsx',
    lineNumber: 23,
    message: 'Missing semicolon',
    ruleId: 'semi',
    fixable: true,
    score: 5,
  };

  const mockAnalysisResult: AnalysisResult = {
    id: 'analysis-1',
    projectId: 'project-1',
    timestamp: new Date(),
    duration: 1500,
    overallScore: 85,
    toolResults: [
      {
        toolName: 'eslint',
        version: '8.0.0',
        duration: 500,
        issues: [mockIssue],
        summary: {
          totalIssues: 1,
          errorCount: 1,
          warningCount: 0,
          infoCount: 0,
          fixableCount: 1,
        },
      },
    ],
    summary: {
      totalIssues: 1,
      errorCount: 1,
      warningCount: 0,
      infoCount: 0,
      fixableCount: 1,
      overallScore: 85,
      duration: 1500,
      toolsAnalyzed: 1,
    },
    aiPrompts: [],
  };

  describe('processIssues', () => {
    it('should process issues and return prioritizations', async () => {
      const result = await prioritizationService.processIssues([mockIssue], mockAnalysisResult);

      expect(result).toHaveLength(1);
      expect(result[0].issueId).toBe('issue-1');
      expect(result[0].finalScore).toBeGreaterThan(0);
      expect(result[0].triageSuggestion).toBeDefined();
      expect(result[0].severity).toBeGreaterThan(0);
    });

    it('should handle empty issue list', async () => {
      const result = await prioritizationService.processIssues([], mockAnalysisResult);

      expect(result).toHaveLength(0);
    });
  });

  describe('enrichIssuesWithPriority', () => {
    it('should enrich issues with priority data', () => {
      const prioritizations = [
        {
          id: 'priority-1',
          issueId: 'issue-1',
          finalScore: 7.5,
          severity: 8,
          triageSuggestion: {
            action: 'schedule',
            priority: 7,
            estimatedEffort: 3,
            reasoning: 'Medium priority issue found',
            confidence: 0.8,
          },
        } as any,
      ];

      const enriched = prioritizationService.enrichIssuesWithPriority([mockIssue], prioritizations);

      expect(enriched[0]).toHaveProperty('priority');
      expect(enriched[0].priorityScore).toBe(7.5);
      expect(enriched[0].priorityLevel).toBe('high');
      expect(enriched[0]).toHaveProperty('triageSuggestion');
    });

    it('should return original issue when no matching prioritization', () => {
      const prioritizations = [
        {
          id: 'priority-2',
          issueId: 'issue-2',
          finalScore: 5.0,
        } as any,
      ];

      const enriched = prioritizationService.enrichIssuesWithPriority([mockIssue], prioritizations);

      expect(enriched[0]).toEqual(mockIssue);
      expect(enriched[0]).not.toHaveProperty('priority');
    });
  });

  describe('filterByPriority', () => {
    it('should filter issues by priority levels', () => {
      const enrichedIssues = [
        { ...mockIssue, priorityLevel: 'critical' as const },
        { ...mockIssue, id: 'issue-2', priorityLevel: 'high' as const },
        { ...mockIssue, id: 'issue-3', priorityLevel: 'low' as const },
      ] as any[];

      const filtered = prioritizationService.filterByPriority(enrichedIssues, ['critical', 'high']);

      expect(filtered).toHaveLength(2);
      expect(filtered.map(i => i.id)).toEqual(['issue-1', 'issue-2']);
    });

    it('should return all issues when no priority levels specified', () => {
      const enrichedIssues = [
        { ...mockIssue, priorityLevel: 'critical' as const },
        { ...mockIssue, id: 'issue-2', priorityLevel: 'high' as const },
      ] as any[];

      const filtered = prioritizationService.filterByPriority(enrichedIssues, []);

      expect(filtered).toHaveLength(2);
    });
  });

  describe('sortByPriority', () => {
    it('should sort issues by priority in descending order by default', () => {
      const enrichedIssues = [
        { ...mockIssue, id: 'issue-1', priorityScore: 3.0 },
        { ...mockIssue, id: 'issue-2', priorityScore: 8.0 },
        { ...mockIssue, id: 'issue-3', priorityScore: 5.0 },
      ] as any[];

      const sorted = prioritizationService.sortByPriority(enrichedIssues);

      expect(sorted.map(i => i.id)).toEqual(['issue-2', 'issue-3', 'issue-1']);
    });

    it('should sort issues by priority in ascending order when specified', () => {
      const enrichedIssues = [
        { ...mockIssue, id: 'issue-1', priorityScore: 3.0 },
        { ...mockIssue, id: 'issue-2', priorityScore: 8.0 },
        { ...mockIssue, id: 'issue-3', priorityScore: 5.0 },
      ] as any[];

      const sorted = prioritizationService.sortByPriority(enrichedIssues, 'asc');

      expect(sorted.map(i => i.id)).toEqual(['issue-1', 'issue-3', 'issue-2']);
    });
  });

  describe('getPriorityStatistics', () => {
    it('should calculate priority statistics correctly', () => {
      const enrichedIssues = [
        { ...mockIssue, priorityLevel: 'critical' as const, priorityScore: 9.0 },
        { ...mockIssue, id: 'issue-2', priorityLevel: 'high' as const, priorityScore: 7.0 },
        { ...mockIssue, id: 'issue-3', priorityLevel: 'high' as const, priorityScore: 6.0 },
        { ...mockIssue, id: 'issue-4', priorityLevel: 'low' as const, priorityScore: 2.0 },
        { ...mockIssue, id: 'issue-5' }, // No priority data
      ] as any[];

      const stats = prioritizationService.getPriorityStatistics(enrichedIssues);

      expect(stats.critical).toBe(1);
      expect(stats.high).toBe(2);
      expect(stats.medium).toBe(0);
      expect(stats.low).toBe(1);
      expect(stats.total).toBe(5);
      expect(stats.averageScore).toBe(6.0); // (9 + 7 + 6 + 2) / 4
    });

    it('should handle empty issues list', () => {
      const stats = prioritizationService.getPriorityStatistics([]);

      expect(stats.critical).toBe(0);
      expect(stats.high).toBe(0);
      expect(stats.medium).toBe(0);
      expect(stats.low).toBe(0);
      expect(stats.total).toBe(0);
      expect(stats.averageScore).toBe(0);
    });
  });
});

