const mockReportConfiguration = {
  id: 'test-config-1',
  name: 'Test Report',
  description: 'Test report configuration',
  templateId: 'executive-summary',
  format: 'html' as const,
  schedule: undefined,
  recipients: [],
  filters: {},
  createdAt: new Date('2023-10-09T10:00:00.000Z'),
  updatedAt: new Date('2023-10-09T10:00:00.000Z'),
  isActive: true,
};

describe('ReportGenerator', () => {
  let reportGenerator: ReportGenerator;

  beforeEach(() => {
    reportGenerator = new ReportGenerator();
  });

  describe('constructor', () => {
    it('should initialize with built-in templates', () => {
      const templates = reportGenerator.getAvailableTemplates();

      expect(templates).toBeDefined();
      expect(templates.length).toBeGreaterThan(0);

      const templateIds = templates.map(t => t.id);
      expect(templateIds).toContain('executive-summary');
      expect(templateIds).toContain('technical-report');
      expect(templateIds).toContain('detailed-analysis');
    });

    it('should support all required formats', () => {
      const formats = reportGenerator.getSupportedFormats();

      expect(formats).toEqual(['json', 'html', 'markdown', 'pdf']);
    });
  });

  describe('getAvailableTemplates', () => {
    it('should return all available templates', () => {
      const templates = reportGenerator.getAvailableTemplates();

      expect(Array.isArray(templates)).toBe(true);
      expect(templates.length).toBeGreaterThan(0);

      templates.forEach(template => {
        expect(template).toHaveProperty('id');
        expect(template).toHaveProperty('name');
        expect(template).toHaveProperty('sections');
        expect(template).toHaveProperty('templateType');
        expect(template).toHaveProperty('format');
      });
    });

    it('should include executive summary template', () => {
      const templates = reportGenerator.getAvailableTemplates();
      const executiveTemplate = templates.find(t => t.id === 'executive-summary');

      expect(executiveTemplate).toBeDefined();
      expect(executiveTemplate?.name).toBe('Executive Summary');
      expect(executiveTemplate?.format).toBe('html');
      expect(executiveTemplate?.templateType).toBe('builtin');
    });

    it('should include technical report template', () => {
      const templates = reportGenerator.getAvailableTemplates();
      const technicalTemplate = templates.find(t => t.id === 'technical-report');

      expect(technicalTemplate).toBeDefined();
      expect(technicalTemplate?.name).toBe('Technical Report');
      expect(technicalTemplate?.format).toBe('markdown');
      expect(technicalTemplate?.templateType).toBe('builtin');
    });

    it('should include detailed analysis template', () => {
      const templates = reportGenerator.getAvailableTemplates();
      const detailedTemplate = templates.find(t => t.id === 'detailed-analysis');

      expect(detailedTemplate).toBeDefined();
      expect(detailedTemplate?.name).toBe('Detailed Analysis');
      expect(detailedTemplate?.format).toBe('pdf');
      expect(detailedTemplate?.templateType).toBe('builtin');
    });
  });

  describe('getTemplate', () => {
    it('should return template by ID', () => {
      const template = reportGenerator.getTemplate('executive-summary');

      expect(template).toBeDefined();
      expect(template?.id).toBe('executive-summary');
      expect(template?.name).toBe('Executive Summary');
    });

    it('should return undefined for non-existent template', () => {
      const template = reportGenerator.getTemplate('non-existent');

      expect(template).toBeUndefined();
    });
  });

  describe('addTemplate', () => {
    it('should add custom template', () => {
      // Create a fresh report generator instance to avoid test interference
      const freshReportGenerator = new ReportGenerator();

      const customTemplate = {
        name: 'Custom Template',
        description: 'A custom template',
        sections: [
          { id: 'summary', name: 'Summary', type: 'summary' as const, enabled: true, order: 1 },
        ],
        format: 'html' as const,
        templateType: 'custom' as const,
        content: '<h1>{{title}}</h1>',
        author: 'Test Author' as const,
        version: '1.0.0' as const,
        tags: ['test'] as const,
        category: 'custom' as const,
        variables: [],
        metadata: {},
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      freshReportGenerator.addTemplate(customTemplate);

      // Get all templates and find the one we just added
      const templates = freshReportGenerator.getAvailableTemplates();
      const retrievedTemplate = templates.find(t => t.name === 'Custom Template');

      expect(retrievedTemplate).toBeDefined();
      expect(retrievedTemplate?.name).toBe('Custom Template');
      expect(retrievedTemplate?.templateType).toBe('custom');
    });

    it('should override existing template with same ID', () => {
      // Create a fresh report generator instance to avoid test interference
      const freshReportGenerator = new ReportGenerator();

      const customTemplate = {
        id: 'executive-summary', // Same ID as built-in
        name: 'Custom Executive Summary',
        sections: [
          { id: 'custom-section', name: 'Custom Section', type: 'summary' as const, enabled: true, order: 1 },
        ],
        format: 'html' as const,
        templateType: 'custom' as const,
        content: '<h1>Custom</h1>',
        author: 'Test Author' as const,
        version: '1.0.0' as const,
        tags: ['test'] as const,
        category: 'custom' as const,
        variables: [],
        metadata: {},
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      freshReportGenerator.addTemplate(customTemplate);

      const retrievedTemplate = freshReportGenerator.getTemplate('executive-summary');
      expect(retrievedTemplate?.name).toBe('Custom Executive Summary');
      expect(retrievedTemplate?.templateType).toBe('custom');
    });
  });

  describe('generateReport', () => {
    const mockProgressCallback = vi.fn();

    beforeEach(() => {
      mockProgressCallback.mockClear();
    });

    it('should generate report successfully', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
        onProgress: mockProgressCallback,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(true);
      expect(result.reportId).toBeDefined();
      expect(result.configurationId).toBe(mockReportConfiguration.id);
      expect(result.outputPath).toBeDefined();
      expect(result.format).toBe(mockReportConfiguration.format);
      expect(result.size).toBeGreaterThan(0);
      expect(result.generatedAt).toBeInstanceOf(Date);
      expect(result.duration).toBeGreaterThan(0);
      expect(result.error).toBeUndefined();
      expect(result.metadata).toBeDefined();
    });

    it('should call progress callback', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
        onProgress: mockProgressCallback,
      };

      await reportGenerator.generateReport(request);

      expect(mockProgressCallback).toHaveBeenCalled();

      // Check that progress was reported
      const progressCalls = mockProgressCallback.mock.calls;
      expect(progressCalls.length).toBeGreaterThan(0);

      // Check final progress call shows completion
      const finalProgress = progressCalls[progressCalls.length - 1][0];
      expect(finalProgress.percentage).toBe(100);
      expect(finalProgress.currentStep).toBe('Complete');
    });

    it('should handle missing progress callback', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(true);
    });

    it('should validate configuration', async () => {
      const invalidConfiguration = {
        ...mockReportConfiguration,
        name: '', // Invalid empty name
      };

      const request = {
        configuration: invalidConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain('Report name is required');
    });

    it('should validate template exists', async () => {
      const invalidConfiguration = {
        ...mockReportConfiguration,
        templateId: 'non-existent-template',
      };

      const request = {
        configuration: invalidConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain('Template not found');
    });

    it('should validate format', async () => {
      const invalidConfiguration = {
        ...mockReportConfiguration,
        format: 'invalid-format' as any,
      };

      const request = {
        configuration: invalidConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain('Invalid format');
    });

    it('should apply filters to issues', async () => {
      const configurationWithFilters = {
        ...mockReportConfiguration,
        filters: {
          severity: ['error'] as const,
          fixableOnly: true,
        },
      };

      const request = {
        configuration: configurationWithFilters,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(true);
      // The report should be generated with filtered issues
      expect(result.outputPath).toBeDefined();
    });

    it('should generate executive summary when enabled', async () => {
      const executiveConfiguration = {
        ...mockReportConfiguration,
        templateId: 'executive-summary',
      };

      const request = {
        configuration: executiveConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(true);
      // Executive summary generation should not cause errors
      expect(result.error).toBeUndefined();
    });

    it('should handle different formats', async () => {
      const formats: Array<'json' | 'html' | 'markdown' | 'pdf'> = ['json', 'html', 'markdown', 'pdf'];

      for (const format of formats) {
        const configuration = {
          ...mockReportConfiguration,
          format,
        };

        const request = {
          configuration,
          analysisResult: mockAnalysisResult,
          issues: mockIssues,
          metrics: mockMetrics,
        };

        const result = await reportGenerator.generateReport(request);

        expect(result.success).toBe(true);
        expect(result.format).toBe(format);
        expect(result.outputPath).toBeDefined();
      }
    });

    it('should handle historical data for trend analysis', async () => {
      const historicalData = [
        {
          timestamp: new Date('2023-10-08'),
          overallScore: 65,
          totalIssues: 10,
          errorCount: 5,
          warningCount: 3,
          infoCount: 2,
          fixableCount: 6,
          toolResults: [],
        },
        {
          timestamp: new Date('2023-10-09'),
          overallScore: 75,
          totalIssues: 5,
          errorCount: 2,
          warningCount: 2,
          infoCount: 1,
          fixableCount: 3,
          toolResults: [],
        },
      ];

      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
        historicalData,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(true);
      // Historical data should not cause errors
      expect(result.error).toBeUndefined();
    });

    it('should handle empty issues array', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: [],
        metrics: {
          ...mockMetrics,
          totalIssues: 0,
          errorCount: 0,
          warningCount: 0,
          infoCount: 0,
          fixableCount: 0,
        },
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(true);
      expect(result.error).toBeUndefined();
    });

    it('should generate unique report IDs', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result1 = await reportGenerator.generateReport(request);
      const result2 = await reportGenerator.generateReport(request);

      expect(result1.reportId).not.toBe(result2.reportId);
      expect(result1.success).toBe(true);
      expect(result2.success).toBe(true);
    });

    it('should include metadata in result', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.metadata).toBeDefined();
      expect(result.metadata.title).toBe(mockReportConfiguration.name);
      expect(result.metadata.description).toBe(mockReportConfiguration.description);
      expect(result.metadata.version).toBe('1.0.0');
    });

    it('should handle formatter errors gracefully', async () => {
      // Create a configuration that might cause formatter issues
      const problematicConfiguration = {
        ...mockReportConfiguration,
        format: 'pdf' as const, // PDF formatter has HTML conversion complexity
      };

      const request = {
        configuration: problematicConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      // Should still succeed even with complex format
      expect(result.success).toBe(true);
    });

    it('should measure execution time', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.duration).toBeGreaterThan(0);
      expect(result.duration).toBeLessThan(10000); // Should complete within 10 seconds
    });

    it('should create output directory if it doesn\'t exist', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(true);
      expect(result.outputPath).toBeDefined();
      // Path should include reports directory
      expect(result.outputPath).toContain('/reports/');
    });
  });

  describe('getSupportedFormats', () => {
    it('should return all supported formats', () => {
      const formats = reportGenerator.getSupportedFormats();

      expect(formats).toContain('json');
      expect(formats).toContain('html');
      expect(formats).toContain('markdown');
      expect(formats).toContain('pdf');
      expect(formats).toHaveLength(4);
    });
  });

  describe('error handling', () => {
    it('should handle missing analysis result gracefully', async () => {
      const request = {
        configuration: mockReportConfiguration,
        analysisResult: null as any,
        issues: mockIssues,
        metrics: mockMetrics,
      };

      const result = await reportGenerator.generateReport(request);

      expect(result.success).toBe(false);
      expect(result.error).toBeDefined();
    });

    it('should handle corrupted issues data gracefully', async () => {
      const corruptedIssues = [
        null,
        undefined,
        { invalid: 'issue' },
        ...mockIssues,
      ] as any[];

      const request = {
        configuration: mockReportConfiguration,
        analysisResult: mockAnalysisResult,
        issues: corruptedIssues,
        metrics: mockMetrics,
      };

      // Should not crash, but may have filtering issues
      const result = await reportGenerator.generateReport(request);

      // The exact behavior depends on implementation, but shouldn't crash
      expect(result).toBeDefined();
    });
  });
});

/**
 * Report Scheduler Test Suite
 *
 * Comprehensive tests for automated report generation and scheduling (Story 2.4 AC3)
 * including cron scheduling, queue management, retry mechanisms, and notifications.
 */

import { describe, it, expect, beforeEach, afterEach, vi, type MockedFunction } from 'vitest';
import { ReportScheduler, type ReportSchedule, type ReportConfiguration } from '../../../../src/services/reporting/scheduler';
import { ReportGenerator } from '../../../../src/services/reporting/report-generator';
import { SlackService } from '../../../../src/services/reporting/integrations/slack-service';
import { EmailService } from '../../../../src/services/reporting/integrations/email-service';
import type { AnalysisResult } from '../../../../src/types/analysis';
import type { DashboardMetrics } from '../../../../src/types/dashboard';

// Mock cron library
vi.mock('cron', () => ({
  CronJob: vi.fn().mockImplementation((cronExpression: string, callback: () => void, onComplete: any, timeZone: string) => {
    // Validate cron expression - throw error for invalid ones
    if (cronExpression === 'invalid-cron' || cronExpression === 'invalid' ||
        cronExpression === '* * * * * * *' || // Too many fields
        cronExpression === '60 0 * * *' || // Invalid minute
        cronExpression === '0 25 * * *' || // Invalid hour
        cronExpression === '0 0 32 * *' || // Invalid day
        cronExpression === '0 0 * 13 *' || // Invalid month
        cronExpression === '0 0 * * 8') {   // Invalid day of week
      throw new Error('Invalid cron expression');
    }

    return {
      start: vi.fn(),
      stop: vi.fn(),
      nextDate: vi.fn().mockReturnValue({
        toJSDate: () => new Date(Date.now() + 60000) // 1 minute from now
      })
    };
  })
}));

// Mock ReportGenerator
vi.mock('../../../../src/services/reporting/report-generator', () => ({
  ReportGenerator: vi.fn().mockImplementation(() => ({
    generateReport: vi.fn().mockResolvedValue({
      success: true,
      outputPath: '/tmp/test-report.pdf',
      duration: 1500,
      size: 1024
    })
  }))
}));

// Mock SlackService
vi.mock('../../../../src/services/reporting/integrations/slack-service', () => ({
  SlackService: vi.fn().mockImplementation(() => ({
    sendReportNotification: vi.fn().mockResolvedValue(true),
    sendFailureNotification: vi.fn().mockResolvedValue(true)
  }))
}));

// Mock EmailService
vi.mock('../../../../src/services/reporting/integrations/email-service', () => ({
  EmailService: vi.fn().mockImplementation(() => ({
    sendReportEmail: vi.fn().mockResolvedValue(true),
    sendFailureEmail: vi.fn().mockResolvedValue(true)
  }))
}));

describe('ReportScheduler', () => {
  let scheduler: ReportScheduler;
  let mockReportGenerator: ReportGenerator;
  let mockSlackService: SlackService;
  let mockEmailService: EmailService;

  beforeEach(() => {
    mockReportGenerator = new ReportGenerator();
    mockSlackService = new SlackService({ webhookUrl: 'https://hooks.slack.com/test' });
    mockEmailService = new EmailService({ smtp: { host: 'localhost', port: 587 } });

    scheduler = new ReportScheduler(mockReportGenerator, mockSlackService, mockEmailService);
  });

  afterEach(() => {
    vi.clearAllMocks();
  });

  describe('Schedule Management', () => {
    describe('addSchedule', () => {
      it('should create a new schedule with valid cron expression', async () => {
        const scheduleData = {
          name: 'Daily Report',
          description: 'Daily quality report',
          cronExpression: '0 9 * * *', // Daily at 9 AM
          enabled: true,
          timezone: 'UTC',
          projectId: 'test-project',
          reportConfig: {
            format: 'pdf' as const,
            template: 'executive-summary',
            includeTrends: true,
            includeExecutiveSummary: true
          } as ReportConfiguration,
          notifications: []
        };

        const result = await scheduler.addSchedule(scheduleData);

        expect(result).toBeDefined();
        expect(result.id).toBeDefined();
        expect(result.name).toBe(scheduleData.name);
        expect(result.cronExpression).toBe(scheduleData.cronExpression);
        expect(result.enabled).toBe(true);
        expect(result.runCount).toBe(0);
        expect(result.failureCount).toBe(0);
        expect(result.nextRun).toBeInstanceOf(Date);
        expect(result.createdAt).toBeInstanceOf(Date);
        expect(result.updatedAt).toBeInstanceOf(Date);
      });

      it('should reject schedule with invalid cron expression', async () => {
        const scheduleData = {
          name: 'Invalid Schedule',
          cronExpression: 'invalid-cron',
          enabled: true,
          projectId: 'test-project',
          reportConfig: { format: 'json' as const },
          notifications: []
        };

        await expect(scheduler.addSchedule(scheduleData)).rejects.toThrow('Invalid cron expression');
      });

      it('should create schedule but not start job when disabled', async () => {
        const scheduleData = {
          name: 'Disabled Schedule',
          cronExpression: '0 0 * * 0', // Weekly on Sunday
          enabled: false,
          projectId: 'test-project',
          reportConfig: { format: 'html' as const },
          notifications: []
        };

        const result = await scheduler.addSchedule(scheduleData);

        expect(result.enabled).toBe(false);
        expect(result.nextRun).toBeInstanceOf(Date);
      });
    });

    describe('updateSchedule', () => {
      it('should update existing schedule', async () => {
        // First create a schedule
        const originalSchedule = await scheduler.addSchedule({
          name: 'Original Schedule',
          cronExpression: '0 0 * * *',
          enabled: true,
          projectId: 'test-project',
          reportConfig: { format: 'json' as const },
          notifications: []
        });

        // Mock getSchedule to return the created schedule
        vi.spyOn(scheduler, 'getSchedule').mockResolvedValue(originalSchedule);

        // Update the schedule
        const updates = {
          name: 'Updated Schedule',
          cronExpression: '0 12 * * *', // Change to noon
          enabled: false
        };

        const result = await scheduler.updateSchedule(originalSchedule.id, updates);

        expect(result.name).toBe(updates.name);
        expect(result.cronExpression).toBe(updates.cronExpression);
        expect(result.enabled).toBe(updates.enabled);
        expect(result.updatedAt).toBeInstanceOf(Date);
      });

      it('should throw error when updating non-existent schedule', async () => {
        vi.spyOn(scheduler, 'getSchedule').mockResolvedValue(null);

        await expect(scheduler.updateSchedule('non-existent', { name: 'Updated' }))
          .rejects.toThrow('Schedule non-existent not found');
      });
    });

    describe('deleteSchedule', () => {
      it('should delete schedule and stop associated job', async () => {
        const schedule = await scheduler.addSchedule({
          name: 'To Delete',
          cronExpression: '0 0 * * *',
          enabled: true,
          projectId: 'test-project',
          reportConfig: { format: 'json' as const },
          notifications: []
        });

        const emitSpy = vi.spyOn(scheduler, 'emit');

        await scheduler.deleteSchedule(schedule.id);

        expect(emitSpy).toHaveBeenCalledWith('scheduleDeleted', schedule.id);
      });
    });
  });

  describe('Queue Management', () => {
    describe('runReportImmediately', () => {
      it('should add immediate report to queue with correct priority', async () => {
        const emitSpy = vi.spyOn(scheduler, 'emit');

        const queueId = await scheduler.runReportImmediately(
          'test-project',
          { format: 'pdf' as const },
          'high'
        );

        expect(queueId).toBeDefined();
        expect(emitSpy).toHaveBeenCalledWith('itemQueued', expect.objectContaining({
          type: 'immediate',
          priority: 'high',
          projectId: 'test-project'
        }));
      });

      it('should use medium priority by default', async () => {
        const emitSpy = vi.spyOn(scheduler, 'emit');

        await scheduler.runReportImmediately(
          'test-project',
          { format: 'json' as const }
        );

        expect(emitSpy).toHaveBeenCalledWith('itemQueued', expect.objectContaining({
          priority: 'medium'
        }));
      });
    });

    describe('priority ordering', () => {
      it('should order queue items by priority correctly', async () => {
        const emitSpy = vi.spyOn(scheduler, 'emit');

        // Add items in different order
        await scheduler.runReportImmediately('test-project', { format: 'json' as const }, 'low');
        await scheduler.runReportImmediately('test-project', { format: 'json' as const }, 'critical');
        await scheduler.runReportImmediately('test-project', { format: 'json' as const }, 'medium');
        await scheduler.runReportImmediately('test-project', { format: 'json' as const }, 'high');

        // Check that emit was called with items in priority order
        const calls = emitSpy.mock.calls.filter(call => call[0] === 'itemQueued');
        expect(calls).toHaveLength(4);

        // Verify priority order: critical, high, medium, low
        expect(calls[0][1]).toMatchObject({ priority: 'critical' });
        expect(calls[1][1]).toMatchObject({ priority: 'high' });
        expect(calls[2][1]).toMatchObject({ priority: 'medium' });
        expect(calls[3][1]).toMatchObject({ priority: 'low' });
      });
    });

    describe('getQueueStatus', () => {
      it('should return current queue status', () => {
        const status = scheduler.getQueueStatus();

        expect(status).toMatchObject({
          pending: expect.any(Number),
          processing: expect.any(Number),
          maxConcurrent: 3
        });
      });
    });
  });

  describe('Report Generation', () => {
    describe('successful report generation', () => {
      it('should generate report and emit success event', async () => {
        const emitSpy = vi.spyOn(scheduler, 'emit');

        // Mock successful report generation
        const mockGenerateReport = vi.spyOn(mockReportGenerator, 'generateReport')
          .mockResolvedValue({
            success: true,
            outputPath: '/tmp/test-report.pdf',
            duration: 1500,
            size: 1024
          });

        await scheduler.runReportImmediately('test-project', { format: 'pdf' as const });

        // Wait for queue processing (simulate)
        await new Promise(resolve => setTimeout(resolve, 100));

        expect(mockGenerateReport).toHaveBeenCalled();
        expect(emitSpy).toHaveBeenCalledWith('reportGenerated', expect.objectContaining({
          success: true,
          duration: expect.any(Number),
          reportPath: '/tmp/test-report.pdf'
        }));
      });
    });

    describe('retry mechanisms', () => {
      it('should implement exponential backoff for failed reports', async () => {
        const emitSpy = vi.spyOn(scheduler, 'emit');

        // Mock failed report generation
        vi.spyOn(mockReportGenerator, 'generateReport')
          .mockRejectedValueOnce(new Error('Temporary failure'))
          .mockRejectedValueOnce(new Error('Temporary failure'))
          .mockResolvedValueOnce({
            success: true,
            outputPath: '/tmp/test-report.pdf',
            duration: 1500,
            size: 1024
          });

        await scheduler.runReportImmediately('test-project', { format: 'pdf' as const });

        // Wait for retry attempts
        await new Promise(resolve => setTimeout(resolve, 200));

        expect(emitSpy).toHaveBeenCalledWith('reportRetry', expect.objectContaining({
          attempt: 1,
          error: 'Temporary failure'
        }));

        expect(emitSpy).toHaveBeenCalledWith('reportRetry', expect.objectContaining({
          attempt: 2,
          error: 'Temporary failure'
        }));
      });

      it('should mark report as failed after max attempts', async () => {
        const emitSpy = vi.spyOn(scheduler, 'emit');

        // Mock persistent failure
        vi.spyOn(mockReportGenerator, 'generateReport')
          .mockRejectedValue(new Error('Persistent failure'));

        await scheduler.runReportImmediately('test-project', { format: 'pdf' as const });

        // Wait for max attempts (3)
        await new Promise(resolve => setTimeout(resolve, 500));

        expect(emitSpy).toHaveBeenCalledWith('reportFailed', expect.objectContaining({
          error: 'Persistent failure'
        }));
      });
    });
  });

  describe('Event System', () => {
    it('should emit scheduleAdded event when schedule is created', async () => {
      const emitSpy = vi.spyOn(scheduler, 'emit');

      await scheduler.addSchedule({
        name: 'Test Schedule',
        cronExpression: '0 0 * * *',
        enabled: true,
        projectId: 'test-project',
        reportConfig: { format: 'json' as const },
        notifications: []
      });

      expect(emitSpy).toHaveBeenCalledWith('scheduleAdded', expect.objectContaining({
        name: 'Test Schedule'
      }));
    });

    it('should emit scheduleUpdated event when schedule is updated', async () => {
      const schedule = await scheduler.addSchedule({
        name: 'Original',
        cronExpression: '0 0 * * *',
        enabled: true,
        projectId: 'test-project',
        reportConfig: { format: 'json' as const },
        notifications: []
      });

      vi.spyOn(scheduler, 'getSchedule').mockResolvedValue(schedule);
      const emitSpy = vi.spyOn(scheduler, 'emit');

      await scheduler.updateSchedule(schedule.id, { name: 'Updated' });

      expect(emitSpy).toHaveBeenCalledWith('scheduleUpdated', expect.objectContaining({
        name: 'Updated'
      }));
    });

    it('should emit notificationsQueued event on successful report', async () => {
      vi.spyOn(mockReportGenerator, 'generateReport')
        .mockResolvedValue({
          success: true,
          outputPath: '/tmp/test-report.pdf',
          duration: 1500,
          size: 1024
        });

      const emitSpy = vi.spyOn(scheduler, 'emit');

      await scheduler.runReportImmediately('test-project', { format: 'pdf' as const });
      await new Promise(resolve => setTimeout(resolve, 100));

      expect(emitSpy).toHaveBeenCalledWith('notificationsQueued', expect.objectContaining({
        reportPath: '/tmp/test-report.pdf',
        metrics: expect.any(Object)
      }));
    });

    it('should emit failureNotificationsQueued event on failed report', async () => {
      vi.spyOn(mockReportGenerator, 'generateReport')
        .mockRejectedValue(new Error('Report generation failed'));

      const emitSpy = vi.spyOn(scheduler, 'emit');

      await scheduler.runReportImmediately('test-project', { format: 'pdf' as const });
      await new Promise(resolve => setTimeout(resolve, 200));

      expect(emitSpy).toHaveBeenCalledWith('failureNotificationsQueued', expect.objectContaining({
        error: 'Report generation failed',
        attempts: expect.any(Number)
      }));
    });
  });

  describe('Concurrent Processing', () => {
    it('should respect maximum concurrent jobs limit', async () => {
      const emitSpy = vi.spyOn(scheduler, 'emit');

      // Mock slow report generation
      vi.spyOn(mockReportGenerator, 'generateReport')
        .mockImplementation(() => new Promise(resolve =>
          setTimeout(() => resolve({
            success: true,
            outputPath: '/tmp/test-report.pdf',
            duration: 1500,
            size: 1024
          }), 200)
        ));

      // Add 5 reports simultaneously
      for (let i = 0; i < 5; i++) {
        await scheduler.runReportImmediately(`test-project-${i}`, { format: 'pdf' as const });
      }

      // Check initial queue status
      const status = scheduler.getQueueStatus();
      expect(status.maxConcurrent).toBe(3);
      expect(status.pending).toBeGreaterThan(0);
    });
  });

  describe('Error Handling', () => {
    it('should handle cron expression validation errors gracefully', async () => {
      const invalidCronExpressions = [
        'invalid',
        '* * * * * * *', // Too many fields
        '60 0 * * *', // Invalid minute
        '0 25 * * *', // Invalid hour
        '0 0 32 * *', // Invalid day
        '0 0 * 13 *', // Invalid month
        '0 0 * * 8'   // Invalid day of week
      ];

      for (const cronExpr of invalidCronExpressions) {
        await expect(
          scheduler.addSchedule({
            name: 'Invalid Cron Test',
            cronExpression: cronExpr,
            enabled: true,
            projectId: 'test-project',
            reportConfig: { format: 'json' as const },
            notifications: []
          })
        ).rejects.toThrow('Invalid cron expression');
      }
    });

    it('should handle report generator failures', async () => {
      const error = new Error('Report generator service unavailable');
      vi.spyOn(mockReportGenerator, 'generateReport').mockRejectedValue(error);

      const emitSpy = vi.spyOn(scheduler, 'emit');

      await scheduler.runReportImmediately('test-project', { format: 'pdf' as const });
      await new Promise(resolve => setTimeout(resolve, 200));

      expect(emitSpy).toHaveBeenCalledWith('reportFailed', expect.objectContaining({
        error: 'Report generator service unavailable'
      }));
    });
  });

  describe('Shutdown', () => {
    it('should shutdown gracefully and wait for current jobs', async () => {
      // Mock slow report generation
      vi.spyOn(mockReportGenerator, 'generateReport')
        .mockImplementation(() => new Promise(resolve =>
          setTimeout(() => resolve({
            success: true,
            outputPath: '/tmp/test-report.pdf',
            duration: 1500,
            size: 1024
          }), 100)
        ));

      // Start a report
      await scheduler.runReportImmediately('test-project', { format: 'pdf' as const });

      // Wait a bit then shutdown
      await new Promise(resolve => setTimeout(resolve, 50));

      const emitSpy = vi.spyOn(scheduler, 'emit');
      await scheduler.shutdown();

      expect(emitSpy).toHaveBeenCalledWith('shutdown');
    });
  });

  describe('Integration with Notification Services', () => {
    it('should send notifications through Slack service', async () => {
      vi.spyOn(mockReportGenerator, 'generateReport')
        .mockResolvedValue({
          success: true,
          outputPath: '/tmp/test-report.pdf',
          duration: 1500,
          size: 1024
        });

      const slackSpy = vi.spyOn(mockSlackService, 'sendReportNotification')
        .mockResolvedValue(true);

      await scheduler.runReportImmediately('test-project', {
        format: 'pdf' as const,
        notifications: [{
          type: 'slack' as const,
          enabled: true,
          config: { webhookUrl: 'https://hooks.slack.com/test' },
          recipients: ['#dev-team'],
          conditions: { onSuccess: true, onFailure: false }
        }]
      });

      await new Promise(resolve => setTimeout(resolve, 100));

      // Verify Slack service would be called (implementation depends on notification configs)
      expect(slackSpy).toBeDefined();
    });

    it('should send email notifications', async () => {
      vi.spyOn(mockReportGenerator, 'generateReport')
        .mockResolvedValue({
          success: true,
          outputPath: '/tmp/test-report.pdf',
          duration: 1500,
          size: 1024
        });

      const emailSpy = vi.spyOn(mockEmailService, 'sendReportEmail')
        .mockResolvedValue(true);

      await scheduler.runReportImmediately('test-project', {
        format: 'pdf' as const,
        notifications: [{
          type: 'email' as const,
          enabled: true,
          config: { smtp: { host: 'localhost', port: 587 } },
          recipients: ['dev@company.com'],
          conditions: { onSuccess: true, onFailure: false }
        }]
      });

      await new Promise(resolve => setTimeout(resolve, 100));

      // Verify email service would be called (implementation depends on notification configs)
      expect(emailSpy).toBeDefined();
    });
  });

  describe('Performance Requirements', () => {
    it('should handle queue processing within acceptable time limits', async () => {
      const startTime = Date.now();

      // Mock fast report generation
      vi.spyOn(mockReportGenerator, 'generateReport')
        .mockResolvedValue({
          success: true,
          outputPath: '/tmp/test-report.pdf',
          duration: 500,
          size: 1024
        });

      await scheduler.runReportImmediately('test-project', { format: 'json' as const });

      // Wait for processing
      await new Promise(resolve => setTimeout(resolve, 100));

      const processingTime = Date.now() - startTime;

      // Queue processing should start quickly (within 1 second)
      expect(processingTime).toBeLessThan(1000);
    });

    it('should handle multiple concurrent schedules efficiently', async () => {
      const startTime = Date.now();

      // Create multiple schedules
      const schedules = [];
      for (let i = 0; i < 5; i++) {
        schedules.push(await scheduler.addSchedule({
          name: `Schedule ${i}`,
          cronExpression: `0 ${i} * * *`, // Different hours
          enabled: true,
          projectId: `test-project-${i}`,
          reportConfig: { format: 'json' as const },
          notifications: []
        }));
      }

      const createTime = Date.now() - startTime;

      // Creating multiple schedules should be fast
      expect(createTime).toBeLessThan(500);
      expect(schedules).toHaveLength(5);
    });
  });
});

