describe('TypeScriptConfigGenerator', () => {
  let testDir: string;
  let generator: TypeScriptConfigGenerator;

  beforeEach(() => {
    testDir = createTestDir('ts-test');
    generator = new TypeScriptConfigGenerator({ projectPath: testDir });
  });

  afterEach(() => {
    cleanupTestDir(testDir);
  });

