// Core types
export interface ProjectConfig {
  project: {
    type: "javascript" | "typescript" | "react" | "node";
    path: string;
  };
  tools: {
    eslint: {
      enabled: boolean;
      configPath?: string;
      rules?: Record<string, any>;
    };
    prettier: {
      enabled: boolean;
      configPath?: string;
      rules?: Record<string, any>;
    };
    bunTest: {
      enabled: boolean;
