      coverage?: {
        enabled: boolean;
        threshold: number;
      };
    };
  };
  analysis: {
    includePatterns: string[];
    excludePatterns: string[];
    cacheEnabled: boolean;
  };
  reporting: {
    format: "json" | "markdown" | "html";
    outputPath?: string;
  };
}

export interface AnalysisResult {
  id: string;
  timestamp: Date;
  duration: number;
  projectPath: string;
  overallScore: number;
  toolResults: ToolResult[];
  summary: {
    totalIssues: number;
    errorCount: number;
    warningCount: number;
    infoCount: number;
    coverage?: {
      line: number;
      branch: number;
      function: number;
    };
  };
}

export interface ToolResult {
  toolName: string;
  executionTime: number;
  status: "success" | "error" | "warning";
  issues: Issue[];
  metrics: Record<string, any>;
  coverage?: CoverageData;
}

export interface Issue {
  id: string;
  type: "error" | "warning" | "info";
  toolName: string;
  filePath: string;
  lineNumber: number;
  message: string;
  ruleId?: string;
  fixable: boolean;
  suggestion?: string;
  severity: number; // 1-10 score
}

export interface CoverageData {
  line: number;
  branch: number;
  function: number;
  files: {
    [filePath: string]: {
      line: number;
      branch: number;
      function: number;
    };
  };
}

export interface AnalysisOptions {
  quickMode?: boolean;
  jsonOutput?: boolean;
  outputPath?: string;
  includePatterns?: string[];
  excludePatterns?: string[];
  cacheEnabled?: boolean;
}
