## Build and Deployment

### 1. Build Script

**scripts/build.ts:**

```typescript
import { build } from "bun";
import fs from "fs/promises";
import path from "path";

async function buildProject() {
  console.log("🔨 Building DevQuality CLI...\n");

  try {
    // Clean dist directory
    await fs.rm("dist", { recursive: true, force: true }).catch(() => {});
    await fs.mkdir("dist", { recursive: true });

    // Build main bundle
    console.log("📦 Building main bundle...");
    await build({
      entrypoints: ["./src/index.ts"],
      outdir: "./dist",
      target: "node",
      format: "esm",
      splitting: false,
      sourcemap: "external",
      minify: true
    });

    // Copy package.json and modify for distribution
    console.log("📋 Preparing package.json...");
    const packageJson = JSON.parse(await fs.readFile("package.json", "utf-8"));

    // Remove dev dependencies and scripts for distribution
    delete packageJson.devDependencies;
    delete packageJson.scripts;

    await fs.writeFile(
      path.join("dist", "package.json"),
      JSON.stringify(packageJson, null, 2)
    );

    // Copy README and LICENSE
    console.log("📄 Copying documentation...");
    try {
      await fs.copyFile("README.md", path.join("dist", "README.md"));
      await fs.copyFile("LICENSE", path.join("dist", "LICENSE"));
    } catch (error) {
      console.log("⚠️  Some documentation files not found");
    }

    // Generate TypeScript types
    console.log("📝 Generating TypeScript types...");
    await build({
      entrypoints: ["./src/index.ts"],
      outdir: "./dist",
      target: "node",
      format: "esm",
      declaration: true,
      declarationMap: true,
      sourcemap: "external"
    });

    console.log("\n✅ Build complete!");
    console.log("📁 Output directory: ./dist");
    console.log("📦 Package ready for distribution");
  } catch (error) {
    console.error("\n❌ Build failed:", error.message);
    process.exit(1);
  }
}

// Run build
buildProject();
```

### 2. Deployment Script

**scripts/deploy.ts:**

```typescript
import { execSync } from "child_process";
import fs from "fs/promises";
import path from "path";

async function deploy() {
  console.log("🚀 Deploying DevQuality CLI...\n");

  try {
    // Run tests
    console.log("🧪 Running tests...");
    execSync("bun test", { stdio: "inherit" });

    // Run build
    console.log("🔨 Building project...");
    execSync("bun run build", { stdio: "inherit" });

    // Check version
    const packageJson = JSON.parse(await fs.readFile("package.json", "utf-8"));
    const version = packageJson.version;

    console.log(`📦 Version: ${version}`);

    // Tag release
    console.log("🏷️  Creating git tag...");
    execSync(`git tag -a v${version} -m "Release v${version}"`, {
      stdio: "inherit"
    });

    // Push to npm
    console.log("📤 Publishing to npm...");
    execSync("cd dist && npm publish", { stdio: "inherit" });

    // Push tags
    console.log("📤 Pushing tags...");
    execSync("git push origin --tags", { stdio: "inherit" });

    console.log("\n✅ Deployment complete!");
    console.log(`🎉 DevQuality CLI v${version} is now live!`);
  } catch (error) {
    console.error("\n❌ Deployment failed:", error.message);
    process.exit(1);
  }
}

// Run deployment
deploy();
```

