#!/usr/bin/env node

import fs from 'fs';
import path from 'path';

const rootDir = './packages/core/src';

const fixCorruptedPatterns = (filePath) => {
  let content = fs.readFileSync(filePath, 'utf8');
  let modified = false;

  // Fix corrupted variable name patterns like "criticalDomain(s as any)" -> "criticalDomains"
  content = content.replace(/(\w+)\(s as any\)/g, (match, varName) => {
    modified = true;
    return varName + 's';
  });

  // Fix corrupted property access like "context.(config as any)" -> "context.config as any"
  const propertyPattern = new RegExp('\\.\\(([^)]*\\)\\s+as any\\)', 'g');
  content = content.replace(propertyPattern, (match, propAccess) => {
    modified = true;
    const prop = propAccess.replace(/[()]/g, '');
    return `.${prop}`;
  });

  // Fix corrupted array access patterns
  content = content.replace(/(\w+)\(\s*as any\)/g, '$1');
  content = content.replace(/(\w+)\s+as any\)\./g, '$1.');

  // Fix corrupted parameter declarations
  content = content.replace(/(\w+):\s*(\w+)\s+as any\)/g, '$1: $2)');

  // Fix broken property assignment patterns
  content = content.replace(/:\s*([^,\n]+)\s+as any,/g, ': $1,');

  // Fix broken object property patterns
  content = content.replace(/(\w+):\s*([^,\n}]+)\s+as any(\s*[,\}])/g, '$1: $2$3');

  if (modified) {
    fs.writeFileSync(filePath, content);
    console.log(`Fixed corrupted patterns in ${filePath}`);
  }
};

const walkDir = (dir, callback) => {
  const files = fs.readdirSync(dir);

  for (const file of files) {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    if (stat.isDirectory()) {
      walkDir(filePath, callback);
    } else if (file.endsWith('.ts')) {
      callback(filePath);
    }
  }
};

console.log('Fixing corrupted patterns from previous batch fixes...');

walkDir(rootDir, fixCorruptedPatterns);

console.log('Completed fixing corrupted patterns.');

#!/usr/bin/env node

import fs from 'fs';

const aggregationPath = './packages/core/src/__tests__/result-aggregation-simple.test.ts';
let content = fs.readFileSync(aggregationPath, 'utf8');

// Fix all metrics objects to include missing properties
const metricsPattern = /metrics:\s*\{([^}]+)\}/g;
content = content.replace(metricsPattern, (match, inner) => {
  // Check what properties are missing
  if (!inner.includes('infoCount')) {
    inner += ',\n          infoCount: 0';
  }
  if (!inner.includes('fixableCount')) {
    inner += ',\n          fixableCount: 0';
  }

  // Make sure all required properties are present
  const metrics = {
    issuesCount: 0,
    errorsCount: 0,
    warningsCount: 0,
    infoCount: 0,
    fixableCount: 0,
    score: 100
  };

  // Parse existing metrics and add missing ones
  const parsed = {};
  inner.split(',').forEach(prop => {
    const [key, value] = prop.trim().split(':');
    if (key && value) {
      parsed[key.trim()] = value.trim();
    }
  });

  // Add missing properties with defaults
  Object.keys(metrics).forEach(key => {
    if (!parsed[key]) {
      parsed[key] = metrics[key];
    }
  });

  // Reconstruct the object
  const result = Object.entries(parsed)
    .map(([key, value]) => `${key}: ${value}`)
    .join(',\n          ');

  return `metrics: {\n          ${result}\n        }`;
});

fs.writeFileSync(aggregationPath, content);
console.log('Fixed all metrics objects in result-aggregation-simple.test.ts');

